def _client_settings_payload():
    """Read the frozen client's writable settings JSON without exposing source."""
    if not getattr(sys, "frozen", False):
        return {"values": {}, "types": {}}
    try:
        data = json.loads(CLIENT_SETTINGS_FILE.read_text(encoding="utf-8"))
        if not isinstance(data, dict) or int(data.get("version") or 0) != 1:
            return {"values": {}, "types": {}}
        return {"values": data.get("values") if isinstance(data.get("values"), dict) else {},
                "types": data.get("types") if isinstance(data.get("types"), dict) else {}}
    except Exception:
        return {"values": {}, "types": {}}


def _apply_client_settings_to_engine():
    if not getattr(sys, "frozen", False):
        return
    payload = _client_settings_payload()
    apply_settings = getattr(E, "apply_desktop_settings", None)
    if callable(apply_settings):
        apply_settings(payload.get("values") or {}, payload.get("types") or {})


