def apply_theme(name: str) -> str:
    """Set the palette used by every widget of the window."""
    global _THEME
    name = str(name or "").upper()
    if name not in THEMES:
        name = THEME_ORDER[0]
    _THEME = name
    g = globals()
    for key, val in THEMES[name].items():
        g[key] = val
    if name == "LIGHT":
        g["GOLD2"] = "#8a6a1f"
    return name


def cycle_theme() -> str:
    try:
        i = THEME_ORDER.index(_THEME)
    except Exception:
        i = 0
    return apply_theme(THEME_ORDER[(i + 1) % len(THEME_ORDER)])


