# --------------------------------------------------------------------------- #
#  log plumbing (the engine writes into a queue, the window shows it)
# --------------------------------------------------------------------------- #
# The command-line engine retains its LIVE safety prompt. The desktop app uses
# its own explicit account/risk acknowledgement before any real trading starts.
os.environ.setdefault("EDGEQUANT_APP", "1")

LOG_Q: "queue.Queue[tuple]" = queue.Queue()
RESULT_Q: "queue.Queue[tuple]" = queue.Queue()      # worker thread -> window
CLIENT_BOX: dict = {}


def q_log(msg: str = "", level: str = "info") -> None:
    LOG_Q.put(("log", time.time(), level, str(msg)))


def q_raw(text: str, level: str = "info") -> None:
    LOG_Q.put(("raw", time.time(), level, str(text)))


def patch_engine() -> None:
    """Send the engine's output into the queue instead of a console."""
    E.log = q_log
    E.rule = lambda char="-", width=76: q_raw(char * 66, "rule")
    # the engine also uses plain print() (the banner) - show it in the window too
    E.print = lambda *a, **kw: q_log(" ".join(str(x) for x in a),
                                     "info" if kw.get("flush") else "info")
    E.confirm_live = lambda acc: True          # the window asks instead
    if E.TelegramClient is not None:
        base = E.TelegramClient

        class _Tracked(base):                   # keep the client so STOP can work
            def __init__(self, *a, **kw):
                super().__init__(*a, **kw)
                CLIENT_BOX["client"] = self

        E.TelegramClient = _Tracked


patch_engine()


# v1.9.6: Telethon clients are bound to the event loop that connected them.
# SEND CODE / USE CODE / 2FA are separate GUI clicks, so their coroutines must
# all run on one persistent loop instead of asyncio.run() creating a new loop
# for every button click.
_TG_LOGIN_LOOP = None
_TG_LOGIN_THREAD = None
_TG_LOGIN_LOOP_LOCK = threading.Lock()


def _ensure_tg_login_loop():
    global _TG_LOGIN_LOOP, _TG_LOGIN_THREAD
    with _TG_LOGIN_LOOP_LOCK:
        if _TG_LOGIN_LOOP is not None and _TG_LOGIN_LOOP.is_running():
            return _TG_LOGIN_LOOP
        ready = threading.Event()
        box = {}

        def _loop_thread():
            loop = asyncio.new_event_loop()
            asyncio.set_event_loop(loop)
            box["loop"] = loop
            ready.set()
            try:
                loop.run_forever()
            finally:
                try:
                    pending = asyncio.all_tasks(loop)
                    for task in pending:
                        task.cancel()
                    if pending:
                        loop.run_until_complete(asyncio.gather(*pending,
                                                               return_exceptions=True))
                except Exception:
                    pass
                try:
                    loop.close()
                except Exception:
                    pass

        thread = threading.Thread(target=_loop_thread, name="edgequant-tg-login-loop",
                                  daemon=True)
        thread.start()
        if not ready.wait(10.0) or box.get("loop") is None:
            raise RuntimeError("Telegram login event loop did not start")
        _TG_LOGIN_LOOP = box["loop"]
        _TG_LOGIN_THREAD = thread
        return _TG_LOGIN_LOOP


def _run_tg_login_coro(coro, timeout: float = 180.0):
    """Run a GUI login step on the same live asyncio loop every time."""
    loop = _ensure_tg_login_loop()
    future = asyncio.run_coroutine_threadsafe(coro, loop)
    try:
        return future.result(timeout=max(30.0, float(timeout)))
    except TimeoutError as exc:
        future.cancel()
        raise TimeoutError(f"Telegram login step timed out after {timeout:g}s") from exc


def _stop_tg_login_loop():
    global _TG_LOGIN_LOOP, _TG_LOGIN_THREAD
    with _TG_LOGIN_LOOP_LOCK:
        loop, thread = _TG_LOGIN_LOOP, _TG_LOGIN_THREAD
        _TG_LOGIN_LOOP = None
        _TG_LOGIN_THREAD = None
    if loop is not None and loop.is_running():
        try:
            loop.call_soon_threadsafe(loop.stop)
        except Exception:
            pass
    if thread is not None and thread.is_alive() and thread is not threading.current_thread():
        try:
            thread.join(timeout=3.0)
        except Exception:
            pass


def load_ui_prefs() -> dict:
    """Theme + language are remembered in edgequant_desktop.json."""
    try:
        cfg = json.loads(SETTINGS_FILE.read_text(encoding="utf-8"))
    except Exception:
        cfg = {}
    return cfg if isinstance(cfg, dict) else {}


def save_ui_prefs(**kw) -> None:
    try:
        cfg = load_ui_prefs()
        cfg.update({k: v for k, v in kw.items() if v is not None})
        SETTINGS_FILE.write_text(json.dumps(cfg, indent=2), encoding="utf-8")
    except Exception:
        pass


def load_studio_publications() -> list:
    try:
        rows = json.loads(STUDIO_SIGNALS_FILE.read_text(encoding="utf-8"))
        return [row for row in rows if isinstance(row, dict)][-200:] if isinstance(rows, list) else []
    except Exception:
        return []


def save_studio_publications(rows) -> None:
    tmp = STUDIO_SIGNALS_FILE.with_suffix(".json.tmp")
    tmp.write_text(json.dumps(list(rows or [])[-200:], ensure_ascii=False, indent=2),
                   encoding="utf-8")
    tmp.replace(STUDIO_SIGNALS_FILE)


def load_studio_provider_links() -> list:
    """Load Provider-only explicit links to manually created MT5 magic=0 tickets."""
    return _load_studio_json_records(STUDIO_PROVIDER_JOURNAL_FILE, "links", 2000)


def save_studio_provider_links(rows) -> None:
    tmp = STUDIO_PROVIDER_JOURNAL_FILE.with_suffix(".json.tmp")
    tmp.write_text(json.dumps({"version": 1, "links": list(rows or [])[-2000:]},
                              ensure_ascii=False, indent=2), encoding="utf-8")
    tmp.replace(STUDIO_PROVIDER_JOURNAL_FILE)


def _load_studio_json_records(path, key, limit=500):
    try:
        data = json.loads(Path(path).read_text(encoding="utf-8"))
        rows = data.get(key, []) if isinstance(data, dict) else []
        return [dict(row) for row in rows if isinstance(row, dict)][-limit:]
    except Exception:
        return []


def _save_studio_json_records(path, key, rows, limit=500):
    path = Path(path)
    tmp = path.with_suffix(path.suffix + ".tmp")
    payload = {"version": 1, key: [dict(row) for row in (rows or []) if isinstance(row, dict)][-limit:]}
    tmp.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding="utf-8")
    tmp.replace(path)


