def telegram_display_name(value="") -> str:
    """Extract a safe display name from the saved `Name (@username)` status."""
    name = str(value or "").split(" (@", 1)[0]
    name = re.sub(r"[\r\n\x00-\x1f]", " ", name)
    return re.sub(r"\s+", " ", name).strip()[:80]


def bilingual_welcome(name="", telegram=False) -> str:
    """Welcome text always contains both English and Sinhala lines."""
    name = telegram_display_name(name)
    if telegram:
        if name:
            return (f"Welcome, {name}! Your Telegram account is connected.\n"
                    f"ආයුබෝවන්, {name}! ඔබගේ Telegram ගිණුම සාර්ථකව සම්බන්ධ වුණා.")
        return ("Welcome! Your Telegram account is connected.\n"
                "ආයුබෝවන්! ඔබගේ Telegram ගිණුම සාර්ථකව සම්බන්ධ වුණා.")
    if name:
        return (f"Welcome back, {name}! EdgeQuant Sentinel is ready.\n"
                f"ආයුබෝවන්, {name}! EdgeQuant Sentinel සූදානම්.")
    return ("Welcome to EdgeQuant Sentinel!\n"
            "EdgeQuant Sentinel වෙත සාදරයෙන් පිළිගනිමු!")


def money(v, cur="") -> str:
    try:
        return f"{float(v):,.2f} {cur}".strip()
    except Exception:
        return "-"


def mt5_trade_mode_label(mt5, value, server="", company="") -> str:
    """Return a conservative MT5 account classification (never guess REAL)."""
    text = str(value or "").strip().upper()
    if text in ("DEMO", "REAL", "CONTEST", "UNKNOWN"):
        return text
    try:
        number = int(value)
    except Exception:
        number = None
    if number is not None:
        for label in ("DEMO", "CONTEST", "REAL"):
            constant = getattr(mt5, "ACCOUNT_TRADE_MODE_" + label, None)
            try:
                if constant is not None and number == int(constant):
                    return label
            except Exception:
                continue
    hint = (str(server or "") + " " + str(company or "")).casefold()
    if "demo" in hint or "practice" in hint:
        return "DEMO"
    return "UNKNOWN"


# Windows execution-state flags.  Deliberately omit ES_DISPLAY_REQUIRED so the
# display's normal timeout can turn the monitor off while the PC stays awake.
ES_CONTINUOUS = 0x80000000
ES_SYSTEM_REQUIRED = 0x00000001
ES_DISPLAY_REQUIRED = 0x00000002


def windows_keep_awake_flags(enabled: bool) -> int:
    """Prevent system idle sleep, but never keep the display awake."""
    return ES_CONTINUOUS | (ES_SYSTEM_REQUIRED if enabled else 0)


def set_windows_keep_awake(enabled: bool) -> tuple[bool, str]:
    """Set/clear Windows system-awake request without suppressing display-off."""
    if os.name != "nt":
        return False, "This control is available on Windows only."
    try:
        import ctypes
        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        api = kernel32.SetThreadExecutionState
        api.argtypes = [ctypes.c_ulong]
        api.restype = ctypes.c_ulong
        result = api(ctypes.c_ulong(windows_keep_awake_flags(bool(enabled))))
        if not result:
            error = ctypes.get_last_error()
            return False, f"Windows could not apply the power request (error {error})."
        return True, ""
    except Exception as exc:
        return False, f"{type(exc).__name__}: {exc}"


def engine_status() -> dict:
    """v1.9.2: what the running engine says about Telegram / MT5 (any window).

    Reads the engine's status file.  "fresh" means a bot is running somewhere
    right now (this window or another one).
    """
    try:
        return E.tg_status_read() or {}
    except Exception:
        return {}


def quiet(call, *a, **kw):
    """Run an engine helper without writing its log lines into the window."""
    keep = E.log
    E.log = lambda *x, **y: None
    try:
        return call(*a, **kw)
    finally:
        E.log = keep


def fmt_money(v, cur="") -> str:
    try:
        v = float(v)
    except Exception:
        return "-"
    sign = "-" if v < 0 else ""
    return f"{sign}{abs(v):,.2f}{(' ' + cur) if cur else ''}"


def fmt_pl(v) -> str:
    try:
        v = float(v)
    except Exception:
        return "-"
    return f"{'+' if v >= 0 else '-'}{abs(v):,.2f}"


def pl_colour(v) -> str:
    try:
        v = float(v)
    except Exception:
        return MUTED
    return GREEN if v > 0 else (RED if v < 0 else MUTED)


def st_all_txt(st) -> str:
    return (f"{st['n']} orders | {st['pending']} pending | {st['open']} live | "
            f"TP {st['tp']} / SL {st['sl']} / BE {st['be']} | net {st['pl']:+,.2f}")


def fmt_win(win):
    return "-" if win is None else f"{win:.1f}%"


SINHALA_OK = None            # is a Sinhala-capable font installed ?


def _sinhala_family() -> str:
    """Windows: Nirmala UI carries the Sinhala glyphs (Segoe UI does not)."""
    global SINHALA_OK
    if SINHALA_OK is not None:
        return "Nirmala UI" if SINHALA_OK else ""
    try:
        import tkinter.font as tkfont
        fams = set(tkfont.families())
    except Exception:
        fams = set()
    SINHALA_OK = ("Nirmala UI" in fams or "Iskoola Pota" in fams or "Noto Sans Sinhala" in fams)
    if "Nirmala UI" in fams:
        return "Nirmala UI"
    if "Iskoola Pota" in fams:
        return "Iskoola Pota"
    if "Noto Sans Sinhala" in fams:
        return "Noto Sans Sinhala"
    return ""


def widget_font(name="Segoe UI", size=9, bold=False):
    """A Tk font tuple.  Tk only accepts an INTEGER size - never a float
    (a float raises: expected integer but got "8.5"), so it is rounded here.

    v1.7.0: while the app is in SINHALA the text widgets switch to a font that
    actually has the Sinhala letters (otherwise you see empty boxes).
    """
    try:
        size = int(round(float(size)))
    except Exception:
        size = 9
    if LANG == "SI" and name.startswith("Segoe UI"):
        fam = _sinhala_family()
        if fam:
            name = fam
    return (name, size, "bold") if bold else (name, size)


def open_path(path: Path) -> None:
    try:
        if hasattr(os, "startfile"):
            os.startfile(str(path))                     # Windows
        elif sys.platform == "darwin":
            subprocess.Popen(["open", str(path)])
        else:
            subprocess.Popen(["xdg-open", str(path)])
    except Exception as exc:
        q_log(f"cannot open {path.name}: {exc}", "warn")


class BotRunner(threading.Thread):
    """Runs the engine in its own thread with its own asyncio loop."""

    def __init__(self, dry: bool):
        super().__init__(daemon=True, name="edgequant-bot")
        self.dry = dry
        self.loop = None

    def run(self):
        E.DRY_RUN = bool(self.dry)
        self.loop = asyncio.new_event_loop()
        asyncio.set_event_loop(self.loop)
        q_log(f"engine starting ({'TEST RUN - no real orders' if self.dry else 'LIVE'})",
              "warn" if self.dry else "live")
        try:
            self.loop.run_until_complete(E.run_bot(debug_only=False))
        except Exception as exc:
            q_log(f"bot stopped: {exc}", "err")
        finally:
            try:
                self.loop.close()
            except Exception:
                pass
            E.release_singleton()
            q_log("engine finished", "info")

    def stop(self) -> bool:
        # v1.9.5: the engine may be waiting for a new Telegram login (there is
        # no client to disconnect) - the stop flag reaches that wait loop too.
        try:
            E.request_stop()
        except Exception:
            pass
        cl = CLIENT_BOX.get("client")
        if cl is not None and self.loop is not None and self.loop.is_running():
            try:
                asyncio.run_coroutine_threadsafe(cl.disconnect(), self.loop)
                q_log("stopping: closing the Telegram session ...", "warn")
                return True
            except Exception as exc:
                q_log(f"stop: {exc}", "err")
        return False


# --------------------------------------------------------------------------- #
#  v1.6.6  -  why did the .exe stop ?   (one diagnostic, always written to disk)
# --------------------------------------------------------------------------- #
def startup_diagnostics(write: bool = True) -> list:
    """Check everything the app needs and write it to edgequant_startup.log.

    This is the first thing to look at when an .exe "starts and stops".
    """
    L = ["=" * 74]
    L.append(f"  EDGEQUANT  STARTUP DIAGNOSTIC   {datetime.now().strftime('%Y-%m-%d %H:%M:%S')}")
    L.append("=" * 74)
    L.append(f"  app build     {APP_BUILD}      engine file v{getattr(E, 'VERSION', '?')}")
    L.append(f"  running as    {'a built .exe (frozen)' if getattr(sys, 'frozen', False) else 'python ' + sys.version.split()[0]}")
    L.append(f"  python        {sys.version.split()[0]}   ({sys.executable})")
    L.append(f"  app folder    {APP_DIR}")
    try:
        _t = APP_DIR / "edgequant_write_test.tmp"
        _t.write_text("ok", encoding="utf-8")
        _t.unlink()
        L.append("  folder        writable (session + journal can be saved here)")
    except Exception as exc:
        L.append(f"  folder        [!] NOT writable -> {exc}")
        L.append("                the bot cannot work here: move the folder to F:\\ or a")
        L.append("                folder outside Program Files / OneDrive.")
    for mod, label in (("telethon", "Telegram (telethon)"),
                       ("MetaTrader5", "MetaTrader 5 (mt5 module)"),
                       ("PIL", "Pillow (optional - PDF pictures)")):
        try:
            m = __import__(mod)
            v = getattr(m, "__version__", getattr(m, "version", ""))
            L.append(f"  {label:<28} OK   {v}")
        except Exception as exc:
            L.append(f"  {label:<28} MISSING  ({exc})")
            if mod in ("telethon", "MetaTrader5"):
                L.append("                -> open BUILD-EXE.bat again (it installs these)")
                L.append("                   or run:   pip install -r requirements.txt")
            if mod == "MetaTrader5" and ("_core" in str(exc).lower() or
                                         "dll load failed" in str(exc).lower()):
                L.append("                MT5 native _core DLL failed before terminal/account login.")
                L.append("                Install the Microsoft Visual C++ x64 runtime, use 64-bit Python,")
                L.append('                verify `python -c "import MetaTrader5"`, then rebuild.')
    sess = list(APP_DIR.glob("*.session"))
    L.append(f"  telegram session    {'FOUND ' + sess[0].name if sess else 'not yet - the first start will ask for your phone/code'}")
    try:
        _jr = APP_DIR / str(getattr(E, "TRADE_REPORT", "EDGEQUANT-JOURNAL-REPORT.txt"))
        L.append(f"  journal report      {'found' if _jr.exists() else 'will be written on the first order'}"
                 f"   (journal {'ON' if getattr(E, 'TRADE_JOURNAL', False) else 'OFF'})")
    except Exception as exc:
        L.append(f"  journal report      [?] {exc}")
    L.append(f"  logo files          {'ok' if (APP_DIR / 'edgequant-logo-small.png').exists() else 'missing -> copy them next to the exe'}")
    L.append(f"  lock file           {'present (another window may be running)' if (APP_DIR / 'edgequant.lock').exists() else 'free'}")
    L.append(f"  D(RY_RUN)           DRY_RUN = {getattr(E, 'DRY_RUN', '?')}   "
             f"CONFIRM_LIVE_START = {getattr(E, 'CONFIRM_LIVE_START', '?')}")
    L.append(f"  channels            LIMIT {len(getattr(E, 'LIMIT_CHANNELS', []))}   "
             f"MARKET {len(getattr(E, 'MARKET_CHANNELS', []))}   "
             f"(switch them on the CHANNELS tab)")
    L.append("=" * 74)
    if getattr(sys, "frozen", False):
        L.append("  NOTE  inside the .exe the engine runs in this same window (no second")
        L.append("        process).  If Telegram asks for a code, type it in the dialog.")
    if write:
        try:
            (APP_DIR / "edgequant_startup.log").write_text("\n".join(L) + "\n", encoding="utf-8")
        except Exception:
            pass
    return L


