    def _chip(self, parent, title, value):
        box = ttk.Frame(parent, style="Panel.TFrame")
        box.pack(side="left", padx=(0, 14))
        ttk.Label(box, text=title, style="Muted.TLabel").pack(anchor="w")
        lab = ttk.Label(box, text=value, style="H2.TLabel", background=PANEL,
                        foreground=ACCENT)
        lab.pack(anchor="w")
        return lab

    # --------------------------------------------------------- DASHBOARD ---
    def _safe_tab(self, builder, tab, label: str) -> None:
        """Build one tab; if it fails, show the reason INSIDE the tab instead of
        closing the whole app."""
        try:
            builder(tab)
        except Exception as exc:
            import traceback
            detail = traceback.format_exc()
            try:
                with open(APP_DIR / "edgequant_desktop_error.log", "a",
                          encoding="utf-8") as fh:
                    fh.write(f"\n===== tab {label} =====\n{detail}")
            except Exception:
                pass
            try:
                tk.Label(tab, text=f"this tab could not be drawn:\n\n{exc}\n\n"
                                   f"(the rest of the app works normally - the full "
                                   f"detail is in edgequant_desktop_error.log)",
                         bg=PANEL, fg=RED, justify="left", anchor="w",
                         font=widget_font("Segoe UI", 9)).pack(fill="both", expand=True,
                                                               padx=14, pady=14)
            except Exception:
                pass
            q_log(f"the {label} tab could not be drawn: {exc}", "err")

    def _card(self, parent, row, col, title, accent=ACCENT):
        """Layered metric card with a soft offset shadow and raised accent edge."""
        host = tk.Frame(parent, bg=BG)
        host.grid(row=row, column=col, sticky="nsew", padx=6, pady=6)
        box = tk.Frame(host, bg=PANEL, highlightbackground=LINE, highlightthickness=1)
        # Leave four pixels of the outer dark base exposed on the right/bottom.
        box.pack(fill="both", expand=True, padx=(0, 4), pady=(0, 4))
        tk.Frame(box, bg=accent, height=3).pack(fill="x")
        tk.Frame(box, bg="#29384c", height=1).pack(fill="x")
        tk.Label(box, text=title, bg=PANEL, fg=MUTED, font=widget_font("Segoe UI", 8, True),
                 anchor="w").pack(fill="x", padx=14, pady=(9, 0))
        val = tk.Label(box, text="-", bg=PANEL, fg=FG,
                       font=widget_font("Segoe UI", 22, True), anchor="w")
        val.pack(fill="x", padx=14)
        sub = tk.Label(box, text="", bg=PANEL, fg=MUTED, font=widget_font("Segoe UI", 8),
                       anchor="w", justify="left")
        sub.pack(fill="x", padx=14, pady=(0, 11))
        return val, sub

