    def apply_layers(self):
        """Keep the two-layer count fixed; the first target is Dashboard-configurable."""
        E.LAYERS_PER_PRICE = 2
        if hasattr(self, "lay_var"):
            self.lay_var.set("2")
        note = (f"fixed 2 layers per entry: L1 +{float(E.LAYER1_TP_PIPS):g} pips, "
                "L2 = exact selected signal TP")
        if hasattr(self, "quick_note"):
            self.quick_note.configure(text=L("2 layers fixed", "layers 2ක් ස්ථිරයි"))
        q_log(note, "info")
        try:
            self.refresh_dashboard()
        except Exception:
            pass

    def apply_layer1_target(self):
        """Save the Dashboard-controlled first-layer quick-target distance."""
        try:
            value = float(str(self.layer1_tp_var.get()).strip().replace(",", ""))
            if not math.isfinite(value) or not 1.0 <= value <= 10000.0:
                raise ValueError("Enter a first-layer target from 1 to 10,000 pips.")
            value = round(value, 2)
            value = int(value) if value.is_integer() else value
        except Exception as exc:
            messagebox.showerror(L("Layer 1 target", "Layer 1 ඉලක්කය"), str(exc), parent=self.root)
            return False
        E.LAYER1_TP_PIPS = value
        E.QUICK_TP_PIPS = value  # keep the legacy alias synchronized for older helpers
        self.layer1_tp_var.set(f"{value:g}")
        self._save_to_settings_file("LAYER1_TP_PIPS", value)
        text = L(f"Layer 1 quick target: +{value:g} pips · saved locally",
                 f"Layer 1 quick target: +{value:g} pips · දේශීයව සුරැකිණි")
        if hasattr(self, "layer1_target_note"):
            self.layer1_target_note.configure(text=text, fg=CYAN)
        if hasattr(self, "exec_profile_note"):
            self.exec_profile_note.configure(text=L(
                f"Two orders per signal · Layer 1 +{value:g} pips · Layer 2 signal TP shifted 10 pips inward",
                f"signal එකකට orders දෙකයි · Layer 1 +{value:g} pips · Layer 2 signal TP එකමයි"))
        q_log(text, "ok")
        try:
            self.refresh_dashboard()
        except Exception:
            pass
        return True

    def apply_auto_be(self):
        """Master switch for automatic BE handling; threshold defaults to +50 pips."""
        enabled = bool(self.auto_be_var.get())
        E.AUTO_BE_ENABLED = enabled
        self._save_to_settings_file("AUTO_BE_ENABLED", enabled)
        threshold = max(0.0, float(getattr(E, "AUTO_BE_PIPS", 50) or 0))
        note = L(f"Automatic BE is {'ON' if enabled else 'OFF'} · trigger +{threshold:g} pips",
                 f"ස්වයංක්‍රීය BE {'ON' if enabled else 'OFF'} · trigger +{threshold:g} pips")
        if hasattr(self, "auto_be_note"):
            self.auto_be_note.configure(text=note, fg=GREEN if enabled else MUTED)
        q_log(note, "ok")
        return True

    def apply_be(self):
        """Set the optional break-even trigger/ladder step; default is +50 pips."""
        try:
            v = float(self.be_var.get())
        except Exception:
            v = 0.0
        v = max(0.0, min(200.0, v))
        self.be_var.set(str(int(v)))
        E.BE_LADDER_PIPS = v
        E.AUTO_BE_PIPS = v
        save_ui_prefs(be_ladder=v)
        try:
            E.state_set("be_ladder_pips", v)
            E.state_set("be_ladder_pips_ts", time.time())
        except Exception:
            pass
        self._save_to_settings_file("BE_LADDER_PIPS", v)
        self._save_to_settings_file("AUTO_BE_PIPS", v)
        msg = (f"BE trigger/step {int(v)} pips  " +
               ("OFF" if v <= 0 else f"ON only when AUTO BE is ON; first trigger +{int(v)} pips"))
        self.quick_note.configure(text=msg)
        if hasattr(self, "auto_be_note"):
            enabled = bool(getattr(E, "AUTO_BE_ENABLED", False))
            self.auto_be_note.configure(
                text=f"{'ON' if enabled else 'OFF'} · +{v:g} pips",
                fg=GREEN if enabled else MUTED)
        q_log(msg, "ok")

    def _save_to_settings_file(self, name: str, value):
        """Persist one setting (including bool) and preserve live-engine behavior."""
        if isinstance(value, bool):
            stored, kind = value, "bool"
        else:
            try:
                numeric = float(value)
                if not math.isfinite(numeric):
                    raise ValueError("setting value must be finite")
                stored = int(numeric) if numeric.is_integer() else numeric
                kind = "int" if numeric.is_integer() else "float"
            except Exception as exc:
                q_log(f"         could not save {name}: {exc}", "warn")
                return
        updates = {name: (stored, kind)}
        if name == "LAYER1_TP_PIPS":
            updates["QUICK_TP_PIPS"] = (stored, kind)
        if self.bot and self.bot.is_alive():
            try:
                if getattr(sys, "frozen", False):
                    _save_client_engine_settings(updates)
                    q_log(f"         {name} = {stored} saved to the client settings file and applied live", "info")
                    return
                src = (APP_DIR / "edgequant_auto.py").read_text(encoding="utf-8")
                new_src, added = apply_updates(src, updates)
                compile(new_src, "edgequant_auto.py", "exec")
                (APP_DIR / "edgequant_auto.py.bak").write_text(src, encoding="utf-8")
                (APP_DIR / "edgequant_auto.py").write_text(new_src, encoding="utf-8")
                q_log(f"         {name} = {stored} saved in the engine file "
                      f"(active right away - the running bot already uses it"
                      f"{'; settings added: ' + ', '.join(added) if added else ''})", "info")
            except Exception as exc:
                q_log(f"         {name} stays {stored} for this session ({exc})", "warn")
            return
        try:
            save_settings_file(APP_DIR / "edgequant_auto.py", updates)
            if LAST_ADDED_SETTINGS:
                q_log(f"         {name} was not in the engine file - added at the end "
                      f"of it ({', '.join(LAST_ADDED_SETTINGS)})", "warn")
            else:
                q_log(f"         {name} = {stored} saved in the engine file", "info")
        except Exception as exc:
            q_log(f"         could not save {name}: {exc}", "warn")

