    BP_PERIODS = (("today", "DAILY", "දින"), ("week", "WEEKLY", "සති"),
                  ("month", "MONTHLY", "මාසික"), ("all", "ALL", "සියල්ල"))

    def _build_best_board(self, parent, row=4):
        box = tk.Frame(parent, bg=PANEL, highlightbackground=GOLD, highlightthickness=1)
        box.grid(row=row, column=0, columnspan=4, sticky="nsew", padx=6, pady=(2, 6))
        head = tk.Frame(box, bg=PANEL)
        head.pack(fill="x", padx=14, pady=(8, 0))
        tk.Label(head, text=L("BEST TRADES   (closed results; full details in TRADE JOURNAL)",
                              "හොඳම ට්‍රේඩ්ස්   (වැසූ ප්‍රතිඵල; සම්පූර්ණ විස්තර TRADE JOURNAL හි)"),
                 bg=PANEL, fg=GOLD, font=widget_font("Segoe UI", 10, True)).pack(side="left")
        self.bp_btns = {}
        for key, en, si in reversed(self.BP_PERIODS):
            b = tk.Button(head, text=L(en, si), relief="flat", bd=0, padx=12, pady=2,
                          bg=PANEL2, fg=FG, activebackground=GOLD, activeforeground="#101010",
                          font=widget_font("Segoe UI", 8, True),
                          command=lambda k=key: self.bp_set_period(k))
            b.pack(side="right", padx=2)
            self.bp_btns[key] = b
        self.bp_chan = tk.StringVar(value="ALL CHANNELS")
        self.bp_combo = ttk.Combobox(head, textvariable=self.bp_chan, width=24,
                                     state="readonly", values=["ALL CHANNELS"])
        self.bp_combo.pack(side="right", padx=(0, 10))
        self.bp_combo.bind("<<ComboboxSelected>>", lambda e: self.bp_refresh(True))
        tk.Label(head, text=L("CHANNEL:", "චැනල්:"), bg=PANEL, fg=MUTED,
                 font=widget_font("Segoe UI", 8)).pack(side="right")

        body = tk.Frame(box, bg=PANEL)
        body.pack(fill="both", expand=True, padx=10, pady=(4, 8))
        body.columnconfigure(0, weight=3)
        body.columnconfigure(1, weight=2)
        body.rowconfigure(0, weight=1)
        self.bp_canvas = tk.Canvas(body, bg=DEEP, highlightthickness=0, height=165,
                                   bd=0)
        self.bp_canvas.grid(row=0, column=0, sticky="nsew")
        self.bp_canvas.bind("<Configure>", lambda e: self.bp_draw())
        self.bp_side = tk.Frame(body, bg=DEEP, highlightbackground=LINE,
                                highlightthickness=1)
        self.bp_side.grid(row=0, column=1, sticky="nsew", padx=(8, 0))
        self.bp_side_inner = tk.Frame(self.bp_side, bg=DEEP)
        self.bp_side_inner.pack(fill="both", expand=True, padx=10, pady=6)
        self.bp_kz_title = tk.Label(self.bp_side_inner,
                                    text=L("BEST KILL ZONE   (the hour that pays)",
                                           "හොඳම කිල් සෝන්   (සල්ලි එන පැය)"),
                                    bg=DEEP, fg=CYAN,
                                    font=widget_font("Segoe UI", 9, True), anchor="w")
        self.bp_kz_title.pack(fill="x")
        self.bp_kz_big = tk.Label(self.bp_side_inner, text="-", bg=DEEP, fg=GOLD,
                                  font=widget_font("Consolas", 17, True), anchor="w")
        self.bp_kz_big.pack(fill="x", pady=(2, 0))
        self.bp_kz_txt = tk.Label(self.bp_side_inner, text="", bg=DEEP, fg=FG, justify="left",
                                  anchor="w", font=widget_font("Consolas", 9))
        self.bp_kz_txt.pack(fill="x", pady=(4, 0))
        self.bp_kz_hours = tk.Label(self.bp_side_inner, text="", bg=DEEP, fg=MUTED,
                                    justify="left", anchor="w", wraplength=330,
                                    font=widget_font("Segoe UI", 8))
        self.bp_kz_hours.pack(fill="x", pady=(6, 0))
        self.bp_data = []
        self.bp_kz_data = []
        self.bp_phase = 0.0
        # Start with historical closed trades visible; users can switch to DAILY.
        self.bp_period = "all"
        self.bp_last = 0.0
        self.bp_set_period("all", redraw=False)
        self.root.after(600, lambda: self.bp_refresh(True))

    def bp_set_period(self, key: str, redraw: bool = True):
        self.bp_period = key if key in dict((k, 1) for k, _e, _s in self.BP_PERIODS) \
            else "today"
        for k, b in self.bp_btns.items():
            on = (k == self.bp_period)
            try:
                b.configure(bg=GOLD if on else PANEL2, fg="#101010" if on else FG)
            except Exception:
                pass
        if redraw:
            self.bp_refresh(True)

    def bp_channels(self) -> list:
        names = ["ALL CHANNELS"]
        try:
            for r in E.best_trades("all", limit=500):
                if r["channel"] not in names:
                    names.append(r["channel"])
        except Exception:
            pass
        try:
            for r in E.channel_catalog():
                nm = r.get("name")
                if nm and nm not in names:
                    names.append(nm)
        except Exception:
            pass
        return names[:40]

    def bp_refresh(self, force: bool = False):
        if time.time() - self.bp_last < (0.4 if force else 6.0):
            return
        self.bp_last = time.time()
        chan = "" if self.bp_chan.get().startswith("ALL") else self.bp_chan.get()
        try:
            self.bp_data = E.best_trades(self.bp_period, chan, limit=6)
            self.bp_kz_data = E.kill_zones("all" if self.bp_period == "all" else self.bp_period)
        except Exception as exc:
            self.bp_data, self.bp_kz_data = [], []
            q_log(f"best-trades board: {exc}", "warn")
        try:
            vals = self.bp_channels()
            if list(self.bp_combo["values"]) != vals:
                self.bp_combo.configure(values=vals)
        except Exception:
            pass
        self._bp_kill_zone()
        self.bp_draw()

    def _bp_kill_zone(self):
        rows = self.bp_kz_data
        if not rows:
            self.bp_kz_big.configure(text="-")
            self.bp_kz_txt.configure(text=L("no closed trades in this period yet",
                                            "මේ කාලයේ ට්‍රේඩ්ස් වැහිලා නෑ"))
            self.bp_kz_hours.configure(text=L("the board fills up as trades close",
                                              "ට්‍රේඩ් වැහෙන කොට පිරෙනවා"))
            return
        b = rows[0]
        self.bp_kz_big.configure(text=f"{b['hour']:02d}:00")
        win = "-" if b["win"] is None else f"{b['win']:.0f}%"
        self.bp_kz_txt.configure(
            text=f"{b['net']:+.2f} USD   {b['n']} trade(s)   win {win}\n"
                 f"TP {b['tp']}   SL {b['sl']}")
        top = sorted(rows, key=lambda r: r["net"], reverse=True)[:3]
        good = [r for r in rows if r["net"] > 0]
        self.bp_kz_hours.configure(
            text=L("BEST HOURS: ", "හොඳම පැය: ") +
                 ", ".join(f"{r['hour']:02d}:00 ({r['net']:+.2f})" for r in top) +
                 ("\n" + L("profitable hours: ", "ලාභ ගත් පැය: ") +
                  ", ".join(f"{r['hour']:02d}" for r in
                            sorted(good, key=lambda r: r["hour"])) if good else ""))

    def bp_draw(self):
        """One frame of the animated board: bars + labels + the scanning light."""
        c = self.bp_canvas
        try:
            c.delete("all")
            w = max(240, c.winfo_width())
            h = max(120, c.winfo_height())
        except Exception:
            return
        data = list(self.bp_data or [])
        if not data:
            c.create_text(w / 2, h / 2 - 8,
                          text=L("no closed trades yet - the board fills up as trades close",
                                 "තාම වැහුණු ට්‍රේඩ්ස් නෑ - ට්‍රේඩ් වැහෙන කොට පිරෙනවා"),
                          fill=MUTED, font=widget_font("Segoe UI", 10))
            c.create_text(w / 2, h / 2 + 12,
                          text=L("(TEST RUN orders are not journaled)",
                                 "(ටෙස්ට් රන් ඕඩර්ස් ජර්නලයට වැටෙන්නේ නෑ)"),
                          fill=MUTED, font=widget_font("Segoe UI", 8))
            return
        top = max(abs(float(r["net"])) for r in data) or 1.0
        n = len(data)
        gap = 14
        bw = max(40.0, min(120.0, (w - 24 - gap * (n - 1)) / float(n)))
        total_w = bw * n + gap * (n - 1)
        x0 = (w - total_w) / 2.0
        base = h - 30.0
        span = max(24.0, base - 30.0)
        c.create_line(x0 - 6, base, x0 + total_w + 6, base, fill=LINE, width=2)
        for i, r in enumerate(data):
            net = float(r["net"])
            x = x0 + i * (bw + gap)
            pulse = 0.90 + 0.10 * math.sin(self.bp_phase * 2.0 + i * 0.8)
            bh = max(8.0, (abs(net) / top) * span * pulse)
            y = base - bh
            col = GREEN if net >= 0 else RED
            c.create_rectangle(x + 3, y + 3, x + bw + 3, base + 3,
                               fill="#161d29" if _THEME != "LIGHT" else "#c8d3e2",
                               outline="")
            c.create_rectangle(x, y, x + bw, base, fill=col,
                               outline=GOLD if i == 0 else col, width=2 if i == 0 else 1)
            c.create_text(x + bw / 2, y - 9, text=f"{net:+.2f}",
                          fill=GOLD if i == 0 else FG,
                          font=widget_font("Consolas", 9, True))
            c.create_text(x + bw / 2, base + 9, text=str(r["channel"])[:13],
                          fill=GOLD if i == 0 else MUTED,
                          font=widget_font("Segoe UI", 7, True))
            c.create_text(x + bw / 2, base + 20,
                          text=f"{r['symbol']} {r['direction']}  {float(r['pips']):+.0f}p",
                          fill=MUTED, font=widget_font("Consolas", 7))
            if i == 0:
                c.create_text(x + bw / 2, max(9, y - 22), text="TOP", fill=GOLD,
                              font=widget_font("Segoe UI", 8, True))
        sx = x0 + ((self.bp_phase * 0.30) % 1.0) * total_w
        c.create_line(sx, 6, sx, base, fill=GOLD, dash=(3, 5))

    def bp_animate(self):
        """Called from the 400 ms UI tick - the board breathes."""
        if not hasattr(self, "bp_canvas"):
            return
        self.bp_phase += 0.13
        try:
            self.bp_draw()
        except Exception:
            pass

