    def _build_target_board(self, parent, row=6):
        box = tk.Frame(parent, bg=PANEL, highlightbackground=GOLD, highlightthickness=1)
        box.grid(row=row, column=0, columnspan=4, sticky="nsew", padx=6, pady=(2, 6))
        head = tk.Frame(box, bg=PANEL)
        head.pack(fill="x", padx=14, pady=(8, 0))
        tk.Label(head, text=L("DAILY TARGET   (capital -> target -> done)",
                              "දිනපතා ඉලක්කය   (මුල් මුදල -> ඉලක්කය -> ඉටු කිරීම)"),
                 bg=PANEL, fg=GOLD, font=widget_font("Segoe UI", 10, True)).pack(side="left")
        self.dt_note = tk.Label(head, text="", bg=PANEL, fg=CYAN,
                                font=widget_font("Consolas", 9))
        self.dt_note.pack(side="right")
        ttk.Button(head, text=L("STOP AFTER", "ඊට පස්සේ නවත්වන්න"), width=13,
                   command=self.dt_toggle_stop).pack(side="right", padx=3)

        # ---- v1.9.4 : the user TYPES the target himself ---------------------
        setrow = tk.Frame(box, bg=PANEL2, highlightbackground=GOLD, highlightthickness=1)
        setrow.pack(fill="x", padx=14, pady=(6, 2))
        tk.Label(setrow, text=L("SET THE TARGET  ", "ඉලක්කය දාන්න  "), bg=PANEL2, fg=GOLD,
                 font=widget_font("Segoe UI", 9, True)).pack(side="left", padx=(8, 10), pady=5)

        def _lbl(txt):
            tk.Label(setrow, text=txt, bg=PANEL2, fg=MUTED,
                     font=widget_font("Segoe UI", 8, True)).pack(side="left", padx=(8, 3))

        def _entry(var, width):
            e = tk.Entry(setrow, textvariable=var, width=width, bg=PANEL, fg=FG,
                         relief="flat", insertbackground=FG, justify="right",
                         font=widget_font("Consolas", 11, True))
            e.pack(side="left", pady=4)
            e.bind("<Return>", lambda ev: self.dt_apply())
            return e

        _lbl(L("MODE", "මෝඩ්"))
        self.dt_mode = tk.StringVar(value=str(getattr(E, "DAILY_TARGET_MODE", "PCT")).upper())
        if self.dt_mode.get() not in ("PCT", "USD", "PLAN"):
            self.dt_mode.set("PCT")
        cbm = ttk.Combobox(setrow, textvariable=self.dt_mode, width=7, state="readonly",
                           values=["PCT", "USD", "PLAN"])
        cbm.pack(side="left", padx=(2, 6))
        cbm.bind("<<ComboboxSelected>>", lambda e: self.dt_mode_hint())
        _lbl(L("VALUE", "අගය"))
        self.dt_value = tk.StringVar(value=self.dt_value_now())
        self.dt_value_entry = _entry(self.dt_value, 6)
        _lbl(L("CAPITAL", "මුල් මුදල"))
        self.dt_capital = tk.StringVar(value=f"{float(getattr(E, 'DAILY_TARGET_CAPITAL', 0) or 0):g}")
        _entry(self.dt_capital, 8)
        ttk.Button(setrow, text=L("SAVE THE TARGET", "සේව් කරන්න"), style="Go.TButton",
                   command=self.dt_apply).pack(side="left", padx=(10, 4), pady=4)
        self.dt_on_btn = ttk.Button(setrow, text="", width=10, command=self.dt_toggle_on)
        self.dt_on_btn.pack(side="left", padx=4, pady=4)
        self.dt_set_note = tk.Label(setrow, text="", bg=PANEL2, fg=CYAN,
                                    font=widget_font("Consolas", 8), anchor="w")
        self.dt_set_note.pack(side="left", padx=(10, 6))
        self.dt_mode_hint()

        # Target behavior and periodic update controls stay with the target board,
        # not buried in the generic Settings tab.
        options_row = tk.Frame(box, bg=PANEL2, highlightbackground=LINE, highlightthickness=1)
        options_row.pack(fill="x", padx=14, pady=(2, 4))
        self.dt_compound_var = tk.BooleanVar(value=bool(getattr(E, "DAILY_TARGET_COMPOUND", True)))
        tk.Checkbutton(options_row, text="COMPOUND TOMORROW", variable=self.dt_compound_var,
                       command=self.dt_toggle_compound, bg=PANEL2, fg=FG,
                       activebackground=PANEL2, activeforeground=FG, selectcolor=DEEP,
                       relief="flat", font=widget_font("Segoe UI", 8, True)).pack(side="left", padx=(8, 12), pady=5)
        tk.Label(options_row, text="UPDATE EVERY (MIN)", bg=PANEL2, fg=MUTED,
                 font=widget_font("Segoe UI", 8, True)).pack(side="left", padx=(4, 4))
        self.dt_update_every_var = tk.StringVar(value=str(int(getattr(E, "UPDATE_EVERY_MIN", 30) or 0)))
        tk.Entry(options_row, textvariable=self.dt_update_every_var, width=5,
                 bg=PANEL, fg=FG, relief="flat", insertbackground=FG,
                 justify="right", font=widget_font("Consolas", 10, True)).pack(side="left", padx=(0, 8), pady=4)
        self.dt_update_voice_var = tk.BooleanVar(value=bool(getattr(E, "UPDATE_VOICE", True)))
        tk.Checkbutton(options_row, text="UPDATE VOICE", variable=self.dt_update_voice_var,
                       bg=PANEL2, fg=FG, activebackground=PANEL2, activeforeground=FG,
                       selectcolor=DEEP, relief="flat", font=widget_font("Segoe UI", 8, True)).pack(side="left", padx=5)
        tk.Label(options_row, text="TARGET REACHED  •  VOICE ALERT ON",
                 bg=PANEL2, fg=CYAN,
                 font=widget_font("Segoe UI", 7, True)).pack(side="left", padx=(8, 4))
        self.dt_update_telegram_var = tk.BooleanVar(value=bool(getattr(E, "UPDATE_TELEGRAM", False)))
        tk.Checkbutton(options_row, text="TELEGRAM UPDATE", variable=self.dt_update_telegram_var,
                       bg=PANEL2, fg=FG, activebackground=PANEL2, activeforeground=FG,
                       selectcolor=DEEP, relief="flat", font=widget_font("Segoe UI", 8, True)).pack(side="left", padx=5)
        ttk.Button(options_row, text="SAVE UPDATE OPTIONS", command=self.dt_save_updates).pack(side="right", padx=8, pady=4)
        self.dt_options_note = tk.Label(options_row, text="", bg=PANEL2, fg=CYAN,
                                        font=widget_font("Segoe UI", 8))
        self.dt_options_note.pack(side="right", padx=8)

        body = tk.Frame(box, bg=PANEL)
        body.pack(fill="both", expand=True, padx=10, pady=(2, 8))
        body.columnconfigure(0, weight=3)
        body.columnconfigure(1, weight=2)
        self.dt_canvas = tk.Canvas(body, bg=DEEP, highlightthickness=0, height=132, bd=0)
        self.dt_canvas.grid(row=0, column=0, sticky="nsew")
        self.dt_canvas.bind("<Configure>", lambda e: self.dt_draw())
        side = tk.Frame(body, bg=DEEP, highlightbackground=LINE, highlightthickness=1)
        side.grid(row=0, column=1, sticky="nsew", padx=(8, 0))
        self.dt_side = tk.Label(side, text="", bg=DEEP, fg=FG, justify="left",
                                anchor="nw", font=widget_font("Consolas", 9), padx=10,
                                pady=8)
        self.dt_side.pack(fill="both", expand=True)
        self.dt_update = tk.Label(box, text="", bg=PANEL, fg=CYAN, anchor="w",
                                  font=widget_font("Consolas", 8), padx=14)
        self.dt_update.pack(fill="x", pady=(0, 3))
        self.dt_voice_report_note = tk.Label(
            box,
            text=L("The spoken update covers today's net result, open P&L, TP/SL/BE outcomes, best trade and source.",
                   "හඬ වාර්තාවට අද ශුද්ධ ප්‍රතිඵලය, විවෘත P&L, ලාභ/පාඩු ප්‍රතිඵල, හොඳම ගනුදෙනුව සහ මූලාශ්‍රය ඇතුළත්."),
            bg=PANEL, fg=MUTED, anchor="w", justify="left", wraplength=1100,
            font=widget_font("Segoe UI", 8))
        self.dt_voice_report_note.pack(fill="x", padx=14, pady=(0, 7))
        self.dt_data = {}
        self.dt_phase = 0.0
        self.dt_last = 0.0
        self.root.after(800, lambda: self.dt_refresh(True))

    def dt_value_now(self) -> str:
        """What belongs in the VALUE box right now (pct or usd)."""
        try:
            mode = str(self.dt_mode.get()).upper()
        except Exception:
            mode = str(getattr(E, "DAILY_TARGET_MODE", "PCT")).upper()
        if mode == "USD":
            return f"{float(getattr(E, 'DAILY_TARGET_USD', 0) or 0):g}"
        return f"{float(getattr(E, 'DAILY_TARGET_PCT', 3) or 0):g}"

    def dt_mode_hint(self):
        """Say what the VALUE box means in this mode."""
        try:
            mode = str(self.dt_mode.get()).upper()
            hint = {"PCT": L("% of the capital, a day", "මුල් මුදලෙන් % - දිනකට"),
                    "USD": L("USD a day (fixed money)", "දිනකට USD (නියමිත මුදල)"),
                    "PLAN": L("from the AI plan (VALUE is not used)",
                              "AI ප්ලෑන් එකෙන් (අගය ඕන නෑ)")}[mode]
            self.dt_set_note.configure(text="   " + hint, fg=MUTED)
        except Exception:
            pass

    def dt_apply(self):
        """v1.9.4: MODE + VALUE + CAPITAL typed by the user -> the daily target."""
        try:
            mode = str(self.dt_mode.get()).upper()
            msg = E.daily_target_apply(mode, self.dt_value.get(),
                                       self.dt_capital.get(), True)
            reload_engine()
            first = " ".join(str(msg).splitlines()[0].split())
            ok = not first.startswith("!!")
            self.dt_set_note.configure(text=first[:110], fg=CYAN if ok else RED)
            q_log(("daily target: " if ok else "daily target NOT saved: ") + first[:150],
                  "info" if ok else "err")
            if ok:
                self.dt_value.set(self.dt_value_now())
                self.dt_refresh(True)
        except Exception as exc:
            self.dt_set_note.configure(text=str(exc)[:110], fg=RED)
            q_log(f"daily target save: {exc}", "err")

    def dt_toggle_on(self):
        """Turn the daily target system itself ON / OFF (the number is kept)."""
        try:
            keep = bool(getattr(E, "DAILY_TARGET_ON", True))
            mode = str(self.dt_mode.get()).upper()
            msg = E.daily_target_apply(mode, self.dt_value_now(),
                                       getattr(E, "DAILY_TARGET_CAPITAL", 0), not keep)
            reload_engine()
            first = " ".join(str(msg).splitlines()[0].split())
            self.dt_set_note.configure(text=first[:110], fg=CYAN)
            q_log("daily target: " + first[:150], "info")
            self.dt_refresh(True)
        except Exception as exc:
            q_log(f"daily target on/off: {exc}", "err")

    # kept for the older buttons / scripts that still call dt_save
    def dt_save(self):
        self.dt_apply()

    def dt_toggle_stop(self):
        try:
            want = not bool(getattr(E, "DAILY_TARGET_STOP_AFTER", False))
            save_settings_file(APP_DIR / "edgequant_auto.py",
                               {"DAILY_TARGET_STOP_AFTER": (want, "bool")})
            reload_engine()
            q_log("daily target: stop-after is now "
                  + ("ON (no new orders once the day is done)" if want else "OFF"),
                  "info")
            self.dt_refresh(True)
        except Exception as exc:
            q_log(f"daily target stop: {exc}", "err")

    def dt_toggle_compound(self):
        try:
            want = bool(self.dt_compound_var.get())
            save_settings_file(APP_DIR / "edgequant_auto.py",
                               {"DAILY_TARGET_COMPOUND": (want, "bool")})
            reload_engine()
            if hasattr(self, "dt_options_note"):
                self.dt_options_note.configure(text="Compound is ON" if want else "Compound is OFF")
            q_log("daily target compounding: " + ("ON" if want else "OFF"), "info")
            self.dt_refresh(True)
        except Exception as exc:
            q_log(f"daily target compound: {exc}", "err")

    def dt_save_updates(self):
        try:
            minutes = int(float(str(self.dt_update_every_var.get()).strip() or "0"))
            if minutes < 0 or minutes > 1440:
                raise ValueError("Update interval must be 0–1440 minutes (0 turns it off).")
            values = {
                "UPDATE_EVERY_MIN": (minutes, "int"),
                "UPDATE_VOICE": (bool(self.dt_update_voice_var.get()), "bool"),
                "UPDATE_TELEGRAM": (bool(self.dt_update_telegram_var.get()), "bool"),
            }
            save_settings_file(APP_DIR / "edgequant_auto.py", values)
            reload_engine()
            self.dt_options_note.configure(text="Update options saved")
            q_log(f"daily target update options saved ({minutes} min)", "info")
        except Exception as exc:
            self.dt_options_note.configure(text=str(exc)[:70], fg=RED)
            q_log(f"daily target update options: {exc}", "err")

    def dt_say_now(self):
        """Read today's report without making a competing MT5/API call."""
        if getattr(self, "_voice_report_busy", False):
            return
        self._voice_report_busy = True
        try:
            self.dt_say_btn.configure(state="disabled")
            self.dt_voice_report_note.configure(
                text=L("Preparing today's spoken report…", "අද හඬ වාර්තාව සකස් කරමින්…"),
                fg=CYAN)
        except Exception:
            pass
        local_task = not bool(self.bot and self.bot.is_alive())
        if local_task:
            self._mt5_ui_tasks = getattr(self, "_mt5_ui_tasks", 0) + 1

        def worker():
            error, report = "", ""
            try:
                if self.bot and self.bot.is_alive():
                    loop = getattr(self.bot, "loop", None)
                    if loop is None or not loop.is_running():
                        raise RuntimeError("The engine loop is not ready; try again shortly.")
                    async def make_report_on_engine_loop():
                        return E.half_hour_update(force=True, speak=True, send=False)
                    future = asyncio.run_coroutine_threadsafe(make_report_on_engine_loop(), loop)
                    report = future.result(timeout=90)
                else:
                    with self._mt5_api_lock:
                        report = E.half_hour_update(force=True, speak=True, send=False)
            except Exception as exc:
                error = f"{type(exc).__name__}: {exc}"
            finally:
                if local_task:
                    self._mt5_ui_tasks = max(0, getattr(self, "_mt5_ui_tasks", 1) - 1)
            RESULT_Q.put(("voice_report", report, error))

        threading.Thread(target=worker, name="edgequant-voice-report", daemon=True).start()

    def _voice_report_playback_check(self, request_id: str, deadline: float):
        """Update the report note only after the worker confirms actual playback."""
        try:
            dispatch = E.voice_last_dispatch("update")
            if str(dispatch.get("id") or "") != str(request_id or ""):
                return  # a newer report replaced this status panel
            state = str(dispatch.get("state") or "unknown")
            if state == "played":
                self.dt_voice_report_note.configure(
                    text=L("The offline Sinhala female report finished playing on this PC.",
                           "දේශීය සිංහල කාන්තා හඬ වාර්තාව වාදනය කර අවසන්."), fg=GREEN)
                return
            if state == "failed":
                error = str(dispatch.get("error") or "voice worker failed")[:100]
                self.dt_voice_report_note.configure(
                    text=L("Offline Sinhala voice failed: " + error,
                           "සිංහල හඬ අසාර්ථකයි: " + error), fg=RED)
                return
            if state == "queued" and time.time() < float(deadline or 0):
                self.root.after(1800, lambda rid=request_id, until=deadline:
                                self._voice_report_playback_check(rid, until))
                return
            if state == "queued":
                self.dt_voice_report_note.configure(
                    text=L("Still queued; playback is not confirmed. Check the voice log.",
                           "තවම පෝලිමේ; වාදනය තහවුරු නැත. හඬ ලොගය බලන්න."), fg=AMBER)
        except Exception:
            pass

    def dt_refresh(self, force: bool = False):
        if time.time() - self.dt_last < (0.15 if force else 1.5):
            return
        self.dt_last = time.time()
        try:
            st = E.daily_target_state()
        except Exception as exc:
            q_log(f"daily target: {exc}", "warn")
            return
        self.dt_data = st
        # v1.9.4: keep the input boxes in step with what the engine really has
        try:
            mode = str(st.get("mode") or getattr(E, "DAILY_TARGET_MODE", "PCT")).upper()
            if mode != str(self.dt_mode.get()).upper():
                self.dt_mode.set(mode)
            if not self.dt_value_entry.focus_get() == self.dt_value_entry:
                self.dt_value.set(self.dt_value_now())
            on = bool(getattr(E, "DAILY_TARGET_ON", True))
            self.dt_on_btn.configure(text=L("TARGET ON", "ටාගට් ON") if on
                                     else L("TARGET OFF", "ටාගට් OFF"))
            if force:
                self.dt_set_note.configure(
                    text="   " + L(f"saved - {mode} mode", f"සේව් - {mode}"), fg=CYAN)
        except Exception:
            pass
        c = st.get("counts") or {}
        if st.get("target", 0) > 0:
            pct_show = max(0.0, min(100.0, float(st.get("done_pct") or 0.0)))
            status = ("TARGET ARCHIVED" if st.get("archived") else
                      "REALIZED PROFIT NEEDED" if st.get("floating_target") else
                      f"{st['remaining']:,.2f} USD left")
            self.dt_note.configure(
                text=(f"{st.get('progress_net', st['net']):+,.2f} / {st['target']:,.2f} USD   "
                      f"{pct_show:.0f}%   {status}"))
        else:
            self.dt_note.configure(text=L("no target set - press SAVE with a %",
                                          "ඉලක්කයක් නෑ - % එකක් දාලා SAVE ඔබන්න"))
        eta = (f"{st['eta_min']} min" if st.get("eta_min") else "-")
        self.dt_side.configure(text=(
            f"capital      {st.get('capital', 0):>12,.2f}\n"
            f"target       {st.get('target', 0):>12,.2f}   ({st.get('mode', 'PCT')})\n"
            f"realized     {st.get('net', 0):>+12,.2f}\n"
            f"floating     {st.get('floating', 0):>+12,.2f}\n"
            f"progress     {st.get('progress_net', st.get('net', 0)):>+12,.2f}\n"
            f"remaining    {st.get('remaining', 0):>12,.2f}\n"
            f"state        {'ARCHIVED' if st.get('archived') else 'IN PROGRESS'}\n"
            f"trades       {c.get('placed', 0):>4} placed   {c.get('filled', 0):>3} hit\n"
            f"TP / SL      {c.get('tp', 0):>4} / {c.get('sl', 0):<3}   "
            f"BE {c.get('be', 0)}   man {c.get('manual', 0)}\n"
            f"pace         {st.get('pace', 0):>+12,.2f}/h   eta {eta}\n"
            f"streak       {st.get('streak', 0):>4} day(s)   "
            f"{'stop-after ON' if st.get('stop_after') else 'keeps trading'}"))
        try:
            self.dt_update.configure(text=self._update_line())
        except Exception:
            pass
        self.dt_draw()

    def dt_draw(self):
        """The modern animated target widget: ring + bar + milestones."""
        c = getattr(self, "dt_canvas", None)
        st = getattr(self, "dt_data", None) or {}
        if c is None:
            return
        try:
            c.delete("all")
            w = max(260, c.winfo_width())
            h = max(110, c.winfo_height())
        except Exception:
            return
        target = float(st.get("target") or 0.0)
        if target <= 0:
            c.create_text(w / 2, h / 2, text=L("set a daily target % and press SAVE",
                                               "දිනකට % එකක් දාලා SAVE ඔබන්න"),
                          fill=MUTED, font=widget_font("Segoe UI", 10))
            return
        pct = float(st.get("done_pct") or 0.0)
        shown = max(0.0, min(100.0, pct))
        done = bool(st.get("archived") or st.get("achieved"))
        floating_goal = bool(st.get("floating_target"))
        col = GOLD if done else (RED if pct < 0 else GREEN)
        # ---- the ring -----------------------------------------------------
        r = min(h - 40.0, 84.0) / 2.0
        cx, cy = r + 26.0, h / 2.0
        for i, a in enumerate(range(0, 360, 12)):
            on = (i / 30.0) * 100.0 <= shown
            if on:
                c.create_arc(cx - r, cy - r, cx + r, cy + r, start=90 + a,
                             extent=10, style="arc", outline=col if not done else GOLD,
                             width=9)
            else:
                c.create_arc(cx - r, cy - r, cx + r, cy + r, start=90 + a,
                             extent=10, style="arc", outline="#1d2635", width=9)
        pulse = 1.0 + 0.06 * math.sin(self.dt_phase * 2.0)
        ring_pct = 100.0 if done else shown
        c.create_text(cx, cy - 4, text=f"{ring_pct:,.0f}%",
                      fill=GOLD if done else (RED if pct < 0 else FG),
                      font=widget_font("Consolas", int(20 * pulse) + 1, True))
        c.create_text(cx, cy + 15, text=L("of the target", "ඉලක්කයෙන්"), fill=MUTED,
                      font=widget_font("Segoe UI", 7))
        # ---- the bar + numbers -------------------------------------------
        x0 = cx + r + 26.0
        bw = max(80.0, w - x0 - 22.0)
        by = cy - 34.0
        c.create_rectangle(x0, by, x0 + bw, by + 20, fill="#141b27", outline=LINE)
        frac = shown / 100.0
        if frac > 0:
            c.create_rectangle(x0, by, x0 + bw * frac, by + 20, fill=col, outline=col)
            sh = (self.dt_phase * 0.5) % 1.0
            sx = x0 + bw * frac * sh
            c.create_rectangle(sx, by, min(x0 + bw * frac, sx + 14), by + 20,
                               fill="#ffffff", outline="", stipple="gray50")
        c.create_text(x0 + bw / 2, by + 10,
                      text=f"{float(st.get('progress_net', st.get('net')) or 0):+,.2f} / {target:,.2f} USD",
                      fill="#0f141c" if frac > 0.45 else FG,
                      font=widget_font("Consolas", 9, True))
        # ---- the milestone dots ------------------------------------------
        hit = set(st.get("hit") or [])
        mx = x0
        for m in (st.get("milestones") or (25, 50, 75, 100)):
            on = (m in hit) or shown >= m
            X = x0 + bw * min(1.0, m / 100.0)
            c.create_oval(X - 5, by + 26, X + 5, by + 36,
                          fill=GOLD if on else "#1d2635", outline="")
            c.create_text(X, by + 48, text=f"{m}%", fill=GOLD if on else MUTED,
                          font=widget_font("Consolas", 7))
        # ---- the status line ---------------------------------------------
        if done:
            glow = 0.5 + 0.5 * math.sin(self.dt_phase * 3.0)
            c.create_text(x0, by + 66,
                          text=L("TARGET ARCHIVED  -  READY FOR TOMORROW",
                                 "ඉලක්කය සංරක්ෂිතයි  -  හෙටට සූදානම්"),
                          fill=GOLD, font=widget_font("Segoe UI", 10, True), anchor="w")
            for i in range(6):
                a = (self.dt_phase * 1.2 + i * 0.9) % 1.0
                X = x0 + bw * a
                Y = by + 66 - 9 - 6 * abs(math.sin(a * 6.28))
                c.create_oval(X - 2, Y - 2, X + 2, Y + 2,
                              fill=GOLD if glow > 0.5 else GREEN, outline="")
        elif floating_goal:
            c.create_text(x0, by + 66,
                          text=L("TARGET IN RANGE - floating P/L; realized profit archives it",
                                 "ඉලක්කය පෙනෙයි - floating P/L; realized වූ පසු සංරක්ෂණය වේ"),
                          fill=AMBER, font=widget_font("Segoe UI", 9, True), anchor="w")
        else:
            c.create_text(x0, by + 66,
                          text=(L("still to go: ", "තව ඕන: ")
                                + f"{float(st.get('remaining') or 0):,.2f} USD   "
                                + (f"~{st.get('eta_min')} min at this pace"
                                   if st.get("eta_min") else
                                   L("no pace yet today", "අද තාම වේගයක් නෑ"))),
                          fill=FG, font=widget_font("Segoe UI", 9), anchor="w")
        self.dt_phase += 0.14

    def dt_animate(self):
        if not hasattr(self, "dt_canvas"):
            return
        try:
            self.dt_draw()
        except Exception:
            pass

    def _build_flow_board(self, parent, row=7):
        """Every TP / SL / BE that happened - channel-wise, animated, live."""
        box = tk.Frame(parent, bg=PANEL, highlightbackground=CYAN, highlightthickness=1)
        box.grid(row=row, column=0, columnspan=4, sticky="nsew", padx=6, pady=(2, 6))
        head = tk.Frame(box, bg=PANEL)
        head.pack(fill="x", padx=14, pady=(8, 0))
        tk.Label(head, text=L("LIVE PROFIT FLOW   (animated - channel by channel)",
                              "ලයිව් ප්‍රොෆිට් ෆ්ලෝ   (චැනල් අනුව - දිවෙන)"),
                 bg=PANEL, fg=CYAN, font=widget_font("Segoe UI", 10, True)).pack(side="left")
        self.fl_best = tk.Label(head, text="", bg=PANEL, fg=GOLD,
                                font=widget_font("Consolas", 9, True))
        self.fl_best.pack(side="right")
        self.fl_period = tk.StringVar(value="today")
        for key, en, si in reversed((("today", "TODAY", "අද"), ("week", "WEEK", "සතිය"),
                                     ("month", "MONTH", "මාසය"),
                                     ("all", "ALL", "සියල්ල"))):
            tk.Button(head, text=L(en, si), relief="flat", bd=0, padx=10, pady=1,
                      bg=PANEL2, fg=FG, activebackground=CYAN, activeforeground="#101010",
                      font=widget_font("Segoe UI", 8, True),
                      command=lambda k=key: self.fl_set(k)).pack(side="right", padx=2)

        body = tk.Frame(box, bg=PANEL)
        body.pack(fill="both", expand=True, padx=10, pady=(4, 8))
        body.columnconfigure(0, weight=3)
        body.columnconfigure(1, weight=2)
        self.fl_canvas = tk.Canvas(body, bg=DEEP, highlightthickness=0, height=150, bd=0)
        self.fl_canvas.grid(row=0, column=0, sticky="nsew")
        self.fl_canvas.bind("<Configure>", lambda e: self.fl_draw())
        side = tk.Frame(body, bg=DEEP, highlightbackground=LINE, highlightthickness=1)
        side.grid(row=0, column=1, sticky="nsew", padx=(8, 0))
        self.fl_side = tk.Frame(side, bg=DEEP)
        self.fl_side.pack(fill="both", expand=True, padx=10, pady=6)
        self.fl_title = tk.Label(self.fl_side,
                                 text=L("CHANNEL FLOW   (who is paying today)",
                                        "චැනල් ෆ්ලෝ   (අද සල්ලි දෙන කෙනා)"),
                                 bg=DEEP, fg=GOLD, anchor="w",
                                 font=widget_font("Segoe UI", 9, True))
        self.fl_title.pack(fill="x")
        self.fl_rows = tk.Label(self.fl_side, text="", bg=DEEP, fg=FG, justify="left",
                                anchor="w", font=widget_font("Consolas", 9))
        self.fl_rows.pack(fill="x", pady=(4, 0))
        self.fl_phase = 0.0
        self.fl_data = []
        self.fl_last = 0.0
        self.root.after(900, lambda: self.fl_refresh(True))

    def fl_set(self, key: str):
        self.fl_period.set(key if key in ("today", "week", "month", "all") else "today")
        self.fl_refresh(True)

    def fl_refresh(self, force: bool = False):
        if time.time() - self.fl_last < (0.4 if force else 4.0):
            return
        self.fl_last = time.time()
        try:
            st = E.stream_board_stats(self.fl_period.get())
            self.fl_data = st["rows"]
            best = st.get("best")
        except Exception as exc:
            self.fl_data, best = [], None
            q_log(f"profit flow: {exc}", "warn")
        if best:
            self.fl_best.configure(
                text=(f"BEST TP  {best['best_symbol']}  {best['best_pips']:+.0f} pips"
                      f"  ({best['best_usd']:+.2f} USD)  -  {best['channel'][:22]}"))
        else:
            self.fl_best.configure(text=L("no closed trades in this period yet",
                                          "මේ කාලයේ වැහුණු ට්‍රේඩ්ස් නෑ"))
        self._fl_side()
        self.fl_draw()

    def _fl_side(self):
        rows = self.fl_data[:9]
        if not rows:
            self.fl_rows.configure(
                text=L("the list fills up as trades close", "ට්‍රේඩ් වැහෙන කොට පිරෙනවා"))
            return
        tot = {"tp": 0, "sl": 0, "be": 0, "manual": 0, "usd": 0.0}
        for r in self.fl_data:
            for k in ("tp", "sl", "be", "manual"):
                tot[k] += int(r.get(k) or 0)
            tot["usd"] += float(r.get("usd") or 0.0)
        head = (f"{L('TOTAL', 'මුළු'):<7} {tot['tp']:>3}TP {tot['sl']:>3}SL "
                f"{tot['be']:>3}BE {tot['manual']:>3}MAN   {tot['usd']:>+9.2f}"
                f"\n" + "-" * 46 + "\n")
        out = []
        for r in rows:
            emo = "\u25B2" if r["usd"] >= 0 else "\u25BC"
            out.append(f"{emo} {r['channel'][:20]:<20} "
                       f"{r['tp']:>2}TP {r['sl']:>2}SL {r['be']:>2}BE  "
                       f"{r['usd']:>+9.2f}")
        self.fl_rows.configure(text=head + "\n".join(out))

    def fl_draw(self):
        """One frame: a bar per channel + an event ticker that slides."""
        c = self.fl_canvas
        try:
            c.delete("all")
            w = max(240, c.winfo_width())
            h = max(110, c.winfo_height())
        except Exception:
            return
        rows = list(self.fl_data or [])
        if not rows:
            c.create_text(w / 2, h / 2, text=L("no events yet today",
                                               "අද තාම සිදුවීම් නෑ"),
                          fill=MUTED, font=widget_font("Segoe UI", 10))
            return
        top = max(abs(float(r["usd"])) for r in rows) or 1.0
        n = len(rows)
        gap = 10
        bw = max(34.0, min(96.0, (w - 20 - gap * (n - 1)) / float(n)))
        total = bw * n + gap * (n - 1)
        x0 = (w - total) / 2.0
        base = h - 26.0
        span = max(20.0, base - 34.0)
        c.create_line(x0 - 6, base, x0 + total + 6, base, fill=LINE, width=2)
        for i, r in enumerate(rows):
            usd = float(r["usd"])
            x = x0 + i * (bw + gap)
            pulse = 0.88 + 0.12 * math.sin(self.fl_phase * 2.4 + i * 0.7)
            bh = max(6.0, (abs(usd) / top) * span * pulse)
            y = base - bh
            col = GREEN if usd >= 0 else RED
            c.create_rectangle(x, y, x + bw, base, fill=col, outline=col)
            c.create_text(x + bw / 2, y - 9, text=f"{usd:+.1f}", fill=FG,
                          font=widget_font("Consolas", 8, True))
            c.create_text(x + bw / 2, base + 8, text=str(r["channel"])[:12],
                          fill=GOLD if i == 0 else MUTED,
                          font=widget_font("Segoe UI", 7, True))
            c.create_text(x + bw / 2, base + 19,
                          text=f"{r['tp']}TP/{r['sl']}SL/{r['be']}BE",
                          fill=MUTED, font=widget_font("Consolas", 7))
            if r.get("last_kind"):
                c.create_text(x + bw / 2, max(8, y - 21),
                              text=str(r["last_kind"]).upper(), fill=CYAN,
                              font=widget_font("Segoe UI", 7, True))
        sx = x0 + ((self.fl_phase * 0.34) % 1.0) * total
        c.create_line(sx, 6, sx, base, fill=CYAN, dash=(3, 5))

    def fl_animate(self):
        if not hasattr(self, "fl_canvas"):
            return
        self.fl_phase += 0.16
        try:
            self.fl_draw()
        except Exception:
            pass

    def _studio_scroll_page(self, parent, key):
        """A responsive, mouse-wheel scroll surface for the Telegram Studio forms."""
        outer = ttk.Frame(parent, style="Panel.TFrame")
        outer.pack(fill="both", expand=True)
        canvas = tk.Canvas(outer, bg=PANEL, highlightthickness=0, bd=0)
        vsb = ttk.Scrollbar(outer, orient="vertical", command=canvas.yview)
        canvas.configure(yscrollcommand=vsb.set)
        vsb.pack(side="right", fill="y")
        canvas.pack(side="left", fill="both", expand=True)
        body = tk.Frame(canvas, bg=PANEL)
        win = canvas.create_window((0, 0), window=body, anchor="nw")
        body.bind("<Configure>", lambda e: canvas.configure(scrollregion=canvas.bbox("all")))
        canvas.bind("<Configure>", lambda e: canvas.itemconfigure(win, width=e.width))
        self._studio_scroll_canvases = getattr(self, "_studio_scroll_canvases", {})
        self._studio_scroll_canvases[key] = canvas
        self._wheel_canvases[str(self.tab_studio)] = canvas
        canvas.bind("<Enter>", lambda e, c=canvas: self._wheel_canvases.__setitem__(
            str(self.tab_studio), c))
        return body, canvas

    def _studio_merge_chats(self, incoming=(), include_owned=True):
        by_id = {}
        candidates = list(incoming or [])
        if include_owned:
            candidates += list(self.owned_chats or [])
        owned_ids = set()
        for owned in (self.owned_chats or []):
            try:
                owned_ids.add(int(owned.get("id")))
            except Exception:
                pass
        account_managed = {}
        for account_row in (getattr(self, "studio_joined_chats", []) or []):
            try:
                account_managed[int(account_row.get("id"))] = dict(account_row)
            except Exception:
                pass
        for row in candidates:
            if not isinstance(row, dict):
                continue
            try:
                cid = int(row.get("id"))
            except Exception:
                continue
            name = fix_text(str(row.get("name") or "")).strip()
            if not name:
                continue
            clean = dict(row)
            account_row = account_managed.get(cid) or {}
            access = str(row.get("access") or account_row.get("access") or "").upper()
            if bool(row.get("owned") or account_row.get("owned")):
                access = "OWNED"
            elif bool(row.get("admin") or account_row.get("admin")) and access not in ("OWNED",):
                access = "ADMIN"
            elif cid in owned_ids and not access:
                access = "OWNED"
            if access not in ("OWNED", "ADMIN", "JOINED", "READ ONLY"):
                access = "JOINED"
            clean.update({"id": cid, "name": name,
                          "kind": str(row.get("kind") or "GROUP").upper(),
                          "access": access, "created_by_user": cid in owned_ids,
                          "owned": bool(row.get("owned") or account_row.get("owned") or cid in owned_ids),
                          "admin": bool(row.get("admin") or account_row.get("admin") or cid in owned_ids),
                          "can_post": row.get("can_post", account_row.get("can_post", True))})
            if cid in by_id:
                previous = by_id[cid]
                for key, value in clean.items():
                    if value not in (None, ""):
                        previous[key] = value
                previous["created_by_user"] = cid in owned_ids
            else:
                by_id[cid] = clean
        rows = list(by_id.values())
        rows.sort(key=lambda x: (x["name"].casefold(), x["id"]))
        self.studio_chats = rows
        self._studio_sync_targets()
        self._studio_draw_destination_directory()
        self._studio_refresh_provider_report_destinations()
        return rows

    def _studio_favorite_ids(self):
        ids = set()
        for row in (getattr(self, "studio_favorites", []) or []):
            try:
                ids.add(int(row.get("id")))
            except Exception:
                continue
        return ids

    def _studio_destination_search_changed(self, *_):
        self._studio_sync_targets()
        self._studio_draw_destination_directory()

    def _studio_favorites_filter_changed(self):
        """Favorites-only is a true destination filter; hide and deselect other chats."""
        try:
            enabled = bool(self.studio_favorites_only_var.get())
        except Exception:
            enabled = False
        if enabled:
            fav_ids = self._studio_favorite_ids()
            self._studio_selected_destination_ids = {
                int(cid) for cid in (getattr(self, "_studio_selected_destination_ids", set()) or set())
                if int(cid) in fav_ids
            }
        self._studio_sync_targets()
        self._studio_publish_selection_changed()

    def _studio_draw_destination_directory(self):
        created_tree = getattr(self, "studio_created_tree", None)
        joined_tree = getattr(self, "studio_joined_tree", None)
        if created_tree is None and joined_tree is None:
            return
        search_var = getattr(self, "studio_destination_search_var", None)
        query = str(search_var.get() if search_var is not None else "").strip().casefold()
        all_rows = {int(r.get("id")): r for r in (getattr(self, "studio_chats", []) or [])
                    if isinstance(r, dict) and str(r.get("id", "")).lstrip("-").isdigit()}
        own_ids = {int(r.get("id")) for r in (getattr(self, "owned_chats", []) or [])
                   if isinstance(r, dict) and str(r.get("id", "")).lstrip("-").isdigit()}
        own_ids.update(int(r.get("id")) for r in (getattr(self, "studio_joined_chats", []) or [])
                       if isinstance(r, dict) and str(r.get("id", "")).lstrip("-").isdigit()
                       and (bool(r.get("owned") or r.get("admin")) or
                            str(r.get("access") or "").upper() in ("OWNED", "ADMIN")))
        fav_ids = self._studio_favorite_ids()

        def matches(row):
            haystack = " ".join(str(row.get(k) or "") for k in ("name", "username", "id", "kind")).casefold()
            return not query or query in haystack

        def fill(tree, rows):
            if tree is None:
                return
            try:
                children = tree.get_children()
                if children:
                    tree.delete(*children)
                for row in rows:
                    if not matches(row):
                        continue
                    cid = int(row.get("id"))
                    iid = ("created_" if cid in own_ids else "joined_") + str(cid)
                    username = "@" + str(row.get("username")) if row.get("username") else "—"
                    access = str(row.get("access") or ("OWNED" if cid in own_ids else "JOINED"))
                    tree.insert("", "end", iid=iid, values=(row.get("kind", "GROUP"),
                                access, row.get("name", ""), cid, username,
                                "★" if cid in fav_ids else "—"))
            except Exception as exc:
                q_log(f"Provider destination directory refresh: {exc}", "warn")

        created = [all_rows[cid] for cid in sorted(own_ids) if cid in all_rows]
        joined_ids = set()
        for row in (getattr(self, "studio_joined_chats", []) or []):
            try:
                joined_ids.add(int(row.get("id")))
            except Exception:
                pass
        joined = [all_rows[cid] for cid in sorted(joined_ids) if cid in all_rows and cid not in own_ids]
        fill(created_tree, created)
        fill(joined_tree, joined)

    def _studio_directory_select(self, event=None):
        tree = getattr(event, "widget", None) if event is not None else None
        if tree is None:
            return
        try:
            selected = tree.selection()
            if not selected:
                return
            cid = int(tree.set(selected[0], "id"))
            row = next((r for r in (self.studio_chats or []) if int(r.get("id")) == cid), None)
            if row:
                self.studio_target_var.set(self._studio_chat_label(row))
                self.studio_link_var.set(str(row.get("link") or ""))
        except Exception:
            pass

    def _studio_add_directory_to_publish(self):
        """Add explicitly highlighted owned/joined destinations to the recipient list."""
        selected_ids = set(getattr(self, "_studio_selected_destination_ids", set()) or set())
        found = []
        for attr in ("studio_created_tree", "studio_joined_tree"):
            tree = getattr(self, attr, None)
            if tree is None:
                continue
            try:
                for iid in tree.selection():
                    cid = int(tree.set(iid, "id"))
                    if cid not in selected_ids:
                        selected_ids.add(cid)
                    found.append(cid)
            except Exception:
                continue
        if not found:
            try:
                self.studio_members_status.configure(
                    text=L("Select one or more rows in the owned/joined directory first.",
                           "පළමුව owned/joined directory එකෙන් row එකක් හෝ කිහිපයක් තෝරන්න."), fg=AMBER)
            except Exception:
                pass
            return
        try:
            if getattr(self, "studio_favorites_only_var", None) is not None:
                self.studio_favorites_only_var.set(False)
        except Exception:
            pass
        self._studio_selected_destination_ids = selected_ids
        self._studio_sync_targets()
        self._studio_publish_selection_changed()
        try:
            rows = self._studio_selected_publish_chats()
            self.studio_members_status.configure(
                text=L(f"{len(rows)} recipient(s) selected. These are used by the signal, post/poll, and mirror tools.",
                       f"Recipients {len(rows)}ක් තෝරා ඇත. Signal, post/poll සහ mirror මෙවලම් ඒවා භාවිතා කරයි."),
                fg=GREEN)
        except Exception:
            pass

    def _studio_toggle_directory_favorite(self):
        selected_row = None
        for attr in ("studio_created_tree", "studio_joined_tree"):
            tree = getattr(self, attr, None)
            if tree is None:
                continue
            try:
                selection = tree.selection()
                if selection:
                    cid = int(tree.set(selection[0], "id"))
                    selected_row = next((dict(r) for r in (self.studio_chats or [])
                                         if int(r.get("id")) == cid), None)
                    if selected_row:
                        break
            except Exception:
                continue
        if not selected_row:
            try:
                self.studio_members_status.configure(text="Select one owned or joined destination first.", fg=AMBER)
            except Exception:
                pass
            return
        cid = int(selected_row["id"])
        favorites = list(getattr(self, "studio_favorites", []) or [])
        found = any(int(x.get("id")) == cid for x in favorites if str(x.get("id", "")).lstrip("-").isdigit())
        if found:
            self.studio_favorites = [x for x in favorites
                                     if not (str(x.get("id")) == str(cid))]
            note = f"Removed {selected_row.get('name')} from favorites."
        else:
            self.studio_favorites.append({k: selected_row.get(k) for k in
                                          ("id", "name", "kind", "username", "link")})
            note = f"Added {selected_row.get('name')} to favorites."
        save_ui_prefs(studio_favorites=self.studio_favorites)
        self._studio_sync_targets()
        try:
            self.studio_members_status.configure(text=note, fg=GREEN)
        except Exception:
            pass

    @staticmethod
    def _studio_chat_label(row):
        kind = "CHANNEL" if str(row.get("kind", "")).upper() == "CHANNEL" else "GROUP"
        access = str(row.get("access") or ("OWNED" if row.get("created_by_user") else "JOINED")).upper()
        if not row.get("can_post", True):
            access += " · READ ONLY"
        return f"{access}  |  {kind}  |  {row.get('name', 'Telegram chat')}  |  {row.get('id', '')}"

    def _studio_sync_targets(self):
        previous_map = dict(getattr(self, "_studio_choice_map", {}) or {})
        selected_ids = set(getattr(self, "_studio_selected_destination_ids", set()) or set())
        targets = getattr(self, "signal_targets_list", None)
        if targets is not None:
            try:
                for index in targets.curselection():
                    row = previous_map.get(targets.get(index))
                    if row:
                        selected_ids.add(int(row.get("id")))
            except Exception:
                pass
        query_var = getattr(self, "studio_destination_search_var", None)
        query = str(query_var.get() if query_var is not None else "").strip().casefold()
        favorites_only_var = getattr(self, "studio_favorites_only_var", None)
        favorites_only = bool(favorites_only_var.get()) if favorites_only_var is not None else False
        favorite_ids = self._studio_favorite_ids() if favorites_only else set()
        all_rows = [r for r in (getattr(self, "studio_chats", []) or []) if isinstance(r, dict)]
        filtered = []
        for row in all_rows:
            try:
                chat_id = int(row.get("id"))
            except Exception:
                continue
            if favorites_only and chat_id not in favorite_ids:
                continue
            haystack = " ".join(str(row.get(k) or "") for k in ("name", "username", "id", "kind")).casefold()
            if not query or query in haystack:
                filtered.append(row)
        self._studio_choice_map = {}
        values = []
        for row in filtered:
            label = self._studio_chat_label(row)
            if label in self._studio_choice_map:
                continue
            self._studio_choice_map[label] = row
            values.append(label)
        self._studio_selected_destination_ids = selected_ids
        combo = getattr(self, "studio_target_combo", None)
        var = getattr(self, "studio_target_var", None)
        if combo is not None and var is not None:
            try:
                combo.configure(values=values)
                current = var.get()
                if current not in values:
                    var.set(values[0] if values else "")
            except Exception:
                pass
        if targets is not None:
            try:
                targets.delete(0, "end")
                for index, label in enumerate(values):
                    targets.insert("end", label)
                    row = self._studio_choice_map.get(label) or {}
                    if int(row.get("id", 0) or 0) in selected_ids:
                        targets.selection_set(index)
            except Exception:
                pass
            self._studio_publish_selection_changed()
        fav_list = getattr(self, "studio_favorites_list", None)
        if fav_list is not None:
            try:
                fav_list.delete(0, "end")
                self._studio_favorite_choice_map = {}
                row_by_id = {int(r.get("id")): r for r in all_rows
                             if str(r.get("id", "")).lstrip("-").isdigit()}
                favorite_rows = []
                for favorite in (getattr(self, "studio_favorites", []) or []):
                    try:
                        cid = int(favorite.get("id"))
                    except Exception:
                        continue
                    row = dict(row_by_id.get(cid) or favorite)
                    if not row.get("name"):
                        continue
                    label = "★  " + self._studio_chat_label(row)
                    if label in self._studio_favorite_choice_map:
                        continue
                    self._studio_favorite_choice_map[label] = row
                    favorite_rows.append((label, row))
                favorite_rows.sort(key=lambda item: str(item[1].get("name", "")).casefold())
                self._studio_favorite_choice_map = {}
                for label, row in favorite_rows:
                    fav_list.insert("end", label)
                    self._studio_favorite_choice_map[label] = row
            except Exception:
                pass
        self._studio_draw_destination_directory()

    def _studio_selected_publish_chats(self):
        selected_ids = set(getattr(self, "_studio_selected_destination_ids", set()) or set())
        targets = getattr(self, "signal_targets_list", None)
        if targets is not None:
            try:
                for index in targets.curselection():
                    row = (getattr(self, "_studio_choice_map", {}) or {}).get(targets.get(index))
                    if row:
                        selected_ids.add(int(row.get("id")))
            except Exception:
                pass
        rows_by_id = {int(r.get("id")): r for r in (getattr(self, "studio_chats", []) or [])
                      if isinstance(r, dict) and str(r.get("id", "")).lstrip("-").isdigit()}
        self._studio_selected_destination_ids = selected_ids
        return [rows_by_id[cid] for cid in sorted(selected_ids) if cid in rows_by_id]

    def _studio_publish_selection_changed(self, *_):
        label = getattr(self, "signal_targets_note", None)
        targets = getattr(self, "signal_targets_list", None)
        if targets is not None:
            try:
                visible_ids = set()
                selected_visible = set()
                for index in range(targets.size()):
                    row = (getattr(self, "_studio_choice_map", {}) or {}).get(targets.get(index))
                    if row:
                        cid = int(row.get("id"))
                        visible_ids.add(cid)
                        if index in set(targets.curselection()):
                            selected_visible.add(cid)
                hidden_selected = set(getattr(self, "_studio_selected_destination_ids", set()) or set()) - visible_ids
                self._studio_selected_destination_ids = hidden_selected | selected_visible
            except Exception:
                pass
        if label is not None:
            try:
                rows = self._studio_selected_publish_chats()
                label.configure(text=(L(f"{len(rows)} destination(s) selected — the signal is published to each; "
                                        "local processing, if selected, runs once.",
                                        f"Destinations {len(rows)}ක් තෝරා ඇත — signal එක ඒ සියල්ලට යවයි; "
                                        "local processing තෝරා තිබුණොත් එක් වරක් පමණයි.") if rows else
                                      L("No destinations selected. Use Ctrl/Shift to choose one or more.",
                                        "Destinations තෝරා නැහැ. එකක් හෝ කිහිපයක් තෝරාගන්න Ctrl/Shift භාවිතා කරන්න.")),
                                fg=CYAN if rows else MUTED)
            except Exception:
                pass
        try:
            self._studio_community_targets_refresh()
        except Exception:
            pass
        self._studio_manual_mirror_selection_changed()

    def _studio_manual_mirror_selection_changed(self):
        if not getattr(self, "_studio_manual_mirror_enabled", False):
            return
        try:
            selected = self._studio_selected_publish_chats()
            selected_ids = {int(row.get("id")) for row in selected}
            captured = list(getattr(self, "_studio_manual_mirror_targets", []) or [])
            captured_ids = {int(row.get("id")) for row in captured}
            if selected_ids == captured_ids:
                names = ", ".join(str(row.get("name") or row.get("id")) for row in captured[:6])
                if len(captured) > 6:
                    names += f" +{len(captured)-6} more"
                note = L(f"ON · mirroring new magic=0 orders to the selected destinations: {names}",
                         f"ON · නව magic=0 orders තෝරාගත් destinations වෙත යවයි: {names}")
                color = CYAN
            else:
                note = L("ON · recipients are fixed to the destinations captured when enabled. "
                         "Current Signal Composer selection differs; turn the mirror OFF, select the new recipients, then re-enable.",
                         "ON · mirror ON කළ අවස්ථාවේ destinations ස්ථිරයි. දැන් Signal Composer තේරීම වෙනස්; mirror OFF කර නව recipients තෝරා නැවත ON කරන්න.")
                color = AMBER
            self.studio_manual_mirror_status_var.set(note)
            self.studio_manual_mirror_status.configure(fg=color)
        except Exception:
            pass

    def _studio_select_favorites_for_publish(self):
        favorite_list = getattr(self, "studio_favorites_list", None)
        if favorite_list is None:
            return
        selected = set(getattr(self, "_studio_selected_destination_ids", set()) or set())
        try:
            for index in favorite_list.curselection():
                row = (getattr(self, "_studio_favorite_choice_map", {}) or {}).get(favorite_list.get(index))
                if row:
                    selected.add(int(row.get("id")))
        except Exception:
            pass
        self._studio_selected_destination_ids = selected
        self._studio_sync_targets()
        self._studio_publish_selection_changed()

    def _studio_clear_publish_selection(self):
        self._studio_selected_destination_ids = set()
        targets = getattr(self, "signal_targets_list", None)
        if targets is not None:
            try:
                targets.selection_clear(0, "end")
            except Exception:
                pass
        self._studio_publish_selection_changed()

    def _studio_selected_chat(self, var_name="studio_target_var"):
        var = getattr(self, var_name, None)
        label = var.get() if var is not None else ""
        return (getattr(self, "_studio_choice_map", {}) or {}).get(label)

    def _studio_run_async(self, label, async_fn, args=(), status=None, buttons=(),
                          on_success=None, timeout=300.0, on_error=None):
        """Run Studio work on the existing bot loop or an isolated stopped-bot login loop."""
        def set_status(text, color):
            if status is None:
                return
            try:
                textvariable = str(status.cget("textvariable") or "")
                if textvariable:
                    status.setvar(textvariable, text)
                else:
                    status.configure(text=text)
                status.configure(fg=color)
            except Exception:
                pass
        if self._studio_busy:
            set_status("Another Telegram Studio action is still running.", AMBER)
            return
        try:
            login_win = self._tg_login_window
            if login_win is not None and login_win.winfo_exists():
                raise RuntimeError("Close the pending Telegram LOGIN dialog before using Studio.")
        except AttributeError:
            pass
        login_client = getattr(E, "_login_client", None)
        try:
            if login_client is not None and login_client.is_connected():
                raise RuntimeError("Finish or close Telegram LOGIN first; its client uses this session file.")
        except AttributeError:
            pass
        self._studio_busy = True
        old_states = []
        for widget in buttons or ():
            try:
                old_states.append((widget, widget.cget("state")))
                widget.configure(state="disabled")
            except Exception:
                pass
        set_status(f"{label}…", AMBER)

        def worker():
            result, error = None, None
            try:
                if self.bot and self.bot.is_alive():
                    loop = getattr(self.bot, "loop", None)
                    client = CLIENT_BOX.get("client")
                    if loop is None or not loop.is_running() or client is None:
                        raise RuntimeError("The bot's Telegram client is still connecting; wait and retry.")
                    future = asyncio.run_coroutine_threadsafe(
                        async_fn(*args, client=client), loop)
                    try:
                        result = future.result(timeout=max(30.0, float(timeout)))
                    except TimeoutError:
                        future.cancel()
                        raise TimeoutError(f"{label} timed out after {timeout:g}s")
                else:
                    if not E.tg_session_exists():
                        raise RuntimeError("Telegram is not logged in in this folder. Press LOGIN first.")
                    lock = E.acquire_singleton()
                    if lock is None:
                        raise RuntimeError("Another EdgeQuant window/bot is using Telegram. Close it, then retry.")
                    try:
                        result = _run_tg_login_coro(async_fn(*args), timeout=timeout)
                    finally:
                        E.release_singleton()
            except Exception as exc:
                error = f"{type(exc).__name__}: {exc}"
            try:
                self.root.after(0, lambda: finish(result, error))
            except Exception:
                pass

        def finish(result, error):
            self._studio_busy = False
            for widget, state in old_states:
                try:
                    if widget.winfo_exists():
                        widget.configure(state=state)
                except Exception:
                    pass
            if status is not None:
                try:
                    if not status.winfo_exists():
                        return
                except Exception:
                    return
            if error:
                set_status(f"{label} failed: {error}", RED)
                q_log(f"Telegram Studio {label.lower()} failed: {error}", "err")
                if on_error is not None:
                    try:
                        on_error(error)
                    except Exception as callback_exc:
                        q_log(f"Telegram Studio error callback failed: {callback_exc}", "err")
                return
            try:
                if on_success is not None:
                    on_success(result)
            except Exception as exc:
                set_status(f"{label} completed, but the UI update failed: {exc}", AMBER)
                q_log(f"Telegram Studio UI update failed: {exc}", "err")

        threading.Thread(target=worker, name="edgequant-studio", daemon=True).start()

    def studio_refresh_targets(self):
        status = getattr(self, "studio_create_status", None) or getattr(self, "studio_members_status", None)
        buttons = [getattr(self, "studio_refresh_btn", None),
                   getattr(self, "signal_refresh_btn", None)]
        buttons = [b for b in buttons if b is not None]

        def done(rows):
            self.studio_joined_chats = [dict(x) for x in (rows or []) if isinstance(x, dict)]
            merged = self._studio_merge_chats(rows or [], include_owned=True)
            managed = sum(1 for row in self.studio_joined_chats
                          if bool(row.get("owned") or row.get("admin")) or
                          str(row.get("access") or "").upper() in ("OWNED", "ADMIN"))
            joined = max(0, len(self.studio_joined_chats) - managed)
            note = L(f"Loaded {len(self.studio_joined_chats)} account destinations: {managed} owned/admin, "
                     f"{joined} joined; {len(self.owned_chats)} locally saved destination(s). "
                     "Select rows and press ADD SELECTED TO RECIPIENTS.",
                     f"Account destinations {len(self.studio_joined_chats)}ක් ලබාගත්තා: owned/admin {managed}ක්, "
                     f"joined {joined}ක්; local saved destinations {len(self.owned_chats)}ක්. "
                     "Rows තෝරා ADD SELECTED TO RECIPIENTS ඔබන්න.")
            if status is not None:
                status.configure(text=note, fg=GREEN)
            q_log("Telegram Studio destination list refreshed (dialog metadata only)", "ok")

        self._studio_run_async("Refreshing destinations",
                               E.telegram_studio_list_chats, status=status,
                               buttons=buttons, on_success=done)

    def _studio_username_touched(self, *_):
        if not getattr(self, "_studio_username_autofilling", False):
            self._studio_username_manual = True

    def _studio_suggest_username(self, *_):
        try:
            is_public = str(self.studio_visibility_var.get()).upper() == "PUBLIC"
            entry_widget = getattr(self, "studio_username_entry", None)
            if entry_widget is not None:
                entry_widget.configure(state="normal" if is_public else "disabled")
            if not is_public:
                self._studio_username_manual = False
                self._studio_username_autofilling = True
                self.studio_username_var.set("")
                return
            if self._studio_username_manual:
                return
            value = E.telegram_studio_username_suggestion(self.studio_name_var.get())
            self._studio_username_autofilling = True
            self.studio_username_var.set(value)
        finally:
            self._studio_username_autofilling = False

    def studio_create_chat(self):
        title = self.studio_name_var.get().strip()
        kind = self.studio_kind_var.get().upper().strip()
        visibility = self.studio_visibility_var.get().upper().strip()
        username = self.studio_username_var.get().strip()
        if visibility == "PUBLIC" and not username:
            username = E.telegram_studio_username_suggestion(title)
            self.studio_username_var.set(username)
        about = self.studio_about_var.get().strip()
        if not title:
            self.studio_create_status.configure(text="Enter a group/channel name first.", fg=AMBER)
            return
        buttons = [self.studio_create_btn, self.studio_refresh_btn]

        def done(row):
            if not isinstance(row, dict):
                raise RuntimeError("Telegram returned no chat details.")
            self.owned_chats = [x for x in self.owned_chats
                                if str(x.get("id")) != str(row.get("id"))]
            self.owned_chats.append(dict(row))
            save_ui_prefs(studio_chats=self.owned_chats)
            self._studio_merge_chats([row])
            created_label = self._studio_chat_label(row)
            self.studio_target_var.set(created_label)
            self.sig_target_var.set(created_label)
            self.studio_link_var.set(str(row.get("link") or ""))
            text = (f"Created {row.get('kind')} '{row.get('name')}' as "
                    f"{row.get('visibility')}  •  ID {row.get('id')}.")
            if row.get("warning"):
                text += "  " + str(row["warning"])
            self.studio_create_status.configure(text=text,
                                                fg=AMBER if row.get("warning") else GREEN)
            self.studio_members_status.configure(
                text="Chat created. Refresh contacts or select this new destination to invite members.",
                fg=GREEN)
            q_log(f"Telegram Studio created {row.get('kind')} {row.get('name')} "
                  f"({row.get('visibility')}, id {row.get('id')})", "ok")

        self._studio_run_async("Creating Telegram group/channel",
                               E.telegram_studio_create_chat,
                               args=(title, kind, visibility, username, about),
                               status=self.studio_create_status, buttons=buttons,
                               on_success=done, timeout=300.0)

    def studio_export_link(self):
        row = self._studio_selected_chat("studio_target_var")
        if not row:
            self.studio_members_status.configure(
                text="Refresh the joined-destination list and select a group/channel first.", fg=AMBER)
            return

        def done(link):
            self.studio_link_var.set(str(link or ""))
            self.studio_members_status.configure(
                text="Invite link ready. Telegram permissions determine whether this account may export one.",
                fg=GREEN)
            q_log(f"Telegram Studio invite link generated for {row.get('name')}", "ok")

        self._studio_run_async("Generating invite link", E.telegram_studio_export_link,
                               args=(row["id"],), status=self.studio_members_status,
                               buttons=[self.studio_link_btn], on_success=done)

    def studio_copy_link(self):
        link = str(self.studio_link_var.get() or "").strip()
        if not link:
            self.studio_members_status.configure(text="Generate an invite link first.", fg=AMBER)
            return
        try:
            self.root.clipboard_clear()
            self.root.clipboard_append(link)
            self.root.update_idletasks()
            self.studio_members_status.configure(text="Invite link copied to clipboard.", fg=GREEN)
        except Exception as exc:
            self.studio_members_status.configure(text=f"Clipboard unavailable: {exc}", fg=RED)

    def studio_load_join_requests(self):
        row = self._studio_selected_chat("studio_target_var")
        if not row:
            self.studio_members_status.configure(text="Select a joined group/channel first.", fg=AMBER)
            return

        def done(rows):
            tree = self.studio_join_requests_tree
            tree.delete(*tree.get_children())
            for item in rows or []:
                user_id = int(item.get("id") or 0)
                if not user_id:
                    continue
                tree.insert("", "end", iid=str(user_id),
                            values=(item.get("name") or "User", item.get("username") or "", user_id))
            note = f"Loaded {len(tree.get_children())} pending join request(s) for {row.get('name')}."
            self.studio_members_status.configure(text=note, fg=GREEN if tree.get_children() else MUTED)

        self._studio_run_async("Loading join requests", E.telegram_studio_pending_join_requests,
                               args=(row["id"],), status=self.studio_members_status,
                               buttons=[self.studio_join_refresh_btn], on_success=done)

    def studio_decide_join_requests(self, approved):
        row = self._studio_selected_chat("studio_target_var")
        selected = list(self.studio_join_requests_tree.selection())
        if not row:
            self.studio_members_status.configure(text="Select a group/channel first.", fg=AMBER)
            return
        if not selected:
            self.studio_members_status.configure(text="Select one or more pending requests first.", fg=AMBER)
            return
        ids = [int(x) for x in selected]
        action = "approve" if approved else "decline"
        if not messagebox.askyesno(
                "Confirm join request",
                f"{action.title()} {len(ids)} selected join request(s) for '{row['name']}'?\n\n"
                "Telegram admin permissions are required.", parent=self.root):
            return

        def done(result):
            completed = list(result.get("done") or [])
            failed = list(result.get("failed") or [])
            self.studio_members_status.configure(
                text=f"{action.title()}d {len(completed)} request(s); {len(failed)} failed.",
                fg=AMBER if failed else GREEN)
            q_log(f"Telegram join requests {action}d: {len(completed)} ok, {len(failed)} failed", "ok" if not failed else "warn")
            self.studio_load_join_requests()

        self._studio_run_async(f"{action.title()}ing join requests",
                               E.telegram_studio_decide_join_requests,
                               args=(row["id"], ids, bool(approved)),
                               status=self.studio_members_status,
                               buttons=[self.studio_join_approve_btn,
                                        self.studio_join_decline_btn], on_success=done)

    def studio_load_contacts(self):
        def done(rows):
            self.studio_contacts = list(rows or [])
            self._studio_draw_contacts()
            self.studio_members_status.configure(
                text=f"Loaded {len(self.studio_contacts)} contacts. Select up to 10 for one invite action.",
                fg=GREEN)
            q_log(f"Telegram Studio contacts loaded: {len(self.studio_contacts)}", "ok")

        self._studio_run_async("Loading Telegram contacts", E.telegram_studio_contacts,
                               status=self.studio_members_status,
                               buttons=[self.studio_contacts_btn], on_success=done)

    def _studio_draw_contacts(self, *_):
        tree = getattr(self, "studio_contacts_tree", None)
        if tree is None:
            return
        for iid in tree.get_children(""):
            tree.delete(iid)
        search_var = getattr(self, "studio_contact_search_var", None)
        search = str(search_var.get() if search_var is not None else "")
        rows = filter_telegram_dialogs(self.studio_contacts, search)
        for row in rows:
            uid = int(row.get("id") or 0)
            iid = f"contact_{uid}"
            username = ("@" + str(row.get("username"))) if row.get("username") else "—"
            tree.insert("", "end", iid=iid,
                        values=(row.get("name", ""), username, uid,
                                "YES" if row.get("mutual") else "NO"))

    def studio_invite_selected(self):
        row = self._studio_selected_chat("studio_target_var")
        if not row:
            self.studio_members_status.configure(text="Select a destination group/channel first.", fg=AMBER)
            return
        selected = list(self.studio_contacts_tree.selection())
        if not selected:
            self.studio_members_status.configure(text="Select one or more contacts from the list.", fg=AMBER)
            return
        if len(selected) > 10:
            self.studio_members_status.configure(text="Select no more than 10 contacts per operation.", fg=RED)
            return
        user_ids = [int(self.studio_contacts_tree.set(iid, "id")) for iid in selected]
        if not messagebox.askyesno(
                "Confirm member invite",
                f"Invite {len(user_ids)} selected contact(s) to '{row['name']}'?\n\n"
                "Telegram privacy settings, admin permissions, and rate limits may prevent some invites.",
                parent=self.root):
            return

        def done(result):
            added = list(result.get("added") or [])
            failed = list(result.get("failed") or [])
            summary = f"Added {len(added)} contact(s)."
            if failed:
                summary += f" {len(failed)} could not be added; use the invite link if Telegram requires it."
                q_log("Telegram Studio invite partial failures: " + "; ".join(
                    f"{x.get('id')}: {x.get('error')}" for x in failed[:5]), "warn")
            self.studio_members_status.configure(text=summary, fg=AMBER if failed else GREEN)
            q_log(f"Telegram Studio invitation result: {len(added)} added, {len(failed)} failed", "ok")

        self._studio_run_async("Inviting selected contacts", E.telegram_studio_invite_members,
                               args=(row["id"], user_ids), status=self.studio_members_status,
                               buttons=[self.studio_invite_btn, self.studio_contacts_btn],
                               on_success=done, timeout=300.0)

    def _studio_signal_advice(self):
        mode = str(self.sig_be_mode.get() or "").upper()
        if mode.startswith("NO"):
            return ""
        if mode.startswith("AFTER TP1"):
            return "After TP1, move SL to Entry"
        if mode.startswith("AFTER TP2"):
            return "After TP2, move SL to Entry"
        custom = str(self.sig_be_custom_var.get() or "").strip()
        if not custom:
            raise ValueError("Enter the custom BE advice, or choose a preset/none.")
        return custom

    def _studio_signal_message(self):
        count = max(1, min(10, int(self.sig_tp_count_var.get())))
        values = [var.get().strip() for var in self.sig_tp_vars[:count]]
        return build_signal_message(
            self.sig_symbol_var.get(), self.sig_direction_var.get(),
            self.sig_entry_mode_var.get(), self.sig_entry_var.get(),
            self.sig_range_end_var.get(), self.sig_order_type_var.get(),
            self.sig_sl_var.get(), values, self._studio_signal_advice())

    @staticmethod
    def _studio_signal_message_for_destination(message, destination_name):
        """Replace the brand in the first line with the selected destination name."""
        lines = str(message or "").splitlines()
        if not lines:
            return str(message or "")
        if "TRADE SIGNAL" not in lines[0]:
            return str(message or "")
        name = re.sub(r"\s+", " ", str(destination_name or "Telegram group")).strip()[:100]
        candidate = list(lines)
        candidate[0] = f"📊 {name or 'Telegram group'} • TRADE SIGNAL"
        personalized = "\n".join(candidate)
        # Keep Telegram's text maximum even for unusually long destination names.
        while len(personalized.encode("utf-16-le")) // 2 > 4096 and name:
            name = name[:-1].rstrip()
            candidate[0] = f"📊 {name or 'Telegram group'} • TRADE SIGNAL"
            personalized = "\n".join(candidate)
        if len(personalized.encode("utf-16-le")) // 2 > 4096:
            raise ValueError("Signal content exceeds Telegram's 4096-character limit.")
        return personalized

    def studio_preview_signal(self):
        try:
            message = self._studio_signal_message()
            preview_targets = self._studio_selected_publish_chats()
            if preview_targets:
                message = self._studio_signal_message_for_destination(
                    message, preview_targets[0].get("name") or preview_targets[0].get("id"))
            self.sig_preview.configure(state="normal")
            self.sig_preview.delete("1.0", "end")
            self.sig_preview.insert("1.0", message)
            self.sig_preview.configure(state="disabled")
            self.sig_preview_status.configure(
                text="Preview validated by EdgeQuant's signal parser.", fg=GREEN)
            return message
        except Exception as exc:
            self.sig_preview_status.configure(text=f"Check signal fields: {exc}", fg=RED)
            return None

    def _confirm_studio_live(self):
        dlg = tk.Toplevel(self.root)
        dlg.title("Confirm LIVE signal processing")
        dlg.configure(bg=PANEL)
        dlg.transient(self.root)
        dlg.grab_set()
        dlg.resizable(False, False)
        tk.Label(dlg, text="REAL TRADING — TYPE LIVE", bg=PANEL, fg=RED,
                 font=widget_font("Segoe UI", 12, True)).pack(padx=20, pady=(18, 8))
        tk.Label(dlg, text=("This signal will be passed to the running LIVE engine and may place "
                            "real MT5 orders. Type LIVE exactly to continue."),
                 bg=PANEL, fg=FG, wraplength=430, justify="center",
                 font=widget_font("Segoe UI", 9)).pack(padx=20)
        var = tk.StringVar()
        ent = ttk.Entry(dlg, textvariable=var, width=16, justify="center")
        ent.pack(pady=12)
        ent.focus_set()
        result = {"ok": False}

        def done(*_):
            result["ok"] = var.get() == "LIVE"
            dlg.destroy()

        buttons = ttk.Frame(dlg, style="Panel.TFrame")
        buttons.pack(pady=(0, 16))
        ttk.Button(buttons, text="CONTINUE", style="Stop.TButton", command=done).pack(side="left", padx=5)
        ttk.Button(buttons, text="CANCEL", command=dlg.destroy).pack(side="left", padx=5)
        ent.bind("<Return>", done)
        self._center_toplevel(dlg)
        dlg.wait_window()
        return result["ok"]

    @staticmethod
    def _studio_signal_key(text):
        """Normalize a signal caption and its journal form (newlines stored as pipes)."""
        try:
            return " ".join(re.sub(r"[^a-z0-9]+", " ",
                                   str(text or "").replace("|", " ").lower()).split())
        except Exception:
            return ""

    def _studio_selected_publication(self):
        try:
            selection = self.studio_publication_tree.selection()
            return next((r for r in self.studio_publications
                         if str(r.get("id")) == str(selection[0])), None) if selection else None
        except Exception:
            return None

    def _studio_logo_display(self):
        path = Path(str(getattr(self, "studio_logo_path", "") or ""))
        if path.is_file():
            return f"Using: {path.name}"
        return "No custom logo selected; Telegram Studio will use the bundled EdgeQuant logo if available."

    def studio_choose_logo(self):
        path = filedialog.askopenfilename(
            parent=self.root, title="Choose a signal logo",
            filetypes=(("Image files", "*.png *.jpg *.jpeg *.webp"), ("All files", "*.*")))
        if not path:
            return
        chosen = Path(path)
        if not chosen.is_file() or chosen.suffix.lower() not in (".png", ".jpg", ".jpeg", ".webp"):
            messagebox.showerror("Telegram Studio", "Choose a PNG, JPG, JPEG or WebP image.", parent=self.root)
            return
        self.studio_logo_path = str(chosen)
        save_ui_prefs(studio_logo=self.studio_logo_path)
        self.studio_logo_note.configure(text=self._studio_logo_display(), fg=CYAN)
        if hasattr(self, "studio_report_logo_note"):
            self.studio_report_logo_note.configure(text=self._studio_logo_display(), fg=CYAN)
        q_log(f"Provider logo selected: {chosen.name}", "ok")

    def studio_use_default_logo(self):
        default_logo = BRAND_LOGO if BRAND_LOGO.is_file() else LOGO_SMALL
        self.studio_logo_path = str(default_logo) if default_logo.is_file() else ""
        save_ui_prefs(studio_logo=self.studio_logo_path)
        self.studio_logo_note.configure(text=self._studio_logo_display(), fg=CYAN if self.studio_logo_path else MUTED)
        if hasattr(self, "studio_report_logo_note"):
            self.studio_report_logo_note.configure(text=self._studio_logo_display(),
                                                   fg=CYAN if self.studio_logo_path else MUTED)
        q_log("Provider logo reset to the bundled EdgeQuant logo", "info")

    def _studio_composer_payload(self):
        count = max(1, min(10, int(self.sig_tp_count_var.get())))
        return {"symbol": self.sig_symbol_var.get().strip().upper(),
                "direction": self.sig_direction_var.get().strip().upper(),
                "entry_mode": self.sig_entry_mode_var.get().strip().upper(),
                "entry": self.sig_entry_var.get().strip(),
                "range_end": self.sig_range_end_var.get().strip(),
                "order_type": self.sig_order_type_var.get().strip().upper(),
                "sl": self.sig_sl_var.get().strip(),
                "tp_levels": [v.get().strip() for v in self.sig_tp_vars[:count]],
                "be_advice": self._studio_signal_advice()}

    def _studio_active_progress_events(self, row, events=None):
        try:
            revision = max(1, int((row or {}).get("level_revision") or 1))
        except Exception:
            revision = 1
        active = []
        for event in (events if events is not None else (row or {}).get("progress_events") or []):
            if not isinstance(event, dict):
                continue
            try:
                event_revision = int(event.get("revision") or 1)
            except Exception:
                event_revision = 1
            if event_revision == revision:
                active.append(event)
        return active

    @staticmethod
    def _studio_tracking_label(row):
        mode = str((row or {}).get("tracking_mode") or "").upper()
        if mode == "MT5_AUTO":
            return "MT5 AUTO · READ-ONLY"
        if mode == "JOURNAL_AUTO" or ((row or {}).get("auto_progress") and
                                         (row or {}).get("local_trade_ids")):
            return "LINKED JOURNAL AUTO"
        return "MANUAL"

    def _studio_refresh_publications(self):
        tree = getattr(self, "studio_publication_tree", None)
        if tree is None:
            return
        try:
            selected = tree.selection()
            selected_id = str(selected[0]) if selected else ""
            children = tree.get_children()
            if children:
                tree.delete(*children)
            filter_var = getattr(self, "studio_publication_filter_var", None)
            wanted_type = str(filter_var.get() if filter_var is not None else "ALL").upper()
            for row in sorted(self.studio_publications or [],
                              key=lambda r: float(r.get("created_ts") or 0), reverse=True)[:200]:
                rid = str(row.get("id") or "")
                if not rid:
                    continue
                composer = row.get("composer") if isinstance(row.get("composer"), dict) else {}
                order_type = str(composer.get("order_type") or row.get("order_type") or "LIMIT").upper()
                if wanted_type in ("MARKET", "LIMIT") and order_type != wanted_type:
                    continue
                when = row.get("created_ts") or 0
                try:
                    time_text = datetime.fromtimestamp(float(when)).strftime("%Y-%m-%d %H:%M")
                except Exception:
                    time_text = "-"
                signal = f"{composer.get('symbol', 'SIGNAL')} {composer.get('direction', '')}".strip()
                entry_text = str(composer.get("entry") or "—")
                if str(composer.get("entry_mode") or "").upper() == "RANGE" and composer.get("range_end"):
                    entry_text += "–" + str(composer.get("range_end"))
                sl_text = str(composer.get("sl") or "—")
                tp_text = ", ".join(str(x) for x in (composer.get("tp_levels") or [])) or "—"
                targets = row.get("targets") or []
                target_names = ", ".join(str(x.get("name") or x.get("id")) for x in targets[:4])
                if len(targets) > 4:
                    target_names += f" +{len(targets)-4}"
                events = self._studio_active_progress_events(row)
                state = str(row.get("status") or "PUBLISHED")
                if events:
                    state += " • " + str(events[-1].get("label") or "")
                tree.insert("", "end", iid=rid, values=(time_text, signal[:40], order_type,
                            entry_text[:28], sl_text[:16], tp_text[:45], state[:55],
                            self._studio_tracking_label(row)[:28], target_names[:110]))
                if rid == selected_id:
                    tree.selection_set(rid)
            if selected_id:
                self._studio_show_publication_details()
        except Exception as exc:
            q_log(f"Telegram Studio tracker refresh failed: {exc}", "warn")

    def _studio_show_publication_details(self, *_):
        text_widget = getattr(self, "studio_publication_detail", None)
        if text_widget is None:
            return
        row = self._studio_selected_publication()
        if not row:
            detail = "Select a publication to view the full signal, destinations, tracking mode and MT5 quote status."
        else:
            composer = row.get("composer") if isinstance(row.get("composer"), dict) else {}
            entry = str(composer.get("entry") or "—")
            if str(composer.get("entry_mode") or "").upper() == "RANGE" and composer.get("range_end"):
                entry += " - " + str(composer.get("range_end"))
            events = self._studio_active_progress_events(row)
            last_event = str(events[-1].get("label") or "—") if events else "—"
            targets = ", ".join(str(x.get("name") or x.get("id")) for x in (row.get("targets") or [])) or "No Telegram posts"
            quote = str(row.get("monitor_quote_text") or "No MT5 quote recorded")
            monitor_note = str(row.get("monitor_note") or "")
            order_type = str(composer.get("order_type") or row.get("order_type") or "LIMIT").upper()
            detail = (f"{composer.get('symbol') or 'SIGNAL'} {composer.get('direction') or ''}  ·  "
                      f"TYPE {order_type}  ·  ENTRY {entry}  ·  SL {composer.get('sl') or '—'}  ·  "
                      f"TPs {', '.join(str(x) for x in (composer.get('tp_levels') or [])) or '—'}\n"
                      f"Status: {row.get('status') or 'PUBLISHED'}  ·  Last update: {last_event}  ·  "
                      f"Tracking: {self._studio_tracking_label(row)}\n"
                      f"Posted to: {targets}\n"
                      f"MT5 quote (read-only): {quote}" +
                      (f"\nMonitoring note: {monitor_note}" if monitor_note else ""))
        try:
            text_widget.configure(state="normal")
            text_widget.delete("1.0", "end")
            text_widget.insert("1.0", detail)
            text_widget.configure(state="disabled")
        except Exception:
            pass
        monitor_status = getattr(self, "studio_monitor_status", None)
        if monitor_status is not None and row and self._studio_tracking_label(row) == "MT5 AUTO · READ-ONLY":
            note = str(row.get("monitor_note") or "")
            quote = str(row.get("monitor_quote_text") or "")
            try:
                monitor_status.configure(text=(f"{quote}  ·  {note}" if quote or note else
                    "Read-only quote monitoring opted in. Keep this PC and MT5 terminal open; a demo account is fine."),
                    fg=AMBER if "review" in note.lower() or "waiting" in note.lower() else CYAN)
            except Exception:
                pass

    def _studio_load_publication_to_composer(self):
        row = self._studio_selected_publication()
        if not row:
            self.studio_tracker_status_var.set("Select a publication to load into the composer.")
            return
        composer = row.get("composer") if isinstance(row.get("composer"), dict) else {}
        self.sig_symbol_var.set(str(composer.get("symbol") or "XAUUSD"))
        self.sig_direction_var.set(str(composer.get("direction") or "BUY").upper())
        mode = str(composer.get("entry_mode") or "SINGLE").upper()
        self.sig_entry_mode_var.set("RANGE" if mode == "RANGE" else "SINGLE")
        self.sig_entry_var.set(str(composer.get("entry") or ""))
        self.sig_range_end_var.set(str(composer.get("range_end") or ""))
        self.sig_order_type_var.set(str(composer.get("order_type") or row.get("order_type") or "LIMIT").upper())
        self.sig_sl_var.set(str(composer.get("sl") or ""))
        levels = [str(x) for x in (composer.get("tp_levels") or row.get("tp_levels") or [])]
        self.sig_tp_count_var.set(str(max(1, min(10, len(levels) or 1))))
        self._studio_rebuild_tp_inputs()
        for var, value in zip(self.sig_tp_vars, levels):
            var.set(value)
        advice = str(composer.get("be_advice") or "No BE advice")
        known = tuple(self.sig_be_combo.cget("values"))
        if advice in known:
            self.sig_be_mode.set(advice)
            self.sig_be_custom_var.set("")
        else:
            self.sig_be_mode.set("Custom note")
            self.sig_be_custom_var.set(advice)
        self._studio_entry_mode_changed()
        self._studio_be_mode_changed()
        self.studio_tracker_status_var.set("Loaded selected signal into the composer. Review fields before updating posts.")
        try:
            self.studio_inner_nb.select(1)
        except Exception:
            pass

    def _studio_enable_mt5_monitoring(self):
        row = self._studio_selected_publication()
        if not row:
            self.studio_tracker_status_var.set("Select a publication to enable read-only MT5 monitoring.")
            return
        if not row.get("targets"):
            self.studio_tracker_status_var.set("This publication has no active Telegram posts to update.")
            return
        if str(row.get("status") or "").upper() in (
                "SL HIT", "BREAK EVEN", "CLOSED", "CLOSED (MANUAL)", "CANCELLED", "DELETED"):
            self.studio_tracker_status_var.set("This signal is already terminal; review it manually rather than restarting monitoring.")
            return
        if not messagebox.askyesno(
                "Enable read-only MT5 monitoring",
                "Enable quote-only progress checks for this published signal?\n\n"
                "No MT5 order will be placed or modified. The original Telegram posts may be edited when a clear price level is reached. Keep this PC and the MT5 terminal open. A demo account is fine.",
                parent=self.root):
            return
        row["tracking_mode"] = "MT5_AUTO"
        row["auto_progress"] = True
        row["monitor_start_ts"] = time.time()
        row["monitor_last_mid"] = None
        row["monitor_last_exit"] = None
        row["monitor_last_exec"] = None
        row["monitor_last_tick_ts"] = None
        row["monitor_quote_text"] = ""
        row["monitor_note"] = "Monitoring enabled locally; waiting for the first fresh post-enable MT5 quote."
        row["monitor_last_event"] = ""
        self._studio_persist_publications()
        self.studio_tracker_status_var.set("Read-only MT5 quote monitoring enabled. No MT5 order action is possible from this tracker.")
        self._studio_show_publication_details()

    def _studio_persist_publications(self):
        try:
            save_studio_publications(self.studio_publications)
            self._studio_refresh_publications()
            self._studio_refresh_provider_journal()
        except Exception as exc:
            q_log(f"Telegram Studio tracker could not be saved: {exc}", "err")
            messagebox.showerror("Telegram Studio", f"Could not save the local signal tracker.\n\n{exc}",
                                 parent=self.root)

    def studio_send_signal(self):
        rows = self._studio_selected_publish_chats()
        if not rows:
            self.sig_preview_status.configure(text="Select one or more Telegram destinations first.", fg=AMBER)
            return
        message = self.studio_preview_signal()
        if not message:
            return
        try:
            composer = self._studio_composer_payload()
            provider_quick_tp_pips = float(self.sig_provider_l1_var.get())
            if not math.isfinite(provider_quick_tp_pips) or not (1.0 <= provider_quick_tp_pips <= 100000.0):
                raise ValueError("Provider Layer 1 quick TP must be between 1 and 100000 pips.")
        except Exception as exc:
            self.sig_preview_status.configure(text=f"Check signal fields: {exc}", fg=RED)
            return
        self.studio_provider_layer1_pips = provider_quick_tp_pips
        save_ui_prefs(studio_provider_layer1_pips=provider_quick_tp_pips)
        action = str(self.sig_send_mode_var.get() or "PUBLISH ONLY").upper()
        process_local = action == "PUBLISH + PROCESS"
        tracking_var = getattr(self, "sig_tracking_mode_var", None)
        tracking_choice = str(tracking_var.get() if tracking_var is not None else "MANUAL").upper()
        tracking_mode = ("MT5_AUTO" if tracking_choice.startswith("MT5 AUTO") else
                         ("JOURNAL_AUTO" if tracking_choice.startswith("LINKED JOURNAL") else "MANUAL"))
        if process_local and tracking_mode == "MT5_AUTO":
            messagebox.showinfo(
                "Use linked journal tracking for processed signals",
                "MT5 AUTO is quote-only and cannot confirm the actual placed trade's entry or outcome. "
                "PUBLISH + PROCESS will use LINKED JOURNAL AUTO to track the local MT5 pending/open/close states. "
                "For quote-only signal tracking without local processing, choose PUBLISH ONLY + MT5 AUTO.",
                parent=self.root)
            tracking_choice = "LINKED JOURNAL AUTO"
            tracking_mode = "JOURNAL_AUTO"
            self.sig_tracking_mode_var.set(tracking_choice)
        live = bool(process_local and self.bot and self.bot.is_alive() and not self.bot.dry)
        if process_local and not (self.bot and self.bot.is_alive()):
            self.sig_preview_status.configure(
                text="Local processing needs a running engine. Start TEST RUN or LIVE first.", fg=AMBER)
            return
        if live and not self._confirm_studio_live():
            self.sig_preview_status.configure(text="LIVE confirmation cancelled; nothing was published.", fg=AMBER)
            return
        mode_text = (("publish to all selected groups, then process locally once "
                      + ("(LIVE — may place real orders)" if live else "(DRY RUN — no real orders)")
                      if process_local else "publish to all selected Telegram destinations only")
                     + f"; tracking: {tracking_choice}")
        names = [str(row.get("name") or "Telegram group") for row in rows]
        name_lines = "\n".join("  • " + name for name in names[:8])
        if len(names) > 8:
            name_lines += f"\n  ... and {len(names)-8} more"
        logo_path = str(getattr(self, "studio_logo_path", "") or "")
        if not Path(logo_path).is_file():
            fallback_logo = BRAND_LOGO if BRAND_LOGO.is_file() else LOGO_SMALL
            if fallback_logo.is_file():
                logo_path = str(fallback_logo)
        logo_note = Path(logo_path).name if logo_path else "text-only (no image available)"
        if not messagebox.askyesno(
                "Confirm signal SEND",
                f"Destinations ({len(rows)}):\n{name_lines}\n\n"
                f"Action: {mode_text}\nSender: each destination group/channel identity "
                "(basic groups post as your signed-in account; channels/supergroups require target Send As).\n"
                "Signal header: each post includes that destination's own group/channel name.\n"
                f"Logo: {logo_note}\n\nContinue?",
                parent=self.root):
            return
        category = str(self.sig_order_type_var.get() or "LIMIT").upper()

        async def send_selected(client=None):
            sent_rows, failures = [], []
            first_sent_message = message
            for row in rows:
                try:
                    destination_message = self._studio_signal_message_for_destination(
                        message, row.get("name") or row.get("id"))
                    if self.bot and self.bot.is_alive() and getattr(E, "ALLOW_OWN_POSTS", False):
                        E.studio_mark_echo(row["id"], destination_message)
                    msg_id = await E.telegram_studio_send_signal(
                        row["id"], destination_message, logo_path, client=client)
                    if not sent_rows:
                        first_sent_message = destination_message
                    sent_rows.append({"id": int(row["id"]), "name": str(row["name"]),
                                      "message_id": int(msg_id or 0)})
                except Exception as exc:
                    failures.append({"id": row.get("id"), "name": row.get("name"),
                                     "error": f"{type(exc).__name__}: {exc}"})
            process_error = ""
            local_trade_ids = []
            if process_local and sent_rows:
                try:
                    # One local parse/execution per composed signal, not one per
                    # destination (which would multiply the trading risk).
                    process_started = time.time()
                    E.handle_signal(first_sent_message, "Telegram Studio", sent_rows[0]["id"],
                                    category, sent_rows[0]["message_id"],
                                    provider_quick_tp_pips=provider_quick_tp_pips)
                    # Studio actions are serialized by _studio_busy. Source +
                    # placement timestamp therefore bind only this one action,
                    # without relying on the journal's intentionally short text field.
                    local_trade_ids = [str(t.get("id")) for t in list(getattr(E, "TRADES", []))
                                       if str(t.get("source") or "") == "Telegram Studio"
                                       and float(t.get("placed_ts") or 0) >= process_started - 2.0]
                except Exception as exc:
                    process_error = f"{type(exc).__name__}: {exc}"
            return {"sent": sent_rows, "failures": failures,
                    "processed": bool(process_local and sent_rows),
                    "local_trade_ids": local_trade_ids,
                    "process_error": process_error}

        def done(result):
            sent_rows = list(result.get("sent") or [])
            failures = list(result.get("failures") or [])
            if sent_rows:
                record = {"id": str(time.time_ns()), "created_ts": time.time(),
                          "message": message, "composer": composer,
                          "tp_levels": list(composer.get("tp_levels") or []),
                          "targets": sent_rows, "progress_events": [],
                          "status": "PUBLISHED", "logo": logo_path,
                          "local_processing": bool(result.get("processed")),
                          "local_trade_ids": list(result.get("local_trade_ids") or []),
                          "auto_progress": tracking_mode != "MANUAL",
                          "tracking_mode": tracking_mode,
                          "monitor_start_ts": time.time() if tracking_mode == "MT5_AUTO" else None,
                          "monitor_last_mid": None, "monitor_last_exit": None,
                          "monitor_last_exec": None, "monitor_last_tick_ts": None,
                          "monitor_quote_text": "", "monitor_note": "",
                          "level_revision": 1,
                          "order_type": category}
                self.studio_publications.append(record)
                self.studio_publications = self.studio_publications[-200:]
                self._studio_persist_publications()
            if result.get("process_error"):
                status_text = f"Published to {len(sent_rows)}/{len(rows)} destinations; local processing failed: {result['process_error']}"
                status_color = AMBER
            else:
                status_text = f"Published to {len(sent_rows)}/{len(rows)} destinations. " + (
                    "Processed once locally." if result.get("processed") else "Publish-only mode.")
                if tracking_mode == "MT5_AUTO":
                    status_text += " Read-only MT5 monitoring is opted in; keep the PC and terminal open."
                elif tracking_mode == "JOURNAL_AUTO":
                    status_text += (" Linked journal tracking selected."
                                    if result.get("local_trade_ids") else
                                    " No local trade is linked yet; use manual progress or process locally.")
                status_color = GREEN if not failures else AMBER
            if failures:
                status_text += " Failed: " + "; ".join(
                    f"{x.get('name')}: {x.get('error')}" for x in failures[:3])
            self.sig_preview_status.configure(text=status_text, fg=status_color)
            if failures:
                q_log("Telegram Studio partial publish: " + "; ".join(
                    f"{x.get('name')}: {x.get('error')}" for x in failures[:6]), "warn")
            else:
                q_log(f"Telegram Studio signal posted to {len(sent_rows)} destination(s); "
                      f"local processing {'once' if result.get('processed') else 'off'}", "ok")
            if result.get("process_error"):
                q_log("Telegram Studio local processing failed after publish: " + result["process_error"], "err")

        self._studio_run_async("Publishing signal", send_selected,
                               status=self.sig_preview_status,
                               buttons=[self.sig_send_btn, self.sig_preview_btn,
                                        self.signal_refresh_btn, self.studio_next_tp_btn],
                               on_success=done, timeout=300.0)

    def studio_mark_next_tp(self):
        row = self._studio_selected_publication()
        if not row:
            self.studio_tracker_status_var.set("Select a published signal first.")
            return
        current = sum(1 for item in self._studio_active_progress_events(row)
                      if str(item.get("kind", "")).startswith("TP"))
        total = len(row.get("tp_levels") or [])
        if current >= total:
            self.studio_tracker_status_var.set("All configured TP levels are already marked. Use BREAK EVEN or CLOSE / CANCEL if appropriate.")
            return
        self.studio_mark_progress(f"TP{current + 1} HIT")

    def _studio_progress_caption(self, row, events, destination_name=""):
        """Build the status footer while preserving the per-destination signal header."""
        row = row if isinstance(row, dict) else {}
        base = str(row.get("message") or "").strip()
        if destination_name:
            base = self._studio_signal_message_for_destination(base, destination_name)
        levels = list(row.get("tp_levels") or [])
        try:
            revision = max(1, int(row.get("level_revision") or 1))
        except Exception:
            revision = 1
        active_events = []
        for item in events or []:
            if not isinstance(item, dict):
                continue
            try:
                event_revision = int(item.get("revision") or 1)
            except Exception:
                event_revision = 1
            if event_revision == revision:
                active_events.append(item)
        hit_tp = 0
        terminal = ""
        for event in active_events:
            label = str(event.get("label") or "").upper()
            match = re.match(r"TP\s*(\d+)", label)
            if match and "HIT" in label:
                hit_tp = max(hit_tp, int(match.group(1)))
            if label in ("BREAK EVEN", "SL HIT", "CLOSED", "CANCELLED", "REVIEW NEEDED"):
                terminal = label
        lines = ["📊 TRADE PROGRESS"]
        for index, level in enumerate(levels, 1):
            state = "✅ HIT" if index <= hit_tp else "⏳ PENDING"
            lines.append(f"{state}   TP{index}: {level}")
        state = str(row.get("status") or "").upper()
        if state in ("PENDING", "OPEN", "OPEN + PENDING", "RUNNING", "REVIEW NEEDED",
                     "CLOSED", "CLOSED (MANUAL)", "CANCELLED", "SL HIT", "BREAK EVEN"):
            lines.append(f"STATUS: {state}")
        if terminal:
            icon = "🛡️" if terminal == "BREAK EVEN" else (
                "⛔" if terminal in ("SL HIT", "CANCELLED", "REVIEW NEEDED") else "☑️")
            if terminal not in ("CLOSED", "SL HIT", "BREAK EVEN", "REVIEW NEEDED"):
                lines.append(f"{icon} {terminal}")
            elif not any(line == f"STATUS: {terminal}" for line in lines):
                lines.append(f"{icon} {terminal}")
        if row.get("monitor_quote_text"):
            lines.append("📈 MT5 quote: " + str(row.get("monitor_quote_text")))
        if row.get("monitor_note"):
            lines.append("ℹ️ " + str(row.get("monitor_note")))
        if active_events:
            lines.append("Updated " + str(active_events[-1].get("time") or ""))
        footer = "\n".join(lines)
        caption = (base + "\n\n" + footer) if base else footer
        # Telegram captions are limited by UTF-16 units. Keep the signal body and
        # status first; trim the oldest/longest body only if necessary.
        units = len(caption.encode("utf-16-le")) // 2
        if units > 1000:
            excess = units - 1000
            trim_chars = min(max(0, len(base) - 80), excess + 4)
            if trim_chars:
                base = base[:-trim_chars].rstrip() + "…"
                caption = base + "\n\n" + footer
        return caption

    def _studio_submit_progress(self, row, label, auto=False, display_status=None,
                                monitor_result=None):
        label = str(label or "").strip().upper()
        if not row or not row.get("targets"):
            if not auto:
                self.studio_tracker_status_var.set("This signal has no remaining Telegram posts to update.")
            return
        try:
            revision = max(1, int(row.get("level_revision") or 1))
        except Exception:
            revision = 1
        events = list(row.get("progress_events") or [])
        if any(str(e.get("label") or "").upper() == label
               for e in self._studio_active_progress_events(row, events)):
            return
        stamp = datetime.now().strftime("%Y-%m-%d %H:%M")
        event = {"label": label, "kind": label.split()[0], "ts": time.time(), "time": stamp,
                 "source": "mt5_quote" if monitor_result else ("engine" if auto else "provider"),
                 "revision": revision}
        if monitor_result:
            event["quote_text"] = str(monitor_result.get("quote_text") or "")
            event["note"] = str(monitor_result.get("note") or "")
            for key in ("last_mid", "last_exit", "last_exec", "last_tick_ts"):
                row["monitor_" + key.replace("last_", "last_")] = monitor_result.get(key)
            row["monitor_quote_text"] = str(monitor_result.get("quote_text") or row.get("monitor_quote_text") or "")
            row["monitor_note"] = str(monitor_result.get("note") or "")
            row["monitor_last_event"] = label
        row["status"] = str(display_status or label).upper()
        caption = self._studio_progress_caption(row, events + [event])

        async def update_all(client=None):
            updated, failed = [], []
            for target in list(row.get("targets") or []):
                try:
                    target_caption = self._studio_progress_caption(
                        row, events + [event], str(target.get("name") or ""))
                    await E.telegram_studio_edit_signal(
                        target["id"], target["message_id"], target_caption, client=client)
                    updated.append(target)
                except Exception as exc:
                    failed.append({"target": target, "error": f"{type(exc).__name__}: {exc}"})
            return {"updated": updated, "failed": failed}

        def done(result):
            row["progress_events"] = (events + [event])[-100:]
            row["status"] = str(display_status or label).upper()
            row["last_caption"] = caption
            row["last_progress_ts"] = time.time()
            self._studio_persist_publications()
            try:
                self._studio_auto_retry_after.pop(str(row.get("id")), None)
            except Exception:
                pass
            failed = list(result.get("failed") or [])
            msg = f"Updated {len(result.get('updated') or [])}/{len(row.get('targets') or [])} posts: {label}"
            if failed:
                msg += f" • {len(failed)} failed"
            if monitor_result:
                msg += " · read-only MT5 quote monitor"
            self.studio_tracker_status_var.set(msg)
            q_log(f"Studio signal update '{label}': {len(result.get('updated') or [])} updated, "
                  f"{len(failed)} failed", "ok" if not failed else "warn")

        if auto:
            self._studio_auto_retry_after = getattr(self, "_studio_auto_retry_after", {})
            self._studio_auto_retry_after[str(row.get("id"))] = time.time() + 60.0
        self._studio_run_async(f"Updating {label}", update_all,
                               status=self.studio_tracker_status,
                               buttons=[self.studio_next_tp_btn], on_success=done)

    def studio_mark_progress(self, label):
        row = self._studio_selected_publication()
        if not row:
            self.studio_tracker_status_var.set("Select a published signal first.")
            return
        label = str(label or "").strip().upper()
        if not row.get("targets"):
            self.studio_tracker_status_var.set("This signal has no remaining Telegram posts to update.")
            return
        if not messagebox.askyesno(
                "Update signal status",
                f"Update {label} in {len(row['targets'])} Telegram destination(s)?\n\n"
                "The same selected posts will be edited to show each TP as HIT or PENDING.",
                parent=self.root):
            return
        self._studio_submit_progress(row, label, auto=False)

    def _studio_request_monitor_snapshot(self, rows):
        """Fetch quote snapshots only for explicitly opted-in MT5_AUTO publications."""
        eligible = []
        for row in rows or []:
            if not isinstance(row, dict) or not row.get("targets"):
                continue
            if not row.get("auto_progress") or str(row.get("tracking_mode") or "").upper() != "MT5_AUTO":
                continue
            if str(row.get("status") or "").upper() in (
                    "SL HIT", "BREAK EVEN", "CLOSED", "CLOSED (MANUAL)", "CANCELLED",
                    "REVIEW NEEDED", "DELETED"):
                continue
            composer = row.get("composer") if isinstance(row.get("composer"), dict) else {}
            symbol = str(composer.get("symbol") or row.get("symbol") or "").strip().upper()
            if symbol:
                eligible.append((dict(row), symbol))
        if not eligible or getattr(self, "_studio_monitor_busy", False):
            return
        now = time.time()
        if now - float(getattr(self, "_studio_monitor_last_request", 0.0) or 0.0) < 15.0:
            return
        self._studio_monitor_busy = True
        self._studio_monitor_last_request = now
        symbols = list(dict.fromkeys(symbol for _row, symbol in eligible))

        def worker():
            try:
                if not callable(getattr(E, "mt5_provider_quote_snapshot", None)):
                    snapshot = {"status": "unavailable", "reason": "Read-only MT5 quote helper is unavailable.",
                                "quotes": {}, "updated_ts": time.time()}
                elif self.bot and self.bot.is_alive():
                    loop = getattr(self.bot, "loop", None)
                    if loop is None or not loop.is_running():
                        snapshot = {"status": "not_connected", "reason": "Trading engine loop is not ready; waiting for the next check.",
                                    "quotes": {}, "updated_ts": time.time()}
                    else:
                        async def quote_on_engine_loop():
                            # Serialized with the engine's MT5 work; this helper is read-only.
                            return E.mt5_provider_quote_snapshot(symbols)
                        future = asyncio.run_coroutine_threadsafe(quote_on_engine_loop(), loop)
                        snapshot = future.result(timeout=30.0)
                else:
                    with self._mt5_api_lock:
                        snapshot = E.mt5_provider_quote_snapshot(symbols)
                snapshot = snapshot if isinstance(snapshot, dict) else {
                    "status": "unavailable", "reason": "MT5 returned an invalid quote snapshot.",
                    "quotes": {}, "updated_ts": time.time()}
            except Exception as exc:
                snapshot = {"status": "unavailable",
                            "reason": f"{type(exc).__name__}: {exc}",
                            "quotes": {}, "updated_ts": time.time()}
            try:
                quotes = snapshot.get("quotes") or {}
                checked = []
                for row, symbol in eligible:
                    quote = quotes.get(symbol) or {"error": snapshot.get("reason") or
                                                   "MT5 quote unavailable."}
                    try:
                        transition = (ProviderStudio.monitor_transition(
                            row, quote, now_ts=snapshot.get("updated_ts"), engine=E)
                            if ProviderStudio is not None else
                            {"status": row.get("status") or "PUBLISHED", "event": "",
                             "note": "Provider monitoring helpers are unavailable."})
                    except Exception as exc:
                        transition = {"status": row.get("status") or "PUBLISHED", "event": "",
                                      "note": f"{type(exc).__name__}: {exc}"}
                    checked.append({"id": str(row.get("id") or ""),
                                    "symbol": symbol, "transition": transition})
                RESULT_Q.put(("provider_monitor", snapshot, checked))
            finally:
                self._studio_monitor_busy = False

        threading.Thread(target=worker, daemon=True,
                         name="edgequant-provider-quote-monitor").start()

    def _studio_monitor_result(self, snapshot, checked):
        snapshot = snapshot if isinstance(snapshot, dict) else {}
        checked = checked if isinstance(checked, list) else []
        connected = snapshot.get("status") == "connected"
        account_tag = (f"#{snapshot.get('login')} @ {snapshot.get('server')}"
                       if snapshot.get("login") or snapshot.get("server") else "active MT5 terminal")
        global_note = (f"MT5 connected · {snapshot.get('broker') or 'broker'} · {account_tag} · "
                       "read-only quotes only. Keep this PC and terminal open; demo accounts are fine." if connected else
                       f"Read-only MT5 monitor waiting: {snapshot.get('reason') or 'terminal/account not connected'}. "
                       "Keep this PC and terminal open; demo accounts are fine.")
        status_label = getattr(self, "studio_monitor_status", None)
        if status_label is not None:
            try:
                status_label.configure(text=global_note, fg=GREEN if connected else AMBER)
            except Exception:
                pass
        rows_by_id = {str(row.get("id") or ""): row
                      for row in (getattr(self, "studio_publications", []) or [])
                      if isinstance(row, dict)}
        changed = False
        for item in checked:
            row = rows_by_id.get(str(item.get("id") or ""))
            transition = item.get("transition") if isinstance(item.get("transition"), dict) else {}
            if row is None:
                continue
            old_status = str(row.get("status") or "PUBLISHED").upper()
            new_status = str(transition.get("status") or old_status).upper()
            label = str(transition.get("event") or "").strip().upper()
            if not label and new_status != old_status and new_status in ("PENDING", "RUNNING", "REVIEW NEEDED"):
                label = new_status
            retry_after = getattr(self, "_studio_auto_retry_after", {}) or {}
            if label and (getattr(self, "_studio_busy", False) or
                          float(retry_after.get(str(row.get("id")), 0.0) or 0.0) > time.time()):
                # Keep the old baseline so the next fresh sample can still detect the crossing.
                continue
            monitor_fields = {
                "monitor_last_mid": transition.get("last_mid"),
                "monitor_last_exit": transition.get("last_exit"),
                "monitor_last_exec": transition.get("last_exec"),
                "monitor_last_tick_ts": transition.get("last_tick_ts"),
                "monitor_quote_text": str(transition.get("quote_text") or row.get("monitor_quote_text") or ""),
                "monitor_note": str(transition.get("note") or ""),
            }
            if label:
                self._studio_submit_progress(row, label, auto=True,
                                             display_status=new_status,
                                             monitor_result={**transition, **monitor_fields})
                return
            for key, value in monitor_fields.items():
                if row.get(key) != value:
                    row[key] = value
                    changed = True
            if new_status != old_status:
                row["status"] = new_status
                changed = True
        if checked and (changed or time.time() - float(getattr(self, "_studio_monitor_last_persist", 0.0) or 0.0) >= 30.0):
            self._studio_monitor_last_persist = time.time()
            if changed:
                self._studio_persist_publications()
            else:
                self._studio_refresh_publications()
        if checked:
            self._studio_show_publication_details()

    def _studio_auto_progress_check(self):
        """Update linked journal outcomes and poll read-only MT5 quotes when opted in."""
        if getattr(self, "_studio_busy", False):
            return
        rows = list(getattr(self, "studio_publications", []) or [])
        if not rows:
            return
        retry_after = getattr(self, "_studio_auto_retry_after", {})
        trades_by_id = {str(t.get("id")): t for t in list(getattr(E, "TRADES", []) or [])
                        if t.get("id") is not None}
        now = time.time()
        for row in reversed(rows):
            mode = str(row.get("tracking_mode") or "").upper()
            if mode == "MT5_AUTO":
                continue
            if mode not in ("", "JOURNAL_AUTO"):
                continue
            trade_ids = [str(x) for x in (row.get("local_trade_ids") or [])]
            if not row.get("auto_progress") or not trade_ids or not row.get("targets"):
                continue
            rid = str(row.get("id") or "")
            if float(retry_after.get(rid, 0) or 0) > now:
                continue
            trades = [trades_by_id[x] for x in trade_ids if x in trades_by_id]
            if not trades:
                continue
            events = self._studio_active_progress_events(row)
            done_tp = 0
            for ev in events:
                match = re.match(r"TP\s*(\d+)", str(ev.get("label") or "").upper())
                if match and "HIT" in str(ev.get("label") or "").upper():
                    done_tp = max(done_tp, int(match.group(1)))
            hit_levels = []
            for trade in trades:
                tag = str(trade.get("tag") or "").lower()
                match = re.fullmatch(r"tp(\d+)", tag)
                if match and str(trade.get("status") or "").lower() == "closed" \
                        and str(trade.get("result") or "").lower() == "tp":
                    hit_levels.append(int(match.group(1)))
            reached = max(hit_levels or [0])
            if reached > done_tp:
                self._studio_submit_progress(row, f"TP{reached} HIT", auto=True)
                return
            labels = {str(ev.get("label") or "").upper() for ev in events}
            if "SL HIT" not in labels and any(
                    str(t.get("status") or "").lower() == "closed"
                    and str(t.get("result") or "").lower() == "sl" for t in trades):
                self._studio_submit_progress(row, "SL HIT", auto=True)
                return
            if "BREAK EVEN" not in labels and any(
                    str(t.get("status") or "").lower() == "closed"
                    and str(t.get("result") or "").lower() == "be" for t in trades):
                self._studio_submit_progress(row, "BREAK EVEN", auto=True)
                return
            state_events = [str(ev.get("label") or "").upper() for ev in events
                            if str(ev.get("label") or "").upper() in
                            ("PENDING", "OPEN", "OPEN + PENDING")]
            trade_states = {str(t.get("status") or "").lower() for t in trades}
            has_open, has_pending = "open" in trade_states, "pending" in trade_states
            desired_state = ("OPEN + PENDING" if has_open and has_pending else
                             "OPEN" if has_open else "PENDING" if has_pending else "")
            latest_state = state_events[-1] if state_events else ""
            if desired_state and (latest_state != desired_state or
                                  str(row.get("status") or "").upper() != desired_state):
                self._studio_submit_progress(row, desired_state, auto=True,
                                             display_status=desired_state)
                return
            terminal_states = {"closed", "cancelled", "rejected", "expired"}
            all_closed_by_tp = (trade_states == {"closed"} and bool(trades) and
                                all(str(t.get("result") or "").lower() == "tp" for t in trades))
            if (trade_states and trade_states <= terminal_states and not all_closed_by_tp and not any(
                    label in labels for label in ("SL HIT", "BREAK EVEN", "CLOSED", "CANCELLED"))):
                label = "CANCELLED" if trade_states <= {"cancelled", "rejected", "expired"} else "CLOSED"
                self._studio_submit_progress(row, label, auto=True,
                                             display_status=label)
                return
        self._studio_request_monitor_snapshot(rows)

    def _studio_toggle_manual_mirror(self):
        """Explicitly opt in to posting future magic=0 MT5 orders to chosen chats."""
        requested = bool(getattr(self, "studio_manual_mirror_var", None).get()) \
            if getattr(self, "studio_manual_mirror_var", None) is not None else False
        if not requested:
            self._studio_manual_mirror_enabled = False
            self._studio_manual_mirror_targets = []
            self._studio_manual_mirror_awaiting_baseline = False
            try:
                self.studio_manual_mirror_status_var.set(
                    "OFF · no new manual MT5 order posts will be sent; existing Telegram posts remain unchanged.")
            except Exception:
                pass
            return
        targets = self._studio_selected_publish_chats()
        if not targets:
            self.studio_manual_mirror_var.set(False)
            self._studio_manual_mirror_enabled = False
            self.studio_manual_mirror_status_var.set("Select one or more Telegram destinations above first.")
            return
        if ProviderStudio is None or not callable(getattr(ProviderStudio, "manual_trade_mirror_caption", None)):
            self.studio_manual_mirror_var.set(False)
            self._studio_manual_mirror_enabled = False
            self.studio_manual_mirror_status_var.set("Manual MT5 mirror helper is unavailable; feature remains OFF.")
            return
        names = ", ".join(str(row.get("name") or row.get("id")) for row in targets[:8])
        if len(targets) > 8:
            names += f" +{len(targets)-8} more"
        if not messagebox.askyesno(
                "Enable manual MT5 order copy",
                "Copy only manual MT5 orders/positions (magic=0) to these Telegram destinations?\n\n"
                f"{names}\n\n"
                "EA/algorithm tickets are excluded. Existing open/pending orders are baselined and will NOT be posted. "
                "New orders are read-only mirrored; this feature never places or modifies MT5 orders. "
                "Telegram messages/updates will be sent as each destination group/channel itself "
                "(basic groups use your signed-in account; channels/supergroups require target Send As). "
                "Telegram messages/updates will be sent while this option is enabled.", parent=self.root):
            self.studio_manual_mirror_var.set(False)
            self._studio_manual_mirror_enabled = False
            return
        self._studio_manual_mirror_targets = [
            {"id": int(row["id"]), "name": str(row.get("name") or "Telegram destination")}
            for row in targets if str(row.get("id", "")).lstrip("-").isdigit()]
        self._studio_manual_mirror_enabled = bool(self._studio_manual_mirror_targets)
        self._studio_manual_mirror_awaiting_baseline = self._studio_manual_mirror_enabled
        self._studio_manual_mirror_baseline_after = time.time()
        if not self._studio_manual_mirror_enabled:
            self.studio_manual_mirror_var.set(False)
            self.studio_manual_mirror_status_var.set("No valid destination IDs; mirror remains OFF.")
            return
        self.studio_manual_mirror_status_var.set(
            "Checking the connected MT5 snapshot. Existing magic=0 orders will be skipped; future orders only.")
        self.poll_mt5(schedule=False)

    @staticmethod
    def _studio_manual_mirror_num(value):
        try:
            number = float(str(value if value is not None else "").replace(",", "").strip())
            return number if math.isfinite(number) else None
        except Exception:
            return None

    def _studio_manual_mirror_row_key(self, row):
        try:
            if int(row.get("magic", -1)) != 0:
                return ""
        except Exception:
            return ""
        try:
            if ProviderStudio is not None:
                return str(ProviderStudio.manual_trade_mirror_key(row) or "")
            ticket = int(row.get("ticket") or row.get("order_ticket") or 0)
            return f"{str(row.get('broker') or 'MAIN').upper()}:{ticket}" if ticket > 0 else ""
        except Exception:
            return ""

    def _studio_manual_mirror_live_rows(self, snapshot):
        rows = []
        for row in (snapshot.get("manage_rows") or []) if isinstance(snapshot, dict) else []:
            if not isinstance(row, dict):
                continue
            if self._studio_manual_mirror_row_key(row):
                rows.append(dict(row))
        return rows

    def _studio_manual_record_aliases(self, record):
        ids = set()
        for key in ("ticket", "position_id"):
            try:
                value = int(record.get(key) or 0)
                if value > 0:
                    ids.add(value)
            except Exception:
                pass
        for key in ("alias_tickets", "alias_position_ids"):
            for value in record.get(key) or []:
                try:
                    value = int(value)
                    if value > 0:
                        ids.add(value)
                except Exception:
                    pass
        return ids

    def _studio_manual_mirror_matches(self, record, trade, allow_fuzzy=False):
        if not isinstance(record, dict) or not isinstance(trade, dict):
            return False
        if str(record.get("broker") or "MAIN").upper() != str(trade.get("broker") or "MAIN").upper():
            return False
        aliases = self._studio_manual_record_aliases(record)
        try:
            trade_ids = {int(trade.get("ticket") or 0), int(trade.get("position_id") or 0),
                         int(trade.get("identifier") or 0), int(trade.get("order_ticket") or 0)} - {0}
        except Exception:
            trade_ids = set()
        if aliases.intersection(trade_ids):
            return True
        if not allow_fuzzy:
            return False
        saved = record.get("trade_snapshot") if isinstance(record.get("trade_snapshot"), dict) else {}
        if str(saved.get("kind") or "").upper() not in ("PENDING", "OPEN", "LIVE"):
            return False
        if str(saved.get("symbol") or "").upper() != str(trade.get("symbol") or "").upper():
            return False
        if str(saved.get("direction") or "").upper() != str(trade.get("direction") or "").upper():
            return False
        entry_a = self._studio_manual_mirror_num(saved.get("entry"))
        entry_b = self._studio_manual_mirror_num(trade.get("entry"))
        lot_a = self._studio_manual_mirror_num(saved.get("lot"))
        lot_b = self._studio_manual_mirror_num(trade.get("lot"))
        if entry_a is None or entry_b is None or lot_a is None or lot_b is None:
            return False
        try:
            pip = float(E.pip_size_of(str(saved.get("symbol") or "")) or 0.0)
        except Exception:
            pip = 0.0
        entry_tol = max(pip * 3.0, abs(entry_a) * 1e-6, 1e-5)
        lot_tol = max(1e-8, abs(lot_a) * 1e-5)
        if abs(entry_a - entry_b) > entry_tol or abs(lot_a - lot_b) > lot_tol:
            return False
        try:
            created = float(record.get("created_ts") or 0.0)
            opened = float(trade.get("opened_ts") or trade.get("time") or 0.0)
            if created and opened and abs(opened - created) > 7 * 86400:
                return False
        except Exception:
            pass
        return True

    def _studio_manual_mirror_caption_for_record(self, record, target_name=""):
        """Public Telegram signal caption, branded for the exact destination."""
        saved = dict(record.get("trade_snapshot") or {})
        saved["magic"] = 0
        caption = ProviderStudio.manual_trade_mirror_caption(saved, state=record.get("status"),
                                                           destination_name=target_name)
        extra = []
        pips = self._studio_manual_mirror_num(record.get("actual_pips"))
        net = self._studio_manual_mirror_num(record.get("net_total"))
        if pips is not None:
            extra.append(f"Realized distance: {pips:+.1f} pips")
        if net is not None:
            extra.append(f"MT5 net: {net:+.2f}")
        if record.get("close_price") not in (None, "", 0, 0.0):
            extra.append(f"Close: {record.get('close_price')}")
        if extra:
            caption += "\n" + " · ".join(extra)
        if len(caption.encode("utf-16-le")) // 2 > 1000:
            caption = caption[:930].rstrip() + "…"
        return caption

    def _studio_manual_mirror_save(self):
        try:
            self._studio_manual_mirror_posts = self._studio_manual_mirror_posts[-500:]
            save_studio_manual_mirror_posts(self._studio_manual_mirror_posts)
        except Exception as exc:
            q_log(f"Provider manual-order mirror could not be saved: {exc}", "err")

    def _studio_refresh_manual_mirror_view(self):
        tree = getattr(self, "studio_manual_mirror_tree", None)
        if tree is None:
            return
        try:
            children = tree.get_children()
            if children:
                tree.delete(*children)
            mirror_records = list(reversed(self._studio_manual_mirror_posts[-200:]))
            view_var = getattr(self, "studio_manual_mirror_filter_var", None)
            view = str(view_var.get() if view_var is not None else "ALL").upper()
            if view != "ALL":
                filtered = []
                for record in mirror_records:
                    trade = record.get("trade_snapshot") if isinstance(record.get("trade_snapshot"), dict) else {}
                    kind = str(trade.get("kind") or "").upper()
                    raw_type = str(trade.get("order_type") or trade.get("order_kind") or "").upper().replace("_", " ")
                    order_kind = str(trade.get("order_kind") or "").upper()
                    category = ("MARKET" if kind in ("OPEN", "LIVE") or raw_type == "MARKET" else
                                "LIMIT" if order_kind == "LIMIT" or
                                ("LIMIT" in raw_type and "STOP" not in raw_type) else
                                "STOP" if "STOP" in raw_type or "STOP" in order_kind else "OTHER")
                    if category == view:
                        filtered.append(record)
                mirror_records = filtered
            for index, record in enumerate(mirror_records):
                trade = record.get("trade_snapshot") if isinstance(record.get("trade_snapshot"), dict) else {}
                try:
                    when = datetime.fromtimestamp(float(record.get("created_ts") or 0)).strftime("%m-%d %H:%M")
                except Exception:
                    when = "—"
                kind = str(trade.get("kind") or "").upper()
                order_type = ("MARKET" if kind in ("OPEN", "LIVE") else
                              str(trade.get("order_type") or trade.get("order_kind") or "PENDING").replace("_", " "))
                targets = record.get("targets") or []
                names = ", ".join(str(row.get("name") or row.get("id")) for row in targets[:3]) or "—"
                status = str(record.get("status") or "—")
                if str(record.get("send_state") or "").upper() in ("PARTIAL", "REVIEW NEEDED"):
                    status += " · SEND REVIEW"
                iid = f"manual_mirror_{index}"
                tree.insert("", "end", iid=iid, values=(
                    when, trade.get("symbol") or "—", trade.get("direction") or "—", order_type[:18],
                    trade.get("entry") or "—", trade.get("market_price") or trade.get("current") or "—",
                    trade.get("sl") or "—", trade.get("tp") or "—", status[:35], names[:70]))
        except Exception as exc:
            q_log(f"Provider manual-order mirror view refresh failed: {exc}", "warn")

    def _studio_manual_mirror_reconcile(self, snapshot, live_rows):
        changed = False
        terminal = {"TP HIT", "SL HIT", "BREAK EVEN", "CLOSED", "CLOSED (MANUAL)", "CANCELLED"}
        posts = list(self._studio_manual_mirror_posts or [])
        # Attach a newly observed live position to a unique earlier pending ticket when MT5
        # assigns a different position ticket after the pending order is filled.
        for live in live_rows:
            if str(live.get("kind") or "").upper() != "OPEN":
                continue
            matches = [record for record in posts
                       if str(record.get("status") or "").upper() not in terminal
                       and self._studio_manual_mirror_matches(record, live, allow_fuzzy=True)]
            if len(matches) == 1:
                record = matches[0]
                key = self._studio_manual_mirror_row_key(live)
                if key:
                    self._studio_manual_mirror_seen.add(key)
                saved = record.get("trade_snapshot") if isinstance(record.get("trade_snapshot"), dict) else {}
                prior_status = str(record.get("status") or "").upper()
                old_levels = (saved.get("sl"), saved.get("tp"))
                new_levels = (live.get("sl"), live.get("tp"))
                if prior_status != "OPEN" or old_levels != new_levels:
                    record["trade_snapshot"] = dict(live)
                    record["trade_snapshot"]["magic"] = 0
                    record["status"] = "OPEN"
                    record["last_updated_ts"] = time.time()
                    record["position_id"] = int(live.get("position_id") or live.get("ticket") or 0)
                    record.setdefault("alias_tickets", [])
                    record.setdefault("alias_position_ids", [])
                    for target_key, value in (("alias_tickets", live.get("ticket")),
                                              ("alias_position_ids", live.get("position_id") or live.get("ticket"))):
                        try:
                            value = int(value or 0)
                            if value > 0 and value not in record[target_key]:
                                record[target_key].append(value)
                        except Exception:
                            pass
                    changed = True
        closed_rows = [dict(row) for row in (snapshot.get("trades") or [])
                       if isinstance(row, dict) and str(row.get("status") or "").upper() == "CLOSED"
                       and int(row.get("magic", -1) or 0) == 0]
        for record in posts:
            if str(record.get("status") or "").upper() in terminal:
                continue
            saved = record.get("trade_snapshot") if isinstance(record.get("trade_snapshot"), dict) else {}
            live = next((row for row in live_rows
                         if self._studio_manual_mirror_matches(record, row, allow_fuzzy=False)), None)
            if live is not None:
                row_status = "OPEN" if str(live.get("kind") or "").upper() == "OPEN" else "PENDING"
                old_levels = (saved.get("sl"), saved.get("tp"))
                new_levels = (live.get("sl"), live.get("tp"))
                if str(record.get("status") or "").upper() != row_status or old_levels != new_levels:
                    record["trade_snapshot"] = dict(live)
                    record["trade_snapshot"]["magic"] = 0
                    record["status"] = row_status
                    record["last_updated_ts"] = time.time()
                    changed = True
                continue
            candidates = [trade for trade in closed_rows
                          if self._studio_manual_mirror_matches(record, trade, allow_fuzzy=True)]
            if len(candidates) != 1:
                continue
            trade = candidates[0]
            result = str(trade.get("result") or "").lower()
            status = {"tp": "TP HIT", "sl": "SL HIT", "be": "BREAK EVEN"}.get(
                result, "CLOSED (MANUAL)" if result == "manual" else "CLOSED")
            close_px = self._studio_manual_mirror_num(trade.get("current"))
            entry = self._studio_manual_mirror_num(saved.get("entry"))
            direction = str(saved.get("direction") or trade.get("direction") or "BUY").upper()
            try:
                pip = float(E.pip_size_of(str(saved.get("symbol") or trade.get("symbol") or "")) or 0.0)
            except Exception:
                pip = 0.0
            actual_pips = None
            if close_px is not None and entry is not None and pip > 0:
                actual_pips = ((close_px - entry) / pip) * (-1.0 if direction == "SELL" else 1.0)
            record["status"] = status
            record["closed_ts"] = self._studio_manual_mirror_num(trade.get("closed_ts")) or time.time()
            record["last_updated_ts"] = time.time()
            record["close_price"] = close_px
            record["actual_pips"] = actual_pips
            record["net_total"] = self._studio_manual_mirror_num(trade.get("net_total"))
            record["trade_snapshot"] = {**saved, "magic": 0, "kind": "OPEN",
                                        "market_price": close_px or saved.get("market_price"),
                                        "current": close_px or saved.get("current"),
                                        "sl": trade.get("sl", saved.get("sl")),
                                        "tp": trade.get("tp", saved.get("tp"))}
            changed = True
        if changed:
            self._studio_manual_mirror_save()
            self._studio_refresh_manual_mirror_view()
        updates = []
        for record in posts:
            if not record.get("targets") or str(record.get("send_state") or "").upper() not in ("SENT", "PARTIAL"):
                continue
            for target in record.get("targets") or []:
                try:
                    message_id = int(target.get("message_id") or 0)
                    chat_id = int(target.get("id") or 0)
                except Exception:
                    continue
                target_name = str(target.get("name") or "Telegram Signals")
                try:
                    caption = self._studio_manual_mirror_caption_for_record(
                        record, target_name=target_name)
                except Exception as exc:
                    record["update_error"] = str(exc)
                    changed = True
                    continue
                if message_id > 0 and chat_id and str(target.get("last_caption") or "") != caption:
                    updates.append({"mirror_key": record.get("mirror_key"), "chat_id": chat_id,
                                   "message_id": message_id, "caption": caption})
        if changed:
            self._studio_manual_mirror_save()
            self._studio_refresh_manual_mirror_view()
        return updates

    def _studio_manual_mirror_send_new(self, records):
        if not records or getattr(self, "_studio_busy", False) or getattr(self, "_studio_manual_mirror_busy", False):
            return
        self._studio_manual_mirror_busy = True
        payload = [dict(record) for record in records]
        targets = [dict(row) for row in (self._studio_manual_mirror_targets or [])]
        logo_path = str(getattr(self, "studio_logo_path", "") or "")

        async def send_batch(batch, destinations, logo, client=None):
            results = []
            for record in batch:
                sent, failed = [], []
                for destination in destinations:
                    destination_name = str(destination.get("name") or "Telegram Signals")
                    caption = self._studio_manual_mirror_caption_for_record(
                        record, target_name=destination_name)
                    try:
                        message_id = await E.telegram_studio_send_signal(
                            destination["id"], caption, logo, client=client)
                        sent.append({"id": int(destination["id"]),
                                     "name": destination_name,
                                     "message_id": int(message_id or 0), "last_caption": caption})
                    except Exception as exc:
                        failed.append(f"{destination.get('name') or destination.get('id')}: {type(exc).__name__}: {exc}")
                results.append({"mirror_key": record.get("mirror_key"), "targets": sent,
                                "failed": failed, "caption": (sent[0].get("last_caption") if sent else "")})
            return results

        def done(results):
            by_key = {str(row.get("mirror_key") or ""): row
                      for row in (self._studio_manual_mirror_posts or [])}
            total_sent, total_failed = 0, 0
            for result in results or []:
                record = by_key.get(str(result.get("mirror_key") or ""))
                if record is None:
                    continue
                sent = list(result.get("targets") or [])
                failed = list(result.get("failed") or [])
                record["targets"] = sent
                record["last_caption"] = str(result.get("caption") or "")
                record["send_state"] = "SENT" if not failed and sent else (
                    "PARTIAL" if sent else "REVIEW NEEDED")
                record["send_error"] = "; ".join(failed)[:600]
                record["sent_ts"] = time.time() if sent else None
                total_sent += len(sent)
                total_failed += len(failed)
            self._studio_manual_mirror_busy = False
            self._studio_manual_mirror_save()
            self._studio_refresh_manual_mirror_view()
            if total_failed:
                self.studio_manual_mirror_status_var.set(
                    f"Manual mirror sent to {total_sent} destination(s); {total_failed} send(s) need review. No automatic retry to avoid duplicates.")
            else:
                self.studio_manual_mirror_status_var.set(
                    f"Manual magic=0 order mirrored to {total_sent} destination(s). Status updates are monitored read-only.")

        def failed(error):
            by_key = {str(row.get("mirror_key") or ""): row
                      for row in (self._studio_manual_mirror_posts or [])}
            for record in records:
                item = by_key.get(str(record.get("mirror_key") or ""))
                if item is not None:
                    item["send_state"] = "REVIEW NEEDED"
                    item["send_error"] = str(error)[:600]
            self._studio_manual_mirror_busy = False
            self._studio_manual_mirror_save()
            self._studio_refresh_manual_mirror_view()
            self.studio_manual_mirror_status_var.set(
                "Manual-order send could not be confirmed; review the local tracker. Automatic resend is disabled to avoid duplicates.")

        self._studio_run_async("Mirroring manual MT5 order", send_batch,
                               args=(payload, targets, logo_path),
                               status=getattr(self, "studio_manual_mirror_status", None),
                               on_success=done, on_error=failed, timeout=300.0)

    def _studio_manual_mirror_send_updates(self, updates):
        if not updates or getattr(self, "_studio_busy", False) or getattr(self, "_studio_manual_mirror_busy", False):
            return
        self._studio_manual_mirror_busy = True
        payload = [dict(item) for item in updates]

        async def edit_batch(batch, client=None):
            results = []
            for item in batch:
                try:
                    await E.telegram_studio_edit_signal(
                        item["chat_id"], item["message_id"], item["caption"], client=client)
                    results.append({**item, "ok": True, "error": ""})
                except Exception as exc:
                    results.append({**item, "ok": False,
                                    "error": f"{type(exc).__name__}: {exc}"})
            return results

        def done(results):
            by_key = {str(row.get("mirror_key") or ""): row
                      for row in (self._studio_manual_mirror_posts or [])}
            failures = 0
            for result in results or []:
                record = by_key.get(str(result.get("mirror_key") or ""))
                if record is None:
                    continue
                target = next((row for row in (record.get("targets") or [])
                               if int(row.get("id") or 0) == int(result.get("chat_id") or 0)
                               and int(row.get("message_id") or 0) == int(result.get("message_id") or 0)), None)
                if not target:
                    continue
                if result.get("ok"):
                    target["last_caption"] = str(result.get("caption") or "")
                    target.pop("last_error", None)
                else:
                    target["last_error"] = str(result.get("error") or "edit failed")[:400]
                    failures += 1
            self._studio_manual_mirror_busy = False
            self._studio_manual_mirror_save()
            self._studio_refresh_manual_mirror_view()
            self.studio_manual_mirror_status_var.set(
                f"Manual MT5 status updated in Telegram posts ({len(results or []) - failures}/{len(results or [])} successful)." +
                (" Some edits remain pending for review." if failures else ""))

        def failed(error):
            self._studio_manual_mirror_busy = False
            self.studio_manual_mirror_status_var.set(f"Manual MT5 post edit failed: {str(error)[:240]}")

        self._studio_run_async("Updating manual MT5 mirror posts", edit_batch,
                               args=(payload,), status=getattr(self, "studio_manual_mirror_status", None),
                               on_success=done, on_error=failed, timeout=300.0)

    def _studio_manual_mirror_process_snapshot(self, snapshot):
        if not getattr(self, "_studio_manual_mirror_enabled", False):
            return
        snapshot = snapshot if isinstance(snapshot, dict) else {}
        if snapshot.get("status") != "connected":
            try:
                self.studio_manual_mirror_status_var.set(
                    "Manual mirror is ON but MT5 is not connected; waiting. No order was sent or changed.")
            except Exception:
                pass
            return
        try:
            updated_ts = float(snapshot.get("updated_ts") or 0.0)
        except Exception:
            updated_ts = 0.0
        baseline_after = float(getattr(self, "_studio_manual_mirror_baseline_after", 0.0) or 0.0)
        live_rows = self._studio_manual_mirror_live_rows(snapshot)
        if getattr(self, "_studio_manual_mirror_awaiting_baseline", False):
            if updated_ts < baseline_after:
                return
            for row in live_rows:
                key = self._studio_manual_mirror_row_key(row)
                if key:
                    self._studio_manual_mirror_seen.add(key)
            self._studio_manual_mirror_awaiting_baseline = False
            self.studio_manual_mirror_status_var.set(
                f"Baseline ready ({len(live_rows)} existing manual order(s) skipped). Copying only new magic=0 orders.")
        if getattr(self, "_studio_busy", False) or getattr(self, "_studio_manual_mirror_busy", False):
            return
        updates = self._studio_manual_mirror_reconcile(snapshot, live_rows)
        if updates:
            self._studio_manual_mirror_send_updates(updates)
            return
        existing = {str(row.get("mirror_key") or "") for row in (self._studio_manual_mirror_posts or [])}
        new_records = []
        for row in live_rows:
            key = self._studio_manual_mirror_row_key(row)
            if not key or key in self._studio_manual_mirror_seen or key in existing:
                continue
            try:
                caption_probe = ProviderStudio.manual_trade_mirror_caption(row)
            except Exception as exc:
                q_log(f"Manual MT5 mirror skipped an invalid row: {exc}", "warn")
                self._studio_manual_mirror_seen.add(key)
                continue
            try:
                ticket = int(row.get("ticket") or row.get("order_ticket") or 0)
                position_id = int(row.get("position_id") or row.get("identifier") or 0)
            except Exception:
                ticket, position_id = 0, 0
            record = {"mirror_key": key, "broker": str(row.get("broker") or "MAIN").upper(),
                      "ticket": ticket, "position_id": position_id,
                      "alias_tickets": [ticket] if ticket else [],
                      "alias_position_ids": [position_id] if position_id else [],
                      "created_ts": time.time(), "trade_snapshot": {**dict(row), "magic": 0},
                      "status": "PENDING" if str(row.get("kind") or "").upper() == "PENDING" else "OPEN",
                      "send_state": "SENDING", "targets": [], "last_caption": "",
                      "order_caption_preview": caption_probe}
            self._studio_manual_mirror_posts.append(record)
            self._studio_manual_mirror_seen.add(key)
            existing.add(key)
            new_records.append(record)
        if new_records:
            # Persist the send intent before the network side effect. Ambiguous failures
            # are held for manual review rather than automatically duplicating Telegram posts.
            self._studio_manual_mirror_save()
            self._studio_refresh_manual_mirror_view()
            self._studio_manual_mirror_send_new(new_records)
        else:
            self._studio_refresh_manual_mirror_view()

    def studio_auto_update_publications(self):
        """Run on the UI heartbeat: journal tracking, quote checks and opted-in EOD reports."""
        try:
            self._studio_auto_progress_check()
        except Exception as exc:
            q_log(f"automatic Studio progress check: {exc}", "warn")
        try:
            self.studio_daily_report_tick()
        except Exception as exc:
            q_log(f"automatic Provider EOD report check: {exc}", "warn")

    def studio_edit_publication(self):
        row = self._studio_selected_publication()
        if not row:
            self.studio_tracker_status_var.set("Select a published signal to edit first.")
            return
        if not row.get("targets"):
            self.studio_tracker_status_var.set("This signal has no active Telegram posts to update.")
            return
        try:
            message = self._studio_signal_message()
            composer = self._studio_composer_payload()
        except Exception as exc:
            self.studio_tracker_status_var.set(f"Check the composer fields first: {exc}")
            return
        old = row.get("composer") if isinstance(row.get("composer"), dict) else {}
        old_entry = str(old.get("entry") or "—") + (
            f" - {old.get('range_end')}" if old.get("range_end") else "")
        new_entry = str(composer.get("entry") or "—") + (
            f" - {composer.get('range_end')}" if composer.get("range_end") else "")
        changes = []
        for key, title in (("entry", "Entry"), ("sl", "SL"), ("tp_levels", "TP levels")):
            if old.get(key) != composer.get(key):
                before = old_entry if key == "entry" else str(old.get(key) or "—")
                after = new_entry if key == "entry" else str(composer.get(key) or "—")
                changes.append(f"{title}: {before} → {after}")
        if not changes:
            changes = ["Signal caption / other composer fields"]
        if not messagebox.askyesno(
                "Edit published signal",
                f"Update the original Telegram post(s) in {len(row.get('targets') or [])} destination(s)?\n\n"
                + "\n".join(changes[:6]) + "\n\n"
                "This edits Telegram captions only. It does NOT place, cancel, or modify any MT5 order. "
                "Any broker order change must be handled separately and explicitly.", parent=self.root):
            return

        old_composer = dict(old)
        old_message = str(row.get("message") or "")

        async def edit_all(client=None):
            changed, failed = [], []
            for target in list(row.get("targets") or []):
                try:
                    target_message = self._studio_signal_message_for_destination(
                        message, target.get("name") or target.get("id"))
                    await E.telegram_studio_edit_signal(
                        target["id"], target["message_id"], target_message, client=client)
                    changed.append(target)
                except Exception as exc:
                    failed.append({"target": target, "error": f"{type(exc).__name__}: {exc}"})
            return {"changed": changed, "failed": failed}

        def done(result):
            changed = list(result.get("changed") or [])
            failed = list(result.get("failed") or [])
            if not changed:
                self.studio_tracker_status_var.set(
                    f"No Telegram posts were edited; {len(failed)} failed. Local signal values were not changed.")
                return
            try:
                old_revision = max(1, int(row.get("level_revision") or 1))
            except Exception:
                old_revision = 1
            new_revision = old_revision + 1
            row.setdefault("edit_history", []).append({
                "revision": old_revision, "ts": time.time(), "composer": old_composer,
                "message": old_message,
                "linked_trade_ids": list(row.get("local_trade_ids") or [])})
            row["level_revision"] = new_revision
            row["message"] = message
            row["composer"] = composer
            row["tp_levels"] = list(composer.get("tp_levels") or [])
            row["order_type"] = str(composer.get("order_type") or row.get("order_type") or "LIMIT")
            row["status"] = "PUBLISHED"
            row.setdefault("progress_events", []).append({
                "label": "EDITED", "kind": "EDITED", "ts": time.time(),
                "time": datetime.now().strftime("%Y-%m-%d %H:%M"),
                "source": "provider", "revision": new_revision})
            row["last_edit_ts"] = time.time()
            row["monitor_last_mid"] = None
            row["monitor_last_exit"] = None
            row["monitor_last_exec"] = None
            row["monitor_last_tick_ts"] = None
            row["monitor_quote_text"] = ""
            if row.get("tracking_mode") == "MT5_AUTO":
                row["monitor_start_ts"] = time.time()
                row["monitor_note"] = "Signal levels were edited; waiting for a new post-edit MT5 quote baseline. No MT5 order was changed."
            elif row.get("tracking_mode") == "JOURNAL_AUTO":
                row["tracking_mode"] = "MANUAL"
                row["auto_progress"] = False
                row["monitor_note"] = "Linked journal auto-tracking stopped after caption edit; existing MT5 trades were not changed."
            row["caption_update_failures"] = [dict(x) for x in failed]
            self._studio_persist_publications()
            note = f"Edited {len(changed)}/{len(row.get('targets') or [])} original post(s)"
            if failed:
                note += f" • {len(failed)} post(s) failed and may need a manual retry"
            note += " • MT5 orders unchanged"
            self.studio_tracker_status_var.set(note)

        self._studio_run_async("Editing published signal", edit_all,
                               status=self.studio_tracker_status,
                               buttons=[self.studio_next_tp_btn], on_success=done)

    def studio_delete_publication(self):
        row = self._studio_selected_publication()
        if not row:
            self.studio_tracker_status_var.set("Select a published signal to delete first.")
            return
        targets = list(row.get("targets") or [])
        if not targets:
            self.studio_tracker_status_var.set("This signal has no active Telegram posts.")
            return
        if not messagebox.askyesno(
                "Delete published signal",
                f"Delete this EdgeQuant post from {len(targets)} Telegram destination(s)?\n\n"
                "Telegram permissions determine whether each deletion succeeds. This does not change MT5 orders.",
                parent=self.root):
            return

        async def delete_all(client=None):
            deleted, failed = [], []
            for target in targets:
                try:
                    await E.telegram_studio_delete_signal(
                        target["id"], target["message_id"], client=client)
                    deleted.append(target)
                except Exception as exc:
                    failed.append({"target": target, "error": f"{type(exc).__name__}: {exc}"})
            return {"deleted": deleted, "failed": failed}

        def done(result):
            failed = list(result.get("failed") or [])
            failed_ids = {str(item.get("target", {}).get("id")) + ":" +
                          str(item.get("target", {}).get("message_id")) for item in failed}
            row["targets"] = [target for target in targets
                              if str(target.get("id")) + ":" +
                                 str(target.get("message_id")) in failed_ids]
            row["status"] = "DELETE PARTIAL" if failed else "DELETED"
            self._studio_persist_publications()
            self.studio_tracker_status_var.set(
                f"Deleted {len(result.get('deleted') or [])}/{len(targets)} posts" +
                (f" • {len(failed)} failed" if failed else ""))

        self._studio_run_async("Deleting published signal", delete_all,
                               status=self.studio_tracker_status,
                               buttons=[self.studio_next_tp_btn], on_success=done)

    def _studio_report_plan_data(self):
        plan = dict(getattr(self, "plan_data", {}) or {})
        try:
            # Export the values currently visible in the Trading Plan form, even if
            # the user has not yet pressed GENERATE after editing an input.
            values = self.plan_values()
            kwargs = {k: values[k] for k in ("capital", "win", "rr", "risk", "target")
                      if values.get(k) is not None}
            if values.get("months"):
                kwargs["months"] = int(values["months"])
            if values.get("days"):
                kwargs["days"] = int(values["days"])
            if values.get("trades_day"):
                kwargs["trades_day"] = int(values["trades_day"])
            kwargs["per"] = values.get("per") or "DAYS"
            plan = dict(E.trading_plan(**kwargs))
        except Exception:
            if not plan.get("table"):
                plan = {}
        try:
            state = dict(E.daily_target_state() or {})
        except Exception as exc:
            state = {"target": 0.0, "net": 0.0, "progress_net": 0.0,
                     "done_pct": 0.0, "remaining": 0.0, "achieved": False,
                     "error": f"{type(exc).__name__}: {exc}"}
        plan["daily_target_status"] = {
            "target": state.get("target"), "net": state.get("net"),
            "floating": state.get("floating"), "progress_net": state.get("progress_net"),
            "done_pct": state.get("done_pct"), "remaining": state.get("remaining"),
            "achieved": state.get("achieved"), "error": state.get("error", "")}
        return plan, state

    @staticmethod
    def _studio_successful_signal_destinations(publications, start_ts, end_ts):
        """Unique chats that actually received a Provider signal within the requested local-day window."""
        by_id = {}
        for publication in publications or []:
            if not isinstance(publication, dict):
                continue
            try:
                created = float(publication.get("created_ts") or 0.0)
            except Exception:
                continue
            if created < float(start_ts) or created > float(end_ts):
                continue
            for target in publication.get("targets") or []:
                if not isinstance(target, dict):
                    continue
                try:
                    chat_id = int(target.get("id"))
                    message_id = int(target.get("message_id") or 0)
                except Exception:
                    continue
                if chat_id == 0 or message_id <= 0:
                    continue
                row = by_id.setdefault(chat_id, {"id": chat_id,
                    "name": str(target.get("name") or chat_id), "signals": 0})
                row["signals"] += 1
        return sorted(by_id.values(), key=lambda row: str(row.get("name") or "").casefold())

    def _studio_daily_report_targets_for_day(self, now=None):
        now = now if isinstance(now, datetime) else datetime.now().astimezone()
        if now.tzinfo is None:
            now = now.astimezone()
        start = now.replace(hour=0, minute=0, second=0, microsecond=0).timestamp()
        return self._studio_successful_signal_destinations(
            getattr(self, "studio_publications", []) or [], start, now.timestamp())

    def _studio_daily_report_refresh_status(self):
        if not hasattr(self, "studio_daily_report_status_var"):
            return
        now = datetime.now().astimezone()
        targets = self._studio_daily_report_targets_for_day(now)
        names = ", ".join(str(row.get("name") or row.get("id")) for row in targets[:4])
        if len(targets) > 4:
            names += f" +{len(targets)-4}"
        if getattr(self, "studio_daily_report_enabled", False):
            text = (f"ON · {getattr(self, 'studio_daily_report_time', '23:58')} local time · "
                    f"today's sent-signal recipients are automatic: {len(targets)} · {names or 'none yet'} · PDF + Excel")
            color = GREEN if targets else AMBER
        else:
            text = (f"OFF · default time {getattr(self, 'studio_daily_report_time', '23:58')} local · "
                    "enable the schedule to send a PDF + Excel to today's signal destinations")
            color = MUTED
        self.studio_daily_report_status_var.set(text)
        try:
            self.studio_daily_report_status.configure(fg=color)
        except Exception:
            pass

    def _studio_capture_daily_report_targets(self):
        # Backward-compatible handler name: recipients are now derived from
        # successful publications for this local day, never manually captured.
        self._studio_preview_daily_report_targets()

    def _studio_preview_daily_report_targets(self):
        now = datetime.now().astimezone()
        targets = self._studio_daily_report_targets_for_day(now)
        if not targets:
            messagebox.showinfo("Today's report recipients",
                                "No successfully sent Provider signals are recorded for today yet. "
                                "No EOD files would be sent.", parent=self.root)
            return
        lines = [f"{row.get('name')}  ·  {row.get('signals', 0)} signal(s)"
                 for row in targets]
        messagebox.showinfo("Today's report recipients",
                            "At the opted-in local report time, a destination-specific PDF and Excel workbook will be sent to each chat below:\n\n"
                            + "\n".join(lines), parent=self.root)

    def _studio_daily_report_time_changed(self):
        time_var = getattr(self, "studio_daily_report_time_var", None)
        value = str(time_var.get() if time_var is not None else
                    getattr(self, "studio_daily_report_time", "23:58") or "").strip()
        try:
            parsed = datetime.strptime(value, "%H:%M")
            normalized = parsed.strftime("%H:%M")
        except Exception:
            self.studio_daily_report_status_var.set("Enter report time in 24-hour HH:MM format, e.g. 23:58.")
            return False
        self.studio_daily_report_time = normalized
        save_ui_prefs(studio_daily_report_time=normalized)
        self._studio_daily_report_refresh_status()
        return True

    def _studio_daily_report_toggle(self):
        requested = bool(self.studio_daily_report_var.get())
        if not requested:
            self.studio_daily_report_enabled = False
            self.studio_daily_report_bundle_optin = False
            save_ui_prefs(studio_daily_report_enabled=False, studio_daily_report_bundle_optin=False)
            self._studio_daily_report_refresh_status()
            return
        if not self._studio_daily_report_time_changed():
            self.studio_daily_report_var.set(False)
            return
        if not messagebox.askyesno(
                "Enable daily Provider PDF + Excel reports",
                f"At {self.studio_daily_report_time} local time, send a professional PDF + Excel bundle to every "
                "group/channel that successfully received at least one Provider signal today?\n\n"
                "Each destination receives a branded PDF and Excel workbook with its name as the report title, "
                "the Provider logo, and the EdgeQuant Sentinel footer. Only that day's successfully sent "
                "Signal Provider data is included. Basic groups use the signed-in account; channels/supergroups require the authorized destination identity. "
                "The app must remain open and Telegram logged in. Failed/uncertain sends are recorded and "
                "never automatically retried. Enable this opt-in schedule?",
                parent=self.root):
            self.studio_daily_report_var.set(False)
            return
        self.studio_daily_report_enabled = True
        self.studio_daily_report_bundle_optin = True
        save_ui_prefs(studio_daily_report_enabled=True,
                      studio_daily_report_bundle_optin=True,
                      studio_daily_report_time=self.studio_daily_report_time)
        self._studio_daily_report_refresh_status()

    def _studio_daily_report_delivery(self, key):
        return next((dict(row) for row in reversed(self.studio_report_deliveries or [])
                     if str(row.get("key") or "") == str(key)), None)

    def _studio_daily_report_store_delivery(self, row):
        key = str(row.get("key") or "")
        self.studio_report_deliveries = [item for item in (self.studio_report_deliveries or [])
                                         if str(item.get("key") or "") != key]
        self.studio_report_deliveries.append(dict(row))
        self.studio_report_deliveries = self.studio_report_deliveries[-2000:]
        save_studio_report_deliveries(self.studio_report_deliveries)

    @staticmethod
    def _studio_pips_split(values):
        values = [float(x) for x in (values or []) if isinstance(x, (int, float)) and math.isfinite(float(x))]
        return sum(x for x in values if x > 0), sum(x for x in values if x < 0)

    def _studio_build_daily_report_text(self, destination, now=None):
        if ProviderStudio is None:
            return ""
        now = now if isinstance(now, datetime) else datetime.now().astimezone()
        if now.tzinfo is None:
            now = now.astimezone()
        date_key = now.date().isoformat()
        start_ts = now.replace(hour=0, minute=0, second=0, microsecond=0).timestamp()
        try:
            chat_id = int(destination.get("id"))
        except Exception:
            return ""
        publications = []
        for row in (getattr(self, "studio_publications", []) or []):
            try:
                created = float(row.get("created_ts") or 0.0)
            except Exception:
                continue
            if created < start_ts or created > now.timestamp():
                continue
            if any(str(target.get("id")) == str(chat_id) for target in (row.get("targets") or [])):
                publications.append(dict(row))
        trades = self._studio_provider_journal_trades()
        signal_rows = ProviderStudio.provider_signal_rows(publications, trades=trades, engine=E)
        signal_rows.sort(key=lambda row: float(row.get("created_ts") or 0.0), reverse=True)
        manual_posts = []
        manual_terminal = {"TP HIT", "SL HIT", "BREAK EVEN", "CLOSED", "CLOSED (MANUAL)", "CANCELLED"}
        for record in (getattr(self, "_studio_manual_mirror_posts", []) or []):
            try:
                created_ts = float(record.get("created_ts") or 0.0)
                closed_ts = float(record.get("closed_ts") or 0.0)
                updated_ts = float(record.get("last_updated_ts") or 0.0)
            except Exception:
                continue
            status = str(record.get("status") or "").upper()
            if (max(created_ts, closed_ts, updated_ts) < start_ts
                    and status in manual_terminal):
                continue
            if any(str(target.get("id")) == str(chat_id) for target in (record.get("targets") or [])):
                manual_posts.append(record)
        if not signal_rows and not manual_posts:
            return ""
        wins = sum(1 for row in signal_rows if row.get("outcome") == "WIN")
        losses = sum(1 for row in signal_rows if row.get("outcome") == "LOSS")
        be = sum(1 for row in signal_rows if row.get("outcome") == "BE")
        decided = wins + losses
        win_rate = 100.0 * wins / decided if decided else None
        actual_pips = [row.get("actual_pips") for row in signal_rows if row.get("actual_pips") is not None]
        nominal_pips = [row.get("nominal_pips") for row in signal_rows if row.get("nominal_pips") is not None]
        actual_net = [row.get("actual_net") for row in signal_rows if row.get("actual_net") is not None]
        actual_up, actual_down = self._studio_pips_split(actual_pips)
        estimate_up, estimate_down = self._studio_pips_split(nominal_pips)
        manual_actual = [self._studio_manual_mirror_num(row.get("actual_pips")) for row in manual_posts]
        manual_actual = [x for x in manual_actual if x is not None]
        manual_up, manual_down = self._studio_pips_split(manual_actual)
        manual_nets = [self._studio_manual_mirror_num(row.get("net_total")) for row in manual_posts]
        manual_nets = [x for x in manual_nets if x is not None]
        destination_name = str(destination.get("name") or chat_id)
        lines = [f"📊 PROVIDER EOD · {date_key}", destination_name[:70]]
        if signal_rows:
            lines.append(f"Signals {len(signal_rows)} · W/L/BE {wins}/{losses}/{be} · "
                         f"Win rate {'—' if win_rate is None else f'{win_rate:.1f}%'}")
            lines.append("MT5 actual pips W/L: " +
                         (f"{actual_up:+.1f}/{actual_down:+.1f}" if actual_pips else "not recorded"))
            lines.append("MT5 actual net: " +
                         (f"{sum(actual_net):+,.2f}" if actual_net else "not recorded"))
            lines.append("Signal-level estimated pips W/L: " +
                         (f"{estimate_up:+.1f}/{estimate_down:+.1f}" if nominal_pips else "not recorded"))
            best_actual = [row for row in signal_rows if row.get("actual_net") is not None]
            best_nominal = [row for row in signal_rows if row.get("nominal_pips") is not None]
            best = (max(best_actual, key=lambda row: float(row.get("actual_net") or 0.0))
                    if best_actual else max(best_nominal,
                        key=lambda row: float(row.get("nominal_pips") or 0.0)) if best_nominal else None)
            if best:
                metric = (f"{float(best['actual_net']):+,.2f} USD" if best.get("actual_net") is not None
                          else f"{float(best.get('nominal_pips') or 0):+.1f} estimated pips")
                lines.append(f"Best: {best.get('symbol')} {best.get('direction')} · {metric}")
            lines.append("History:")
            for item in signal_rows[:4]:
                signal = next((row for row in publications if str(row.get("id")) == str(item.get("id"))), {})
                composer = signal.get("composer") if isinstance(signal.get("composer"), dict) else {}
                entry = str(item.get("entry") or "—")
                sl = str(item.get("sl") or "—")
                tps = str(item.get("tps") or "—")
                order_type = str(composer.get("order_type") or signal.get("order_type") or "LIMIT").upper()
                pips = (f"actual {float(item['actual_pips']):+.1f}p" if item.get("actual_pips") is not None else
                        f"est {float(item['nominal_pips']):+.1f}p" if item.get("nominal_pips") is not None else "pips —")
                try:
                    time_text = datetime.fromtimestamp(float(item.get("created_ts") or 0)).strftime("%H:%M")
                except Exception:
                    time_text = "--:--"
                lines.append(f"{time_text} {item.get('symbol')} {item.get('direction')} {order_type} "
                             f"E{entry} SL{sl} TP{tps} · {item.get('status')} · {pips}")
        if manual_posts:
            lines.append(f"Manual MT5 magic=0 mirrors: {len(manual_posts)}")
            if manual_actual:
                lines.append(f"Manual actual pips W/L {manual_up:+.1f}/{manual_down:+.1f} · "
                             f"net {sum(manual_nets):+,.2f}" if manual_nets else
                             f"Manual actual pips W/L {manual_up:+.1f}/{manual_down:+.1f}")
        text = "\n".join(lines)
        if len(text.encode("utf-16-le")) // 2 > 950:
            text = text[:930].rstrip() + "…"
        return text

    def studio_daily_report_tick(self):
        """Opt-in 23:58 Provider PDF + Excel delivery, once per local date and successful destination."""
        if (not getattr(self, "studio_daily_report_enabled", False) or
                not getattr(self, "studio_daily_report_bundle_optin", False)):
            return
        role = str(getattr(self, "app_role", "") or
                   getattr(getattr(self, "cloud_role_var", None), "get", lambda: "")() or "").lower()
        if role != "provider" or getattr(self, "local_role_mode", False):
            return
        now_ts = time.time()
        if now_ts - float(getattr(self, "_studio_daily_report_last_check", 0.0) or 0.0) < 20.0:
            return
        self._studio_daily_report_last_check = now_ts
        if getattr(self, "_studio_busy", False) or getattr(self, "_studio_daily_report_busy", False):
            return
        time_var = getattr(self, "studio_daily_report_time_var", None)
        time_text = str(time_var.get() if time_var is not None else
                        getattr(self, "studio_daily_report_time", "23:58") or "23:58").strip()
        try:
            scheduled = datetime.strptime(time_text, "%H:%M")
        except Exception:
            return
        now = datetime.now().astimezone()
        if (now.hour, now.minute) < (scheduled.hour, scheduled.minute):
            return
        date_key = now.date().isoformat()
        targets = self._studio_daily_report_targets_for_day(now)
        if not targets:
            return
        reports = []
        skipped_empty = 0
        for target in targets:
            try:
                chat_id = int(target.get("id"))
            except Exception:
                continue
            key = f"provider-pdf-xlsx-v1:{date_key}:{chat_id}"
            marker = self._studio_daily_report_delivery(key)
            if marker and str(marker.get("state") or "").upper() in (
                    "SENT", "NO DATA", "SENDING", "REVIEW NEEDED"):
                continue
            caption = (f"Daily Signal Provider Report · {date_key} · "
                       f"{str(target.get('name') or chat_id)[:80]}")
            marker_row = {"key": key, "date": date_key, "chat_id": chat_id,
                          "chat_name": target.get("name"), "state": "SENDING",
                          "format": "PDF+XLSX", "signals": int(target.get("signals") or 0),
                          "attachments": ["PDF", "XLSX"],
                          "updated_ts": now_ts, "message": caption}
            self._studio_daily_report_store_delivery(marker_row)
            reports.append({"key": key, "chat_id": chat_id,
                            "chat_name": str(target.get("name") or chat_id),
                            "signals": int(target.get("signals") or 0),
                            "message": caption, "report_now": now})
        if not reports:
            if skipped_empty and hasattr(self, "studio_daily_report_status_var"):
                self.studio_daily_report_status_var.set(
                    f"EOD check complete · no report data for {skipped_empty} destination(s).")
            return
        self._studio_daily_report_busy = True
        publications = [dict(row) for row in (getattr(self, "studio_publications", []) or [])
                        if isinstance(row, dict)]
        trades = self._studio_provider_journal_trades()
        logo_path = str(getattr(self, "studio_logo_path", "") or "")
        if not Path(logo_path).is_file():
            fallback_logo = BRAND_LOGO if BRAND_LOGO.is_file() else LOGO_SMALL
            logo_path = str(fallback_logo) if fallback_logo.is_file() else ""

        async def send_reports(batch, client=None):
            import tempfile
            results = []
            with tempfile.TemporaryDirectory(prefix="edgequant-provider-eod-") as temp_dir:
                for index, report in enumerate(batch, 1):
                    pdf_message_id = 0
                    xlsx_message_id = 0
                    try:
                        report_path = Path(temp_dir) / f"provider-eod-{index}.pdf"
                        workbook_path = Path(temp_dir) / f"provider-eod-{index}.xlsx"
                        ProviderStudio.export_provider_daily_pdf(
                            report_path, publications, trades=trades, engine=E,
                            logo_path=logo_path, destination_id=report["chat_id"],
                            destination_name=report["chat_name"], now=report["report_now"])
                        ProviderStudio.export_provider_daily_xlsx(
                            workbook_path, publications, trades=trades, engine=E,
                            logo_path=logo_path, destination_id=report["chat_id"],
                            destination_name=report["chat_name"], now=report["report_now"])
                        pdf_message_id = await E.telegram_studio_send_file(
                            report["chat_id"], str(report_path), caption=report["message"], client=client)
                        xlsx_caption = (f"Daily Signal Provider Excel Report · "
                                        f"{report['report_now']:%Y-%m-%d} · {report['chat_name'][:80]}")
                        xlsx_message_id = await E.telegram_studio_send_file(
                            report["chat_id"], str(workbook_path), caption=xlsx_caption, client=client)
                        results.append({"key": report["key"], "ok": True,
                                        "message_id_pdf": int(pdf_message_id or 0),
                                        "message_id_xlsx": int(xlsx_message_id or 0),
                                        "error": ""})
                    except Exception as exc:
                        results.append({"key": report["key"], "ok": False,
                                        "message_id_pdf": int(pdf_message_id or 0),
                                        "message_id_xlsx": int(xlsx_message_id or 0),
                                        "error": f"{type(exc).__name__}: {exc}"})
            return results

        def done(results):
            failed_count = 0
            for result in results or []:
                marker = self._studio_daily_report_delivery(result.get("key")) or {
                    "key": result.get("key")}
                marker.update({"state": "SENT" if result.get("ok") else "REVIEW NEEDED",
                               "format": "PDF+XLSX", "attachments": ["PDF", "XLSX"],
                               "message_id_pdf": result.get("message_id_pdf"),
                               "message_id_xlsx": result.get("message_id_xlsx"),
                               "error": str(result.get("error") or "")[:600],
                               "updated_ts": time.time()})
                self._studio_daily_report_store_delivery(marker)
                if not result.get("ok"):
                    failed_count += 1
                    q_log(f"Provider EOD PDF+Excel failed [{result.get('key')}]: "
                          f"{result.get('error', 'unknown error')}", "warn")
            self._studio_daily_report_busy = False
            self._studio_daily_report_refresh_status()
            if hasattr(self, "studio_daily_report_status_var"):
                self.studio_daily_report_status_var.set(
                    f"Daily Provider PDF + Excel sent to {len(results or [])-failed_count}/{len(results or [])} "
                    "destination(s)." +
                    (" Failed/uncertain sends need review; no retry was attempted." if failed_count else ""))

        def failed(error):
            for report in reports:
                marker = self._studio_daily_report_delivery(report["key"]) or {"key": report["key"]}
                marker.update({"state": "REVIEW NEEDED", "error": str(error)[:600],
                               "updated_ts": time.time()})
                self._studio_daily_report_store_delivery(marker)
            self._studio_daily_report_busy = False
            if hasattr(self, "studio_daily_report_status_var"):
                self.studio_daily_report_status_var.set(
                    "Daily Provider PDF + Excel could not be confirmed; records are held for review, not retried.")

        try:
            self._studio_run_async("Sending daily Provider PDF + Excel reports", send_reports,
                                   args=(reports,), status=getattr(self, "studio_daily_report_status", None),
                                   on_success=done, on_error=failed, timeout=600.0)
        except Exception as exc:
            failed(f"{type(exc).__name__}: {exc}")

    def _studio_provider_journal_trades(self):
        """Return Provider-local trades plus explicitly linked magic=0 MT5 records only."""
        rows = [dict(row) for row in (getattr(E, "TRADES", []) or [])
                if isinstance(row, dict)]
        snapshot_rows = []
        snap = getattr(self, "external_trade_snapshot", {})
        if isinstance(snap, dict):
            snapshot_rows = [dict(row) for row in (snap.get("trades") or [])
                             if isinstance(row, dict)]
        out_by_id = {str(row.get("id")): row for row in rows if row.get("id") is not None}
        def safe_ticket_id(value):
            try:
                return int(value or 0)
            except Exception:
                return 0
        for link in (getattr(self, "studio_provider_links", []) or []):
            if not isinstance(link, dict):
                continue
            try:
                if int(link.get("magic", 0) or 0) != 0:
                    continue
            except Exception:
                continue
            broker = str(link.get("broker") or "MAIN").strip().casefold()
            ticket = safe_ticket_id(link.get("ticket"))
            position_id = safe_ticket_id(link.get("position_id"))
            ext = next((row for row in snapshot_rows
                        if str(row.get("broker") or "MAIN").strip().casefold() == broker
                        and ((position_id and safe_ticket_id(row.get("position_id")) == position_id)
                             or (ticket and safe_ticket_id(row.get("ticket")) == ticket))), None)
            if ext is None and isinstance(link.get("snapshot"), dict):
                ext = dict(link["snapshot"])
            if not isinstance(ext, dict):
                continue
            trade_id = str(link.get("journal_trade_id") or "")
            if not trade_id or trade_id in out_by_id:
                continue
            ext_status = str(ext.get("status") or "OPEN").upper()
            status = "closed" if ext_status == "CLOSED" else "cancelled" if ext_status in (
                "CANCELLED", "CANCELED") else "open"
            entry = ext.get("entry", 0.0)
            close_price = (ext.get("current", 0.0) if status == "closed" else 0.0)
            try:
                net = float(ext.get("net_total", ext.get("net_today", 0.0)) or 0.0)
            except Exception:
                net = 0.0
            trade = {"id": trade_id, "ticket": ext.get("ticket") or ticket,
                     "position_id": ext.get("position_id") or position_id,
                     "broker": ext.get("broker") or link.get("broker") or "MAIN",
                     "symbol": str(ext.get("symbol") or ""),
                     "direction": str(ext.get("direction") or "").upper(),
                     "status": status, "result": str(ext.get("result") or "manual").lower(),
                     "open_price": entry, "price": entry, "close_price": close_price,
                     "net": net, "placed_ts": ext.get("opened_ts") or link.get("created_ts") or 0.0,
                     "closed_ts": ext.get("closed_ts") or 0.0, "magic": 0,
                     "source": "PROVIDER MANUAL MT5 LINK", "tag": "PROVIDER MAGIC=0 LINK",
                     "lot": ext.get("lot", 0.0), "sl": ext.get("sl", 0.0),
                     "tp": ext.get("tp", 0.0), "external_ticket": ext.get("ticket") or ticket,
                     "external_position_id": ext.get("position_id") or position_id}
            rows.append(trade)
            out_by_id[trade_id] = trade
        return rows

    def _studio_selected_provider_journal_publication(self):
        tree = getattr(self, "studio_provider_journal_tree", None)
        if tree is None:
            return None
        try:
            selected = tree.selection()
            if not selected:
                return None
            pub_id = str(selected[0])
            return next((row for row in (self.studio_publications or [])
                         if str(row.get("id") or "") == pub_id), None)
        except Exception:
            return None

    def _studio_refresh_provider_journal(self, *_args):
        tree = getattr(self, "studio_provider_journal_tree", None)
        if tree is None:
            return
        try:
            for item in tree.get_children():
                tree.delete(item)
            destination = self._studio_selected_report_destination()
            destination_id = str(destination.get("id")) if destination else ""
            pubs = list(getattr(self, "studio_publications", []) or [])
            trades = self._studio_provider_journal_trades()
            performance = ProviderStudio.provider_signal_rows(pubs, trades, E) if ProviderStudio else []
            for item in performance:
                pub = next((row for row in pubs if str(row.get("id") or "") == str(item.get("id") or "")), {})
                targets = list(pub.get("targets") or [])
                target = next((row for row in targets
                               if str(row.get("id")) == destination_id), None) if destination_id else None
                if destination_id and target is None:
                    continue
                target_names = ([str(target.get("name") or destination.get("name") or "")] if target
                                else [str(row.get("name") or row.get("id") or "") for row in targets])
                trade_count = len(item.get("linked_trade_ids") or [])
                self.studio_provider_journal_tree.insert("", "end", iid=str(item.get("id") or time.time_ns()),
                    values=(item.get("created", ""), ", ".join(target_names) or "—",
                            f"{item.get('symbol', '')} {item.get('direction', '')}".strip(),
                            item.get("entry", "—"), item.get("sl", "—"), item.get("tps", "—"),
                            item.get("status", "—"), item.get("outcome", "OPEN"), trade_count,
                            "—" if item.get("actual_net") is None else f"{item['actual_net']:+,.2f}"))
        except Exception as exc:
            q_log(f"Provider signal journal refresh failed: {exc}", "warn")

    def _studio_link_selected_provider_manual_ticket(self):
        publication = self._studio_selected_provider_journal_publication()
        if not publication:
            messagebox.showinfo("Provider journal", "Select a signal in the Provider journal first.", parent=self.root)
            return
        candidates = []
        snap = getattr(self, "external_trade_snapshot", {})
        for row in (snap.get("trades", []) if isinstance(snap, dict) else []):
            if not isinstance(row, dict):
                continue
            try:
                if int(row.get("magic", -1)) != 0:
                    continue
            except Exception:
                continue
            candidates.append(dict(row))
        if not candidates:
            messagebox.showinfo("Provider journal", "No current read-only MT5 magic=0 tickets are available. Connect/select the intended account and refresh the MT5 snapshot.", parent=self.root)
            return
        dlg = tk.Toplevel(self.root)
        dlg.title("Link an explicitly selected manual MT5 ticket")
        dlg.configure(bg=PANEL)
        dlg.transient(self.root)
        dlg.grab_set()
        dlg.geometry("920x360")
        tk.Label(dlg, text="ONLY MAGIC=0 MANUAL TICKETS · NO AUTO / FUZZY MATCHING",
                 bg=PANEL, fg=GOLD, font=widget_font("Segoe UI", 10, True)).pack(anchor="w", padx=12, pady=10)
        frame = ttk.Frame(dlg, style="Panel.TFrame")
        frame.pack(fill="both", expand=True, padx=10, pady=(0, 8))
        cols = ("broker", "ticket", "position", "symbol", "direction", "status", "entry", "SL", "TP", "net")
        tree = ttk.Treeview(frame, columns=cols, show="headings", selectmode="browse", height=9)
        for key, title, width in (("broker","ACCOUNT",110),("ticket","TICKET",90),("position","POSITION ID",100),
                                  ("symbol","SYMBOL",95),("direction","SIDE",65),("status","STATE",75),
                                  ("entry","ENTRY",85),("SL","SL",85),("TP","TP",85),("net","NET",90)):
            tree.heading(key, text=title); tree.column(key, width=width, anchor="center")
        tree.pack(side="left", fill="both", expand=True)
        vsb = ttk.Scrollbar(frame, orient="vertical", command=tree.yview); vsb.pack(side="right", fill="y")
        tree.configure(yscrollcommand=vsb.set)
        by_iid = {}
        for idx, row in enumerate(candidates):
            iid = str(idx); by_iid[iid] = row
            tree.insert("", "end", iid=iid, values=(row.get("broker", ""), row.get("ticket", ""),
                row.get("position_id", ""), row.get("symbol", ""), row.get("direction", ""),
                row.get("status", ""), row.get("entry", ""), row.get("sl", ""), row.get("tp", ""),
                f"{float(row.get('net_total') or 0):+.2f}"))
        buttons = ttk.Frame(dlg, style="Panel.TFrame"); buttons.pack(fill="x", padx=10, pady=(0, 10))
        def link_now():
            sel = tree.selection()
            if not sel:
                messagebox.showwarning("Provider journal", "Choose one ticket explicitly.", parent=dlg); return
            ext = by_iid[sel[0]]
            broker = str(ext.get("broker") or "MAIN").strip()
            ticket = int(ext.get("ticket") or 0)
            position_id = int(ext.get("position_id") or 0)
            if int(ext.get("magic", -1)) != 0 or not (ticket or position_id):
                messagebox.showerror("Provider journal", "Only a verified magic=0 ticket can be linked.", parent=dlg); return
            for existing in self.studio_provider_links:
                if (str(existing.get("broker") or "MAIN").strip().casefold() == broker.casefold()
                        and ((position_id and int(existing.get("position_id") or 0) == position_id)
                             or (ticket and int(existing.get("ticket") or 0) == ticket))):
                    messagebox.showwarning("Provider journal", "This manual MT5 ticket is already linked to a Provider signal.", parent=dlg); return
            trade_id = f"PROVIDER-MANUAL:{broker}:{position_id or ticket}"
            manual_ids = list(publication.get("provider_manual_trade_ids") or [])
            if trade_id not in manual_ids:
                manual_ids.append(trade_id)
            publication["provider_manual_trade_ids"] = manual_ids
            link = {"signal_id": str(publication.get("id") or ""), "journal_trade_id": trade_id,
                    "broker": broker, "ticket": ticket, "position_id": position_id,
                    "magic": 0, "created_ts": time.time(), "snapshot": dict(ext)}
            self.studio_provider_links.append(link)
            save_studio_provider_links(self.studio_provider_links)
            self._studio_persist_publications()
            self._studio_refresh_provider_journal()
            dlg.destroy()
        ttk.Button(buttons, text="LINK SELECTED TICKET", style="Go.TButton", command=link_now).pack(side="left", padx=4)
        ttk.Button(buttons, text="CANCEL", command=dlg.destroy).pack(side="right", padx=4)

    def _studio_unlink_provider_manual_tickets(self):
        publication = self._studio_selected_provider_journal_publication()
        if not publication:
            messagebox.showinfo("Provider journal", "Select a signal first.", parent=self.root); return
        signal_id = str(publication.get("id") or "")
        ids = set(str(x) for x in (publication.get("provider_manual_trade_ids") or []))
        if not ids:
            messagebox.showinfo("Provider journal", "This signal has no linked manual ticket.", parent=self.root); return
        if not messagebox.askyesno("Unlink manual tickets", "Remove explicit magic=0 ticket links from this Provider signal? No MT5 ticket will be changed.", parent=self.root):
            return
        self.studio_provider_links = [row for row in self.studio_provider_links
                                      if not (str(row.get("signal_id") or "") == signal_id
                                              and str(row.get("journal_trade_id") or "") in ids)]
        publication["provider_manual_trade_ids"] = []
        save_studio_provider_links(self.studio_provider_links)
        self._studio_persist_publications()
        self._studio_refresh_provider_journal()

    def _studio_refresh_performance(self):
        tree = getattr(self, "studio_performance_tree", None)
        if tree is None:
            return
        if ProviderStudio is None:
            try:
                self.studio_report_status_var.set(
                    "Provider report module unavailable: " + PROVIDER_STUDIO_IMPORT_ERROR)
            except Exception:
                pass
            return
        try:
            data = ProviderStudio.provider_performance(
                list(getattr(self, "studio_publications", []) or []),
                self._studio_provider_journal_trades(), E)
            self._studio_performance_cache = data
            children = tree.get_children()
            if children:
                tree.delete(*children)
            summaries = data.get("periods") or {}
            for key in ("today", "week", "month", "all"):
                item = summaries.get(key) or {}
                tp = item.get("tp_levels") or {}
                tp_text = "  ".join(f"TP{i}:{tp.get(i, 0)}" for i in range(1, 11)
                                     if tp.get(i, 0)) or "—"
                win = item.get("win_rate")
                best = item.get("best_signal") or {}
                best_text = (f"{best.get('symbol', '')} {best.get('direction', '')}".strip()
                             if best else "—")
                tree.insert("", "end", iid=key, values=(
                    item.get("label", key.upper()), item.get("signals", 0), item.get("wins", 0),
                    item.get("losses", 0), item.get("be", 0),
                    "—" if win is None else f"{win:.1f}%", tp_text,
                    "—" if item.get("actual_pips") is None else f"{item['actual_pips']:+.1f}",
                    "—" if item.get("nominal_pips") is None else f"{item['nominal_pips']:+.1f}",
                    "—" if item.get("actual_net") is None else f"{item['actual_net']:+,.2f}",
                    best_text))
            day = summaries.get("today") or {}
            if day.get("best_signal"):
                best = day["best_signal"]
                metric = (f"{best.get('actual_net'):+,.2f} USD" if best.get("actual_net") is not None
                          else f"{best.get('nominal_pips'):+,.1f} nominal pips" if best.get("nominal_pips") is not None
                          else "outcome not recorded")
                best_text = (f"BEST TODAY: {best.get('symbol')} {best.get('direction')} · {metric} · "
                             f"{best.get('status')} · {self._studio_tracking_label(best)}")
            else:
                best_text = "BEST TODAY: No provider signal outcome recorded yet."
            if hasattr(self, "studio_best_signal_note"):
                self.studio_best_signal_note.configure(text=best_text,
                    fg=GREEN if day.get("best_signal") else MUTED)
            for period in ("today", "week", "month"):
                summary = summaries.get(period) or {}
                value = getattr(self, f"studio_perf_{period}_value", None)
                note = getattr(self, f"studio_perf_{period}_note", None)
                if value is not None:
                    value.configure(text=f"{summary.get('signals', 0)} signals  ·  " +
                                    ("— win rate" if summary.get("win_rate") is None else
                                     f"{summary['win_rate']:.1f}% win rate"))
                if note is not None:
                    net = summary.get("actual_net")
                    actual_pips = summary.get("actual_pips")
                    nominal_pips = summary.get("nominal_pips")
                    actual_wl = ("—" if actual_pips is None else
                                 f"{float(summary.get('actual_pips_won') or 0):+.1f}/"
                                 f"{float(summary.get('actual_pips_lost') or 0):+.1f}")
                    nominal_wl = ("—" if nominal_pips is None else
                                  f"{float(summary.get('nominal_pips_won') or 0):+.1f}/"
                                  f"{float(summary.get('nominal_pips_lost') or 0):+.1f}")
                    note.configure(text=(f"Wins {summary.get('wins',0)} · Losses {summary.get('losses',0)} · "
                                         f"BE {summary.get('be',0)} · "
                                         f"TP hits {sum((summary.get('tp_levels') or {}).values())} · "
                                         f"Actual net {'—' if net is None else f'{net:+,.2f} USD'} · "
                                         f"Actual pips W/L {actual_wl} · Estimated pips W/L {nominal_wl}"))
            self._studio_draw_performance_graph(summaries)
            self._studio_refresh_today_signal_lists(data)
            self._studio_refresh_group_performance(data)
            self._studio_refresh_live_orders()
            plan, state = self._studio_report_plan_data()
            goal = float(state.get("target") or 0.0)
            actual = float(state.get("net") or 0.0)
            progress = float(state.get("progress_net") or actual)
            pct = float(state.get("done_pct") or 0.0)
            achieved = bool(state.get("achieved"))
            if goal <= 0:
                headline, color = "DAILY TARGET NOT SET", MUTED
                detail = "Set a daily target in the Trading Plan / Daily Target panel."
            elif achieved:
                headline, color = f"DAILY TARGET ACHIEVED  ·  {pct:.1f}%", GREEN
                detail = (f"Realized {actual:+,.2f} USD of {goal:,.2f} USD target. "
                          "Achievement is confirmed on realized P&L.")
            else:
                headline, color = f"IN PROGRESS  ·  {pct:.1f}%", GOLD if progress >= 0 else RED
                detail = (f"Progress {progress:+,.2f} USD (realized {actual:+,.2f}) / {goal:,.2f} USD · "
                          f"{float(state.get('remaining') or 0):,.2f} USD remaining. Floating P&L may change.")
            if hasattr(self, "studio_target_banner"):
                self.studio_target_banner.configure(text=headline, fg=color)
            if hasattr(self, "studio_target_detail"):
                self.studio_target_detail.configure(text=detail)
            if hasattr(self, "studio_target_bar"):
                canvas = self.studio_target_bar
                canvas.delete("all")
                width = max(100, canvas.winfo_width())
                canvas.create_rectangle(0, 0, width, 14, fill=PANEL2, outline="")
                fill = min(100.0, max(0.0, pct))
                canvas.create_rectangle(0, 0, width * fill / 100.0, 14,
                                        fill=color if goal > 0 else MUTED, outline="")
                canvas.create_text(width - 5, 7, anchor="e", text=f"{pct:.1f}%",
                                   fill=FG, font=widget_font("Consolas", 8, True))
            if hasattr(self, "studio_report_status_var"):
                self.studio_report_status_var.set(
                    f"Updated {datetime.now().strftime('%H:%M:%S')} · {len(data.get('rows') or [])} publication(s) · "
                    "actual broker results require linked closed local journal trades")
            self._studio_show_publication_details()
        except Exception as exc:
            q_log(f"Provider performance refresh: {type(exc).__name__}: {exc}", "warn")
            try:
                self.studio_report_status_var.set(f"Could not refresh Provider performance: {exc}")
            except Exception:
                pass

    def _studio_refresh_today_signal_lists(self, data):
        today_tp = getattr(self, "studio_today_tp_tree", None)
        today_sl = getattr(self, "studio_today_sl_tree", None)
        if today_tp is None or today_sl is None:
            return
        try:
            for tree in (today_tp, today_sl):
                children = tree.get_children()
                if children:
                    tree.delete(*children)
            today = datetime.now().date()
            rows = list((data or {}).get("rows") or [])
            for index, row in enumerate(rows):
                try:
                    if datetime.fromtimestamp(float(row.get("created_ts") or 0)).date() != today:
                        continue
                except Exception:
                    continue
                signal = f"{row.get('symbol') or '—'} {row.get('direction') or ''}".strip()
                destinations = ", ".join(row.get("destination_names") or []) or "—"
                hits = list(row.get("tp_hits") or [])
                if hits:
                    levels = ", ".join(f"TP{int(level)}" for level in hits)
                    today_tp.insert("", "end", iid=f"tp_{index}",
                                    values=(signal, levels, destinations))
                if bool(row.get("sl_hit")):
                    today_sl.insert("", "end", iid=f"sl_{index}",
                                    values=(signal, str(row.get("status") or "SL HIT"), destinations))
        except Exception as exc:
            q_log(f"Provider today's TP/SL list: {exc}", "warn")

    def _studio_refresh_group_performance(self, data=None):
        tree = getattr(self, "studio_destination_tree", None)
        if tree is None:
            return
        data = data if isinstance(data, dict) else (getattr(self, "_studio_performance_cache", {}) or {})
        groups = list(data.get("groups") or [])
        try:
            children = tree.get_children()
            if children:
                tree.delete(*children)
            for index, row in enumerate(groups):
                tree.insert("", "end", iid=f"dest_{index}", values=(
                    row.get("destination", ""), row.get("signals", 0), row.get("actual_trades", 0),
                    row.get("market", 0), row.get("limit", 0), row.get("wins", 0),
                    row.get("losses", 0), row.get("be", 0), row.get("tp_hits", 0),
                    row.get("sl_hits", 0)))
            names = [str(row.get("destination") or "") for row in groups if row.get("destination")]
            total_signals = sum(int(row.get("signals") or 0) for row in groups)
            linked_trades = sum(int(row.get("actual_trades") or 0) for row in groups)
            self.studio_destination_summary_var.set(L(
                f"Destinations used: {len(names)} · signal publications: {total_signals} · linked closed MT5 trades: {linked_trades}.",
                f"භාවිතා කළ destinations: {len(names)} · signal publications: {total_signals} · linked closed MT5 trades: {linked_trades}."))
        except Exception as exc:
            q_log(f"Provider destination breakdown: {exc}", "warn")

    def _studio_refresh_live_orders(self):
        market_tree = getattr(self, "studio_live_market_tree", None)
        limit_tree = getattr(self, "studio_live_limit_tree", None)
        if market_tree is None or limit_tree is None:
            return
        try:
            for tree in (market_tree, limit_tree):
                children = tree.get_children()
                if children:
                    tree.delete(*children)
            snapshot = getattr(self, "external_trade_snapshot", {}) or {}
            if str(snapshot.get("status") or "").lower() != "connected":
                detail = str(snapshot.get("error") or "")
                self.studio_live_summary_var.set(L(
                    "MT5 live snapshot unavailable; open Dashboard and refresh MT5.",
                    "MT5 live snapshot ලබාගත නොහැක; Dashboard විවෘත කර MT5 refresh කරන්න.") +
                    (f"  {detail[:140]}" if detail else ""))
                return
            try:
                engine_magic = int(getattr(E, "MAGIC", 0) or 0)
            except Exception:
                engine_magic = 0
            brokers = list((getattr(self, "mt5_info", {}) or {}).get("brokers") or [])
            currency_by_broker = {str(item.get("name") or "").strip().casefold():
                                  str(item.get("currency") or "").strip().upper()
                                  for item in brokers if isinstance(item, dict)}
            pnl_by_currency = {}
            market_count = limit_count = 0
            now_rows = [row for row in (snapshot.get("manage_rows") or []) if isinstance(row, dict)]
            for index, row in enumerate(now_rows):
                try:
                    magic = int(row.get("magic", -1))
                except Exception:
                    continue
                if magic not in {0, engine_magic}:
                    continue
                state = str(row.get("state") or "").upper()
                kind = str(row.get("kind") or "").upper()
                order_kind = str(row.get("order_kind") or "").upper()
                symbol = str(row.get("symbol") or "")
                side = str(row.get("direction") or "").upper()
                broker = str(row.get("broker") or "MAIN")
                source = str(row.get("source") or row.get("source_type") or
                             ("MT5 Manual / External" if magic == 0 else "EdgeQuant"))
                entry = float(row.get("entry") or 0.0)
                market_raw = row.get("market_price")
                if market_raw is None:
                    market_raw = row.get("current")
                market = float(market_raw or 0.0)
                sl = float(row.get("sl") or 0.0)
                tp = float(row.get("tp") or 0.0)
                try:
                    pip = float(E.pip_size_of(symbol) or 0.0)
                except Exception:
                    pip = 0.0
                try:
                    ticket = int(row.get("ticket") or row.get("order_ticket") or 0)
                except Exception:
                    ticket = 0
                if state in ("LIVE", "OPEN") or kind == "OPEN":
                    market_count += 1
                    pl = float(row.get("pl") or 0.0)
                    currency = currency_by_broker.get(broker.casefold(), "MT5") or "MT5"
                    pnl_by_currency[currency] = pnl_by_currency.get(currency, 0.0) + pl
                    pips = None
                    if pip > 0 and entry > 0 and market > 0 and side in ("BUY", "SELL"):
                        pips = (market - entry) / pip * (-1.0 if side == "SELL" else 1.0)
                    try:
                        opened = datetime.fromtimestamp(float(row.get("opened_ts") or 0)).strftime("%Y-%m-%d %H:%M")
                    except Exception:
                        opened = "—"
                    market_tree.insert("", "end", iid=f"market_{index}", values=(
                        opened, broker, symbol, side, f"{entry:g}" if entry else "—",
                        f"{market:g}" if market else "—", f"{sl:g}" if sl else "—",
                        f"{tp:g}" if tp else "—", f"{pl:+,.2f}",
                        "—" if pips is None else f"{pips:+.1f}", source, ticket or "—"))
                elif state == "PENDING" and kind == "PENDING" and order_kind == "LIMIT":
                    limit_count += 1
                    gap = abs(market - entry) / pip if pip > 0 and market > 0 and entry > 0 else None
                    limit_tree.insert("", "end", iid=f"limit_{index}", values=(
                        broker, symbol, side, f"{entry:g}" if entry else "—",
                        f"{market:g}" if market else "—", f"{sl:g}" if sl else "—",
                        f"{tp:g}" if tp else "—", "—" if gap is None else f"{gap:.1f}",
                        source, ticket or "—"))
            pnl_note = " · ".join(f"{currency} {value:+,.2f}" for currency, value in sorted(pnl_by_currency.items())) or "—"
            pips_note = L("per position below", "පහත එක් එක් position එක අනුව")
            updated = float(snapshot.get("updated_ts") or 0.0)
            updated_note = datetime.fromtimestamp(updated).strftime("%H:%M:%S") if updated else "—"
            self.studio_live_summary_var.set(L(
                f"Open market: {market_count} · Pending LIMIT: {limit_count} · Floating P&L: {pnl_note} · Open pips: {pips_note} · snapshot {updated_note}",
                f"විවෘත market: {market_count} · Pending LIMIT: {limit_count} · Floating P&L: {pnl_note} · Open pips: {pips_note} · snapshot {updated_note}"))
        except Exception as exc:
            q_log(f"Provider live MT5 rows: {type(exc).__name__}: {exc}", "warn")
            try:
                self.studio_live_summary_var.set(L(f"Could not display the MT5 snapshot: {exc}",
                                                   f"MT5 snapshot පෙන්විය නොහැක: {exc}"))
            except Exception:
                pass

    def _studio_draw_performance_graph(self, summaries):
        canvas = getattr(self, "studio_perf_graph", None)
        if canvas is None:
            return
        try:
            canvas.delete("all")
            width = max(320, int(canvas.winfo_width() or 320))
            height = max(120, int(canvas.winfo_height() or 145))
            top, bottom = 30, height - 24
            rows = [("TODAY", summaries.get("today") or {}),
                    ("WEEK", summaries.get("week") or {}),
                    ("MONTH", summaries.get("month") or {})]
            maximum = max([1] + [int(row.get("signals") or 0) for _name, row in rows])
            colors = (GREEN, RED, GOLD)
            labels = ("WINS", "LOSSES", "BE")
            legend_x = 12
            for label, color in zip(labels, colors):
                canvas.create_rectangle(legend_x, 9, legend_x + 10, 19, fill=color, outline="")
                canvas.create_text(legend_x + 15, 14, anchor="w", text=label,
                                   fill=MUTED, font=widget_font("Segoe UI", 7, True))
                legend_x += 80
            chart_width = max(120, width - 24)
            group_width = chart_width / 3.0
            usable_h = max(35, bottom - top)
            canvas.create_line(12, bottom, width - 12, bottom, fill=LINE, width=1)
            for index, (name, summary) in enumerate(rows):
                center = 12 + group_width * (index + 0.5)
                vals = (int(summary.get("wins") or 0), int(summary.get("losses") or 0),
                        int(summary.get("be") or 0))
                bar_w = max(10, min(30, group_width / 7.0))
                gap = max(3, bar_w * 0.18)
                total_w = len(vals) * bar_w + (len(vals) - 1) * gap
                left = center - total_w / 2.0
                for j, (value, color) in enumerate(zip(vals, colors)):
                    bar_h = usable_h * value / maximum
                    x0 = left + j * (bar_w + gap)
                    y0 = bottom - bar_h
                    canvas.create_rectangle(x0, y0, x0 + bar_w, bottom,
                                            fill=color if value else LINE, outline="")
                    if value:
                        canvas.create_text(x0 + bar_w / 2.0, max(top - 1, y0 - 8),
                                           text=str(value), fill=FG,
                                           font=widget_font("Segoe UI", 7, True))
                canvas.create_text(center, height - 10, text=f"{name} · {summary.get('signals', 0)} signals",
                                   fill=FG, font=widget_font("Segoe UI", 8, True))
            if not any(int((summaries.get(k) or {}).get("signals") or 0)
                       for k in ("today", "week", "month")):
                canvas.create_text(width / 2, height / 2 + 8, text="No Provider signals recorded yet.",
                                   fill=MUTED, font=widget_font("Segoe UI", 9))
        except Exception as exc:
            q_log(f"Provider performance graph render: {exc}", "warn")

    def _studio_refresh_provider_report_destinations(self):
        """Populate the Provider report picker with destinations marked as user-owned."""
        combo = getattr(self, "studio_report_destination_combo", None)
        if combo is None:
            return
        mapping = {}
        values = []
        rows = [row for row in (getattr(self, "studio_chats", []) or [])
                if isinstance(row, dict) and
                (bool(row.get("created_by_user")) or str(row.get("access") or "").upper() == "OWNED")]
        rows.sort(key=lambda row: str(row.get("name") or "").casefold())
        for row in rows:
            try:
                chat_id = int(row.get("id"))
            except Exception:
                continue
            kind = "CHANNEL" if str(row.get("kind") or "").upper() == "CHANNEL" else "GROUP"
            label = f"OWNED | {kind} | {row.get('name') or chat_id} | {chat_id}"
            mapping[label] = {**row, "id": chat_id}
            values.append(label)
        self._studio_report_destination_choice_map = mapping
        try:
            combo.configure(values=values)
            report_var = getattr(self, "studio_report_destination_var", None)
            current = str(report_var.get() if report_var is not None else "")
            if report_var is not None and current not in mapping:
                report_var.set(values[0] if values else "")
            if not values:
                self.studio_destination_report_status_var.set(
                    "No user-owned group/channel is available in the current Telegram destination list.")
            else:
                self.studio_destination_report_status_var.set(
                    f"{len(values)} owned report destination(s) available. Choose one for a local PDF/Excel export.")
            self._studio_refresh_provider_journal()
        except Exception:
            pass

    def _studio_selected_report_destination(self):
        var = getattr(self, "studio_report_destination_var", None)
        label = str(var.get() if var is not None else "")
        row = (getattr(self, "_studio_report_destination_choice_map", {}) or {}).get(label)
        return dict(row) if isinstance(row, dict) else None

    def _studio_export_report(self, kind):
        if ProviderStudio is None:
            messagebox.showerror("Provider exports", PROVIDER_STUDIO_IMPORT_ERROR or
                                 "Provider report module is unavailable.", parent=self.root)
            return
        kind = str(kind or "").lower()
        is_plan = kind.startswith("plan_")
        is_destination_report = kind.startswith("provider_destination_")
        destination = self._studio_selected_report_destination() if is_destination_report else None
        if is_destination_report and not destination:
            messagebox.showwarning("Destination report", "Choose a user-owned group/channel first.", parent=self.root)
            return
        ext = "pdf" if kind.endswith("pdf") else "xlsx"
        description = (f"{destination.get('name')} Trade Journal" if is_destination_report and destination
                       else "Trading Plan" if is_plan else "Provider Performance")
        safe_name = re.sub(r"[^A-Za-z0-9._-]+", "_", str(destination.get("name") or "Destination"))[:60] if destination else ""
        filename = ((f"{safe_name}_Trade_Journal_Report" if is_destination_report else
                     "EdgeQuant_Trading_Plan" if is_plan else "Provider_Performance") + "." + ext)
        path = filedialog.asksaveasfilename(
            parent=self.root, title=f"Export {description} as {ext.upper()}",
            initialfile=filename,
            defaultextension="." + ext,
            filetypes=(("PDF document", "*.pdf"),) if ext == "pdf" else
                      (("Excel workbook", "*.xlsx"),))
        if not path:
            return
        if getattr(self, "_studio_export_busy", False):
            self.studio_report_status_var.set("An export is already being prepared.")
            return
        self._studio_export_busy = True
        provider_name_var = getattr(self, "studio_provider_name_var", None)
        provider_name = (str(destination.get("name") or "Telegram destination") if is_destination_report and destination else
                         (provider_name_var.get().strip() if provider_name_var is not None else
                          getattr(self, "studio_provider_name", "Signal Provider")) or "Signal Provider")
        if not is_destination_report:
            self.studio_provider_name = provider_name
            save_ui_prefs(studio_provider_name=provider_name)
        logo_path = str(getattr(self, "studio_logo_path", "") or "")
        if not Path(logo_path).is_file():
            fallback_logo = BRAND_LOGO if BRAND_LOGO.is_file() else LOGO_SMALL
            logo_path = str(fallback_logo) if fallback_logo.is_file() else ""
        publications = [dict(row) for row in (getattr(self, "studio_publications", []) or [])]
        trades = self._studio_provider_journal_trades()
        plan, _target = self._studio_report_plan_data()
        def worker():
            error = ""
            try:
                if is_plan:
                    if not plan.get("table"):
                        raise RuntimeError("Generate a valid plan in the Trading Plan tab before exporting.")
                    if ext == "xlsx":
                        ProviderStudio.export_plan_xlsx(path, plan, logo_path=logo_path,
                                                        provider_name=provider_name)
                    else:
                        ProviderStudio.export_plan_pdf(path, plan, logo_path=logo_path,
                                                       provider_name=provider_name, engine=E)
                elif ext == "xlsx":
                    ProviderStudio.export_provider_xlsx(
                        path, publications, trades=trades, engine=E, logo_path=logo_path,
                        provider_name=provider_name, plan=None if is_destination_report else
                        (plan if plan.get("table") else None),
                        destination_id=destination.get("id") if is_destination_report else None,
                        destination_name=destination.get("name", "") if is_destination_report else "")
                else:
                    ProviderStudio.export_provider_pdf(
                        path, publications, trades=trades, engine=E, logo_path=logo_path,
                        provider_name=provider_name, plan=None if is_destination_report else
                        (plan if plan.get("table") else None),
                        destination_id=destination.get("id") if is_destination_report else None,
                        destination_name=destination.get("name", "") if is_destination_report else "")
            except Exception as exc:
                error = f"{type(exc).__name__}: {exc}"
            finally:
                RESULT_Q.put(("provider_export", path, description, error))
        threading.Thread(target=worker, daemon=True,
                         name="edgequant-provider-export").start()
        try:
            self.studio_report_status_var.set(f"Preparing branded {description} {ext.upper()}…")
        except Exception:
            pass

