    def _build_studio(self, parent):
        head = tk.Frame(parent, bg=PANEL)
        head.pack(fill="x", padx=2, pady=(0, 7))
        tk.Label(head, text="SIGNAL PROVIDER STUDIO", bg=PANEL, fg=GOLD,
                 font=widget_font("Segoe UI", 13, True)).pack(anchor="w")
        tk.Label(head, text=("Provider workspace: compose a validated branded signal, publish to Telegram destinations "
                             + ("or selected cloud groups, " if CLOUD_BACKEND_ENABLED else "")
                             + "and track TP / BE / SL updates. "
                             + ("Source scanning remains separate." if CLOUD_BACKEND_ENABLED else
                                "Cloud group sharing is intentionally deferred; source scanning remains separate.")),
                 bg=PANEL, fg=MUTED, justify="left", wraplength=950,
                 font=widget_font("Segoe UI", 9)).pack(anchor="w", pady=(2, 0))
        studio_nb = ttk.Notebook(parent)
        studio_nb.pack(fill="both", expand=True, pady=(3, 0))
        self.studio_inner_nb = studio_nb
        manage = ttk.Frame(studio_nb, style="Panel.TFrame", padding=5)
        composer = ttk.Frame(studio_nb, style="Panel.TFrame", padding=5)
        reports = ttk.Frame(studio_nb, style="Panel.TFrame", padding=5)
        posts = ttk.Frame(studio_nb, style="Panel.TFrame", padding=5)
        studio_nb.add(manage, text="  " + L("DESTINATIONS", "ගමනාන්ත") + "  ")
        studio_nb.add(composer, text="  " + L("SIGNAL COMPOSER / TRACKER", "SIGNAL COMPOSER / TRACKER") + "  ")
        studio_nb.add(reports, text="  " + L("PERFORMANCE / EXPORTS", "කාර්යසාධනය / exports") + "  ")
        studio_nb.add(posts, text="  " + L("POST / POLL", "POST / POLL") + "  ")
        manage_body, manage_canvas = self._studio_scroll_page(manage, "manage")
        compose_body, compose_canvas = self._studio_scroll_page(composer, "composer")
        reports_body, reports_canvas = self._studio_scroll_page(reports, "reports")
        posts_body, posts_canvas = self._studio_scroll_page(posts, "posts")
        self._wheel_canvases[str(self.tab_studio)] = manage_canvas
        studio_nb.bind("<<NotebookTabChanged>>", lambda e: self._studio_activate_scroll())
        self.nb.bind("<<NotebookTabChanged>>", lambda e: self._studio_activate_scroll(), add="+")

        def card(parent, title, accent=CYAN):
            f = tk.Frame(parent, bg=PANEL, highlightbackground=LINE, highlightthickness=1)
            f.pack(fill="x", padx=5, pady=(4, 8))
            tk.Label(f, text=title, bg=PANEL, fg=accent,
                     font=widget_font("Segoe UI", 10, True)).pack(anchor="w", padx=10, pady=(8, 5))
            return f

        # ---- destination creation ----------------------------------------
        create = card(manage_body, "CREATE A GROUP OR CHANNEL", GOLD)
        form = tk.Frame(create, bg=PANEL)
        form.pack(fill="x", padx=10, pady=(0, 8))
        form.columnconfigure(1, weight=1)
        form.columnconfigure(3, weight=1)
        self.studio_name_var = tk.StringVar()
        self.studio_kind_var = tk.StringVar(value="GROUP")
        self.studio_visibility_var = tk.StringVar(value="PRIVATE")
        self.studio_username_var = tk.StringVar()
        self.studio_about_var = tk.StringVar()
        self._studio_username_manual = False
        self._studio_username_autofilling = False
        tk.Label(form, text="NAME", bg=PANEL, fg=MUTED,
                 font=widget_font("Segoe UI", 8, True)).grid(row=0, column=0, sticky="w", padx=(0, 6), pady=4)
        ttk.Entry(form, textvariable=self.studio_name_var).grid(row=0, column=1, sticky="ew", padx=(0, 12), pady=4)
        tk.Label(form, text="TYPE", bg=PANEL, fg=MUTED,
                 font=widget_font("Segoe UI", 8, True)).grid(row=0, column=2, sticky="w", padx=(0, 6), pady=4)
        ttk.Combobox(form, textvariable=self.studio_kind_var, state="readonly", width=13,
                     values=("GROUP", "CHANNEL")).grid(row=0, column=3, sticky="w", pady=4)
        tk.Label(form, text="VISIBILITY", bg=PANEL, fg=MUTED,
                 font=widget_font("Segoe UI", 8, True)).grid(row=1, column=0, sticky="w", padx=(0, 6), pady=4)
        ttk.Combobox(form, textvariable=self.studio_visibility_var, state="readonly", width=13,
                     values=("PRIVATE", "PUBLIC")).grid(row=1, column=1, sticky="w", padx=(0, 12), pady=4)
        tk.Label(form, text="PUBLIC USERNAME", bg=PANEL, fg=MUTED,
                 font=widget_font("Segoe UI", 8, True)).grid(row=1, column=2, sticky="w", padx=(0, 6), pady=4)
        self.studio_username_entry = ttk.Entry(form, textvariable=self.studio_username_var)
        self.studio_username_entry.grid(row=1, column=3, sticky="ew", pady=4)
        self.studio_username_entry.bind("<KeyRelease>", self._studio_username_touched)
        self.studio_name_var.trace_add("write", self._studio_suggest_username)
        self.studio_visibility_var.trace_add("write", self._studio_suggest_username)
        self._studio_suggest_username()
        tk.Label(form, text="ABOUT", bg=PANEL, fg=MUTED,
                 font=widget_font("Segoe UI", 8, True)).grid(row=2, column=0, sticky="w", padx=(0, 6), pady=4)
        ttk.Entry(form, textvariable=self.studio_about_var).grid(row=2, column=1, columnspan=3,
                                                                  sticky="ew", pady=4)
        ttk.Label(form, text="Only PUBLIC groups/supergroups and channels use a Telegram @username; the editable suggestion comes from the name and Telegram checks availability. PRIVATE destinations have no public username: use the generated invite link. Private source scanning only lists chats already joined by this account.",
                  style="Muted.TLabel", wraplength=720).grid(row=3, column=0, columnspan=4,
                                                              sticky="w", pady=(3, 6))
        self.studio_create_btn = ttk.Button(form, text="CREATE", style="Go.TButton",
                                            command=self.studio_create_chat)
        self.studio_create_btn.grid(row=4, column=3, sticky="e", pady=(0, 2))
        self.studio_create_status = tk.Label(create, text="Ready. Telegram may reject unavailable usernames or restrict creation.",
                                             bg=PANEL, fg=MUTED, anchor="w", justify="left",
                                             wraplength=850, font=widget_font("Segoe UI", 8))
        self.studio_create_status.pack(fill="x", padx=10, pady=(0, 9))

        # ---- membership and invite links ---------------------------------
        destinations = card(manage_body, "DESTINATION & INVITE LINK", PURPLE)
        target_row = tk.Frame(destinations, bg=PANEL)
        target_row.pack(fill="x", padx=10, pady=(0, 4))
        tk.Label(target_row, text="JOINED GROUP / CHANNEL", bg=PANEL, fg=MUTED,
                 font=widget_font("Segoe UI", 8, True)).pack(anchor="w", pady=(0, 3))
        self.studio_target_var = tk.StringVar()
        self.studio_target_combo = ttk.Combobox(target_row, textvariable=self.studio_target_var,
                                                state="readonly", values=())
        self.studio_target_combo.pack(fill="x", expand=True)
        target_actions = tk.Frame(destinations, bg=PANEL)
        target_actions.pack(fill="x", padx=10, pady=(0, 5))
        self.studio_refresh_btn = ttk.Button(target_actions, text="REFRESH DESTINATIONS",
                                             command=self.studio_refresh_targets)
        self.studio_refresh_btn.pack(side="left", padx=(0, 6))
        self.studio_link_btn = ttk.Button(target_actions, text="GENERATE LINK",
                                          command=self.studio_export_link)
        self.studio_link_btn.pack(side="left")
        link_row = tk.Frame(destinations, bg=PANEL)
        link_row.pack(fill="x", padx=10, pady=(0, 4))
        tk.Label(link_row, text="INVITE LINK", bg=PANEL, fg=MUTED,
                 font=widget_font("Segoe UI", 8, True)).pack(side="left", padx=(0, 8))
        self.studio_link_var = tk.StringVar()
        ttk.Entry(link_row, textvariable=self.studio_link_var, state="readonly").pack(
            side="left", fill="x", expand=True, padx=(0, 7))
        ttk.Button(link_row, text="COPY", command=self.studio_copy_link).pack(side="left")
        self.studio_members_status = tk.Label(destinations,
                                              text="Refresh destinations to list groups/channels already joined by this account.",
                                              bg=PANEL, fg=MUTED, anchor="w", justify="left",
                                              wraplength=850, font=widget_font("Segoe UI", 8))
        self.studio_members_status.pack(fill="x", padx=10, pady=(3, 6))
        directory_tools = tk.Frame(destinations, bg=PANEL2,
                                   highlightbackground=LINE, highlightthickness=1)
        directory_tools.pack(fill="x", padx=10, pady=(0, 7))
        tk.Label(directory_tools, text="DESTINATION DIRECTORY  ·  OWNED VS. JOINED",
                 bg=PANEL2, fg=CYAN, font=widget_font("Segoe UI", 8, True)).pack(
                     anchor="w", padx=8, pady=(7, 3))
        self.studio_destination_search_var = tk.StringVar()
        ttk.Entry(directory_tools, textvariable=self.studio_destination_search_var).pack(
            fill="x", padx=8, pady=(0, 5))
        self.studio_destination_search_var.trace_add("write", self._studio_destination_search_changed)
        directory_columns = ("kind", "access", "name", "id", "username", "favorite")
        for title, attr in (("OWNED / ADMIN-ACCESS DESTINATIONS", "studio_created_tree"),
                            ("OTHER GROUPS / CHANNELS JOINED BY THIS ACCOUNT", "studio_joined_tree")):
            tk.Label(directory_tools, text=title, bg=PANEL2, fg=MUTED,
                     font=widget_font("Segoe UI", 7, True)).pack(anchor="w", padx=8, pady=(3, 2))
            section = ttk.Frame(directory_tools, style="Panel.TFrame")
            section.pack(fill="both", expand=True, padx=8, pady=(0, 4))
            tree = ttk.Treeview(section, columns=directory_columns, show="headings",
                                selectmode="extended", height=5)
            setattr(self, attr, tree)
            for col, heading, width in (("kind", "TYPE", 76), ("access", "ACCESS", 100),
                                        ("name", "DESTINATION", 250), ("id", "CHAT ID", 110),
                                        ("username", "USERNAME", 130), ("favorite", "FAV", 48)):
                tree.heading(col, text=heading)
                tree.column(col, width=width, minwidth=48,
                            anchor="w" if col in ("name", "username") else "center")
            vsb = ttk.Scrollbar(section, orient="vertical", command=tree.yview)
            tree.configure(yscrollcommand=vsb.set)
            tree.grid(row=0, column=0, sticky="nsew")
            vsb.grid(row=0, column=1, sticky="ns")
