    def _studio_community_targets_refresh(self):
        label = getattr(self, "studio_post_targets_note", None)
        if label is None:
            return
        try:
            rows = self._studio_selected_publish_chats()
            names = [str(row.get("name") or row.get("id")) for row in rows]
            shown = ", ".join(names[:5])
            if len(names) > 5:
                shown += f" +{len(names) - 5} more"
            text = (L(f"Selected recipients ({len(rows)}): {shown}. Posts and polls go only to these recipients.",
                      f"තෝරාගත් recipients ({len(rows)}): {shown}. Posts සහ polls යන්නේ මේ අයට පමණයි.") if rows else
                    L("No recipients selected. Choose groups/channels in Signal Composer first.",
                      "Recipients තෝරා නැහැ. පළමුව Signal Composer හි groups/channels තෝරන්න."))
            label.configure(text=text, fg=CYAN if rows else AMBER)
        except Exception as exc:
            label.configure(text=L(f"Could not read recipients: {exc}",
                                   f"Recipients කියවිය නොහැක: {exc}"), fg=AMBER)

