    def _cloud_selected_group(self):
        try:
            picked = self.cloud_group_tree.selection()
            if not picked:
                return None
            return next((r for r in self.cloud_groups if str(r.get("id")) == str(picked[0])), None)
        except Exception:
            return None

    def _cloud_group_selected(self, _event=None):
        if getattr(self, "cloud_session", None) and self._cloud_selected_group():
            self.cloud_refresh_signals()

    def _sync_provider_destinations(self):
        widget = getattr(self, "provider_dest_list", None)
        if widget is None:
            return
        user_id = str(((getattr(self, "cloud_session", None) or {}).get("user") or {}).get("id") or "")
        role = str((getattr(self, "cloud_profile", None) or {}).get("role") or "").lower()
        rows = [dict(group) for group in (getattr(self, "cloud_groups", []) or [])
                if role == "provider" and user_id and str(group.get("owner_id") or "") == user_id]
        self.provider_dest_groups = rows
        try:
            widget.delete(0, "end")
            for group in rows:
                visibility = str(group.get("visibility") or "private").upper()
                widget.insert("end", f"{group.get('name') or 'Untitled'}  •  {visibility}")
            widget.configure(state="normal" if role == "provider" else "disabled")
        except Exception:
            pass
        status = getattr(self, "provider_dest_status", None)
        if status is not None:
            if role != "provider":
                status.configure(text="Sign in as SIGNAL PROVIDER to publish to cloud groups.", fg=MUTED)
            elif rows:
                status.configure(text=f"{len(rows)} provider group(s) ready. Ctrl/Shift-click to choose several.", fg=CYAN)
            else:
                status.configure(text="No owned groups yet. Create a provider group in ACCOUNT / CLOUD, then refresh.", fg=AMBER)

    def _provider_select_all_groups(self):
        if str(getattr(self, "app_role", "")) != "provider":
            return
        try:
            self.provider_dest_list.selection_set(0, "end")
        except Exception:
            pass

    def _provider_selected_group_ids(self):
        try:
            return [str(self.provider_dest_groups[i].get("id"))
                    for i in self.provider_dest_list.curselection()
                    if 0 <= int(i) < len(self.provider_dest_groups)]
        except Exception:
            return []

    def _cloud_selected_signal(self):
        try:
            picked = self.cloud_signal_tree.selection()
            if not picked:
                return None
            return next((r for r in self.cloud_signals if str(r.get("id")) == str(picked[0])), None)
        except Exception:
            return None

    def _cloud_run(self, label, work, on_success=None, buttons=(), status=None):
        if not CLOUD_BACKEND_ENABLED:
            if status is not None:
                try:
                    status.configure(text="Cloud is disabled in this build. No network request was sent.", fg=AMBER)
                except Exception:
                    pass
            return
        if getattr(self, "_cloud_busy", False):
            if status is not None:
                status.configure(text="A cloud request is still running.", fg=AMBER)
            return
        if SupabaseClient is None:
            if status is not None:
                status.configure(text=f"Cloud module is unavailable: {CLOUD_IMPORT_ERROR}", fg=RED)
            return
        self._cloud_busy = True
        old_states = []
        for widget in buttons or ():
            try:
                old_states.append((widget, widget.cget("state")))
                widget.configure(state="disabled")
            except Exception:
                pass
        if status is not None:
            status.configure(text=f"{label}…", fg=AMBER)
        session = dict(self.cloud_session) if isinstance(self.cloud_session, dict) else None
        auth_epoch = getattr(self, "_cloud_auth_epoch", 0)

        def worker():
            client = self.cloud_client
            result, error, new_session = None, None, session
            try:
                if client is None:
                    client = SupabaseClient()
                try:
                    result = work(client, new_session)
                except CloudError as exc:
                    text = str(exc)
                    if new_session and new_session.get("refresh_token") and ("401" in text or "JWT" in text or "expired" in text.lower()):
                        new_session = client.refresh_session(new_session.get("refresh_token"))
                        result = work(client, new_session)
                    else:
                        raise
            except Exception as exc:
                error = f"{type(exc).__name__}: {exc}"
            try:
                self.root.after(0, lambda: finish(result, error, client, new_session))
            except Exception:
                pass

        def finish(result, error, client, new_session):
            self._cloud_busy = False
            if client is not None:
                self.cloud_client = client
            for widget, old_state in old_states:
                try:
                    if widget.winfo_exists():
                        widget.configure(state=old_state)
                except Exception:
                    pass
            if auth_epoch != getattr(self, "_cloud_auth_epoch", 0):
                if status is not None:
                    status.configure(text="Account changed while this request was running; stale result ignored.", fg=AMBER)
                return
            if new_session and new_session.get("access_token"):
                self.cloud_session = new_session
            if error:
                if status is not None:
                    status.configure(text=f"{label} failed: {error}", fg=RED)
                q_log(f"cloud {label.lower()} failed: {error}", "err")
                return
            try:
                if on_success:
                    on_success(result)
            except Exception as exc:
                if status is not None:
                    status.configure(text=f"{label} completed, but the UI update failed: {exc}", fg=AMBER)
                q_log(f"cloud UI update failed: {exc}", "err")

        threading.Thread(target=worker, name="edgequant-cloud", daemon=True).start()

    def cloud_register(self):
        if str(self.cloud_role_var.get() or "").lower() not in ("provider", "receiver"):
            self.cloud_auth_status.configure(text="Choose SIGNAL PROVIDER or RECEIVER before creating the account.", fg=AMBER)
            return
        if self.cloud_password_var.get() != self.cloud_password2_var.get():
            self.cloud_auth_status.configure(text="The two password fields do not match.", fg=RED)
            return
        role = self.cloud_role_var.get().strip().lower()
        email = self.cloud_email_var.get().strip()
        password = self.cloud_password_var.get()
        name = self.cloud_name_var.get().strip()

        def work(client, session):
            new = client.sign_up(email, password, role, name)
            profile = client.profile(new) if new.get("access_token") else None
            return {"session": new, "profile": profile}

        def done(result):
            new = result.get("session") or {}
            self.cloud_password_var.set("")
            self.cloud_password2_var.set("")
            if new.get("access_token"):
                self._activate_cloud_workspace(new, result.get("profile") or {})
            else:
                self.cloud_auth_status.configure(text="Registration submitted. Enter the code from the confirmation email above, then choose VERIFY CODE + FINISH REGISTRATION.", fg=GREEN)
                messagebox.showinfo("Verify your email", "Registration submitted. Check your inbox/spam folder for the confirmation code, enter it in EMAIL CODE, and verify in EdgeQuant.", parent=self.root)

        self._cloud_run("Creating account", work, done,
                        buttons=[self.cloud_register_btn, self.cloud_login_btn],
                        status=self.cloud_auth_status)

    def cloud_verify_email_code(self):
        email = self.cloud_email_var.get().strip()
        code = self.cloud_email_code_var.get().strip()
        if str(self.cloud_role_var.get() or "").lower() not in ("provider", "receiver"):
            self.cloud_auth_status.configure(text="Choose the account role before verifying the signup code.", fg=AMBER)
            return
        if not email or not code:
            self.cloud_auth_status.configure(text="Enter the registered email and the code from the verification email.", fg=AMBER)
            return

        def work(client, session):
            new = client.verify_email_otp(email, code)
            profile = client.profile(new)
            return {"session": new, "profile": profile}

        def done(result):
            self.cloud_email_code_var.set("")
            self.cloud_password_var.set("")
            self.cloud_password2_var.set("")
            self._activate_cloud_workspace(result.get("session") or {}, result.get("profile") or {})

        self._cloud_run("Verifying email code", work, done,
                        buttons=[self.cloud_verify_btn], status=self.cloud_auth_status)

    def cloud_login(self):
        if str(self.cloud_role_var.get() or "").lower() not in ("provider", "receiver"):
            self.cloud_auth_status.configure(text="Choose SIGNAL PROVIDER or RECEIVER before signing in.", fg=AMBER)
            return
        email, password = self.cloud_email_var.get().strip(), self.cloud_password_var.get()

        def work(client, session):
            new = client.sign_in(email, password)
            profile = client.profile(new)
            return {"session": new, "profile": profile}

        def done(result):
            self.cloud_password_var.set("")
            self.cloud_password2_var.set("")
            self._activate_cloud_workspace(result.get("session") or {}, result.get("profile") or {})

        self._cloud_run("Signing in", work, done,
                        buttons=[self.cloud_register_btn, self.cloud_login_btn],
                        status=self.cloud_auth_status)

    def cloud_resend_confirmation(self):
        email = self.cloud_email_var.get().strip()
        self._cloud_run("Resending confirmation email",
                        lambda client, session: (client.resend_confirmation(email), True)[1],
                        lambda _: self.cloud_auth_status.configure(
                            text="If that account can receive another confirmation, Supabase has queued the email. Check inbox/spam.",
                            fg=GREEN),
                        buttons=[self.cloud_resend_btn], status=self.cloud_auth_status)

    def cloud_password_reset(self):
        email = self.cloud_email_var.get().strip()
        self._cloud_run("Sending password reset email",
                        lambda client, session: (client.send_password_reset(email), True)[1],
                        lambda _: self.cloud_auth_status.configure(
                            text="If the account exists, Supabase has queued a password-reset email. Follow its link, then sign in again.",
                            fg=GREEN), status=self.cloud_auth_status)

    def _cloud_update_identity(self):
        profile = self.cloud_profile or {}
        user = (self.cloud_session or {}).get("user") or {}
        role = str(profile.get("role") or "").upper()
        name = profile.get("display_name") or (user.get("user_metadata") or {}).get("display_name") or user.get("email") or ""
        self.cloud_identity_label.configure(text=(f"SIGNED IN  •  {name}  •  {role}" if role else ""),
                                            fg=CYAN)
        try:
            self.cloud_signout_btn.configure(state="normal" if self.cloud_session else "disabled")
        except Exception:
            pass

    def cloud_sign_out(self):
        session = self.cloud_session
        if not session:
            return
        if not messagebox.askyesno("Sign out", "Sign out from the verified cloud account on this PC?", parent=self.root):
            return
        client = self.cloud_client
        access = str(session.get("access_token") or "")
        self._cloud_auth_epoch = getattr(self, "_cloud_auth_epoch", 0) + 1
        # Remove access from the UI immediately, even if the network is offline.
        self.cloud_session = None
        self.cloud_profile = None
        try:
            self.cloud_password_var.set("")
            self.cloud_password2_var.set("")
        except Exception:
            pass
        self.cloud_groups = []
        self.cloud_signals = []
        self.app_role = None
        self.local_role_mode = False
        self.local_only_mode = False
        self.cloud_role_var.set("")
        self._apply_role_workspace(select_home=False)
        self._paint_role_choice()
        try:
            self.nb.select(self.tab_welcome)
        except Exception:
            pass
        self.cloud_identity_label.configure(text="")
        self.cloud_auth_status.configure(text="Signed out locally. The token was memory-only; remote logout will be attempted if online.", fg=MUTED)
        self.cloud_signout_btn.configure(state="disabled")
        self._cloud_draw_groups()
        self._cloud_draw_signals()
        if client is not None and access:
            def revoke():
                try:
                    client.sign_out(access)
                except Exception:
                    pass
            threading.Thread(target=revoke, name="edgequant-cloud-logout", daemon=True).start()

    def cloud_refresh_groups(self):
        if not self.cloud_session:
            self.cloud_group_status.configure(text="Sign in with a verified email first.", fg=AMBER)
            return
        def done(rows):
            self.cloud_groups = list(rows or [])
            self._cloud_draw_groups()
            if self.app_role == "receiver" and not self._cloud_selected_group() and self.cloud_groups:
                try:
                    first_id = str(self.cloud_groups[0].get("id") or "")
                    if first_id:
                        self.cloud_group_tree.selection_set(first_id)
                        self.cloud_group_tree.focus(first_id)
                except Exception:
                    pass
            if self.app_role == "receiver" and self._cloud_selected_group():
                self.cloud_refresh_signals()

        self._cloud_run("Loading groups", lambda client, session: client.list_groups(session),
                        done, status=self.cloud_group_status)

    def _cloud_draw_groups(self):
        try:
            tree = self.cloud_group_tree
            selected = set(map(str, tree.selection()))
            tree.delete(*tree.get_children())
            available = set()
            for row in self.cloud_groups or []:
                rid = str(row.get("id") or "")
                if not rid:
                    continue
                available.add(rid)
                tree.insert("", "end", iid=rid,
                            values=(row.get("name") or "", row.get("visibility") or "private", rid))
            restore = [rid for rid in selected if rid in available]
            if restore:
                tree.selection_set(restore)
        except Exception:
            pass
        self._sync_provider_destinations()

    def cloud_create_group(self):
        if not self.cloud_session:
            self.cloud_group_status.configure(text="Sign in before creating a cloud group.", fg=AMBER)
            return
        if str((self.cloud_profile or {}).get("role")) != "provider":
            self.cloud_group_status.configure(text="Only a Signal Provider account may create shared groups.", fg=RED)
            return
        name = self.cloud_group_name_var.get().strip()
        desc = self.cloud_group_desc_var.get().strip()
        visibility = self.cloud_group_visibility_var.get().strip().lower()

        def done(row):
            self.cloud_group_name_var.set("")
            self.cloud_group_status.configure(text=f"Created cloud group: {row.get('name')} • {row.get('id')}", fg=GREEN)
            self.cloud_refresh_groups()

        self._cloud_run("Creating provider group",
                        lambda client, session: client.create_group(session, name, desc, visibility),
                        done, buttons=[self.cloud_create_group_btn], status=self.cloud_group_status)

    def cloud_create_invite(self):
        group = self._cloud_selected_group()
        if not self.cloud_session or not group:
            self.cloud_group_status.configure(text="Sign in and select a shared group first.", fg=AMBER)
            return
        if str((self.cloud_profile or {}).get("role")) != "provider":
            self.cloud_group_status.configure(text="Only the group provider can create invite codes.", fg=RED)
            return

        def done(code):
            self.cloud_invite_value.set(str(code or ""))
            self.cloud_group_status.configure(text="Invite code created. Share it privately; the receiver's request still requires provider approval.", fg=GREEN)

        self._cloud_run("Creating secure invite code",
                        lambda client, session: client.create_invite(session, group["id"]),
                        done, status=self.cloud_group_status)

    def cloud_copy_invite(self):
        code = str(self.cloud_invite_value.get() or "").strip()
        if not code:
            self.cloud_group_status.configure(text="Create an invite code first.", fg=AMBER)
            return
        self.root.clipboard_clear()
        self.root.clipboard_append(code)
        self.root.update_idletasks()
        self.cloud_group_status.configure(text="Cloud invite code copied. It expires after the configured period; do not post it publicly.", fg=GREEN)

    def cloud_request_by_invite(self):
        if not self.cloud_session:
            self.cloud_group_status.configure(text="Sign in as a verified Receiver first.", fg=AMBER)
            return
        if str((self.cloud_profile or {}).get("role")) != "receiver":
            self.cloud_group_status.configure(text="Only Receiver accounts may request a provider-group join.", fg=RED)
            return
        code = self.cloud_join_code_var.get().strip()

        def done(result):
            self.cloud_join_code_var.set("")
            self.cloud_group_status.configure(text="Access request submitted. A provider must approve it before shared signals become visible.", fg=GREEN)

        self._cloud_run("Submitting group access request",
                        lambda client, session: client.request_join_by_invite(session, code),
                        done, status=self.cloud_group_status)

    def cloud_request_public_group(self):
        group = self._cloud_selected_group()
        if not self.cloud_session or not group:
            self.cloud_group_status.configure(text="Sign in and select a public group first.", fg=AMBER)
            return
        if str((self.cloud_profile or {}).get("role")) != "receiver":
            self.cloud_group_status.configure(text="Only Receiver accounts may request access to public groups.", fg=RED)
            return
        if str(group.get("visibility") or "").lower() != "public":
            self.cloud_group_status.configure(text="This group is private. Use its provider-issued invite code instead.", fg=AMBER)
            return
        name = str(group.get("name") or "selected group")
        if not messagebox.askyesno("Request provider-group access",
                                   f"Send a join request to '{name}'? A provider must approve it.",
                                   parent=self.root):
            return

        def done(result):
            state = str((result or {}).get("status") or "pending")
            text = ("You are already a member of this group." if state == "already_member" else
                    f"Access request sent for {name}. The provider must approve it before signals are visible.")
            self.cloud_group_status.configure(text=text, fg=GREEN)

        self._cloud_run("Requesting public group access",
                        lambda client, session: client.request_join(session, group["id"]),
                        done, status=self.cloud_group_status)

    def cloud_refresh_requests(self):
        group = self._cloud_selected_group()
        if not self.cloud_session or not group:
            self.cloud_group_status.configure(text="Sign in and select a group first.", fg=AMBER)
            return

        def done(rows):
            self.cloud_requests = list(rows or [])
            tree = self.cloud_request_tree
            tree.delete(*tree.get_children())
            for row in self.cloud_requests:
                rid = str(row.get("id") or "")
                if not rid:
                    continue
                try:
                    when = datetime.fromisoformat(str(row.get("created_at")).replace("Z", "+00:00")).strftime("%Y-%m-%d %H:%M")
                except Exception:
                    when = str(row.get("created_at") or "-")[:19]
                tree.insert("", "end", iid=rid,
                            values=(row.get("requester_id") or "", when, rid))
            self.cloud_group_status.configure(text=f"Loaded {len(self.cloud_requests)} pending request(s).", fg=CYAN)

        self._cloud_run("Loading join requests",
                        lambda client, session: client.list_join_requests(session, group["id"]),
                        done, status=self.cloud_group_status)

    def cloud_decide_requests(self, approved):
        group = self._cloud_selected_group()
        selected = list(self.cloud_request_tree.selection())
        if not group or not self.cloud_session or not selected:
            self.cloud_group_status.configure(text="Select a group and one or more pending requests.", fg=AMBER)
            return
        verb = "approve" if approved else "decline"
        if not messagebox.askyesno("Confirm receiver access",
                                   f"{verb.title()} {len(selected)} selected Receiver request(s)?",
                                   parent=self.root):
            return

        def work(client, session):
            output = []
            for request_id in selected:
                client.decide_join_request(session, request_id, bool(approved))
                output.append(request_id)
            return output

        def done(rows):
            self.cloud_group_status.configure(text=f"{verb.title()}d {len(rows)} request(s).", fg=GREEN)
            self.cloud_refresh_requests()
            self.cloud_refresh_signals()

        self._cloud_run(f"{verb.title()}ing join requests", work, done,
                        buttons=[self.cloud_approve_btn, self.cloud_reject_btn],
                        status=self.cloud_group_status)

    def cloud_refresh_signals(self):
        group = self._cloud_selected_group()
        if not self.cloud_session or not group:
            self.cloud_signal_status.configure(text="Sign in and select a shared group to load its signal journal.", fg=AMBER)
            return

        def done(rows):
            self.cloud_signals = list(rows or [])
            self._cloud_draw_signals()
            self.cloud_signal_status.configure(text=f"Loaded {len(self.cloud_signals)} shared signal(s) for {group.get('name')}.", fg=CYAN)

        self._cloud_run("Loading shared signals",
                        lambda client, session: client.list_signals(session, group["id"]),
                        done, status=self.cloud_signal_status)

    def _cloud_draw_signals(self):
        try:
            tree = self.cloud_signal_tree
            tree.delete(*tree.get_children())
            for row in self.cloud_signals or []:
                rid = str(row.get("id") or "")
                if not rid:
                    continue
                try:
                    when = datetime.fromisoformat(str(row.get("created_at")).replace("Z", "+00:00")).strftime("%Y-%m-%d %H:%M")
                except Exception:
                    when = str(row.get("created_at") or "-")[:16]
                levels = f"Entry {row.get('entry')}  •  SL {row.get('stop_loss')}  •  TPs {row.get('take_profits')}"
                state = str(row.get("status") or "published")
                try:
                    progress = max(0, int(row.get("progress") or 0))
                except Exception:
                    progress = 0
                tp_total = len(row.get("take_profits") or [])
                if progress > 0:
                    state += f" • TP1–TP{progress} HIT"
                    if tp_total and progress < tp_total:
                        state += f" • TP{progress + 1}+ PENDING"
                elif tp_total:
                    state += f" • TP1–TP{tp_total} PENDING"
                tree.insert("", "end", iid=rid,
                            values=(when, f"{row.get('symbol', '')} {row.get('direction', '')}",
                                    levels[:120], state, rid))
        except Exception:
            pass

    def cloud_publish_selected_groups(self):
        self.cloud_publish_studio_signal(self._provider_selected_group_ids())

    def cloud_publish_studio_signal(self, group_ids=None):
        if not self.cloud_session:
            self.cloud_signal_status.configure(text="Sign in as a Signal Provider before publishing.", fg=AMBER)
            return
        user_id = str((self.cloud_session.get("user") or {}).get("id") or "")
        if str((self.cloud_profile or {}).get("role")) != "provider":
            self.cloud_signal_status.configure(text="Only Signal Providers may publish to shared groups.", fg=RED)
            return
        if group_ids is None:
            selected_ids = self._provider_selected_group_ids()
            if not selected_ids:
                single = self._cloud_selected_group()
                selected_ids = [str(single.get("id"))] if single else []
        else:
            selected_ids = [str(x) for x in group_ids if x]
        groups = [group for group in (self.cloud_groups or [])
                  if str(group.get("id") or "") in selected_ids
                  and str(group.get("owner_id") or "") == user_id]
        if not groups:
            self.cloud_signal_status.configure(text="Select one or more groups that you own in the Provider Destinations list.", fg=AMBER)
            return
        try:
            message = self._studio_signal_message()
            payload = self._studio_composer_payload()
        except Exception as exc:
            self.cloud_signal_status.configure(text=f"Check the Signal Studio form first: {exc}", fg=RED)
            return
        names = [str(group.get("name") or "Provider group") for group in groups]
        name_lines = "\n".join("  • " + name for name in names[:8])
        if len(names) > 8:
            name_lines += f"\n  ... and {len(names)-8} more"
        if not messagebox.askyesno("Publish shared signal",
                                   f"Publish {payload.get('symbol')} {payload.get('direction')} to {len(groups)} group(s)?\n{name_lines}\n\n"
                                   "Verified group members can view it. This cloud action does not send Telegram posts or MT5 orders.",
                                   parent=self.root):
            return

        def work(client, session):
            published, failures = [], []
            for group in groups:
                try:
                    row = client.create_signal(session, group["id"], payload)
                    published.append({"group": group, "signal": row})
                except Exception as exc:
                    failures.append({"group": group, "error": f"{type(exc).__name__}: {exc}"})
            return {"published": published, "failures": failures}

        def done(result):
            published = list(result.get("published") or [])
            failures = list(result.get("failures") or [])
            status = f"Shared signal published to {len(published)}/{len(groups)} group(s)."
            if failures:
                status += " Failed: " + "; ".join(
                    f"{item['group'].get('name')}: {item['error']}" for item in failures[:3])
            self.cloud_signal_status.configure(text=status, fg=GREEN if not failures else AMBER)
            if hasattr(self, "provider_dest_status"):
                self.provider_dest_status.configure(text=status, fg=GREEN if not failures else AMBER)
            if published:
                try:
                    first_id = str(published[0]["group"].get("id") or "")
                    if first_id:
                        self.cloud_group_tree.selection_set(first_id)
                        self.cloud_group_tree.focus(first_id)
                except Exception:
                    pass
                self.cloud_refresh_signals()

        self._cloud_run("Publishing shared signal", work, done,
                        status=self.cloud_signal_status)

    def cloud_mark_next_tp(self):
        row = self._cloud_selected_signal()
        if not row:
            self.cloud_signal_status.configure(text="Select a cloud signal first.", fg=AMBER)
            return
        levels = row.get("take_profits") or []
        progress = int(row.get("progress") or 0)
        if progress >= len(levels):
            self.cloud_signal_status.configure(text="All configured TP levels are already marked.", fg=AMBER)
            return
        self.cloud_mark_signal(f"TP{progress + 1} HIT")

    def _cloud_signal_update_details(self, row, status, progress, group):
        payload = row.get("payload") if isinstance(row.get("payload"), dict) else {}
        details = {"progress": int(progress), "group_id": str(group.get("id") or ""),
                   "status": str(status).upper()}
        try:
            entry = _signal_decimal(payload.get("entry", row.get("entry")), "Entry")
            if str(payload.get("entry_mode") or "").upper() == "RANGE":
                end = _signal_decimal(payload.get("range_end"), "Range end")
                entry = (entry + end) / Decimal("2")
            direction = str(row.get("direction") or payload.get("direction") or "BUY").upper()
            exit_price = None
            tps = row.get("take_profits") or payload.get("tp_levels") or []
            if not isinstance(tps, (list, tuple)):
                tps = [tps]
            upper = str(status).upper()
            if upper.startswith("TP"):
                match = re.match(r"TP\s*(\d+)", upper)
                idx = max(0, min(len(tps) - 1, int(match.group(1)) - 1)) if match and tps else -1
                if idx >= 0:
                    exit_price = _signal_decimal(tps[idx], f"TP{idx + 1}")
            elif "SL" in upper:
                exit_price = _signal_decimal(row.get("stop_loss") or payload.get("sl"), "SL")
            elif "BREAK EVEN" in upper or upper == "BE":
                exit_price = entry
            elif upper == "CLOSED":
                raw_exit = simpledialog.askstring(
                    "Signal outcome", "Optional exit price for this closed signal (leave blank if unknown):",
                    parent=self.root)
                if raw_exit:
                    exit_price = _signal_decimal(raw_exit, "Exit")
            if exit_price is not None:
                pip = Decimal(str(E.pip_size_of(str(row.get("symbol") or payload.get("symbol") or "XAUUSD"))))
                sign = Decimal("-1") if direction == "SELL" else Decimal("1")
                details["reference_entry"] = str(entry)
                details["exit_price"] = str(exit_price)
                details["target_pips"] = float(((exit_price - entry) / pip) * sign) if pip else 0.0
        except Exception as exc:
            details["calculation_note"] = f"Could not derive target pips: {type(exc).__name__}"
        raw_pnl = simpledialog.askstring(
            "Record realized P&L (optional)",
            "Optional: enter the INCREMENTAL actual NET realized P&L in USD for this update. Leave blank if unknown; the report will not estimate it.",
            parent=self.root)
        if raw_pnl and raw_pnl.strip():
            try:
                value = Decimal(raw_pnl.replace(",", "").replace("$", "").strip())
                if not value.is_finite():
                    raise ValueError("P&L must be a finite number.")
                details["realized_pnl_usd"] = float(value)
            except Exception:
                raise ValueError("Enter a valid USD amount, or leave it blank to skip.")
        raw_pips = simpledialog.askstring(
            "Record realized pips (optional)",
            "Optional: enter the INCREMENTAL actual pips realized by orders closed in this update. Leave blank if unknown.",
            parent=self.root)
        if raw_pips and raw_pips.strip():
            try:
                value = Decimal(raw_pips.replace(",", "").strip())
                if not value.is_finite():
                    raise ValueError("Pips must be a finite number.")
                details["realized_pips"] = float(value)
            except Exception:
                raise ValueError("Enter a valid pip value, or leave it blank to skip.")
        return details

    def cloud_mark_signal(self, status):
        row = self._cloud_selected_signal()
        if not row or not self.cloud_session:
            self.cloud_signal_status.configure(text="Select a cloud signal while signed in.", fg=AMBER)
            return
        status = str(status or "").upper()
        if str((self.cloud_profile or {}).get("role")) != "provider" or str(row.get("provider_id")) != str((self.cloud_session.get("user") or {}).get("id")):
            self.cloud_signal_status.configure(text="Only the signal's owning provider may change progress.", fg=RED)
            return
        progress = int(row.get("progress") or 0)
        if status.startswith("TP"):
            try:
                progress = max(progress, int(status[2:].split()[0]))
            except Exception:
                progress += 1
        else:
            progress = int(row.get("progress") or 0)
        group = self._cloud_selected_group()
        if not group:
            return
        if not messagebox.askyesno("Update shared signal", f"Set this signal status to {status}?", parent=self.root):
            return
        try:
            details = self._cloud_signal_update_details(row, status, progress, group)
        except ValueError as exc:
            self.cloud_signal_status.configure(text=str(exc), fg=RED)
            return

        def work(client, session):
            client.update_signal(session, row["id"], {"status": status, "progress": progress})
            client.add_signal_update(session, row["id"], status, details)
            return True

        def done(_):
            self.cloud_signal_status.configure(text=f"Shared signal updated: {status}", fg=GREEN)
            self.cloud_refresh_signals()

        self._cloud_run("Updating shared signal", work, done, status=self.cloud_signal_status)

    def cloud_export_group_report(self):
        group = self._cloud_selected_group()
        if not self.cloud_session or not group:
            self.cloud_signal_status.configure(text="Sign in and select a shared group before exporting its report.", fg=AMBER)
            return
        slug = re.sub(r"[^A-Za-z0-9_-]+", "_", str(group.get("name") or "Provider_Group")).strip("_")[:48] or "Provider_Group"
        filename = filedialog.asksaveasfilename(
            parent=self.root, title="Save provider group performance report",
            defaultextension=".html", initialfile=f"EdgeQuant_{slug}_Report.html",
            filetypes=(("Shareable HTML report", "*.html"), ("All files", "*.*")))
        if not filename:
            return
        logo_path = str(getattr(self, "studio_logo_path", "") or "")
        if not Path(logo_path).is_file():
            fallback_logo = BRAND_LOGO if BRAND_LOGO.is_file() else LOGO_SMALL
            if fallback_logo.is_file():
                logo_path = str(fallback_logo)
        logo_uri = ""
        try:
            if logo_path and Path(logo_path).is_file():
                ext = Path(logo_path).suffix.lower()
                mime = {".png": "image/png", ".jpg": "image/jpeg", ".jpeg": "image/jpeg",
                        ".webp": "image/webp"}.get(ext, "")
                raw = Path(logo_path).read_bytes()
                if mime and len(raw) <= 4_000_000:
                    logo_uri = f"data:{mime};base64," + base64.b64encode(raw).decode("ascii")
        except Exception:
            logo_uri = ""
        group_snapshot = dict(group)
        path = Path(filename)

        def work(client, session):
            signals = client.list_signals(session, group_snapshot["id"], limit=2000)
            updates = client.list_group_signal_updates(session, group_snapshot["id"], limit=2000)
            content = build_provider_report_html(group_snapshot, signals, updates, logo_uri)
            path.write_text(content, encoding="utf-8")
            return {"path": str(path), "signals": len(signals), "updates": len(updates)}

        def done(result):
            self.cloud_signal_status.configure(
                text=f"Group report saved: {result['signals']} signals, {result['updates']} updates. The logo is embedded in the HTML.",
                fg=GREEN)
            q_log(f"Provider group report exported: {result['path']}", "ok")
            open_path(path)

        self._cloud_run("Building shareable provider report", work, done,
                        status=self.cloud_signal_status)

    def cloud_process_selected_signal(self):
        if not CLOUD_BACKEND_ENABLED:
            status = getattr(self, "cloud_signal_status", None)
            if status is not None:
                status.configure(text="Cloud signal processing is not connected in this stage.", fg=AMBER)
            return
        if str(getattr(self, "app_role", "") or "").lower() != "receiver":
            self.cloud_signal_status.configure(text="Only a verified RECEIVER account can process a shared signal locally.", fg=RED)
            return
        row = self._cloud_selected_signal()
        group = self._cloud_selected_group()
        runner = self.bot
        if not row or not group or not self.cloud_session:
            self.cloud_signal_status.configure(text="Sign in, select a shared group, then select a signal.", fg=AMBER)
            return
        if str(row.get("group_id") or "") != str(group.get("id") or ""):
            self.cloud_signal_status.configure(text="The selected signal does not belong to the selected group. Refresh and retry.", fg=RED)
            return
        if not runner or not runner.is_alive() or not runner.loop or not runner.loop.is_running():
            self.cloud_signal_status.configure(text="Start the local engine in TEST RUN or LIVE before processing a cloud signal.", fg=AMBER)
            return
        if str(row.get("status") or "published").lower() not in ("published", "active") or int(row.get("progress") or 0) > 0:
            self.cloud_signal_status.configure(text="This signal has already progressed or closed; stale signals are blocked from local processing.", fg=AMBER)
            return
        payload = row.get("payload") if isinstance(row.get("payload"), dict) else {}
        entry_mode = str(payload.get("entry_mode") or "SINGLE").upper()
        order_type = str(payload.get("order_type") or "LIMIT").upper()
        entry = payload.get("entry", row.get("entry", ""))
        range_end = payload.get("range_end", "")
        stop = payload.get("sl", row.get("stop_loss", ""))
        levels = payload.get("tp_levels") or row.get("take_profits") or []
        if not isinstance(levels, (list, tuple)):
            levels = [levels]
        try:
            message = build_signal_message(
                payload.get("symbol") or row.get("symbol"),
                payload.get("direction") or row.get("direction"),
                entry_mode, entry, range_end, order_type, stop, levels,
                payload.get("be_advice") or "")
        except Exception as exc:
            self.cloud_signal_status.configure(text=f"Signal validation failed; no local processing: {exc}", fg=RED)
            return
        live = not bool(getattr(runner, "dry", True))
        summary = (f"{row.get('symbol')} {row.get('direction')} from {group.get('name')}\n"
                   f"Entry {entry}{(' - ' + str(range_end)) if entry_mode == 'RANGE' else ''}  •  "
                   f"SL {stop}  •  TPs {', '.join(map(str, levels))}\n\n"
                   + ("LIVE engine: real MT5 orders may be sent." if live else
                      "TEST RUN engine: no real MT5 orders will be sent."))
        if not messagebox.askyesno("Process shared signal locally", summary + "\n\nSubmit it once to the local engine?",
                                   parent=self.root):
            return
        if live and not self._confirm_studio_live():
            self.cloud_signal_status.configure(text="LIVE confirmation cancelled; the cloud signal was not processed.", fg=AMBER)
            return
        source = "CLOUD / " + str(group.get("name") or group.get("id") or "Provider group")
        msg_id = int(time.time())
        self.cloud_process_signal_btn.configure(state="disabled")
        self.cloud_signal_status.configure(text="Submitting the validated shared signal to the local engine…", fg=AMBER)

        async def dispatch():
            # Execute on the engine's own asyncio thread so MT5/engine state is
            # not mutated from the Tk worker thread.
            E.handle_signal(message, source, str(row.get("id") or ""), order_type, msg_id)

        def worker():
            error = ""
            try:
                future = asyncio.run_coroutine_threadsafe(dispatch(), runner.loop)
                future.result(timeout=90.0)
            except Exception as exc:
                error = f"{type(exc).__name__}: {exc}"
            try:
                self.root.after(0, lambda: finish(error))
            except Exception:
                pass

        def finish(error):
            try:
                self.cloud_process_signal_btn.configure(state="normal")
            except Exception:
                pass
            if error:
                self.cloud_signal_status.configure(text=f"Local processing failed: {error}", fg=RED)
            else:
                self.cloud_signal_status.configure(
                    text="Signal submitted once. Check LIVE TRADES / Journal for the engine's parser, risk-guard, and MT5 result.",
                    fg=GREEN)

        threading.Thread(target=worker, name="edgequant-cloud-signal", daemon=True).start()

    def cloud_edit_signal(self):
        row = self._cloud_selected_signal()
        if not row or not self.cloud_session:
            self.cloud_signal_status.configure(text="Select a shared signal to edit.", fg=AMBER)
            return
        if str(row.get("provider_id")) != str((self.cloud_session.get("user") or {}).get("id")):
            self.cloud_signal_status.configure(text="Only the owning provider may edit this signal.", fg=RED)
            return
        try:
            message = self._studio_signal_message()
            payload = self._studio_composer_payload()
        except Exception as exc:
            self.cloud_signal_status.configure(text=f"Check the Studio form: {exc}", fg=RED)
            return
        patch = {"symbol": payload["symbol"], "direction": payload["direction"],
                 "entry": payload["entry"], "stop_loss": payload["sl"],
                 "take_profits": payload["tp_levels"], "payload": payload}
        if not messagebox.askyesno("Edit shared signal",
                                   "Replace this signal's fields with the current Studio composer values?", parent=self.root):
            return
        def work(client, session):
            client.update_signal(session, row["id"], patch)
            client.add_signal_update(session, row["id"], "EDITED", {"payload": payload})
            return True
        self._cloud_run("Editing shared signal", work,
                        lambda _: (self.cloud_signal_status.configure(text="Shared signal edited.", fg=GREEN),
                                   self.cloud_refresh_signals()), status=self.cloud_signal_status)

    def cloud_delete_signal(self):
        row = self._cloud_selected_signal()
        if not row or not self.cloud_session:
            self.cloud_signal_status.configure(text="Select a shared signal to delete.", fg=AMBER)
            return
        if str(row.get("provider_id")) != str((self.cloud_session.get("user") or {}).get("id")):
            self.cloud_signal_status.configure(text="Only the owning provider may delete this signal.", fg=RED)
            return
        if not messagebox.askyesno("Delete shared signal",
                                   "Delete this shared signal record? This does not modify Telegram posts or MT5 trades.",
                                   parent=self.root):
            return
        self._cloud_run("Deleting shared signal",
                        lambda client, session: client.delete_signal(session, row["id"]),
                        lambda _: (self.cloud_signal_status.configure(text="Shared signal deleted.", fg=GREEN),
                                   self.cloud_refresh_signals()), status=self.cloud_signal_status)

    def _studio_activate_scroll(self):
        try:
            selected_index = self.studio_inner_nb.index(self.studio_inner_nb.select())
            key = {0: "manage", 1: "composer", 2: "reports", 3: "posts"}.get(
                selected_index, "manage")
            if selected_index == 2:
                self._studio_refresh_performance()
            elif selected_index == 3:
                self._studio_community_targets_refresh()
            canvas = self._studio_scroll_canvases.get(key)
            if canvas is not None:
                self._wheel_canvases[str(self.tab_studio)] = canvas
        except Exception:
            pass

    def _studio_rebuild_tp_inputs(self):
        area = getattr(self, "sig_tp_area", None)
        if area is None:
            return
        try:
            count = max(1, min(10, int(self.sig_tp_count_var.get())))
        except Exception:
            count = 3
        old = list(getattr(self, "sig_tp_vars", []))
        for child in area.winfo_children():
            child.destroy()
        self.sig_tp_vars = []
        area.columnconfigure(1, weight=1)
        area.columnconfigure(3, weight=1)
        for i in range(count):
            r, side = divmod(i, 2)
            c = side * 2
            var = tk.StringVar(value=old[i].get() if i < len(old) else "")
            self.sig_tp_vars.append(var)
            tk.Label(area, text=f"TP{i+1}", bg=PANEL, fg=CYAN,
                     font=widget_font("Consolas", 8, True)).grid(row=r, column=c, sticky="w", padx=(0, 5), pady=2)
            ttk.Entry(area, textvariable=var).grid(row=r, column=c+1, sticky="ew",
                                                   padx=(0, 10 if side == 0 else 0), pady=2)

    def _studio_send_mode_changed(self):
        """Recommend journal-linked tracking when the provider asks to process a signal."""
        try:
            if (str(self.sig_send_mode_var.get() or "").upper() == "PUBLISH + PROCESS"
                    and str(self.sig_tracking_mode_var.get() or "").upper() == "MANUAL"):
                self.sig_tracking_mode_var.set("LINKED JOURNAL AUTO")
        except Exception:
            pass

    def _studio_entry_mode_changed(self):
        try:
            state = "normal" if self.sig_entry_mode_var.get().upper() == "RANGE" else "disabled"
            self.sig_entry_end_widget.configure(state=state)
            if state == "disabled":
                self.sig_range_end_var.set("")
        except Exception:
            pass

    def _studio_be_mode_changed(self):
        try:
            state = "normal" if self.sig_be_mode.get().upper().startswith("CUSTOM") else "disabled"
            self.sig_be_custom_widget.configure(state=state)
            if state == "disabled":
                self.sig_be_custom_var.set("")
        except Exception:
            pass

