    def refresh_channel_progress(self):
        """Rank each channel by realized net P&L and show its trade outcomes."""
        if not hasattr(self, "cp_channels"):
            return
        try:
            if not (self.bot and self.bot.is_alive()):
                quiet(E.jr_load)
            period_map = {"TODAY": "today", "THIS WEEK": "week",
                          "THIS MONTH": "month", "ALL HISTORY": "all"}
            period = period_map.get(str(self.cp_period.get()).upper(), "all")
            start, end, label = E.jr_period_bounds(period)
            trades = list(E.TRADES)
            groups = {}
            for trade in trades:
                status = str(trade.get("status") or "")
                anchor = (trade.get("closed_ts") if status == "closed" and
                          trade.get("closed_ts") else
                          (trade.get("placed_ts") or trade.get("opened_ts")))
                if not E.jr_in(anchor, start, end):
                    continue
                key = (trade.get("source") or "no channel",
                       (trade.get("source_type") or "").upper())
                groups.setdefault(key, []).append(trade)
            ranked = []
            for key, records in groups.items():
                stats = E.jr_stats(records)
                closed = stats["tp"] + stats["be"] + stats["sl"] + stats["manual"]
                ranked.append((key, records, stats, closed))
            ranked.sort(key=lambda item: (
                item[3] == 0, -float(item[2].get("pl") or 0.0),
                item[2].get("win") is None, -(item[2].get("win") or 0.0),
                -item[3], item[0][0].casefold(), item[0][1]))
            previous = self._cp_selected_key
            self.cp_channels.delete(*self.cp_channels.get_children())
            self._cp_row_keys = {}
            self._cp_groups = {key: records for key, records, _stats, _closed in ranked}
            chosen_iid = None
            for rank, (key, records, stats, closed) in enumerate(ranked, 1):
                iid = f"channel_{rank}"
                tag = ("positive" if stats["pl"] > 0 else
                       ("negative" if stats["pl"] < 0 else "inactive"))
                self.cp_channels.insert("", "end", iid=iid, tags=(tag,), values=(
                    f"#{rank}", key[0], key[1] or "-", stats["n"], stats["open"],
                    stats["pending"], stats["tp"], stats["be"], stats["sl"],
                    stats["manual"], fmt_win(stats["win"]), fmt_pl(stats["pl"])))
                self._cp_row_keys[iid] = key
                if key == previous:
                    chosen_iid = iid
            total_stats = E.jr_stats(trades)
            self.cp_summary.configure(
                text=(f"{label}   |   {len(ranked)} channel(s)   |   "
                      f"{total_stats['tp']} TP / {total_stats['be']} BE / "
                      f"{total_stats['sl']} SL / {total_stats['manual']} manual close   |   "
                      f"realized net {fmt_pl(total_stats['pl'])} USD   |   "
                      f"open {total_stats['open']} / pending {total_stats['pending']}"))
            self.cp_sync.configure(text=f"updated {datetime.now().strftime('%H:%M:%S')}")
            if ranked:
                if chosen_iid is None:
                    chosen_iid = self.cp_channels.get_children()[0]
                self.cp_channels.selection_set(chosen_iid)
                self.cp_channels.focus(chosen_iid)
                self._cp_selected_key = self._cp_row_keys.get(chosen_iid)
                self._paint_channel_progress_detail()
            else:
                self._cp_selected_key = None
                self.cp_detail.delete(*self.cp_detail.get_children())
                self.cp_detail_title.configure(text="No trades recorded for this period.")
        except Exception as exc:
            q_log(f"channel progress: {type(exc).__name__}: {exc}", "err")

    def _channel_progress_select(self, _event=None):
        try:
            selection = self.cp_channels.selection()
            if selection:
                self._cp_selected_key = self._cp_row_keys.get(selection[0])
                self._paint_channel_progress_detail()
        except Exception:
            pass

    def _paint_channel_progress_detail(self):
        if not hasattr(self, "cp_detail"):
            return
        key = self._cp_selected_key
        records = list(self._cp_groups.get(key, [])) if key else []
        name, category = key if key else ("All channels", "")
        self.cp_detail.delete(*self.cp_detail.get_children())
        ordered = sorted(records, key=lambda row: -float(
            row.get("closed_ts") or row.get("opened_ts") or row.get("placed_ts") or 0))
        for row in ordered:
            status = str(row.get("status") or "").lower()
            result = str(row.get("result") or "").lower()
            if status == "pending":
                outcome, tag = "PENDING", "pending"
            elif status == "open":
                outcome, tag = "OPEN", "open"
            elif status == "cancelled":
                outcome, tag = "CANCELLED", "cancelled"
            elif status == "rejected":
                outcome, tag = "REJECTED", "rejected"
            else:
                outcome = (result or "manual").upper()
                tag = result if result in ("tp", "be", "sl", "manual") else "manual"
            opened = row.get("opened_ts") or row.get("placed_ts")
            def clock(value):
                try:
                    return datetime.fromtimestamp(float(value)).strftime("%H:%M") if value else "-"
                except Exception:
                    return "-"
            try:
                opened_dt = datetime.fromtimestamp(float(opened)) if opened else None
            except Exception:
                opened_dt = None
            ticket = row.get("ticket") or "-"
            broker = row.get("broker") or ""
            if broker:
                ticket = f"{broker} / {ticket}"
            self.cp_detail.insert("", "end", tags=(tag,), values=(
                opened_dt.strftime("%Y-%m-%d") if opened_dt else "-",
                clock(opened), clock(row.get("closed_ts")), row.get("symbol") or "-",
                row.get("direction") or "-", outcome,
                f"{float(row.get('open_price') or row.get('price') or 0):g}",
                f"{float(row.get('sl_now') or row.get('sl') or 0):g}",
                f"{float(row.get('tp_now') or row.get('tp') or 0):g}",
                (f"{float(row.get('close_price') or 0):g}" if row.get("close_price") else "-"),
                f"{float(row.get('lot') or 0):g}",
                (fmt_pl(row.get("net") or 0) if status == "closed" else "-"), ticket))
        self.cp_detail_title.configure(
            text=(f"{name}  [{category or 'ALL'}]  •  {len(ordered)} trade(s)  •  "
                  f"TP / BE / SL / manual closes are shown separately"))

    # ---------------------------------------------------------- MANUAL TRADES --
