    def refresh_manual_trades(self):
        if not hasattr(self, "manual_tree"):
            return
        snapshot = self.external_trade_snapshot or {}
        connected = snapshot.get("status") == "connected"
        if connected:
            stamp = snapshot.get("updated_ts")
            try:
                stamp_text = datetime.fromtimestamp(float(stamp)).strftime("%H:%M:%S") if stamp else "just now"
            except Exception:
                stamp_text = "updated"
            accounts = ", ".join(snapshot.get("accounts") or [])
            account_text = f"  •  {accounts}" if accounts else ""
            self.manual_sync_label.configure(
                text=f"MT5 CONNECTED  •  {stamp_text}{account_text}", fg=GREEN)
            realized = float(snapshot.get("net_today") or 0.0)
            floating = float(snapshot.get("float") or 0.0)
            self.manual_card_net.configure(text=f"{fmt_pl(realized)} USD", fg=pl_colour(realized))
            self.manual_card_net_sub.configure(
                text=f"{snapshot.get('deal_count', 0)} deal(s) included; exits today")
            self.manual_card_float.configure(text=f"{fmt_pl(floating)} USD", fg=pl_colour(floating))
            self.manual_card_float_sub.configure(text="non-EdgeQuant open-position floating P&L")
            opened = int(snapshot.get("open_today") or 0) + int(snapshot.get("pending_today") or 0)
            self.manual_card_open.configure(text=str(opened), fg=CYAN if opened else MUTED)
            self.manual_card_open_sub.configure(
                text=f"{snapshot.get('open_today', 0)} live  •  {snapshot.get('pending_today', 0)} pending")
            self.manual_card_closed.configure(text=str(snapshot.get("closed_today", 0)),
                                              fg=PURPLE if snapshot.get("closed_today") else MUTED)
            self.manual_card_closed_sub.configure(text="external positions with a close today")
        else:
            message = str(snapshot.get("error") or "MT5 is not connected; snapshot unavailable.")
            self.manual_sync_label.configure(text=message[:150], fg=AMBER)
            for widget in (self.manual_card_net, self.manual_card_float,
                           self.manual_card_open, self.manual_card_closed):
                widget.configure(text="—", fg=MUTED)
            self.manual_card_net_sub.configure(text="not synced")
            self.manual_card_float_sub.configure(text="not synced")
            self.manual_card_open_sub.configure(text="not synced")
            self.manual_card_closed_sub.configure(text="not synced")

        today = E.jr_today_key()
        rows = [row for row in (snapshot.get("trades") or [])
                if E.jr_day_key(row.get("opened_ts")) == today]
        rows.sort(key=lambda row: (row.get("opened_ts") or 0, row.get("ticket") or 0),
                  reverse=True)
        self.manual_tree.delete(*self.manual_tree.get_children())
        self._manual_rows_by_iid = {}
        self.manual_empty.configure(
            text=("" if rows else
                  ("No non-EdgeQuant trades opened today."
                   if connected else "No rows: connect MT5 to load today's non-EdgeQuant trades.")),
            fg=MUTED if connected else AMBER)
        for index, row in enumerate(rows):
            status = str(row.get("status") or "").upper()
            result = str(row.get("result") or "").lower()
            if status == "OPEN":
                state, tag = "OPEN", "open"
            elif status == "PENDING":
                state, tag = "PENDING", "pending"
            else:
                state = result.upper() if result else "CLOSED"
                tag = result if result in ("tp", "be", "sl", "manual") else "manual"
            try:
                opened = datetime.fromtimestamp(float(row.get("opened_ts") or 0)).strftime("%Y-%m-%d %H:%M")
            except Exception:
                opened = "-"
            broker = str(row.get("broker") or "MAIN")
            ticket = int(row.get("ticket") or 0)
            magic = int(row.get("magic") or 0)
            origin = "MANUAL" if magic == 0 else f"EA #{magic}"
            iid = f"manual_{index}"
            self._manual_rows_by_iid[iid] = row
            self.manual_tree.insert("", "end", iid=iid, tags=(tag,), values=(
                opened, f"{broker} / {ticket}", row.get("symbol") or "-",
                row.get("direction") or "-", row.get("kind") or "-", state,
                f"{float(row.get('lot') or 0):g}", f"{float(row.get('entry') or 0):g}",
                f"{float(row.get('current') or 0):g}", f"{float(row.get('sl') or 0):g}",
                f"{float(row.get('tp') or 0):g}", fmt_pl(row.get("net_today") or 0),
                fmt_pl(row.get("floating") or 0), origin))
        self._manual_selection_changed()

    def _manual_selection_changed(self, _event=None):
        selection = self.manual_tree.selection() if hasattr(self, "manual_tree") else ()
        row = self._manual_rows_by_iid.get(selection[0]) if selection else None
        editable = bool(row and str(row.get("status") or "").upper() in ("OPEN", "PENDING"))
        if hasattr(self, "manual_edit_btn"):
            self.manual_edit_btn.configure(state="normal" if editable else "disabled")

    def _edit_selected_manual_trade(self):
        selection = self.manual_tree.selection() if hasattr(self, "manual_tree") else ()
        row = self._manual_rows_by_iid.get(selection[0]) if selection else None
        if not row:
            messagebox.showinfo("Manual trades", "Select a trade first.", parent=self.root)
            return
        if str(row.get("status") or "").upper() not in ("OPEN", "PENDING"):
            messagebox.showinfo("Manual trades", "Only open positions and pending orders can be edited.",
                                parent=self.root)
            return
        self._open_manual_trade_editor(row)

    def _open_manual_trade_editor(self, row):
        ticket = int(row.get("ticket") or 0)
        broker = str(row.get("broker") or "MAIN")
        status = str(row.get("status") or "").upper()
        if ticket <= 0 or status not in ("OPEN", "PENDING"):
            return
        uid = str(row.get("uid") or f"{broker}:{ticket}:{status}")
        existing = self._manual_edit_dialogs.get(uid)
        if existing is not None:
            try:
                existing.deiconify()
                existing.lift()
                return
            except Exception:
                self._manual_edit_dialogs.pop(uid, None)
        pending = status == "PENDING"
        symbol = str(row.get("symbol") or "")
        direction = str(row.get("direction") or "").upper()

        def price_text(value):
            try:
                number = float(value or 0)
                return f"{number:g}" if number else ""
            except Exception:
                return ""

        win = tk.Toplevel(self.root)
        win.title(f"Edit MT5 trade  •  {broker} / #{ticket}")
        win.configure(bg=BG)
        win.transient(self.root)
        win.resizable(False, False)
        body = tk.Frame(win, bg=PANEL, highlightbackground=LINE, highlightthickness=1)
        body.pack(fill="both", expand=True, padx=12, pady=12)
        tk.Label(body, text=f"{symbol}  {direction}  •  {status}",
                 bg=PANEL, fg=GOLD, font=widget_font("Segoe UI", 13, True)
                 ).pack(anchor="w", padx=16, pady=(14, 3))
        tk.Label(body, text=f"Broker {broker}   |   Ticket {ticket}   |   lot {float(row.get('lot') or 0):g}",
                 bg=PANEL, fg=MUTED, font=widget_font("Consolas", 9)
                 ).pack(anchor="w", padx=16, pady=(0, 10))
        form = tk.Frame(body, bg=PANEL2, highlightbackground=LINE, highlightthickness=1)
        form.pack(fill="x", padx=14, pady=(0, 10))
        vars_by_name = {"entry": tk.StringVar(value=price_text(row.get("entry"))),
                        "sl": tk.StringVar(value=price_text(row.get("sl"))),
                        "tp": tk.StringVar(value=price_text(row.get("tp")))}
        entries = {}
        for grid_row, (field, title) in enumerate((("entry", "Entry price"),
                                                    ("sl", "Stop loss"),
                                                    ("tp", "Take profit"))):
            tk.Label(form, text=title, bg=PANEL2, fg=FG,
                     font=widget_font("Segoe UI", 9, True)).grid(
                         row=grid_row, column=0, sticky="w", padx=12, pady=7)
            edit = tk.Entry(form, textvariable=vars_by_name[field], width=22,
                            bg=PANEL, fg=FG, insertbackground=FG, relief="flat",
                            highlightthickness=1, highlightbackground=LINE,
                            highlightcolor=ACCENT, font=widget_font("Consolas", 11))
            edit.grid(row=grid_row, column=1, sticky="ew", padx=12, pady=7)
            entries[field] = edit
        form.columnconfigure(1, weight=1)
        if not pending:
            entries["entry"].configure(state="disabled", disabledbackground=PANEL2,
                                        disabledforeground=MUTED)
        move_be = tk.BooleanVar(value=False)
        be_check = tk.Checkbutton(
            form, text="Move SL to break-even (profit-only; SL becomes the entry price)",
            variable=move_be, state="normal" if not pending else "disabled",
            bg=PANEL2, fg=FG, selectcolor=PANEL, activebackground=PANEL2,
            activeforeground=FG, font=widget_font("Segoe UI", 8),
            anchor="w", justify="left")
        be_check.grid(row=3, column=0, columnspan=2, sticky="w", padx=12, pady=(2, 8))
        tk.Label(body, text=("Leave a field blank to keep it unchanged. Existing SL protection "
                             "cannot be removed. The selected ticket is re-checked before sending."),
                 bg=PANEL, fg=MUTED, justify="left", wraplength=500,
                 font=widget_font("Segoe UI", 8)).pack(fill="x", padx=16, pady=(0, 8))
        status_label = tk.Label(body, text="No MT5 change is made until you review and confirm.",
                                bg=PANEL, fg=CYAN, anchor="w",
                                font=widget_font("Segoe UI", 8))
        status_label.pack(fill="x", padx=16, pady=(0, 8))
        self._manual_edit_dialogs[uid] = win
        self._manual_edit_status = getattr(self, "_manual_edit_status", {})
        self._manual_edit_status[uid] = status_label

        def close_dialog():
            self._manual_edit_dialogs.pop(uid, None)
            getattr(self, "_manual_edit_status", {}).pop(uid, None)
            try:
                win.destroy()
            except Exception:
                pass

        win.protocol("WM_DELETE_WINDOW", close_dialog)

        def parse_optional(field):
            text = vars_by_name[field].get().strip().replace(",", "")
            if not text:
                return None
            try:
                value = float(text)
            except Exception as exc:
                raise ValueError(f"{field.upper()} must be a price number.") from exc
            if not math.isfinite(value):
                raise ValueError(f"{field.upper()} must be finite.")
            return value

        def review_and_apply():
            try:
                new_entry = parse_optional("entry") if pending else None
                new_sl = None if move_be.get() else parse_optional("sl")
                new_tp = parse_optional("tp")
            except ValueError as exc:
                messagebox.showerror("Invalid price", str(exc), parent=win)
                return
            old_entry = float(row.get("entry") or 0)
            old_sl = float(row.get("sl") or 0)
            old_tp = float(row.get("tp") or 0)
            target_entry = old_entry if new_entry is None else new_entry
            target_sl = target_entry if move_be.get() else (old_sl if new_sl is None else new_sl)
            target_tp = old_tp if new_tp is None else new_tp
            changes = []
            if pending and new_entry is not None and abs(target_entry - old_entry) > 1e-9:
                changes.append(f"Entry: {old_entry:g}  ->  {target_entry:g}")
            if move_be.get():
                changes.append(f"SL: {old_sl:g}  ->  break-even {target_entry:g} (profit-only)")
            elif new_sl is not None and abs(target_sl - old_sl) > 1e-9:
                changes.append(f"SL: {old_sl:g}  ->  {target_sl:g}")
            if new_tp is not None and abs(target_tp - old_tp) > 1e-9:
                changes.append(f"TP: {old_tp:g}  ->  {target_tp:g}")
            if not changes:
                messagebox.showinfo("No changes", "Enter at least one different price or choose break-even.",
                                    parent=win)
                return
            summary = (f"Broker: {broker}\nTicket: {ticket}  •  {symbol} {direction}  •  {status}\n\n"
                       + "\n".join(changes)
                       + "\n\nOnly this ticket will be modified. No order will be opened or closed.\n"
                         "MT5 will re-check the ticket and broker-side price rules before applying.")
            if not messagebox.askyesno("Confirm single-ticket MT5 edit", summary,
                                       icon="warning", parent=win):
                return
            if uid in getattr(self, "_manual_edit_inflight", set()):
                return
            kwargs = {"ticket": ticket, "broker": broker,
                      "order_type": "PENDING" if pending else "OPEN",
                      "entry": new_entry, "sl": new_sl, "tp": new_tp,
                      "move_be": bool(move_be.get())}
            status_label.configure(text="Applying one confirmed ticket edit…", fg=AMBER)
            try:
                self.manual_edit_btn.configure(state="disabled")
            except Exception:
                pass
            self._submit_manual_trade_edit(uid, kwargs)

        buttons = tk.Frame(body, bg=PANEL)
        buttons.pack(fill="x", padx=14, pady=(2, 14))
        ttk.Button(buttons, text="Cancel", command=close_dialog).pack(side="right", padx=(6, 0))
        ttk.Button(buttons, text="Review & confirm…", command=review_and_apply,
                   style="Go.TButton").pack(side="right")
        self._center_toplevel(win)
        win.grab_set()

    def _submit_manual_trade_edit(self, uid, kwargs):
        if not hasattr(self, "_manual_edit_inflight"):
            self._manual_edit_inflight = set()
        if uid in self._manual_edit_inflight:
            return
        self._manual_edit_inflight.add(uid)
        local_task = not bool(self.bot and self.bot.is_alive())
        if local_task:
            self._mt5_ui_tasks = getattr(self, "_mt5_ui_tasks", 0) + 1

        def worker():
            try:
                if self.bot and self.bot.is_alive():
                    loop = getattr(self.bot, "loop", None)
                    if loop is None or not loop.is_running():
                        raise RuntimeError("The trading engine loop is not ready; refresh and try again.")
                    async def apply_on_engine_loop():
                        return E.mt5_edit_ticket(**kwargs)
                    future = asyncio.run_coroutine_threadsafe(apply_on_engine_loop(), loop)
                    result = future.result(timeout=90)
                else:
                    with self._mt5_api_lock:
                        result = E.mt5_edit_ticket(**kwargs)
                if not isinstance(result, dict):
                    result = {"ok": False, "message": "MT5 returned an unexpected edit result."}
            except Exception as exc:
                result = {"ok": False,
                          "message": f"Edit failed: {type(exc).__name__}: {exc}"}
            finally:
                if local_task:
                    self._mt5_ui_tasks = max(0, getattr(self, "_mt5_ui_tasks", 1) - 1)
            RESULT_Q.put(("manual_edit", uid, result))

        threading.Thread(target=worker, daemon=True,
                         name=f"edgequant-edit-{kwargs.get('ticket')}").start()

    def _manual_edit_result(self, uid, result):
        getattr(self, "_manual_edit_inflight", set()).discard(uid)
        dialog = self._manual_edit_dialogs.get(uid)
        status_label = getattr(self, "_manual_edit_status", {}).get(uid)
        ok = bool((result or {}).get("ok"))
        text = str((result or {}).get("message") or "Edit failed.")
        if ok:
            q_log(f"local MT5 edit: {text}  ticket {result.get('ticket')}", "ok")
            if dialog is not None:
                try:
                    self._manual_edit_dialogs.pop(uid, None)
                    getattr(self, "_manual_edit_status", {}).pop(uid, None)
                    dialog.grab_release()
                    dialog.destroy()
                except Exception:
                    pass
            messagebox.showinfo("MT5 trade updated", text, parent=self.root)
            self.poll_mt5(schedule=False)
        else:
            q_log(f"local MT5 edit not applied: {text}", "warn")
            if status_label is not None:
                try:
                    status_label.configure(text=text, fg=RED)
                except Exception:
                    pass
            try:
                self._manual_selection_changed()
                messagebox.showerror("MT5 edit not applied", text, parent=dialog or self.root)
            except Exception:
                pass

    # ------------------------------------------------------------ CHANNELS --
