    def scan_telegram(self):
        """Scan the logged-in account's dialogs only while the engine is stopped."""
        if self.bot and self.bot.is_alive():
            messagebox.showinfo(
                "EdgeQuant",
                "Stop the bot first, then scan.\n\n"
                "Telegram session files must not be opened by two clients at once.")
            return
        try:
            if self._tg_login_window is not None and self._tg_login_window.winfo_exists():
                messagebox.showinfo("EdgeQuant", "Close the Telegram LOGIN dialog before scanning.")
                return
        except Exception:
            pass
        try:
            login_pending = getattr(E, "_login_client", None) is not None and \
                bool(E._login_client.is_connected())
        except Exception:
            login_pending = False
        if login_pending:
            messagebox.showinfo(
                "EdgeQuant",
                "Finish or close the Telegram LOGIN dialog first, then scan.\n\n"
                "The login client is still connected to the same session file.")
            return
        if not getattr(E, "HAVE_TELETHON", False) or getattr(E, "TelegramClient", None) is None:
            messagebox.showerror("EdgeQuant", "Telegram support is unavailable.\n"
                                 "Check telethon / requirements.txt.")
            return
        if not E.tg_session_exists():
            if messagebox.askyesno("EdgeQuant", "Log in to Telegram first, then scan chats?\n\n"
                                   "Press LOGIN, finish the one-time code/2FA steps, "
                                   "then click SCAN TELEGRAM again."):
                self.tg_login_dialog()
            return

        win = tk.Toplevel(self.root)
        win.title(f"{E.BOT_NAME} - Scan Telegram chats")
        win.configure(bg=PANEL)
        dialog_w, dialog_h = self._place_dialog(win, 820, 570, 560, 400)
        win.transient(self.root)

        tk.Label(win, text="SCAN TELEGRAM CHATS", bg=PANEL, fg=GOLD,
                 font=widget_font("Segoe UI", 12, True)).pack(anchor="w", padx=14,
                                                              pady=(12, 2))
        tk.Label(win, text=("Lists groups/channels already visible to this Telegram account. "
                            "Type a name, multi-select with Ctrl/Shift, then choose LIMIT or MARKET. "
                            "Already-joined private groups are supported; no invite link is required or followed. "
                            "Posts sent by this logged-in account are ignored by default (incoming-only). "
                            "Direct messages and bots cannot be sources. Only chat metadata is read, never message history."),
                 bg=PANEL, fg=MUTED, justify="left", wraplength=max(360, dialog_w - 40),
                 font=widget_font("Segoe UI", 8)).pack(anchor="w", padx=14, pady=(0, 8))

        search = tk.Frame(win, bg=PANEL2, highlightbackground=LINE, highlightthickness=1)
        search.pack(fill="x", padx=14, pady=(0, 6))
        tk.Label(search, text="SEARCH BY NAME", bg=PANEL2, fg=GOLD,
                 font=widget_font("Segoe UI", 8, True)).pack(side="left", padx=(8, 7), pady=6)
        search_var = tk.StringVar()
        search_entry = tk.Entry(search, textvariable=search_var, bg=DEEP, fg=FG,
                                insertbackground=FG, relief="flat",
                                font=widget_font("Segoe UI", 10))
        search_entry.pack(side="left", fill="x", expand=True, padx=(0, 8), pady=5)
        search_entry.configure(state="disabled")

        area = ttk.Frame(win, style="Panel.TFrame")
        area.pack(fill="both", expand=True, padx=14, pady=(0, 6))
        tree = ttk.Treeview(area, columns=("name", "type", "id"), show="headings",
                            selectmode="extended",
                            height=max(7, min(16, (dialog_h - 215) // 18)))
        tree.heading("name", text="CHAT / CHANNEL NAME")
        tree.heading("type", text="TYPE")
        tree.heading("id", text="TELEGRAM ID")
        tree.column("name", width=490, minwidth=250, anchor="w")
        tree.column("type", width=100, minwidth=85, anchor="center")
        tree.column("id", width=130, minwidth=110, anchor="e")
        vsb = ttk.Scrollbar(area, orient="vertical", command=tree.yview)
        hsb = ttk.Scrollbar(area, orient="horizontal", command=tree.xview)
        tree.configure(yscrollcommand=vsb.set, xscrollcommand=hsb.set)
        tree.grid(row=0, column=0, sticky="nsew")
        vsb.grid(row=0, column=1, sticky="ns")
        hsb.grid(row=1, column=0, sticky="ew")
        area.rowconfigure(0, weight=1)
        area.columnconfigure(0, weight=1)

        status = tk.Label(win, text="Connecting to Telegram and reading chat names...",
                          bg=PANEL, fg=AMBER, anchor="w",
                          font=widget_font("Consolas", 9))
        status.pack(fill="x", padx=14, pady=(0, 7))
        buttons = ttk.Frame(win, style="Panel.TFrame")
        buttons.pack(fill="x", padx=14, pady=(0, 12))
        limit_btn = ttk.Button(buttons, text="ADD AS LIMIT", style="Go.TButton",
                               state="disabled", command=lambda: add_selected("LIMIT"))
        market_btn = ttk.Button(buttons, text="ADD AS MARKET", style="Go.TButton",
                                state="disabled", command=lambda: add_selected("MARKET"))
        limit_btn.pack(side="left", padx=(0, 7))
        market_btn.pack(side="left")
        ttk.Button(buttons, text="CLOSE", command=win.destroy).pack(side="right")

        data = {"items": [], "by_iid": {}}

        def selected_rows():
            return [data["by_iid"].get(iid) for iid in tree.selection()
                    if data["by_iid"].get(iid)]

        def set_add_state(*_):
            rows = selected_rows()
            enabled = bool(rows) and all(row.get("can_add") for row in rows)
            state = "normal" if enabled else "disabled"
            limit_btn.configure(state=state)
            market_btn.configure(state=state)
            if rows:
                if enabled:
                    names = ", ".join(row["name"] for row in rows[:3])
                    more = f" (+{len(rows)-3})" if len(rows) > 3 else ""
                    status.configure(text=f"{len(rows)} selected: {names}{more}. Choose one category to add them.",
                                     fg=CYAN)
                else:
                    status.configure(text="Only joined groups/channels can be added as signal sources.",
                                     fg=AMBER)

        def draw_matches(*_):
            for iid in tree.get_children(""):
                tree.delete(iid)
            data["by_iid"] = {}
            matches = filter_telegram_dialogs(data["items"], search_var.get())
            for row in matches:
                iid = "chat_" + str(row["id"])
                data["by_iid"][iid] = row
                tree.insert("", "end", iid=iid,
                            values=(row["name"], row["kind"], row["id"]))
            if data["items"]:
                status.configure(text=(f"Showing {len(matches)} of {len(data['items'])} chats. "
                                       "Use Ctrl/Shift to select several joined groups/channels, then choose LIMIT or MARKET."),
                                 fg=CYAN)
            set_add_state()

        def add_selected(category):
            rows = selected_rows()
            if not rows:
                status.configure(text="Select one or more chats first.", fg=AMBER)
                return
            if not all(row.get("can_add") for row in rows):
                status.configure(text="Only joined Telegram groups/channels can be added.", fg=RED)
                return
            names = [row["name"] for row in rows]
            names_preview = "\n".join(f"  • {name}" for name in names[:12])
            if len(names) > 12:
                names_preview += f"\n  ... and {len(names)-12} more"
            prompt = (f"Add {len(rows)} selected source(s) as {category}?\n\n{names_preview}\n\n"
                      "The selected chats will be saved in EdgeQuant and monitored when you START the engine. "
                      "Future signals may place real orders in LIVE mode. Nothing is sent now.")
            if not messagebox.askyesno("Confirm selected sources", prompt, parent=win):
                return
            if self.bot and self.bot.is_alive():
                status.configure(text="Stop the bot before adding sources.", fg=RED)
                return
            try:
                if self._tg_login_window is not None and self._tg_login_window.winfo_exists():
                    status.configure(text="Close the Telegram LOGIN dialog before changing sources.", fg=RED)
                    return
            except Exception:
                pass
            try:
                login_client = getattr(E, "_login_client", None)
                if login_client is not None and login_client.is_connected():
                    status.configure(text="Finish or close Telegram LOGIN before changing sources.", fg=RED)
                    return
            except Exception:
                pass
            lock = E.acquire_singleton()
            if lock is None:
                status.configure(text="Another EdgeQuant window/bot is using Telegram. Close it and retry.", fg=RED)
                return
            try:
                def visible_channel_names(key):
                    box = getattr(self, "set_entries", {}).get(key)
                    if isinstance(box, tk.Text):
                        return [line.strip() for line in
                                box.get("1.0", "end").splitlines()
                                if line.strip() and not line.strip().startswith("#")]
                    value = getattr(E, key, [])
                    return [value] if isinstance(value, str) and value.strip() else list(value or [])

                current_limits = visible_channel_names("LIMIT_CHANNELS")
                current_markets = visible_channel_names("MARKET_CHANNELS")
                current_ids = dict(getattr(E, "CHANNEL_IDS", {}) or {})
                id_box = getattr(self, "set_entries", {}).get("CHANNEL_IDS")
                if isinstance(id_box, tk.Text):
                    current_ids = {}
                    for line in id_box.get("1.0", "end").splitlines():
                        key, sep, cat = line.partition(":")
                        key, cat = key.strip(), cat.strip().upper()
                        if not sep or cat not in ("LIMIT", "MARKET") or not key:
                            continue
                        try:
                            key = int(key)
                        except Exception:
                            pass
                        current_ids[key] = cat
                current_names = dict(getattr(E, "CHANNEL_ID_NAMES", {}) or {})
                last_updates = None
                for row in rows:
                    last_updates = channel_add_settings(
                        row["name"], row["id"], category, current_limits, current_markets,
                        current_ids, current_names)
                    current_limits = last_updates["LIMIT_CHANNELS"][0]
                    current_markets = last_updates["MARKET_CHANNELS"][0]
                    current_names = last_updates["CHANNEL_ID_NAMES"][0]
                    current_ids = {}
                    for item in last_updates["CHANNEL_IDS"][0]:
                        key, sep, cat = str(item).partition(":")
                        if sep:
                            try:
                                key = int(key)
                            except Exception:
                                pass
                            current_ids[key] = cat
                updates = {
                    "LIMIT_CHANNELS": (current_limits, "list"),
                    "MARKET_CHANNELS": (current_markets, "list"),
                    "CHANNEL_IDS": (last_updates["CHANNEL_IDS"][0], "dict"),
                    "CHANNEL_ID_NAMES": (current_names, "map"),
                }
                save_settings_file(APP_DIR / "edgequant_auto.py", updates)
                reload_engine()
                # Keep an already-open SETTINGS page from overwriting the new selection.
                for name, value in (("LIMIT_CHANNELS", getattr(E, "LIMIT_CHANNELS", [])),
                                    ("MARKET_CHANNELS", getattr(E, "MARKET_CHANNELS", []))):
                    box = getattr(self, "set_entries", {}).get(name)
                    if isinstance(box, tk.Text):
                        values = [value] if isinstance(value, str) else list(value or [])
                        box.delete("1.0", "end")
                        box.insert("1.0", "\n".join(str(item) for item in values))
                id_box = getattr(self, "set_entries", {}).get("CHANNEL_IDS")
                if isinstance(id_box, tk.Text):
                    rows_text = [f"{key}: {cat}" for key, cat in
                                 (getattr(E, "CHANNEL_IDS", {}) or {}).items()]
                    id_box.delete("1.0", "end")
                    id_box.insert("1.0", "\n".join(rows_text))
                self.refresh_channels()
                self.root.after(0, self.refresh_dashboard)
                q_log(f"Telegram sources added: {len(rows)} {category} source(s); engine will monitor them after START", "ok")
                status.configure(text=f"Added {len(rows)} source(s) as {category}. They are saved to the engine; press START to monitor them.",
                                 fg=GREEN)
                tree.selection_remove(tree.selection())
            except Exception as exc:
                status.configure(text=f"Could not add selected chats: {exc}", fg=RED)
                q_log(f"Telegram channel add failed: {exc}", "err")
            finally:
                E.release_singleton()

        tree.bind("<<TreeviewSelect>>", set_add_state)
        search_var.trace_add("write", draw_matches)

        def scan_worker():
            try:
                lock = E.acquire_singleton()
                if lock is None:
                    raise RuntimeError("Another EdgeQuant window/bot is using Telegram. "
                                       "Close/stop it, then scan again.")
                try:
                    rows = _run_tg_login_coro(E.telegram_scan_dialogs(), timeout=300.0)
                finally:
                    E.release_singleton()
                if not isinstance(rows, list):
                    raise RuntimeError("Telegram returned an unexpected chat list")
                clean = []
                for item in rows:
                    if not isinstance(item, dict):
                        continue
                    name = fix_text(str(item.get("name") or "")).strip()
                    if not name:
                        continue
                    try:
                        chat_id = int(item.get("id"))
                    except Exception:
                        continue
                    kind = str(item.get("kind") or "OTHER").upper()
                    clean.append({"id": chat_id, "name": name, "kind": kind,
                                  "can_add": bool(item.get("can_add")) and
                                             kind in ("GROUP", "CHANNEL")})
                clean.sort(key=lambda x: (x["name"].casefold(), x["id"]))
                result = (clean, "")
            except Exception as exc:
                result = ([], f"{type(exc).__name__}: {exc}")
            def finish():
                try:
                    if not win.winfo_exists():
                        return
                except Exception:
                    return
                rows, error = result
                if error:
                    status.configure(text=error, fg=RED)
                    q_log("Telegram scan failed: " + error, "err")
                    return
                data["items"] = rows
                # Reuse the safe metadata scan to populate Studio's destination
                # picker as well; no second Telegram client/session is opened.
                try:
                    self._studio_merge_chats(rows, include_owned=True)
                except Exception as exc:
                    q_log(f"Studio destination sync after scan: {exc}", "warn")
                search_entry.configure(state="normal")
                draw_matches()
                search_entry.focus_set()
                q_log(f"Telegram scan complete: {len(rows)} chats listed "
                      "(chat metadata only; no message history or signal text read)", "ok")
            try:
                self.root.after(0, finish)
            except Exception:
                pass

        threading.Thread(target=scan_worker, name="edgequant-telegram-chat-scan",
                         daemon=True).start()

    def remove_channel_dialog(self):
        """Remove an EdgeQuant routing entry only; never leave/delete a Telegram chat."""
        if self.bot and self.bot.is_alive():
            messagebox.showinfo("EdgeQuant", "Stop the bot before editing channel sources.")
            return
        try:
            if self._tg_login_window is not None and self._tg_login_window.winfo_exists():
                messagebox.showinfo("EdgeQuant", "Close the Telegram LOGIN dialog before editing sources.")
                return
        except Exception:
            pass
        try:
            login_client = getattr(E, "_login_client", None)
            if login_client is not None and login_client.is_connected():
                messagebox.showinfo("EdgeQuant", "Finish or close Telegram LOGIN before editing sources.")
                return
        except Exception:
            pass
        rows = channel_remove_rows(
            getattr(E, "LIMIT_CHANNELS", []), getattr(E, "MARKET_CHANNELS", []),
            getattr(E, "CHANNEL_IDS", {}), getattr(E, "CHANNEL_ID_NAMES", {}))
        if not rows:
            messagebox.showinfo("EdgeQuant", "There are no configured channel sources to remove.")
            return
        win = tk.Toplevel(self.root)
        win.title("Remove a source from EdgeQuant")
        win.configure(bg=PANEL)
        dialog_w, _dialog_h = self._place_dialog(win, 700, 430, 540, 360)
        win.transient(self.root)
        tk.Label(win, text="REMOVE FROM EDGEQUANT", bg=PANEL, fg=GOLD,
                 font=widget_font("Segoe UI", 12, True)).pack(anchor="w", padx=14, pady=(12, 3))
        tk.Label(win, text=("Select a name/category or an ID mapping. This removes routing "
                            "from EdgeQuant only; it does not leave or delete the Telegram chat."),
                 bg=PANEL, fg=MUTED, justify="left", wraplength=max(360, dialog_w - 40),
                 font=widget_font("Segoe UI", 9)).pack(anchor="w", padx=14, pady=(0, 10))
        area = ttk.Frame(win, style="Panel.TFrame")
        area.pack(fill="both", expand=True, padx=14, pady=(0, 8))
        tree = ttk.Treeview(area, columns=("name", "category", "id", "action"),
                            show="headings", selectmode="browse")
        for key, label, width in (("name", "CHANNEL / MAPPING", 300),
                                  ("category", "TYPE", 80), ("id", "TELEGRAM ID", 140),
                                  ("action", "REMOVAL", 120)):
            tree.heading(key, text=label)
            tree.column(key, width=width, minwidth=70,
                        anchor="w" if key == "name" else "center")
        vsb = ttk.Scrollbar(area, orient="vertical", command=tree.yview)
        hsb = ttk.Scrollbar(area, orient="horizontal", command=tree.xview)
        tree.configure(yscrollcommand=vsb.set, xscrollcommand=hsb.set)
        tree.grid(row=0, column=0, sticky="nsew")
        vsb.grid(row=0, column=1, sticky="ns")
        hsb.grid(row=1, column=0, sticky="ew")
        area.rowconfigure(0, weight=1)
        area.columnconfigure(0, weight=1)
        by_iid = {}
        for i, row in enumerate(rows):
            iid = f"source_{i}"
            ids_text = str(row.get("id") or "-")
            if row.get("extra_ids"):
                ids_text += f"  (+{len(row['extra_ids'])} more)"
            if row["kind"] == "name":
                label = row["name"]
                action = "Name + linked ID" if row.get("id") else "Name only"
                selection = {"kind": "name", "name": row["name"],
                             "category": row["category"]}
            else:
                label = row.get("name") or "Unlinked Telegram ID"
                action = "ID only"
                selection = {"kind": "id", "id": row["id"],
                             "category": row["category"]}
            by_iid[iid] = selection
            tree.insert("", "end", iid=iid,
                        values=(label, row["category"], ids_text, action))
        status = tk.Label(win, text="Choose one row to remove.", bg=PANEL, fg=MUTED,
                          anchor="w", font=widget_font("Consolas", 9))
        status.pack(fill="x", padx=14, pady=(0, 7))
        buttons = ttk.Frame(win, style="Panel.TFrame")
        buttons.pack(fill="x", padx=14, pady=(0, 12))

        def do_remove():
            chosen = tree.selection()
            selection = by_iid.get(chosen[0]) if chosen else None
            if not selection:
                status.configure(text="Select a row first.", fg=AMBER)
                return
            if selection["kind"] == "name":
                question = (f"Remove '{selection['name']}' ({selection['category']}) from "
                            "EdgeQuant's source list?\n\nThis will also remove ID mappings "
                            "recorded for this exact name. It will NOT leave/delete anything "
                            "in Telegram.")
            else:
                question = (f"Remove Telegram ID {selection['id']} ({selection['category']}) "
                            "from EdgeQuant?\n\nThe Telegram chat and any channel name "
                            "entry will remain unchanged.")
            if not messagebox.askyesno("Confirm remove", question, parent=win):
                return
            lock = E.acquire_singleton()
            if lock is None:
                status.configure(text="Another EdgeQuant window is using the settings/session. "
                                  "Close it and retry.", fg=RED)
                return
            try:
                updates = channel_remove_settings(
                    selection, getattr(E, "LIMIT_CHANNELS", []),
                    getattr(E, "MARKET_CHANNELS", []), getattr(E, "CHANNEL_IDS", {}),
                    getattr(E, "CHANNEL_ID_NAMES", {}))
                save_settings_file(APP_DIR / "edgequant_auto.py", updates)
                reload_engine()
                if selection["kind"] == "name":
                    E.set_channel_on(selection["name"], True,
                                     selection.get("category", ""), quiet=True)
                for field, value in (("LIMIT_CHANNELS", getattr(E, "LIMIT_CHANNELS", [])),
                                     ("MARKET_CHANNELS", getattr(E, "MARKET_CHANNELS", []))):
                    box = getattr(self, "set_entries", {}).get(field)
                    if isinstance(box, tk.Text):
                        vals = [value] if isinstance(value, str) else list(value or [])
                        box.delete("1.0", "end")
                        box.insert("1.0", "\n".join(str(x) for x in vals))
                box = getattr(self, "set_entries", {}).get("CHANNEL_IDS")
                if isinstance(box, tk.Text):
                    lines = [f"{key}: {value}" for key, value in
                             (getattr(E, "CHANNEL_IDS", {}) or {}).items()]
                    box.delete("1.0", "end")
                    box.insert("1.0", "\n".join(lines))
                self.refresh_channels()
                q_log("EdgeQuant source removed: " + str(selection.get("name") or selection.get("id")), "ok")
                status.configure(text="Removed from EdgeQuant. Telegram membership was not changed.",
                                  fg=GREEN)
                win.after(700, lambda: win.winfo_exists() and win.destroy())
            except Exception as exc:
                status.configure(text=f"Could not remove source: {type(exc).__name__}: {exc}", fg=RED)
                q_log(f"channel remove failed: {exc}", "err")
            finally:
                E.release_singleton()

        ttk.Button(buttons, text="REMOVE SELECTED", style="Stop.TButton",
                   command=do_remove).pack(side="left")
        ttk.Button(buttons, text="CLOSE", command=win.destroy).pack(side="right")

    def refresh_channels(self):
        t = self.ch_text
        t.configure(state="normal")
        t.delete("1.0", "end")

        def w(line, tag=None):
            t.insert("end", line + "\n", tag or "")

        w(f"LIMIT CHANNELS  ({len(E.LIMIT_CHANNELS)})", "h")
        for c in E.LIMIT_CHANNELS:
            w(f"    {c}", "g")
        w("")
        w(f"MARKET CHANNELS  ({len(E.MARKET_CHANNELS)})", "h")
        for c in E.MARKET_CHANNELS:
            w(f"    {c}", "g")
        w("")
        ids = getattr(E, "CHANNEL_IDS", {}) or {}
        w(f"BY ID  ({len(ids)})   - used when a title has a typo or changed", "h")
        for cid, cat in ids.items():
            w(f"    {cid:<18}{cat}")
        w("")
        ig = getattr(E, "IGNORE_CHAT_IDS", set()) or set()
        w(f"IGNORED CHAT IDS  ({len(ig)})", "h")
        for cid in (ig if isinstance(ig, (set, list)) else [ig]):
            w(f"    {cid}", "m")
        w("")
        w("Every other chat on your Telegram account is ignored.", "m")
        w("", "m")
        w("TIP: If two Telegram chats share a name, use their IDs to distinguish them; "
          "put an unwanted ID in IGNORE_CHAT_IDS.", "m")
        t.configure(state="disabled")
        self._draw_switches()

    def _draw_switches(self):
        """One row per channel: name, type, today, net, ON/OFF + the button."""
        holder = getattr(self, "ch_sw_holder", None)
        if holder is None:
            return
        for w in holder.winfo_children():
            w.destroy()
        try:
            rows = E.channel_rows()
        except Exception as exc:
            ttk.Label(holder, text=f"channels could not be read: {exc}",
                      style="Muted.TLabel").pack(anchor="w")
            return
        if not rows:
            ttk.Label(holder,
                      text="No Telegram sources are configured. Add your own in CHANNELS → ADD SOURCE.",
                      style="Muted.TLabel").pack(anchor="w", pady=(3, 5))
            return
        head = ttk.Frame(holder, style="Panel.TFrame")
        head.pack(fill="x")
        for txt, w, anchor in (("CHANNEL", 30, "w"), ("TYPE", 9, "w"), ("TODAY", 7, "e"),
                               ("LIVE", 6, "e"), ("NET USD", 12, "e"), ("STATE", 7, "w")):
            tk.Label(head, text=txt, bg=PANEL, fg=MUTED, width=w, anchor=anchor,
                     font=widget_font("Segoe UI", 8, True)).pack(side="left")
        for r in rows:
            row = ttk.Frame(holder, style="Panel.TFrame")
            row.pack(fill="x", pady=1)
            tk.Label(row, text=str(r["name"])[:30], bg=PANEL, fg=FG, width=30, anchor="w",
                     font=widget_font("Segoe UI", 9)).pack(side="left")
            tk.Label(row, text=str(r["cat"])[:9], bg=PANEL, fg=MUTED, width=9, anchor="w",
                     font=widget_font("Segoe UI", 8)).pack(side="left")
            tk.Label(row, text=str(r["today"]), bg=PANEL, fg=MUTED, width=7, anchor="e",
                     font=widget_font("Consolas", 8)).pack(side="left")
            tk.Label(row, text=str(r["live"]), bg=PANEL, fg=MUTED, width=6, anchor="e",
                     font=widget_font("Consolas", 8)).pack(side="left")
            net = float(r["net"] or 0.0)
            tk.Label(row, text=(fmt_pl(net) if net else "-"), bg=PANEL,
                     fg=pl_colour(net) if net else MUTED, width=12, anchor="e",
                     font=widget_font("Consolas", 8)).pack(side="left")
            tk.Label(row, text=("ON" if r["on"] else "OFF"), bg=PANEL,
                     fg=GREEN if r["on"] else RED, width=7, anchor="w",
                     font=widget_font("Segoe UI", 9, True)).pack(side="left")
            tk.Button(row, text=("TURN OFF" if r["on"] else "TURN ON"),
                      command=lambda nm=r["name"], c=r["cat"], on=r["on"]:
                          self.toggle_channel(nm, c, not on),
                      bg=(RED if r["on"] else GREEN), fg="#04120a", bd=0,
                      activebackground=(RED if r["on"] else GREEN), activeforeground="#04120a",
                      font=widget_font("Segoe UI", 8, True), padx=10, pady=0,
                      cursor="hand2").pack(side="left", padx=8)

    def toggle_channel(self, name, cat, on: bool):
        """Flip one channel ON/OFF (the engine + Telegram see it immediately)."""
        try:
            E.set_channel_on(name, on, cat)
        except Exception as exc:
            q_log(f"the channel switch failed: {exc}", "err")
            return
        q_log(f"channel '{name}' -> {'ON (its signals are traded again)' if on else 'OFF (every signal from it is now ignored)'}",
              "ok" if on else "warn")
        self.refresh_channels()

    def all_channels(self, on: bool):
        if not messagebox.askyesno(
                "EdgeQuant",
                (f"Switch EVERY channel {'ON' if on else 'OFF'} ?\n\n"
                 + ("" if on else "No new orders will be placed from any channel "
                                  "(open trades are still managed)."))):
            return
        n = 0
        try:
            for r in E.channel_rows():
                if E.set_channel_on(r["name"], on, r["cat"], quiet=True):
                    n += 1
        except Exception as exc:
            q_log(f"could not switch them all: {exc}", "err")
            return
        q_log(f"every channel ({n}) switched {'ON' if on else 'OFF'}", "ok" if on else "warn")
        self.refresh_channels()

    # ------------------------------------------------------------ CALENDAR --
    CAL_COLS = ("MON", "TUE", "WED", "THU", "FRI", "SAT", "SUN", "WEEK")

    def _sect(self, parent, title, note="", gold=True):
        """Institutional section heading: gold rule + uppercase title."""
        box = tk.Frame(parent, bg=PANEL)
        box.pack(fill="x", pady=(10, 4))
        tk.Frame(box, bg=GOLD if gold else LINE, width=3, height=14).pack(side="left",
                                                                         padx=(0, 8))
        tk.Label(box, text=title.upper(), bg=PANEL, fg=FG,
                 font=widget_font("Segoe UI", 9, True)).pack(side="left")
        if note:
            tk.Label(box, text=note, bg=PANEL, fg=MUTED,
                     font=widget_font("Segoe UI", 7)).pack(side="right")
        return box

    def _build_calendar(self, parent):
        self.cal_shown = None
        self.cal_dayinfo = {}
        self.cal_card = None            # the small hover window (v1.7.0)
