    def _broker_manager(self):
        """Read existing saved accounts and preserve the ON/OFF safety switch."""
        holder = getattr(self, "bman_holder", None)
        if holder is None:
            return
        for w in holder.winfo_children():
            w.destroy()
        try:
            accts = E.accounts()
        except Exception as exc:
            tk.Label(holder, text=f"accounts: {exc}", bg=PANEL, fg=RED,
                     font=widget_font("Consolas", 8)).pack(anchor="w")
            return
        head = tk.Frame(holder, bg=PANEL2)
        head.pack(fill="x")
        for text, width, anchor in (("ACCOUNT", 18, "w"), ("LOGIN", 12, "w"),
                                    ("SERVER", 20, "w"), ("FROM", 8, "w"),
                                    ("STATE", 10, "w")):
            tk.Label(head, text=text, bg=PANEL2, fg=GOLD, width=width, anchor=anchor,
                     font=widget_font("Segoe UI", 7, True)).pack(side="left", padx=4, pady=3)
        for a in accts:
            nm = a.get("name") or "?"
            on = True
            try:
                on = bool(E.broker_is_on(nm))
            except Exception:
                pass
            row = tk.Frame(holder, bg=PANEL2 if on else PANEL)
            row.pack(fill="x", pady=1)
            tk.Label(row, text=nm, bg=row["bg"], fg=GOLD if on else MUTED, width=18,
                     anchor="w", font=widget_font("Consolas", 9, True)
                     ).pack(side="left", padx=4, pady=3)
            tk.Label(row, text=str(a.get("login") or "-"), bg=row["bg"], fg=FG, width=12,
                     anchor="w", font=widget_font("Consolas", 8)).pack(side="left", padx=4)
            tk.Label(row, text=str(a.get("server") or "-")[:20], bg=row["bg"], fg=FG,
                     width=20, anchor="w", font=widget_font("Consolas", 8)
                     ).pack(side="left", padx=4)
            try:
                src = "app" if E.broker_source(nm) == "app" else "engine"
            except Exception:
                src = "engine"
            tk.Label(row, text=src, bg=row["bg"], fg=MUTED, width=8, anchor="w",
                     font=widget_font("Consolas", 8)).pack(side="left", padx=4)
            tk.Label(row, text=("ON" if on else "OFF"), bg=row["bg"],
                     fg=GREEN if on else RED, width=10, anchor="w",
                     font=widget_font("Segoe UI", 8, True)).pack(side="left", padx=4)
            ttk.Button(row, text=L("TURN OFF", "OFF කරන්න") if on else
                       L("TURN ON", "ON කරන්න"),
                       command=lambda n=nm: self.broker_toggle(n)).pack(side="left", padx=6,
                                                                        pady=2)
        try:
            txt = E.brokers_text().splitlines()
            tail = [l for l in txt if l.strip().startswith("ON ") or "change it here" in l]
        except Exception:
            tail = []
        if tail:
            tk.Label(holder, text="\n".join(tail), bg=PANEL, fg=MUTED, anchor="w",
                     justify="left", font=widget_font("Consolas", 8)).pack(anchor="w",
                                                                          pady=(2, 0))

    def broker_symbol_account_changed(self, event=None):
        """Load this MT5 account's exact broker-specific XAUUSD mapping."""
        try:
            name = str(self.broker_symbol_account_var.get() or "").strip().upper()
            selected = E.broker_symbol_map_get(name, "XAUUSD") or "AUTO"
            self.broker_gold_symbol_var.set(selected)
            self.broker_symbol_status.configure(
                text=L(f"{name}: XAUUSD -> {selected} (applies to every source routed here).",
                       f"{name}: XAUUSD -> {selected} (මෙම account එකට route වන හැම source එකටම)."),
                fg=CYAN if selected != "AUTO" else MUTED)
        except Exception as exc:
            q_log(f"symbol mapping selection: {exc}", "warn")

    def broker_symbol_save(self):
        """Save the exact broker symbol for one account; no order/terminal switch occurs."""
        name = str(self.broker_symbol_account_var.get() or "").strip().upper()
        selected = str(self.broker_gold_symbol_var.get() or "AUTO").strip()
        if not name:
            self.broker_symbol_status.configure(text="Choose an MT5 account first.", fg=RED)
            return
        try:
            ok = E.broker_symbol_map_set(name, "XAUUSD", selected or "AUTO")
        except Exception as exc:
            ok = False
            q_log(f"save broker symbol: {exc}", "err")
        if not ok:
            self.broker_symbol_status.configure(
                text=L("Could not save that symbol. Use the exact MT5 symbol name (no path).",
                       "Symbol එක save කරන්න බැරි වුණා. MT5 හි exact symbol නම යොදන්න."), fg=RED)
            return
        shown = "AUTO" if not selected or selected.upper() == "AUTO" else selected
        self.broker_symbol_status.configure(
            text=L(f"Saved for {name}: XAUUSD -> {shown}. Applies to every signal group routed to this account. The engine checks the exact symbol before trading.",
                   f"{name} සඳහා save කළා: XAUUSD -> {shown}. මේ account එකට route වන හැම signal group එකටම apply වෙනවා; trade කිරීමට පෙර exact MT5 symbol එක check කරනවා."),
            fg=GREEN)
        q_log(f"BROKER SYMBOL MAP: {name} XAUUSD -> {shown}", "ok")

    def broker_toggle(self, name):
        try:
            on = not E.broker_is_on(name)
            E.set_broker_on(name, on)
            self.bman_log.configure(
                text=f"{name} is now {'ON - it gets every signal' if on else
                                     'OFF - it gets nothing (open trades are still '
                                     'managed)'}".replace("\n", " "),
                fg=GREEN if on else AMBER)
            q_log(f"MT5 ACCOUNT {name}: {'ON' if on else 'OFF'}", "warn" if not on else "ok")
        except Exception as exc:
            q_log(f"switch {name}: {exc}", "err")
        self.refresh_brokers()

    def refresh_brokers(self):
        try:
            if not (self.bot and self.bot.is_alive()):
                quiet(E.jr_load)
            self._broker_manager()
            if hasattr(self, "broker_symbol_account_combo"):
                symbol_accounts = list(E.broker_names() or ["MAIN"])
                current_symbol_account = str(self.broker_symbol_account_var.get() or "").strip().upper()
                self.broker_symbol_account_combo.configure(values=symbol_accounts)
                if current_symbol_account not in symbol_accounts:
                    self.broker_symbol_account_var.set(symbol_accounts[0])
                    self.broker_symbol_account_changed()
            m = self.mt5_info or {}
            brokers = m.get("brokers") or []
            for w in self.bro_holder.winfo_children():
                w.destroy()
            if not brokers:
                tk.Label(self.bro_holder, text="  MT5 not connected yet - press CHECK ALL "
                                               "ACCOUNTS NOW", bg=PANEL, fg=MUTED,
                         font=widget_font("Consolas", 9)).pack(anchor="w", pady=6)
            for b in brokers:
                row = tk.Frame(self.bro_holder, bg=PANEL)
                row.pack(fill="x", pady=1)
                live = "yes" if b.get("live") else "no"
                cells = ((b.get("name", "?")[:16], 16, "w", GOLD),
                         (str(b.get("login", "-"))[:14], 14, "w", FG),
                         (str(b.get("server", "-"))[:18], 18, "w", MUTED),
                         (b.get("status", "-")[:10], 10, "w",
                          GREEN if b.get("status") == "connected" else RED),
                         (money(b.get("balance", "-"), b.get("currency", "")), 14, "e", FG),
                         (money(b.get("equity", "-"), b.get("currency", "")), 14, "e", FG),
                         (str(b.get("positions", 0)), 6, "e", CYAN),
                         (str(b.get("pendings", 0)), 8, "e", PURPLE),
                         (str(b.get("symbols", ""))[:22], 22, "w", MUTED))
                for text, width, anchor, col in cells:
                    tk.Label(row, text=text, bg=PANEL, fg=col, width=width, anchor=anchor,
                             font=widget_font("Consolas", 8)).pack(side="left", padx=2)
                if b.get("read_error"):
                    tk.Label(self.bro_holder, text=f"  ↳ {b['read_error']}", bg=PANEL,
                             fg=RED, anchor="w", justify="left", wraplength=980,
                             font=widget_font("Consolas", 8)).pack(fill="x", padx=(20, 4),
                                                                    pady=(0, 3))
            # routing map
            self.bro_log.configure(
                text=f"DEFAULT_BROKER = {getattr(E, 'DEFAULT_BROKER', '') or '(first)'}"
                     f"     SEND_TO_ALL_BROKERS = "
                     f"{getattr(E, 'SEND_TO_ALL_BROKERS', False)}"
                     f"     BROKER_FALLBACK = {getattr(E, 'BROKER_FALLBACK', True)}")
            self.notify_note.configure(
                text=f"NOTIFY_CHAT = {E.NOTIFY_CHAT!r}      group: "
                     f"{getattr(E, 'NOTIFY_GROUP_NAME', 'EdgeQuant Alerts')}\n"
                     f"NOTIFY ON: ENTRY TRIGGER / TP / SL / BE   |   bot start message: "
                     f"{getattr(E, 'NOTIFY_ON_START', True)}   |   day summary: "
                     f"{getattr(E, 'DAILY_SUMMARY', True)} at "
                     f"{getattr(E, 'DAILY_SUMMARY_AT', '23:55')}\n"
                     "'me' = your Saved Messages.  Press the button below to create the "
                     "group and save its id automatically.")
        except Exception as exc:
            q_log(f"brokers page: {exc}", "err")

    def run_engine_cli(self, args, title, need_idle=True):
        """Run edgequant_auto.py with extra flags and stream the output to ACTIVITY."""
        if need_idle and self.bot and self.bot.is_alive():
            messagebox.showinfo("EdgeQuant",
                                "Stop the engine first - the Telegram / MT5 login can only "
                                "be used once at a time.")
            return
        self.nb.select(self.tab_log)
        q_log(f"--- {title} ...", "note")

        def worker():
            try:
                if getattr(sys, "frozen", False):
                    command = [sys.executable, "--engine-cli"] + list(args)
                else:
                    command = [sys.executable, "edgequant_auto.py"] + list(args)
                p = subprocess.Popen(command, cwd=str(APP_DIR), stdout=subprocess.PIPE,
                                     stderr=subprocess.STDOUT, text=True)
                for line in p.stdout:
                    line = line.rstrip()
                    if ("unsupported format character" in line or
                            "badly formed help string" in line):
                        q_raw(line, "err")
                        q_log("^^ that means edgequant_auto.py in this folder is the OLD "
                              "file.  Extract the zip to F:\\ again and choose "
                              "'Replace the files in the destination'.", "err")
                        continue
                    q_raw(line, "err" if ("ERROR" in line or "not reachable" in line or
                                          "could not" in line) else
                          ("ok" if ("OK" in line or "created" in line) else "info"))
                p.wait()
                q_log(f"--- {title} : done", "info")
            except Exception as exc:
                q_log(f"{title} failed: {exc}", "err")

        threading.Thread(target=worker, daemon=True).start()

    # ===================================================================== #
    #  v1.7.0   ADVANCED   -   deposits / withdrawals (money in, money out)
    # ===================================================================== #
    # ===================================================================== #
    #  v1.8.0   AI TRADING PLAN  -  risk + money management + compounding
    # ===================================================================== #
    def _build_plan(self, parent):
        head = tk.Frame(parent, bg=PANEL)
        head.pack(fill="x")
        tk.Label(head, text=L("AI TRADING PLAN   -   capital first, then the risk",
                              "AI ට්‍රේඩින් ප්ලෑන්   -   මුලින්ම මුල් මුදල, ඊට පස්සේ රිස්ක් එක"),
                 bg=PANEL, fg=GOLD, font=widget_font("Segoe UI", 12, True)).pack(side="left")
        self.plan_note = tk.Label(head, text="", bg=PANEL, fg=CYAN,
                                  font=widget_font("Consolas", 9))
        self.plan_note.pack(side="right")

        row = tk.Frame(parent, bg=PANEL, highlightbackground=LINE, highlightthickness=1)
        row.pack(fill="x", pady=(8, 6))
        self.plan_vars = {}
        # v1.9.4: the boxes show the SAVED plan (they used to show the defaults,
        # so opening the app quietly re-saved 500 / 20 days over your own plan)
        try:
            _saved_plan = dict(E.plan_settings() or {})
        except Exception:
            _saved_plan = {}
        fields = (("capital", L("CAPITAL (USD)", "මුල් මුදල (USD)"), "500"),
                  ("days", L("TRADING DAYS", "ට්‍රේඩ් දවස්"), "20"),
                  ("months", L("MONTHS", "මාස"), "6"),
                  ("risk", L("RISK % / TRADE", "රිස්ක් % / ට්‍රේඩ්"), "1"),
                  ("target", L("TARGET % / MONTH", "ඉලක්කය % / මාසය"), "8"),
                  ("win", L("WIN RATE %", "දිනන % එක"), "55"),
                  ("rr", L("REWARD : RISK", "ලාභ : පාඩු"), "1.6"),
                  ("trades_day", L("SIGNALS / DAY", "දිනකට සිග්නල්"), "2"))
        for i, (key, label, default) in enumerate(fields):
            cell = tk.Frame(row, bg=PANEL)
            cell.grid(row=0, column=i, padx=10, pady=8, sticky="w")
            tk.Label(cell, text=label, bg=PANEL, fg=MUTED,
                     font=widget_font("Segoe UI", 8, True)).pack(anchor="w")
            _val = _saved_plan.get(key, getattr(E, "PLAN_DEFAULTS", {}).get(key, default))
            var = tk.StringVar(value=str(_val))
            tk.Entry(cell, textvariable=var, width=9, bg=PANEL2, fg=FG, relief="flat",
                     insertbackground=FG, justify="right",
                     font=widget_font("Consolas", 11, True)).pack(anchor="w", pady=(2, 0))
            self.plan_vars[key] = var
        btns = tk.Frame(row, bg=PANEL)
        btns.grid(row=0, column=len(fields), padx=12, pady=8)
        ttk.Button(btns, text=L("GENERATE THE PLAN", "ප්ලෑන් එක හදන්න"),
                   style="Go.TButton", command=self.plan_generate).pack(fill="x")
        ttk.Button(btns, text=L("USE MY LIVE BALANCE", "මගේ බැලන්ස් එක ගන්න"),
                   command=self.plan_live_balance).pack(fill="x", pady=(4, 0))
        ttk.Button(btns, text=L("APPLY RISK + DAILY STOP", "රිස්ක් + ඩේලි ස්ටොප් දාන්න"),
                   command=self.plan_apply).pack(fill="x", pady=(4, 0))
        # ---- v1.9.0: add money to the capital + the daily target -----------
        extra = tk.Frame(row, bg=PANEL)
        extra.grid(row=1, column=0, columnspan=len(fields) + 1, sticky="w",
                   padx=10, pady=(0, 8))
        tk.Label(extra, text=L("ADD TO CAPITAL", "මුල් මුදලට එකතු කරන්න"), bg=PANEL,
                 fg=MUTED, font=widget_font("Segoe UI", 8, True)).pack(side="left")
        self.plan_add = tk.StringVar(value="")
        tk.Entry(extra, textvariable=self.plan_add, width=10, bg=PANEL2, fg=FG,
                 relief="flat", insertbackground=FG, justify="right",
                 font=widget_font("Consolas", 10, True)).pack(side="left", padx=4)
        ttk.Button(extra, text=L("ADD", "එකතු කරන්න"), width=8,
                   command=self.plan_capital_add).pack(side="left", padx=(0, 10))
        ttk.Button(extra, text=L("ADD TODAY'S PROFIT", "අද ලාභය එකතු කරන්න"),
                   command=self.plan_add_profit).pack(side="left", padx=(0, 14))
        tk.Label(extra, text=L("DAILY TARGET", "දිනපතා ඉලක්කය"), bg=PANEL, fg=MUTED,
                 font=widget_font("Segoe UI", 8, True)).pack(side="left")
        ttk.Button(extra, text=L("USE THE PLAN", "ප්ලෑන් එක ගන්න"),
                   command=self.plan_use_target).pack(side="left", padx=4)
        ttk.Button(extra, text=L("NEXT DAY PLAN", "හෙට ප්ලෑන් එක"),
                   command=self.plan_next_day).pack(side="left", padx=(14, 0))
        # ---- v1.9.1: the user chooses HOW the plan is built ---------------
        prow = tk.Frame(row, bg=PANEL, highlightbackground=GOLD, highlightthickness=1)
        prow.grid(row=2, column=0, columnspan=len(fields) + 1, sticky="w",
                  padx=10, pady=(0, 10))
        tk.Label(prow, text=L("  PLAN BY", "  ප්ලෑන් එක හදන්නේ"), bg=PANEL, fg=GOLD,
                 font=widget_font("Segoe UI", 9, True)).pack(side="left", pady=4)
        self.plan_by = tk.StringVar(
            value=str(_saved_plan.get("per")
                      or getattr(E, "PLAN_DEFAULTS", {}).get("per", "DAYS")).upper())
        if self.plan_by.get() not in ("DAYS", "MONTHS"):
            self.plan_by.set("DAYS")
        cbx = ttk.Combobox(prow, textvariable=self.plan_by, width=8, state="readonly",
                           values=["DAYS", "MONTHS"], font=widget_font("Consolas", 10, True))
        cbx.pack(side="left", padx=(4, 10), pady=4)
        cbx.bind("<<ComboboxSelected>>", lambda e: self.plan_by_change())
        self.plan_scope = tk.Label(prow, text="", bg=PANEL, fg=CYAN,
                                   font=widget_font("Consolas", 9))
        self.plan_scope.pack(side="left", pady=4, padx=(0, 10))

        target_banner = tk.Frame(parent, bg=DEEP, highlightbackground=GOLD, highlightthickness=1)
        target_banner.pack(fill="x", pady=(0, 7))
        tk.Frame(target_banner, bg=GOLD, height=3).pack(fill="x")
        self.plan_target_banner = tk.Label(target_banner, text="DAILY TARGET · checking…",
                                           bg=DEEP, fg=GOLD, anchor="w",
                                           font=widget_font("Segoe UI", 15, True))
        self.plan_target_banner.pack(fill="x", padx=12, pady=(7, 1))
        self.plan_target_detail = tk.Label(target_banner, text="", bg=DEEP, fg=MUTED,
                                           anchor="w", wraplength=1000, justify="left",
                                           font=widget_font("Segoe UI", 8))
        self.plan_target_detail.pack(fill="x", padx=12, pady=(0, 5))
        self.plan_target_bar = tk.Canvas(target_banner, height=12, bg=DEEP, highlightthickness=0)
        self.plan_target_bar.pack(fill="x", padx=12, pady=(0, 8))
        plan_exports = tk.Frame(parent, bg=PANEL)
        plan_exports.pack(fill="x", pady=(0, 6))
        ttk.Button(plan_exports, text="EXPORT EDITABLE PLAN · EXCEL",
                   style="Go.TButton",
                   command=lambda: self._studio_export_report("plan_xlsx")).pack(side="left", padx=(0, 6))
        ttk.Button(plan_exports, text="EXPORT PLAN · PDF",
                   command=lambda: self._studio_export_report("plan_pdf")).pack(side="left")

        body = tk.Frame(parent, bg=PANEL)
        body.pack(fill="both", expand=True)
        body.columnconfigure(0, weight=3)
        body.columnconfigure(1, weight=2)
        body.rowconfigure(0, weight=1)
        wrap = tk.Frame(body, bg=DEEP, highlightbackground=LINE, highlightthickness=1)
        wrap.grid(row=0, column=0, sticky="nsew", padx=(0, 6))
        self.plan_canvas = tk.Canvas(wrap, bg=DEEP, highlightthickness=0, height=210)
        self.plan_canvas.pack(fill="both", expand=True, padx=6, pady=6)
        self.plan_canvas.bind("<Configure>", lambda e: self.plan_draw())
        right = tk.Frame(body, bg=DEEP, highlightbackground=LINE, highlightthickness=1)
        right.grid(row=0, column=1, sticky="nsew", padx=(6, 0))
        self.plan_txt = tk.Text(right, bg=DEEP, fg=FG, bd=0, height=18, wrap="word",
                                insertbackground=FG, font=widget_font("Consolas", 9),
                                padx=10, pady=8)
        self.plan_txt.pack(fill="both", expand=True)
        self.plan_data = {}
        self.plan_phase = 0.0
        self.plan_refresh_daily_target_status(force=True)
        self.root.after(700, self.plan_generate)

    def plan_refresh_daily_target_status(self, force=False):
        if not hasattr(self, "plan_target_banner"):
            return
        now = time.time()
        if not force and now - float(getattr(self, "_plan_target_last_refresh", 0.0) or 0.0) < 3.0:
            return
        self._plan_target_last_refresh = now
        try:
            state = E.daily_target_state() or {}
            target = float(state.get("target") or 0.0)
            actual = float(state.get("net") or 0.0)
            progress = float(state.get("progress_net") or actual)
            pct = float(state.get("done_pct") or 0.0)
            achieved = bool(state.get("achieved"))
            if target <= 0:
                headline, color = "DAILY TARGET NOT SET", MUTED
                detail = "Set a daily target to see today's progress and achievement status."
            elif achieved:
                headline, color = f"DAILY TARGET ACHIEVED  ·  {pct:.1f}%", GREEN
                detail = (f"Realized {actual:+,.2f} USD of {target:,.2f} USD. "
                          "Achievement is confirmed using realized P&L.")
            else:
                headline, color = f"DAILY TARGET IN PROGRESS  ·  {pct:.1f}%", GOLD if progress >= 0 else RED
                detail = (f"Progress {progress:+,.2f} USD (realized {actual:+,.2f}) / {target:,.2f} USD · "
                          f"{float(state.get('remaining') or 0):,.2f} USD remaining. "
                          "Floating P&L can change before close.")
            self.plan_target_banner.configure(text=headline, fg=color)
            self.plan_target_detail.configure(text=detail)
            canvas = self.plan_target_bar
            canvas.delete("all")
            width = max(100, canvas.winfo_width())
            canvas.create_rectangle(0, 0, width, 12, fill=PANEL2, outline="")
            canvas.create_rectangle(0, 0, width * min(100.0, max(0.0, pct)) / 100.0, 12,
                                    fill=color if target > 0 else MUTED, outline="")
            canvas.create_text(width - 5, 6, anchor="e", text=f"{pct:.1f}%",
                               fill=FG, font=widget_font("Consolas", 8, True))
        except Exception as exc:
            self.plan_target_banner.configure(text=f"DAILY TARGET STATUS UNAVAILABLE · {exc}", fg=AMBER)

    def plan_values(self) -> dict:
        out = {}
        for k, v in self.plan_vars.items():
            try:
                out[k] = float(str(v.get()).replace(",", "."))
            except Exception:
                out[k] = None
        try:
            out["per"] = str(self.plan_by.get()).upper()[:6]
        except Exception:
            out["per"] = "DAYS"
        return out

    def plan_by_change(self):
        """DAYS <-> MONTHS: rebuild the plan straight away (and animate it)."""
        self.plan_generate()

    def plan_live_balance(self):
        try:
            acc = E.mt5.account_info() if (E.HAVE_MT5 and E.mt5_ready()) else None
            if acc and float(acc.balance or 0) > 0:
                self.plan_vars["capital"].set(f"{float(acc.balance):.2f}")
                self.plan_note.configure(text=L(f"live balance {acc.balance:.2f} "
                                                f"{acc.currency}",
                                                f"ලයිව් බැලන්ස් {acc.balance:.2f}"))
                self.plan_generate()
                return
        except Exception as exc:
            q_log(f"plan balance: {exc}", "warn")
        self.plan_note.configure(text=L("MT5 is not connected - type the capital",
                                        "MT5 සම්බන්ධ නෑ - මුදල අතින් ලියන්න"))

    def plan_generate(self):
        v = self.plan_values()
        kw = {k: v[k] for k in ("capital", "win", "rr") if v.get(k) is not None}
        if v.get("months"):
            kw["months"] = int(v["months"])
        if v.get("days"):
            kw["days"] = int(v["days"])                    # v1.9.1
        if v.get("per"):
            kw["per"] = v["per"]                           # v1.9.1 DAYS / MONTHS
        if v.get("risk"):
            kw["risk"] = v["risk"]
        if v.get("target"):
            kw["target"] = v["target"]
        if v.get("trades_day"):
            kw["trades_day"] = int(v["trades_day"])
        try:
            pl = E.trading_plan(**kw)
            self.plan_data = pl
            try:
                E.plan_save({"capital": pl["capital"], "months": pl["months"],
                             "risk": pl["risk_pct"], "target": pl["target_pct"],
                             "win": pl["win"], "rr": pl["rr"],
                             "trades_day": pl["trades_day"],
                             # v1.9.1: what the DAILY TARGET reads
                             "days": pl["days"], "per": pl["per"],
                             "per_day": pl["per_day"]})
            except Exception:
                pass
        except Exception as exc:
            q_log(f"plan: {exc}", "err")
            return
        lines = [f"{L('CAPITAL', 'මුල් මුදල'):<22}{pl['capital']:>12,.2f}",
                 f"{L('RISK / TRADE', 'රිස්ක් / ට්‍රේඩ්'):<22}{pl['risk_usd']:>12,.2f}"
                 f"   ({pl['risk_pct']:g}%)",
                 f"{L('STOP THE DAY', 'දවස නවත්වන තැන'):<22}{pl['day_stop']:>12,.2f}",
                 f"{L('STOP THE WEEK', 'සතිය නවත්වන තැන'):<22}{pl['week_stop']:>12,.2f}",
                 f"{L('LOT FOR 50 PIPS', 'ලොට් (පිප්ස් 50)'):<22}{pl['lot']:>12.3f}",
                 "",
                 f"{L('WIN RATE USED', 'ගත්ත win % එක'):<22}{pl['win']:>12.1f}%"
                 + ("  (journal)" if pl["from_journal"] else "  (typed)"),
                 f"{L('REWARD : RISK', 'ලාභ : පාඩු'):<22}{pl['rr']:>12.2f}",
                 f"{L('EXPECTANCY', 'එක්ස්පෙක්ටන්සි'):<22}{pl['expectancy_r']:>+12.3f} R"
                 f"   {pl['expectancy_usd']:+,.2f}",
                 f"{L('PER DAY', 'දිනකට'):<22}{pl['per_day']:>+12,.2f}"
                 f"   ({pl.get('day_pct', 0):+.2f}%)",
                 f"{L('PER MONTH', 'මාසෙට'):<22}{pl['per_month']:>+12,.2f}"
                 f"   ({pl['month_pct']:+.2f}%)",
                 "",
                 L("COMPOUNDING (profit stays in, risk follows the balance)",
                   "කම්පවුන්ඩින් (ලාභය ඇතුළේ තියාගෙන)")]
        # v1.9.1: day by day when the user picked DAYS (M1, M2 ... when MONTHS)
        _u = "DAY" if pl.get("per") == "DAYS" else "MONTH"
        lines.append(f"  {_u:<5}  {'START':>10}  {'GAIN':>10}     {'END':>10}")
        for r in pl["table"]:
            lines.append(f"  {str(r.get('label') or 'M' + str(r['month'])):>5}  "
                         f"{r['start']:>10,.2f}  {r['gain']:>+10,.2f}  ->  "
                         f"{r['end']:>10,.2f}")
        if pl.get("per") == "DAYS" and pl.get("goal_days"):
            lines.append("")
            lines.append(f"  the {pl['target_pct']:g}% target lands on trading day "
                         f"{pl['goal_days']}")
        if pl["month_pct"] <= 0:
            lines.append("")
            lines.append("!! with these numbers the expectancy is NEGATIVE - "
                         "fix the win rate or the reward first")
        self.plan_txt.delete("1.0", "end")
        self.plan_txt.insert("1.0", "\n".join(lines))
        # v1.9.0: the tab also shows TODAY's P&L next to the plan numbers
        _today = ""
        try:
            _st = E.daily_target_state()
            _today = (f"   |   today {_st.get('net', 0.0):+,.2f} USD "
                      f"({_st.get('done_pct', 0.0):+.1f}% of the target)")
        except Exception:
            _today = ""
        self.plan_note.configure(
            text=(f"{pl['per_day']:+,.2f} USD / day   {pl['month_pct']:+.2f}% / month   "
                  f"{pl['expectancy_r']:+.3f} R per trade   "
                  f"(risk {pl['risk_usd']:,.2f} USD)" + _today))
        # v1.9.1: say in words which plan is on the screen
        try:
            if pl.get("per") == "DAYS":
                _d = pl["days"]
                _scope = (f"day by day  -  {_d} trading day{'' if _d == 1 else 's'}   "
                          f"({pl['risk_usd']:,.2f} USD a day x {pl['trades_day']} signals"
                          + (f", the {pl['target_pct']:g}% target lands on day "
                             f"{pl['goal_days']}" if pl.get("goal_days") else "") + ")")
            else:
                _scope = f"month by month  -  {pl['months']} months"
            self.plan_scope.configure(text=_scope)
        except Exception:
            pass
        self.plan_phase += 0.4
        self.plan_flash = time.time()
        self.plan_draw()

    def plan_apply(self):
        try:
            note = E.plan_apply_to_settings(self.plan_data or None)
        except Exception as exc:
            note = f"could not apply: {exc}"
        try:
            reload_engine()
        except Exception:
            pass
        self.load_settings_into_form()
        self.plan_note.configure(text=note.splitlines()[0][:90])
        q_log("trading plan: " + note.replace("\n", " "), "info")
        try:
            messagebox.showinfo(L("TRADING PLAN", "ට්‍රේඩින් ප්ලෑන්"), note)
        except Exception:
            pass

    def plan_capital_add(self):
        try:
            amt = float(str(self.plan_add.get()).replace(",", ".") or 0)
        except Exception:
            amt = 0.0
        if not amt:
            self.plan_note.configure(text=L("type an amount first",
                                            "මුලින්ම මුදලක් ලියන්න"))
            return
        got = E.plan_capital_add(amt)
        self.plan_add.set("")
        self.plan_vars["capital"].set(f"{got:,.2f}")
        q_log(f"plan capital is now {got:,.2f} USD", "info")
        self.plan_generate()

    def plan_add_profit(self):
        try:
            net = float(E.daily_target_state().get("net") or 0.0)
        except Exception:
            net = 0.0
        if not net:
            self.plan_note.configure(text=L("today's profit is 0 so far",
                                            "අද ලාභය තාම 0.00"))
            return
        got = E.plan_capital_add(net)
        self.plan_vars["capital"].set(f"{got:,.2f}")
        q_log(f"today's profit {net:+,.2f} added - capital {got:,.2f} USD", "info")
        self.plan_generate()

    def plan_use_target(self):
        """The plan's money a day becomes the DAILY TARGET in the engine."""
        pl = self.plan_data or {}
        try:
            amt = float(pl.get("per_day") or 0.0)
        except Exception:
            amt = 0.0
        if amt <= 0:
            self.plan_note.configure(text=L("press GENERATE THE PLAN first",
                                            "මුලින්ම ප්ලෑන් එක හදන්න"))
            return
        try:
            E.plan_save({"per_day": amt, "days": pl.get("days", 20),
                         "per": pl.get("per", "DAYS")})
            save_settings_file(APP_DIR / "edgequant_auto.py",
                               {"DAILY_TARGET_MODE": ("PLAN", "str"),
                                "DAILY_TARGET_ON": (True, "bool")})
            reload_engine()
            self.plan_note.configure(
                text=L(f"the DAILY TARGET follows this plan: {amt:,.2f} USD a day",
                       f"දිනපතා ඉලක්කය දැන් මේ ප්ලෑන් එකෙන්: {amt:,.2f} USD"))
            q_log(f"daily target -> {amt:,.2f} USD a day (the plan)", "info")
        except Exception as exc:
            q_log(f"plan target: {exc}", "err")

    def plan_next_day(self):
        try:
            txt = E.next_day_plan()
        except Exception as exc:
            txt = f"could not build tomorrow's plan: {exc}"
        self.plan_txt.delete("1.0", "end")
        self.plan_txt.insert("1.0", txt)
        self.plan_note.configure(text=L("next day plan is ready", "හෙට ප්ලෑන් එක සූදානම්"))

    def plan_draw(self):
        """The compounding curve + the risk blocks (animated)."""
        c = getattr(self, "plan_canvas", None)
        pl = getattr(self, "plan_data", None) or {}
        if c is None:
            return
        try:
            c.delete("all")
            w = max(260, c.winfo_width())
            h = max(160, c.winfo_height())
        except Exception:
            return
        table = pl.get("table") or []
        if not table:
            c.create_text(w / 2, h / 2, text=L("press GENERATE THE PLAN",
                                               "ප්ලෑන් එක හදන්න ඔබන්න"),
                          fill=MUTED, font=widget_font("Segoe UI", 10))
            return
        if len(table) == 1:
            # v1.9.0: ONE month still draws (a bar + the numbers), it used to
            # show only the hint text - that is what the screenshot showed
            r0 = table[0]
            start = float(r0.get("start") or 0.0)
            end = float(r0.get("end") or 0.0)
            top = max(start, end, 1.0)
            bx, bw2 = w * 0.30, w * 0.40
            base = h - 30.0
            hs = max(6.0, (start / top) * (base - 40.0))
            he = max(6.0, (end / top) * (base - 40.0))
            c.create_rectangle(bx, base - hs, bx + bw2 * 0.42, base,
                               fill="#2a3648", outline="")
            c.create_rectangle(bx + bw2 * 0.58, base - he, bx + bw2, base,
                               fill=GREEN if end >= start else RED, outline="",
                               activeoutline="")
            pulse = 1.0 + 0.05 * math.sin(self.plan_phase * 3.0)
            c.create_text(bx + bw2 * 0.21, base - hs - 10, text=f"{start:,.2f}",
                          fill=MUTED, font=widget_font("Consolas", 8))
            c.create_text(bx + bw2 * 0.79, base - he - 12,
                          text=f"{end:,.2f}", fill=GOLD,
                          font=widget_font("Consolas", int(10 * pulse) + 1, True))
            c.create_text(w / 2, base + 12,
                          text=(L("1 DAY", "දවස 1") if pl.get("per") == "DAYS"
                                else L("1 MONTH", "මාස 1")),
                          fill=MUTED, font=widget_font("Segoe UI", 8, True))
            c.create_text(w / 2, 14,
                          text=(f"{start:,.2f}  ->  {end:,.2f}   "
                                f"({float(r0.get('pct') or 0):+.2f}% )"),
                          fill=FG, font=widget_font("Consolas", 10, True))
            self.plan_phase += 0.2
            return
        pad = 34.0
        vals = [float(r["end"]) for r in table]
        lo, hi = min(vals + [float(pl.get("capital") or 0)]), max(vals)
        span = (hi - lo) or 1.0
        def X(i): return pad + i * (w - 2 * pad) / max(1, len(vals) - 1)
        def Y(v): return (h - pad) - (v - lo) / span * (h - 2 * pad)
        for k in range(1, 4):
            yy = pad + (h - 2 * pad) * k / 4.0
            c.create_line(pad, yy, w - pad, yy, fill="#1b2433", dash=(2, 4))
        pts = []
        for i, r in enumerate(table):
            pts += [X(i), Y(float(r["end"]))]
        col = GREEN if (table[-1]["end"] - vals[0]) >= 0 else RED
        c.create_line(*pts, fill=col, width=2, smooth=True)
        _step = max(1, len(table) // 12)          # v1.9.1: keep the labels tidy
        for i, r in enumerate(table):
            x, y = X(i), Y(float(r["end"]))
            pulse = 2.0 + 1.4 * math.sin(self.plan_phase + i * 0.5)
            c.create_oval(x - pulse, y - pulse, x + pulse, y + pulse, fill=GOLD,
                          outline="")
            if i % _step == 0 or i == len(table) - 1:
                c.create_text(x, h - 14, text=str(r.get("label") or f"M{int(r['month'])}"),
                              fill=MUTED, font=widget_font("Consolas", 7))
        c.create_text(pad, 12, text=f"start {float(pl.get('capital') or 0):,.2f}",
                      fill=MUTED, font=widget_font("Consolas", 8), anchor="w")
        _rate = (f"{pl.get('day_pct', 0):+.2f}%/day" if pl.get("per") == "DAYS"
                 else f"{pl.get('month_pct', 0):+.2f}%/mo")
        c.create_text(w - pad, 12, text=f"end {vals[-1]:,.2f} ({_rate})",
                      fill=GOLD, font=widget_font("Consolas", 9, True), anchor="e")
        self.plan_phase += 0.18

    def plan_animate(self):
        if not hasattr(self, "plan_canvas"):
            return
        try:
            self.plan_draw()
            self.plan_refresh_daily_target_status()
        except Exception:
            pass

    def tg_chip_refresh(self):
        """v1.9.2: the TELEGRAM chip can not lie any more.

        * the engine runs in THIS window -> ask the live client
        * another window runs it        -> read its status file (fresh = running)
        * nothing runs                  -> a calm "not running", not a red alarm
        """
        try:
            st = engine_status()
        except Exception:
            st = {}
        dead = {}
        try:
            dead = E.session_dead_read(7 * 86400.0)      # v1.9.5
        except Exception:
            dead = {}
        note = ""
        if dead:
            # Telegram ended the login ("the key is not registered in the
            # system").  Say it loud, say what to do, and shout on the button.
            self.chip_tg.configure(text="SESSION DEAD - PRESS LOGIN", foreground=RED)
            try:
                self.b_tglogin.configure(text=L("LOGIN !", "ලොගින් !"))
            except Exception:
                pass
            note = ("TELEGRAM SESSION DEAD - the login was ended by Telegram itself.  "
                    "Press LOGIN (phone + the code Telegram sends you) - the bot keeps "
                    "running and starts again by itself within 20 s.")
            if note != getattr(self, "_tg_note_last", ""):
                self._tg_note_last = note
                for line in str(dead.get("advice") or note).splitlines():
                    q_log(line, "err" if "DEAD" in line else "warn")
                q_log(f"(dead-login flag from {time.strftime('%d %b %H:%M', time.localtime(float(dead.get('ts') or 0)))}"
                      f"{' - ' + str(dead.get('where')) if dead.get('where') else ''})",
                      "warn")
            return note
        try:
            self.b_tglogin.configure(text=L("LOGIN", "ලොගින්"))
        except Exception:
            pass
        try:
            if self.running and (self.bot and self.bot.is_alive()):
                on, who = E.tg_online_now()
                reason = str(getattr(E, "TG_STATE", {}).get("reason") or "")
                if on:
                    self.chip_tg.configure(text=(f"connected  {who}" if who
                                                 else "connected"), foreground=GREEN)
                elif reason:
                    self.chip_tg.configure(text="not connected", foreground=RED)
                    note = reason
                else:
                    self.chip_tg.configure(text="connecting ...", foreground=AMBER)
            elif st.get("fresh") and st.get("telegram"):
                who = str(st.get("who") or "")
                self.chip_tg.configure(
                    text=(f"connected  {who}  (bot window)" if who
                          else "connected  (bot window)"), foreground=GREEN)
            elif st.get("fresh"):
                reason = str(st.get("reason") or "")
                self.chip_tg.configure(text="not connected", foreground=RED)
                note = reason or "the engine is running but Telegram is not connected"
            else:
                self.chip_tg.configure(text="not running", foreground=MUTED)
                note = ""
        except Exception:
            pass
        # say the reason once (and put it where he looks first)
        if note and note != getattr(self, "_tg_note_last", ""):
            self._tg_note_last = note
            q_log("TELEGRAM: " + note, "err")
            try:
                self.status.configure(text="TELEGRAM - " + note, foreground=RED)
            except Exception:
                pass
        elif not note:
            self._tg_note_last = ""
        return note

    def _update_line(self):
        """The half hour update as one line on the dashboard (and the voice)."""
        try:
            st = E.daily_target_state()
            nxt = 0
            try:
                last = float(E.state_get("dt_last_update", 0.0) or 0.0)
                every = float(getattr(E, "UPDATE_EVERY_MIN", 30) or 30)
                nxt = max(0, int((last + every * 60 - time.time()) / 60.0))
            except Exception:
                nxt = 0
            return (f"UPDATE every {getattr(E, 'UPDATE_EVERY_MIN', 30):g} min   "
                    f"(next in {nxt} min)   |   today {st.get('net', 0):+,.2f} USD   "
                    f"{st.get('done_pct', 0):+.1f}% of the target   |   "
                    f"TP {st.get('counts', {}).get('tp', 0)} / "
                    f"SL {st.get('counts', {}).get('sl', 0)}")
        except Exception:
            return ""

