    def install_sinhala_voice(self):
        """Ask before opening the optional Python/model downloader."""
        if getattr(sys, "frozen", False):
            messagebox.showinfo("Offline Sinhala voice",
                "The optional VITS worker is not included in this source-free client build.",
                parent=self.root)
            return
        installer = APP_DIR / "INSTALL-SINHALA-FEMALE-VOICE.bat"
        if not installer.is_file():
            messagebox.showerror("Offline Sinhala voice",
                "INSTALL-SINHALA-FEMALE-VOICE.bat is missing. Re-extract the complete package.",
                parent=self.root)
            return
        accepted = messagebox.askyesno(
            L("Install offline Sinhala female voice", "දේශීය සිංහල කාන්තා හඬ ස්ථාපනය"),
            L("This optional setup downloads about 1 GB of female VITS model data, "
              "plus PyTorch/TTS packages, and can take a while. It uses a separate "
              "Python 3.11 environment; CPU speed and RAM use are not verified.\n\n"
              "Trade/report text is synthesized and played on this PC; report text "
              "is not sent to PyPI or Hugging Face. The speech worker may pause during "
              "setup; the trading engine is not restarted. Continue?",
              "මෙය විකල්ප ස්ථාපනයකි. සිංහල කාන්තා VITS හඬ ආකෘතිය (ආසන්නව 1 GB) සහ "
              "PyTorch/TTS පැකේජ බාගත වේ; කාලයක් ගත විය හැක. වෙනම Python 3.11 පරිසරයක් භාවිතා කරයි. "
              "CPU වේගය සහ RAM භාවිතය පරීක්ෂා කර නැහැ.\n\n"
              "වාර්තාව, ලාභ/අලාභ, මිල සහ චැනල් පෙළ මේ පරිගණකයේම සකසා වාදනය වේ; ඒවා "
              "PyPI හෝ Hugging Face වෙත යවන්නේ නැහැ. ස්ථාපනය අතර හඬ සේවාව තාවකාලිකව නවතී; "
              "වෙළඳ engine එක restart කරන්නේ නැහැ. ඉදිරියට යන්නද?"),
            parent=self.root)
        if not accepted:
            return
        try:
            if os.name != "nt" or not hasattr(os, "startfile"):
                raise OSError("The optional installer runs on Windows only.")
            try:
                E.local_sinhala_voice_stop(timeout=3.0)
            except Exception:
                pass
            os.startfile(str(installer))
            self.sinhala_voice_note.configure(
                text=L("Installer opened. Finish its test, then press REFRESH.",
                       "ස්ථාපකය විවෘතයි. පරීක්ෂණය අවසන් කර REFRESH ඔබන්න."), fg=CYAN)
            q_log("offline female Sinhala voice installer opened; model/runtime download is user-approved",
                  "info")
        except Exception as exc:
            messagebox.showerror("Offline Sinhala voice", str(exc), parent=self.root)
            q_log(f"offline Sinhala voice installer: {exc}", "err")

    def voice_lang_save(self):
        try:
            want = str(self.voice_lang_var.get()).upper()[:2]
            if want not in ("EN", "SI"):
                raise ValueError("Choose EN or SI.")
            save_settings_file(APP_DIR / "edgequant_auto.py",
                               {"VOICE_LANG": (want, "str")})
            if self.bot and self.bot.is_alive():
                # Do not reload the engine/event loop while it is trading.
                E.VOICE_LANG = want
            else:
                reload_engine()
            try:
                E.voice_sapi_refresh(want, scan=False)
            except Exception:
                pass
            note = ("SINHALA selected: English fallback is disabled"
                    if want == "SI" else "ENGLISH selected")
            if hasattr(self, "voice_note"):
                self.voice_note.configure(text=note)
                self.voice_status_refresh()
            q_log("voice language: " + note, "info")
        except Exception as exc:
            q_log(f"voice language: {exc}", "err")

    def speak_welcome(self, name="", telegram=False):
        """Play the login greeting in the configured voice language."""
        try:
            result = E.voice_welcome(name, telegram=telegram)
            if result == "off":
                q_log("voice welcome skipped because VOICE_ON is OFF", "info")
            else:
                q_log(f"voice welcome requested in {getattr(E, 'VOICE_LANG', 'EN')}", "info")
            return result
        except Exception as exc:
            q_log(f"voice welcome could not play: {exc}", "warn")
            return ""

