    #  v1.9.12  CLIENT-OWNED TELEGRAM API KEYS  (local Windows DPAPI store)
    # ===================================================================== #
    def _telegram_api_status_text(self):
        ready = bool(getattr(E, "telegram_credentials_ready", lambda: False)())
        source = str(getattr(E, "telegram_credentials_source", lambda: "missing")() or "missing")
        if not ready:
            return L("Telegram API keys are not set. Use API SETUP before requesting a code.",
                     "Telegram API keys සකසා නැහැ. Code එකක් ඉල්ලීමට පෙර API SETUP භාවිතා කරන්න.")
        if source == "windows_dpapi":
            return L("Telegram API keys are encrypted and saved for this Windows user.",
                     "Telegram API keys මේ Windows user සඳහා encrypt කර සුරකින ලදී.")
        return L("Telegram API keys are loaded from Windows environment variables.",
                 "Telegram API keys Windows environment variables වලින් ලබාගෙන ඇත.")

    def _refresh_telegram_api_status(self):
        try:
            label = getattr(self, "telegram_api_status_label", None)
            if label is not None and label.winfo_exists():
                ready = bool(getattr(E, "telegram_credentials_ready", lambda: False)())
                label.configure(text=self._telegram_api_status_text(),
                                fg=GREEN if ready else AMBER)
        except Exception:
            pass

    def telegram_api_setup_dialog(self, parent=None, on_saved=None):
        """Collect the client's own Telegram API pair and save it with Windows DPAPI."""
        try:
            if self._tg_api_setup_window is not None and self._tg_api_setup_window.winfo_exists():
                self._tg_api_setup_window.lift()
                self._tg_api_setup_window.focus_force()
                return
        except Exception:
            pass
        owner = parent.winfo_toplevel() if parent is not None else self.root
        win = tk.Toplevel(owner)
