    # ---------------------------------------------------------------- loop --
    def poll_mt5(self, schedule=True):
        """Poll account identity + a read-only external-trade snapshot.

        While the engine runs, ALL MT5 reads/broker switches execute on its
        asyncio thread. The UI worker only waits for the resulting snapshot.
        """
        running = bool(self.bot and self.bot.is_alive())
        if getattr(self, "_mt5_info_busy", False):
            if schedule:
                self.root.after(1000, self.poll_mt5)
            return
        self._mt5_info_busy = True
        journal_records = None
        if not running:
            try:
                if not getattr(E, "_JR_LOADED", False):
                    quiet(E.jr_load)
                journal_records = [dict(row) for row in (E.TRADES or [])]
            except Exception:
                journal_records = []

        def mt5_last_error(api):
            try:
                return str(api.last_error())
            except Exception as exc:
                return f"{type(exc).__name__}: {exc}"

        def one(api, name, login=None, password=None, server=None, path=None,
                initialize=True):
            """Read one currently selected MT5 account and import its external trades."""
            info = {"name": name, "account_name": name, "company": "", "trade_mode": "UNKNOWN",
                    "login": "-", "server": "-", "balance": "-", "currency": "",
                    "equity": "-", "float": 0.0, "positions": 0, "pendings": 0,
                    "symbols": "", "status": "not connected"}
            try:
                if initialize:
                    kw = {}
                    if path:
                        kw["path"] = str(path)
                    if login:
                        kw["login"] = int(login)
                    if password:
                        kw["password"] = str(password)
                    if server:
                        kw["server"] = str(server)
                    if not api.initialize(**kw):
                        info["read_error"] = "initialize() failed; last_error=" + mt5_last_error(api)
                        return info
                elif api is None:
                    info["read_error"] = "MT5 Python API is unavailable in this process."
                    return info

                terminal = api.terminal_info()
                if terminal is None:
                    info["read_error"] = "terminal_info() returned None; last_error=" + mt5_last_error(api)
                    return info
                terminal_connected = getattr(terminal, "connected", None)
                info["terminal_connected"] = terminal_connected
                if terminal_connected is False:
                    info["read_error"] = (
                        "MT5 terminal is open but is not connected to its broker/server; "
                        "check the logged-in account and connection status. last_error=" +
                        mt5_last_error(api))
                    return info

                account = api.account_info()
                if not account:
                    info["read_error"] = (
                        "account_info() returned no logged-in trading account; last_error=" +
                        mt5_last_error(api))
                    return info
                account_name = str(getattr(account, "name", "") or name or "Account").strip()
                server_name = str(getattr(account, "server", "") or "").strip()
                company = str(getattr(account, "company", "") or "").strip()
                raw_mode = getattr(account, "trade_mode", None)
                info.update({"login": getattr(account, "login", "-"), "server": server_name,
                             "account_name": account_name,
                             "company": company or server_name,
                             "trade_mode": mt5_trade_mode_label(
                                 api, raw_mode, server_name, company),
                             "balance": getattr(account, "balance", "-"),
                             "currency": getattr(account, "currency", ""),
                             "equity": getattr(account, "equity", "-"),
                             "status": "connected"})
                tracked_external_ids = set()
                mirror_terminal = {"TP HIT", "SL HIT", "BREAK EVEN", "CLOSED",
                                   "CLOSED (MANUAL)", "CANCELLED"}
                # Explicit Provider links keep a selected manual magic=0 ticket in
                # the read-only history snapshot even after it closes / leaves today.
                for provider_link in (getattr(self, "studio_provider_links", []) or []):
                    if not isinstance(provider_link, dict):
                        continue
                    if str(provider_link.get("broker") or "MAIN").strip().casefold() != \
                            str(name or "MAIN").strip().casefold():
                        continue
                    for value in (provider_link.get("ticket"), provider_link.get("position_id")):
                        try:
                            value = int(value or 0)
                            if value > 0:
                                tracked_external_ids.add(value)
                        except Exception:
                            pass
                for mirror in (getattr(self, "_studio_manual_mirror_posts", []) or []):
                    if not isinstance(mirror, dict):
                        continue
                    if str(mirror.get("broker") or "MAIN").strip().casefold() != \
                            str(name or "MAIN").strip().casefold():
                        continue
                    if str(mirror.get("status") or "").upper() in mirror_terminal:
                        continue
                    if str(mirror.get("send_state") or "").upper() not in ("SENT", "PARTIAL"):
                        continue
                    for value in [mirror.get("ticket"), mirror.get("position_id")]:
                        try:
                            value = int(value or 0)
                            if value > 0:
                                tracked_external_ids.add(value)
                        except Exception:
                            pass
                    for alias_name in ("alias_tickets", "alias_position_ids"):
                        for value in mirror.get(alias_name) or []:
                            try:
                                value = int(value or 0)
                                if value > 0:
                                    tracked_external_ids.add(value)
                            except Exception:
                                pass
                positions = list(api.positions_get() or [])
                orders = list(api.orders_get() or [])
                syms, live, pend = set(), 0, 0
                for position in positions:
                    if E.MAGIC and getattr(position, "magic", 0) != E.MAGIC:
                        continue
                    live += 1
                    syms.add(str(getattr(position, "symbol", "") or ""))
                    info["float"] += float(getattr(position, "profit", 0.0) or 0.0)
                for order in orders:
                    if E.MAGIC and getattr(order, "magic", 0) != E.MAGIC:
                        continue
                    pend += 1
                    syms.add(str(getattr(order, "symbol", "") or ""))
                info["positions"], info["pendings"] = live, pend
                info["symbols"] = ", ".join(sorted(x for x in syms if x))[:28]
                if info["status"] == "connected" and hasattr(E, "mt5_external_trade_snapshot"):
                    info["external_snapshot"] = E.mt5_external_trade_snapshot(
                        mt5_api=api, broker=name,
                        journal_trades=E.TRADES if journal_records is None else journal_records,
                        positions=positions, orders=orders,
                        tracked_external_ids=tracked_external_ids)
            except Exception as exc:
                info["read_error"] = f"{type(exc).__name__}: {exc}"
            return info

        def combine(brokers):
            brokers = list(brokers or [])
            snapshots = []
            for row in brokers:
                snap = row.pop("external_snapshot", None)
                if isinstance(snap, dict):
                    snapshots.append(snap)
            ok = [row for row in brokers if row.get("status") == "connected"]
            info = {"login": "-", "server": "-", "balance": "-", "currency": "",
                    "equity": "-", "float": 0.0, "positions": 0, "pendings": 0,
                    "symbols": "", "trade_mode": "UNKNOWN", "account_name": "",
                    "company": "", "brokers": brokers}
            errors = [f"{row.get('name') or 'MT5'}: {row.get('read_error')}"
                      for row in brokers if row.get("read_error")]
            if errors:
                info["read_error"] = " | ".join(errors)
            if ok:
                nums = lambda key: [float(row[key]) for row in ok
                                    if isinstance(row.get(key), (int, float))]
                modes = {str(row.get("trade_mode") or "UNKNOWN").upper() for row in ok}
                overall_mode = (next(iter(modes)) if len(modes) == 1 else
                                ("REAL + DEMO" if modes <= {"REAL", "DEMO"} and
                                 "REAL" in modes and "DEMO" in modes else "MIXED"))
                currencies = {str(row.get("currency") or "").strip().upper() for row in ok}
                same_currency = len(currencies) == 1
                balance_values, equity_values = nums("balance"), nums("equity")
                info.update({"login": ok[0]["login"], "server": ok[0]["server"],
                             "account_name": (ok[0].get("account_name") if len(ok) == 1 else
                                              " / ".join(str(row.get("account_name") or
                                                             row.get("name") or "Account")
                                                         for row in ok)),
                             "company": (ok[0].get("company") if len(ok) == 1 else
                                         " + ".join(str(row.get("company") or row.get("server") or "")
                                                    for row in ok)),
                             "trade_mode": overall_mode,
                             "currency": next(iter(currencies)) if same_currency else "MIXED",
                             "status": "connected",
                             # Never add balances from different currencies.
                             "balance": (round(sum(balance_values), 2) if same_currency and
                                         balance_values else None),
                             "equity": (round(sum(equity_values), 2) if same_currency and
                                        equity_values else None),
                             "float": round(sum(row["float"] for row in ok), 2),
                             "positions": sum(row["positions"] for row in ok),
                             "pendings": sum(row["pendings"] for row in ok)})
                symbols = sorted({part.strip() for row in ok
                                  for part in (row.get("symbols") or "").split(",") if part.strip()})
                info["symbols"] = ", ".join(symbols)[:28]
            if hasattr(E, "mt5_merge_external_snapshots"):
                snapshot = E.mt5_merge_external_snapshots(snapshots)
            else:
                snapshot = {"trades": [], "net_today": 0.0, "float": 0.0,
                            "closed_today": 0, "open_today": 0, "pending_today": 0,
                            "deal_count": 0, "status": "unavailable"}
            return info, snapshot

        def worker():
            nonlocal journal_records
            info = None
            snapshot = None
            try:
                engine_running = bool(self.bot and self.bot.is_alive())
                if engine_running:
                    journal_records = None
                    loop = getattr(self.bot, "loop", None)
                    if loop is None or not loop.is_running():
                        brokers = []
                    else:
                        async def read_on_engine_loop():
                            names = list(E.broker_names() or ["MAIN"])
                            keep = (E.CURRENT_BROKER or {}).get("name")
                            rows = []
                            try:
                                for name in names:
                                    selected = (E.select_broker(name) if len(names) > 1
                                                else E.mt5_ready())
                                    if not selected:
                                        rows.append({"name": name, "account_name": name,
                                                     "status": "not connected", "float": 0.0,
                                                     "positions": 0, "pendings": 0,
                                                     "balance": "-", "equity": "-",
                                                     "currency": "", "symbols": ""})
                                        continue
                                    rows.append(one(E.mt5, name, initialize=False))
                            finally:
                                restore = keep or str(E.DEFAULT_BROKER or names[0]).upper()
                                if len(names) > 1 and restore in names:
                                    try:
                                        E.select_broker(restore)
                                    except Exception:
                                        pass
                            return rows
                        future = asyncio.run_coroutine_threadsafe(read_on_engine_loop(), loop)
                        try:
                            brokers = future.result(timeout=60)
                        except Exception:
                            future.cancel()
                            raise
                else:
                    import MetaTrader5 as mt5
                    brokers = []
                    accs = E.accounts() if hasattr(E, "accounts") else []
                    with self._mt5_api_lock:
                        for i, account in enumerate(accs or [{"name": "MAIN"}]):
                            if i:
                                try:
                                    mt5.shutdown()
                                except Exception:
                                    pass
                            brokers.append(one(mt5, account.get("name") or f"ACC{i+1}",
                                               account.get("login"), account.get("password"),
                                               account.get("server"), account.get("path"),
                                               initialize=True))
                info, snapshot = combine(brokers)
            except Exception as exc:
                q_log(f"MT5 snapshot: {type(exc).__name__}: {exc}", "warn")
                info = {"login": "-", "server": "-", "balance": "-", "currency": "",
                        "equity": "-", "float": 0.0, "positions": 0, "pendings": 0,
                        "symbols": "", "trade_mode": "UNKNOWN", "account_name": "",
                        "company": "", "brokers": [],
                        "read_error": f"{type(exc).__name__}: {exc}"}
                snapshot = {"trades": [], "net_today": 0.0, "float": 0.0,
                            "closed_today": 0, "open_today": 0, "pending_today": 0,
                            "deal_count": 0, "status": "unavailable",
                            "error": f"{type(exc).__name__}: {exc}"}
            finally:
                RESULT_Q.put(("mt5", info or {}))
                RESULT_Q.put(("external_trades", snapshot or {"status": "unavailable", "trades": []}))
                self._mt5_info_busy = False

        threading.Thread(target=worker, daemon=True, name="edgequant-mt5-snapshot").start()

        def again(ms=30000 if (self.bot and self.bot.is_alive()) else 12000):
            if schedule:
                self.root.after(ms, self.poll_mt5)

        again()

    def _paint_mt5(self):
        i = self.mt5_info
        brokers = i.get("brokers") or []
        ok = [b for b in brokers if b.get("status") == "connected"]
        if not ok:
            self.chip_mt5.configure(text="not connected", foreground=RED)
            self.chip_acc.configure(text="no account" if brokers else "-",
                                    foreground=MUTED)
            self._paint_mt5_identity([])
            self._paint_mt5_troubleshooting()
            return
        if len(ok) == 1:
            self.chip_mt5.configure(
                text=f"{ok[0]['login']}  {money(ok[0]['balance'], ok[0]['currency'])}",
                foreground=GREEN)
        else:
            self.chip_mt5.configure(
                text=f"{len(ok)}/{len(brokers)} connected  "
                     f"{money(i['balance'], i['currency'])}", foreground=GREEN)
        self.chip_acc.configure(
            text="  +  ".join((b["name"] or "?").split()[0][:9] for b in ok),
            foreground=GOLD if len(ok) > 1 else MUTED)
        self._paint_mt5_identity(ok)
        self._paint_mt5_troubleshooting()

    def _paint_mt5_troubleshooting(self):
        """Show concise Windows/terminal recovery advice without exposing credentials."""
        widget = getattr(self, "mt5_trouble_note", None)
        if widget is None:
            return
        info = getattr(self, "mt5_info", {}) or {}
        brokers = list(info.get("brokers") or [])
        connected = [b for b in brokers if str(b.get("status") or "").lower() == "connected"]
        error = " ".join(str(info.get("read_error") or "").split())
        if connected:
            note, color = "Terminal and account are connected. Keep MT5 open for monitoring and trading.", GREEN
        elif error:
            short = error if len(error) <= 200 else error[:197] + "..."
            if "_core" in error.lower() or "dll load failed" in error.lower():
                note = ("MT5 Python native _core DLL failed before terminal login. Install the "
                        "Microsoft Visual C++ x64 runtime, verify 64-bit Python and `import MetaTrader5`, "
                        "then rebuild with BUILD-EXE.bat. Detail: " + short)
            else:
                note = ("MT5 diagnostic: " + short +
                        "  ·  Verify the correct terminal is open, logged in, and connected to its broker; "
                        "then press REFRESH MT5.")
            color = RED
        elif not getattr(E, "HAVE_MT5", False):
            note, color = ("MT5 Python API unavailable in this installation. Install the packaged MetaTrader5 dependency "
                           "and restart EdgeQuant.", AMBER)
        elif brokers:
            failed = [str(b.get("name") or "account") for b in brokers
                      if str(b.get("status") or "").lower() != "connected"]
            note = ("No connected account: " + ", ".join(failed[:3]) +
                    ". Open the matching MT5 terminal, sign in, enable Algo Trading if required, "
                    "and verify the server connection.")
            color = AMBER
        else:
            note, color = ("Open MetaTrader 5, sign in to the intended demo/live account, "
                           "wait for the connection bars, then press REFRESH MT5.", AMBER)
        try:
            widget.configure(text=note[:420], fg=color)
        except Exception:
            pass

    def _paint_mt5_identity(self, connected=None):
        """Paint broker, account identity and REAL/DEMO status in header + Dashboard."""
        i = self.mt5_info or {}
        brokers = list(connected if connected is not None else
                       [b for b in (i.get("brokers") or [])
                        if b.get("status") == "connected"])
        modes = {str(b.get("trade_mode") or "UNKNOWN").upper() for b in brokers}
        mode = (next(iter(modes)) if len(modes) == 1 else
                ("REAL + DEMO" if modes == {"REAL", "DEMO"} else
                 ("MIXED" if len(modes) > 1 else "UNKNOWN")))
        color = {"REAL": RED, "DEMO": GREEN, "CONTEST": AMBER,
                 "MIXED": PURPLE, "REAL + DEMO": PURPLE}.get(mode, AMBER)
        if not brokers:
            account = "not connected"
            reason = " ".join(str(i.get("read_error") or "").split())
            if "_core" in reason.lower() or "dll load failed" in reason.lower():
                reason = "MT5 native DLL failed to load; see the troubleshooting note"
            elif len(reason) > 82:
                reason = reason[:79] + "..."
            broker = ("Reason: " + reason) if reason else "Broker: —"
            login = "—"
            balance = equity = "—"
            link_text = "●  MT5 NOT CONNECTED"
            dash_title = "MT5 ACCOUNT  •  NOT CONNECTED"
            dash_detail = ("Reason: " + reason) if reason else "Open MT5 and sign in to a broker account."
        elif len(brokers) == 1:
            b = brokers[0]
            account = str(b.get("account_name") or b.get("name") or "Account").strip()
            broker = str(b.get("company") or b.get("server") or "Unknown broker").strip()
            login = str(b.get("login") or "—")
            balance = money(b.get("balance"), b.get("currency"))
            equity = money(b.get("equity"), b.get("currency"))
            link_text = "●  MT5 CONNECTED"
            dash_title = f"MT5 ACCOUNT  •  {mode}"
            dash_detail = f"{account}  |  Broker: {broker}  |  Login: {login}"
        else:
            account_names = [str(b.get("account_name") or b.get("name") or "Account").strip()
                             for b in brokers]
            broker_names = [str(b.get("company") or b.get("server") or b.get("name") or "Broker").strip()
                            for b in brokers]
            account = " / ".join(name[:22] for name in account_names)
            broker = " + ".join(dict.fromkeys(broker_names))
            login = ", ".join(str(b.get("login") or "—") for b in brokers)
            currency = str(i.get("currency") or "MIXED").upper()
            if currency != "MIXED" and i.get("balance") is not None:
                balance = money(i.get("balance"), currency)
                equity = money(i.get("equity"), currency)
            else:
                # Show separate balances instead of falsely adding unlike currencies.
                balance = " / ".join(
                    f"{name[:12]} {money(b.get('balance'), b.get('currency'))}"
                    for name, b in zip(account_names[:3], brokers[:3]))
                equity = " / ".join(
                    f"{name[:12]} {money(b.get('equity'), b.get('currency'))}"
                    for name, b in zip(account_names[:3], brokers[:3]))
                if len(brokers) > 3:
                    balance += f" / +{len(brokers) - 3} accounts"
                    equity += f" / +{len(brokers) - 3} accounts"
            link_text = f"●  {len(brokers)} MT5 ACCOUNTS LINKED"
            dash_title = f"MT5 ACCOUNTS  •  {mode}"
            dash_detail = "  |  ".join(
                f"{name[:22]} — {broker_name[:24]} (#{b.get('login') or '—'})"
                for name, broker_name, b in zip(account_names, broker_names, brokers))
        broker_line = broker if not brokers else f"Broker: {broker}"
        broker_line_color = RED if not brokers and i.get("read_error") else MUTED
        values = {"mt5_top_mode": (f"MT5  •  {mode}", color),
                  "mt5_top_link": (link_text, GREEN if brokers else RED),
                  "mt5_top_account": (f"Account: {account}  •  #{login}", FG),
                  "mt5_top_broker": (broker_line, broker_line_color),
                  "mt5_top_money": (f"Balance {balance}   •   Equity {equity}", CYAN),
                  "dashboard_account_mode": (dash_title, color),
                  "dashboard_account_detail": (dash_detail, MUTED),
                  "dashboard_account_money": (f"Balance {balance}  ·  Equity {equity}", CYAN)}
        for attr, (text, fg) in values.items():
            try:
                widget = getattr(self, attr)
                widget.configure(text=text[:160], fg=fg)
            except Exception:
                pass

    def _tick(self):
        if getattr(self, "_rebuilding", False):        # v1.7.0: theme/lang redraw
            self.root.after(250, self._tick)
            return
        # drain the engine's log queue
        painted = 0
        while painted < 220:
            try:
                item = LOG_Q.get_nowait()
            except queue.Empty:
                break
            kind, ts, level, text = item
            if kind == "rule":
                self._append(text + "\n", "rule")
            else:
                stamp = datetime.fromtimestamp(ts).strftime("%H:%M:%S")
                self._append(f"{stamp}  ", "ts")
                self._append(text + "\n", level)
                low = text.lower()
                if level == "ok" and text.startswith("Telegram :"):
                    self.chip_tg.configure(text="connected", foreground=GREEN)
                if text.startswith("MT5      : connected"):
                    m = re.search(r"login=(\d+).*?balance=([\d.]+) (\w+)", text)
                    if m:
                        self.chip_mt5.configure(text=f"{m.group(1)}  {money(m.group(2), m.group(3))}",
                                                foreground=GREEN)
                if "TRADE JOURNAL" in text or "journal:" in low:
                    pass
                # the engine heartbeat -> show it in the status bar (proof it is alive)
                if "telegram connected" in low and "pending" in low:
                    live_now = self.running and not E.DRY_RUN
                    self.status.configure(
                        text=("LIVE  -  " if live_now else "") + text.strip(),
                        foreground=RED if live_now else GREEN)
                elif "the bot is now running" in low:
                    self.status.configure(text="engine running - waiting for signals "
                                                "(heartbeat every 60s)", foreground=GREEN)
            painted += 1
        if painted and self.autoscroll.get():
            self.log.see("end")
        # results from the worker threads
        while True:
            try:
                item = RESULT_Q.get_nowait()
            except queue.Empty:
                break
            if item[0] == "mt5":
                self.mt5_info = item[1]
                self._paint_mt5()
            elif item[0] == "external_trades":
                self.external_trade_snapshot = item[1] or {"status": "unavailable", "trades": []}
                try:
                    self._studio_manual_mirror_process_snapshot(self.external_trade_snapshot)
                except Exception as exc:
                    q_log(f"Provider manual-order mirror snapshot: {type(exc).__name__}: {exc}", "warn")
                if self.nb.select() == str(self.tab_manual):
                    self.refresh_manual_trades()
                if self.nb.select() == str(self.tab_dash):
                    self.refresh_dashboard()
                if getattr(self, "studio_live_market_tree", None) is not None:
                    self._studio_refresh_live_orders()
            elif item[0] == "provider_monitor":
                _, snapshot, checked = item
                self._studio_monitor_result(snapshot, checked)
            elif item[0] == "provider_export":
                _, path, description, error = item
                self._studio_export_busy = False
                if error:
                    self.studio_report_status_var.set(f"{description} export failed: {error}")
                    q_log(f"Provider export failed: {error}", "err")
                    messagebox.showerror("Provider export", error, parent=self.root)
                else:
                    self.studio_report_status_var.set(f"Saved {description}: {path}")
                    q_log(f"Provider export saved: {path}", "ok")
                    self._studio_refresh_performance()
            elif item[0] == "manual_edit":
                _, uid, result = item
                self._manual_edit_result(uid, result)
            elif item[0] == "voice_report":
                _, report, error = item
                self._voice_report_busy = False
                try:
                    self.dt_say_btn.configure(state="normal")
                    if error:
                        self.dt_voice_report_note.configure(text=f"Report could not be read: {error}", fg=RED)
                    else:
                        selected = str(getattr(E, "VOICE_LANG", "EN") or "EN").upper()[:2]
                        try:
                            dispatch = E.voice_last_dispatch("update")
                        except Exception:
                            dispatch = {"state": "unknown", "route": ""}
                        state = str(dispatch.get("state") or "unknown")
                        if selected == "SI" and state == "played":
                            note = "වාර්තාව දේශීය සිංහල කාන්තා හඬින් කියවා අවසන්."
                            note_en = "The offline Sinhala female report finished playing on this PC."
                            color = GREEN
                        elif selected == "SI" and state == "queued":
                            note = "වාර්තාව දේශීය සිංහල හඬට යවා ඇත; වාදනය අවසන් බව තවම තහවුරු නැත."
                            note_en = "Report queued for the offline female Sinhala voice; playback is not confirmed yet."
                            color = CYAN
                        elif selected == "SI" and state == "dispatched":
                            note = "Windows සිංහල හඬට වාර්තාව යොමු කළා; වාදනය තහවුරු කර නැත."
                            note_en = "Report dispatched to the female Sinhala Windows voice; playback is not confirmed."
                            color = CYAN
                        elif selected == "SI" and state == "failed":
                            error_text = str(dispatch.get("error") or "voice worker failed")[:100]
                            note = "දේශීය සිංහල හඬ අසාර්ථකයි: " + error_text
                            note_en = "The offline Sinhala voice reported an error: " + error_text
                            color = RED
                        elif selected == "SI":
                            reason = str(dispatch.get("error") or "no matching female voice is ready")[:100]
                            note = "ගණනය කළ වාර්තාව කියවූයේ නැත: " + reason + "; ඉංග්‍රීසි මාරුවක් නැත."
                            note_en = "Report text was generated but not spoken: " + reason + ". English fallback is off."
                            color = AMBER
                        else:
                            note = "Today's report was handed to the selected voice; playback is not confirmed by the app."
                            note_en = note
                            color = CYAN
                        self.dt_voice_report_note.configure(text=L(note_en, note), fg=color)
                        if selected == "SI" and state == "queued" and dispatch.get("id"):
                            self.root.after(1800, lambda rid=str(dispatch.get("id")):
                                self._voice_report_playback_check(rid, time.time() + 600.0))
                except Exception:
                    pass
                if error:
                    q_log(f"spoken report: {error}", "err")
                else:
                    try:
                        dispatch = E.voice_last_dispatch("update")
                    except Exception:
                        dispatch = {"state": "unknown"}
                    q_log("spoken report " + str(dispatch.get("state") or "unknown") +
                          " via " + str(dispatch.get("route") or "none") +
                          " in " + str(getattr(E, "VOICE_LANG", "EN")),
                          "ok" if dispatch.get("state") in ("queued", "played", "dispatched", "started") else "warn")
                    self.dt_refresh(True)
            elif item[0] == "real_pl_sync":
                _, got, error = item
                if error:
                    q_log(f"real P&L: {error}", "err")
                    messagebox.showerror("REAL P&L", error, parent=self.root)
                else:
                    note = (f"{got.get('checked', 0)} trade(s) checked, "
                            f"{got.get('fixed', 0)} updated with the REAL commission + swap")
                    q_log("real P&L: " + note, "info")
                    self.refresh_journal()
                    messagebox.showinfo(L("REAL P&L", "ඇත්ත ලාභය"), note, parent=self.root)
            elif item[0] == "live":
                self.live_info = item[1]
                self._paint_live()
            elif item[0] == "mt5_history":
                _, snapshot, error = item
                if error:
                    self.mt5_history_summary.configure(
                        text=f"MT5 history read failed: {error}")
                    q_log(f"MT5 history read: {error}", "err")
                else:
                    self.mt5_history_snapshot = snapshot or {"trades": [], "status": "unavailable"}
                    self._paint_mt5_account_history()
            elif item[0] == "selftest":
                cb, self._selftest_cb = self._selftest_cb, None
                if cb:
                    cb(bool(item[1]))
        if self.running and not (self.bot and self.bot.is_alive()):
            self.set_running(False)
            q_log("engine stopped", "info")
        # the dashboard refreshes itself (cheap: journal is in memory)
        self._dash_tick = getattr(self, "_dash_tick", 0) + 1
        if self._dash_tick % 10 == 3:
            self.studio_auto_update_publications()       # journal outcomes + opt-in read-only MT5 quotes
        if (self._dash_tick % 75 == 9 and self.nb.select() == str(self.tab_studio)
                and getattr(self, "studio_inner_nb", None) is not None):
            try:
                if self.studio_inner_nb.index(self.studio_inner_nb.select()) == 2:
                    self._studio_refresh_performance()
            except Exception:
                pass
        if (self._dash_tick % 15 == 7 and self.nb.select() == str(self.tab_account)
                and getattr(self, "cloud_session", None) and not getattr(self, "_cloud_busy", False)):
            self.cloud_refresh_signals()                 # near-real-time Supabase polling
        if self._dash_tick % 5 == 3:
            self.tg_chip_refresh()                    # v1.9.2: always the truth
        if self._dash_tick % 8 == 1 and self.nb.select() == str(self.tab_dash):
            self.refresh_dashboard()
            self._paint_live()                       # real time: every ~1 second
            self.refresh_situation()                 # market open?  which session?
            self.refresh_limits()                    # loss limit + telegram queue
        if self._dash_tick % 5 == 2 and self.nb.select() == str(self.tab_ag):
            self.refresh_agent()
        if self.nb.select() == str(self.tab_jr):
            if self._dash_tick % 25 == 1:
                self.refresh_journal()
            if self._dash_tick % 5 == 2:
                self._paint_live()
            journal_page = getattr(self, "journal_nb", None)
            selected_journal_page = journal_page.select() if journal_page is not None else ""
            if selected_journal_page == str(getattr(self, "journal_mt5_history_page", "")):
                if (not getattr(self, "_mt5_history_busy", False) and
                        time.time() - float(getattr(self, "_mt5_history_last_request", 0.0) or 0.0) > 90):
                    self.refresh_mt5_account_history()
            if selected_journal_page == str(getattr(self, "journal_best_page", "")):
                if hasattr(self, "bp_canvas"):
                    self.bp_animate()
                if self._dash_tick % 15 == 3 and hasattr(self, "bp_canvas"):
                    self.bp_refresh()
            elif selected_journal_page == str(getattr(self, "journal_flow_page", "")):
                if hasattr(self, "fl_canvas"):
                    self.fl_animate()
                if self._dash_tick % 15 == 3 and hasattr(self, "fl_canvas"):
                    self.fl_refresh()
        if self._dash_tick % 25 == 4 and self.nb.select() == str(self.tab_progress):
            self.refresh_channel_progress()
        if self._dash_tick % 25 == 6 and self.nb.select() == str(self.tab_manual):
            self.refresh_manual_trades()
        if self._dash_tick % 25 == 3 and self.nb.select() == str(self.tab_cal):
            self.refresh_calendar()
        if self.nb.select() == str(self.tab_dash):
            if hasattr(self, "dt_canvas"):
                self.dt_animate()
            if self._dash_tick % 15 == 3 and hasattr(self, "dt_canvas"):
                self.dt_refresh()
        if self._dash_tick % 50 == 11 and self.nb.select() == str(self.tab_adv):
            self.refresh_advanced()
        if self.nb.select() == str(self.tab_plan):      # v1.8.0
            self.plan_animate()
        if self._dash_tick % 40 == 9 and self.nb.select() == str(self.tab_plan):
            self.plan_generate()
        if self._dash_tick % 25 == 5:
            self._fix_scrollregions()
        if self._dash_tick % 50 == 7 and self.nb.select() == str(self.tab_bro):
            self.refresh_brokers()
        self.root.after(400, self._tick)

    def _append(self, text: str, tag: str):
        self.log.configure(state="normal")
        self.log.insert("end", text, tag)
        if int(self.log.index("end-1c").split(".")[0]) > 4000:
            self.log.delete("1.0", "900.0")
        self.log.configure(state="disabled")

    # ------------------------------------------------------------- window ---
    def _fix_scrollregions(self):
        """The dashboard grows (channels, trades) - keep the scroll region right."""
        for cv in (self._wheel_canvases or {}).values():
            try:
                cv.configure(scrollregion=cv.bbox("all"))
            except Exception:
                pass

    def _on_wheel(self, event, direction: int = 0):
        """Mouse wheel scrolls the tab that is open right now (v1.7.0)."""
        try:
            cv = (self._wheel_canvases or {}).get(str(self.nb.select()))
            if cv is None:
                return
            step = direction or (1 if getattr(event, "delta", 0) > 0 else -1)
            cv.yview_scroll(-step, "units")
        except Exception:
            pass

    def _load_window(self):
        try:
            cfg = json.loads(SETTINGS_FILE.read_text(encoding="utf-8"))
            raw = str(cfg.get("geometry") or "")
            match = re.fullmatch(r"(\d+)x(\d+)([+-]\d+)?([+-]\d+)?", raw)
            if match:
                sw, sh = self._screen_size
                min_w, min_h = self._min_window_size
                w = max(min_w, min(sw - 20, int(match.group(1))))
                h = max(min_h, min(sh - 40, int(match.group(2))))
                x = max(0, min(sw - w, int(match.group(3) or 0)))
                y = max(0, min(sh - h, int(match.group(4) or 0)))
                self.root.geometry(f"{w}x{h}+{x}+{y}")
            if self.app_role in ("provider", "receiver") and isinstance(cfg.get("tab"), int):
                idx = cfg["tab"]
                saved_ver = tuple(int(x) for x in re.findall(r"\d+", str(cfg.get("ui_version") or ""))[:3])
                if idx >= 1 and (not saved_ver or saved_ver < (1, 9, 9)):
                    idx += 1  # Telegram Studio was inserted after the old first tab.
                self.nb.select(max(0, min(len(self.nb.tabs()) - 1, idx)))
        except Exception:
            pass

    def _save_window(self):
        try:
            save_ui_prefs(geometry=self.root.winfo_geometry(),
                          tab=self.nb.index(self.nb.select()),
                          theme=_THEME, lang=LANG, ui_version=APP_BUILD)
        except Exception:
            pass

    def on_close(self):
        self._save_window()
        if self.bot and self.bot.is_alive():
            if not messagebox.askyesno("EdgeQuant",
                                       "The engine is still running.\n\nStop it and exit ?"):
                return
            self.bot.stop()
            time.sleep(0.6)
        try:
            if getattr(self, "keep_awake_enabled", False):
                self.keep_awake_var.set(False)
                self.keep_system_awake()
        except Exception:
            pass
        try:
            if E.TRADE_JOURNAL:
                E.jr_write_files()
        except Exception:
            pass
        _stop_tg_login_loop()
        try:
            if hasattr(E, "local_sinhala_voice_stop"):
                E.local_sinhala_voice_stop(timeout=3.0)
        except Exception as exc:
            q_log(f"offline Sinhala voice shutdown: {exc}", "warn")
        self.root.destroy()


