    def _loss_unlock_button_probe():
        saved = (E.HERE, E.TRADES, E._JR_LOADED, E._LOSS_LOCKED, E.MAX_DAILY_LOSS)
        old_yesno, old_info = messagebox.askyesno, messagebox.showinfo
        try:
            with tempfile.TemporaryDirectory(prefix="eq_v4_loss_unlock_") as td:
                E.HERE = Path(td)
                E.TRADES = [{"status": "closed", "result": "sl", "net": -35.0,
                             "placed_ts": time.time(), "closed_ts": time.time()}]
                E._JR_LOADED = True
                E._LOSS_LOCKED = ""
                E.MAX_DAILY_LOSS = 30.0
                E.state_set("max_daily_loss", 30.0)
                messagebox.askyesno = lambda *a, **k: True
                messagebox.showinfo = lambda *a, **k: None
                app_probe = object.__new__(EdgeQuantApp)
                app_probe.refresh_limits = lambda: None
                before = E.loss_limit_state()
                app_probe.unlock_loss()
                after = E.loss_limit_state()
                return (bool(before.get("hit")), bool(after.get("unlocked")),
                        not bool(after.get("hit")))
        except Exception as exc:
            return (False, False, str(exc))
        finally:
            E.HERE, E.TRADES, E._JR_LOADED, E._LOSS_LOCKED, E.MAX_DAILY_LOSS = saved
            messagebox.askyesno, messagebox.showinfo = old_yesno, old_info
    check("Unlock Today persists a verified same-day unlock and re-enables new signals",
          _loss_unlock_button_probe(), (True, True, True))
    def _loss_cap_save_probe():
        saved = (E.HERE, E.MAX_DAILY_LOSS)
        class _ValueProbe:
            def __init__(self, value): self.value = value
            def get(self): return self.value
            def set(self, value): self.value = value
        class _NoteProbe:
            def __init__(self): self.values = {}
            def configure(self, **kwargs): self.values.update(kwargs)
        try:
            with tempfile.TemporaryDirectory(prefix="eq_v4_loss_cap_") as td:
                E.HERE = Path(td)
                E.MAX_DAILY_LOSS = 30.0
                app_probe = object.__new__(EdgeQuantApp)
                app_probe.loss_cap_var = _ValueProbe("45.50")
                app_probe.loss_enabled_var = _ValueProbe(False)
                app_probe.loss_cap_note = _NoteProbe()
                app_probe.refresh_limits = lambda: None
                app_probe.loss_limit_save()
                return (E.loss_limit_value(), app_probe.loss_cap_var.value,
                        "45.50" in app_probe.loss_cap_note.values.get("text", ""))
        except Exception as exc:
            return (None, str(exc), False)
        finally:
            E.HERE, E.MAX_DAILY_LOSS = saved
    check("Dashboard loss-cap opt-in saves and verifies locally",
          _loss_cap_save_probe(), (45.5, "45.5", True))
    def _loss_toggle_probe():
        saved = (E.HERE, E.MAX_DAILY_LOSS)
        class _VarProbe:
            def __init__(self, value): self.value = value
            def get(self): return self.value
            def set(self, value): self.value = value
        class _NoteProbe:
            def __init__(self): self.values = {}
            def configure(self, **kwargs): self.values.update(kwargs)
        try:
            with tempfile.TemporaryDirectory(prefix="eq_v4_loss_toggle_") as td:
                E.HERE = Path(td)
                E.MAX_DAILY_LOSS = 30.0
                E.state_set("max_daily_loss", 30.0)
                app_probe = object.__new__(EdgeQuantApp)
                app_probe.loss_enabled_var = _VarProbe(True)
                app_probe.loss_cap_var = _VarProbe("30")
                app_probe.loss_cap_note = _NoteProbe()
                app_probe.refresh_limits = lambda: None
                app_probe.loss_limit_toggle()
                on_state = (E.loss_limit_enabled(), E.loss_limit_value())
                app_probe.loss_enabled_var.set(False)
                app_probe.loss_limit_toggle()
                off_state = (E.loss_limit_enabled(), E.loss_limit_value(), E.loss_limit_amount())
                return on_state, off_state
        except Exception as exc:
            return str(exc)
        finally:
            E.HERE, E.MAX_DAILY_LOSS = saved
