    def _fake_login_loop_probe():
        from types import SimpleNamespace
        old_here = E.HERE
        old_client_type = E.TelegramClient
        old_login_client = getattr(E, "_login_client", None)
        old_api_id, old_api_hash = E.API_ID, E.API_HASH
        old_state = dict(E.TG_STATE)
        seen_loops = []
        class _LoopBoundFake:
            def __init__(self, *args, **kwargs):
                self.loop = None
            def _check_loop(self):
                loop = asyncio.get_running_loop()
                if self.loop is None:
                    self.loop = loop
                elif self.loop is not loop:
                    raise RuntimeError("the event loop must not change after connection")
                seen_loops.append(id(loop))
            async def connect(self):
                self._check_loop()
            async def send_code_request(self, phone):
                self._check_loop()
                return SimpleNamespace(phone_code_hash="fake-hash")
            async def sign_in(self, *args, **kwargs):
                self._check_loop()
            async def get_me(self):
                self._check_loop()
                return SimpleNamespace(first_name="Test", username="eq_test")
            async def disconnect(self):
                self._check_loop()
        try:
            with tempfile.TemporaryDirectory(prefix="eq196_login_") as _login_td:
                E.HERE = Path(_login_td)
                E.API_ID, E.API_HASH = 12345678, "a" * 32
                E.TelegramClient = _LoopBoundFake
                E._login_client = None
                E.TG_STATE.update({"online": False, "who": "", "reason": "",
                                   "phase": "idle", "ts": 0.0})
                _sent = _run_tg_login_coro(E.tg_login_send_code("+10000000000"), timeout=8)
                _used = _run_tg_login_coro(
                    E.tg_login_enter_code("+10000000000", "12345"), timeout=8)
                return (_sent.get("ok") is True, _used.get("ok") is True,
                        len(set(seen_loops)) == 1, E._login_client is None)
        except Exception as _err:
            return (False, False, False, str(_err))
        finally:
            E.HERE = old_here
            E.TelegramClient = old_client_type
            E.API_ID, E.API_HASH = old_api_id, old_api_hash
            E._login_client = old_login_client
            E.TG_STATE.clear()
            E.TG_STATE.update(old_state)
            _stop_tg_login_loop()

    check("SEND CODE -> USE CODE survives Telethon's loop binding",
          _fake_login_loop_probe(), (True, True, True, True))

    def _dead_key_retry_probe():
        from types import SimpleNamespace
        old_here = E.HERE
        old_client_type = E.TelegramClient
        old_login_client = getattr(E, "_login_client", None)
        old_api_id, old_api_hash = E.API_ID, E.API_HASH
        old_state = dict(E.TG_STATE)
        seen = []
        made = []
        class SessionPasswordNeededError(Exception):
            pass
        class AuthKeyUnregisteredError(Exception):
            pass
        class _DeadOnceFake:
            def __init__(self, path, *args, **kwargs):
                self.base = Path(str(path))
                self.loop = None
                self.number = len(made) + 1
                made.append(self)
            def _check(self):
                loop = asyncio.get_running_loop()
                if self.loop is None:
                    self.loop = loop
                elif self.loop is not loop:
                    raise RuntimeError("event loop changed")
                seen.append(id(loop))
            async def connect(self):
                self._check()
                self.base.parent.mkdir(parents=True, exist_ok=True)
                Path(str(self.base) + ".session").write_text(f"client-{self.number}")
            async def send_code_request(self, phone):
                self._check()
                return SimpleNamespace(phone_code_hash=f"hash-{self.number}")
            async def sign_in(self, *args, **kwargs):
                self._check()
                if kwargs.get("code"):
                    raise SessionPasswordNeededError("2FA needed")
                if self.number == 1:
                    raise AuthKeyUnregisteredError(
                        "The key is not registered (caused by GetPasswordRequest)")
            async def get_me(self):
                self._check()
                return SimpleNamespace(first_name="Fresh", last_name="Trader",
                                       username="fresh_test")
            async def disconnect(self):
                self._check()
        try:
            with tempfile.TemporaryDirectory(prefix="eq197_deadkey_") as _td:
                E.HERE = Path(_td)
                E.API_ID, E.API_HASH = 12345678, "a" * 32
                # Force the historical filename path: it must be parked too.
                (Path(_td) / "signalpilot_session.session").write_text("legacy-key")
                E.TelegramClient = _DeadOnceFake
                E._login_client = None
                E.TG_STATE.update({"online": False, "who": "", "reason": "",
                                   "phase": "idle", "ts": 0.0})
                first = _run_tg_login_coro(E.tg_login_send_code("+10000000000"), 8)
                need2fa = _run_tg_login_coro(
                    E.tg_login_enter_code("+10000000000", "11111"), 8)
                dead = _run_tg_login_coro(E.tg_login_enter_password("old"), 8)
                old_parked = bool(list(Path(_td).glob("*.session.dead-*")))
                fresh = _run_tg_login_coro(E.tg_login_send_code("+10000000000"), 8)
                need2fa2 = _run_tg_login_coro(
                    E.tg_login_enter_code("+10000000000", "22222"), 8)
                done = _run_tg_login_coro(E.tg_login_enter_password("new"), 8)
                return (first.get("ok") is True,
                        need2fa.get("need_password") is True,
                        "press SEND CODE again" in str(dead.get("error", "")),
                        old_parked, fresh.get("ok") is True,
                        need2fa2.get("need_password") is True,
                        done.get("ok") is True, done.get("name") == "Fresh Trader",
                        len(made) == 2, len(set(seen)) == 1,
                        E._login_client is None)
        except Exception as _err:
            return (False, False, str(_err), False, False, False, False, False,
                    False, False, False)
        finally:
            E.HERE = old_here
            E.TelegramClient = old_client_type
            E.API_ID, E.API_HASH = old_api_id, old_api_hash
            E._login_client = old_login_client
            E.TG_STATE.clear()
            E.TG_STATE.update(old_state)
            _stop_tg_login_loop()

