    def _journal_history_load_probe():
        saved = (E.HERE, E.TRADES, E._JR_LOADED)
        try:
            with tempfile.TemporaryDirectory(prefix="eq_v4_journal_history_") as td:
                E.HERE = Path(td)
                E.TRADES = []
                E._JR_LOADED = False
                path = E.HERE / E.TRADE_LOG
                base = time.time() - 405 * 86400
                path.write_text("\n".join(json.dumps({
                    "id": f"old-{i}", "source": "Historic group", "status": "closed",
                    "result": "tp", "net": 1.0, "placed_ts": base + i * 86400,
                    "closed_ts": base + i * 86400}) for i in range(405)) + "\n",
                    encoding="utf-8")
                E.jr_load()
                return len(E.TRADES), min(float(x["placed_ts"]) for x in E.TRADES) < time.time() - 400 * 86400
        except Exception as exc:
            return (0, str(exc))
        finally:
            E.HERE, E.TRADES, E._JR_LOADED = saved
