def main() -> int:
    try:
        sys.excepthook = _last_resort          # a crash is written down, never silent
        return _main()
    except SystemExit:
        raise
    except Exception:
        text = traceback.format_exc()
        try:
            (APP_DIR / "edgequant_desktop_error.log").write_text(text, encoding="utf-8")
        except Exception:
            pass
        try:
            root = tk.Tk()
            root.withdraw()
            messagebox.showerror(
                "EdgeQuant Desktop - crash",
                "The app could not start.\n\n" + text[-800:] +
                "\n\nFull detail: edgequant_desktop_error.log")
            root.destroy()
        except Exception:
            print(text)
        return 1


def _last_resort(exc_type, exc, tb):
    """Nothing may die without telling us - the .exe has no console to print to."""
    import traceback as _tb
    text = "".join(_tb.format_exception(exc_type, exc, tb))
    try:
        with open(APP_DIR / "edgequant_desktop_error.log", "a", encoding="utf-8") as fh:
            fh.write(f"\n--- {datetime.now().isoformat()} (uncaught) ---\n{text}")
    except Exception:
        pass
    try:
        print(text)
    except Exception:
        pass


def _mt5_import_selfcheck() -> int:
    """Verify the packaged MetaTrader5 native extension imports; never initialize MT5."""
    import tempfile
    log_path = (APP_DIR / "mt5-import-selfcheck.log" if getattr(sys, "frozen", False)
                else Path(tempfile.gettempdir()) / "edgequant-mt5-import-selfcheck.log")
    try:
        import importlib
        api = importlib.import_module("MetaTrader5")
        core = importlib.import_module("MetaTrader5._core")
        api_path = str(getattr(api, "__file__", "") or "")
        core_path = str(getattr(core, "__file__", "") or "")
        if not api_path or not core_path or not Path(core_path).is_file():
            raise RuntimeError(f"MetaTrader5 API/core module path is missing: {api_path!r}, {core_path!r}")
        log_path.write_text(
            f"PASS | MetaTrader5 _core import succeeded | API={api_path} | core={core_path} | {APP_BUILD}\n",
            encoding="utf-8")
        return 0
    except Exception as exc:
        detail = traceback.format_exc()
        try:
            log_path.write_text(
                f"FAIL | {type(exc).__name__}: {exc}\n"
                "Install/repair Microsoft Visual C++ x64 runtime; confirm 64-bit Python; rebuild.\n\n"
                + detail, encoding="utf-8")
        except Exception:
            pass
        return 1


def _xlsx_export_package_selfcheck() -> int:
    """Exercise both branded workbooks and bundled logo embedding in source/frozen app."""
    import tempfile
    import zipfile
    log_path = (APP_DIR / "xlsx-selfcheck.log" if getattr(sys, "frozen", False)
                else Path(tempfile.gettempdir()) / "edgequant-xlsx-selfcheck.log")
    try:
        if ProviderStudio is None:
            raise RuntimeError("Provider Studio could not be imported: " + PROVIDER_STUDIO_IMPORT_ERROR)
        from openpyxl import load_workbook
        logo_path = BRAND_LOGO if BRAND_LOGO.is_file() else LOGO_SMALL
        if not logo_path.is_file():
            raise RuntimeError(f"Bundled logo asset is missing: {logo_path}")
        with tempfile.TemporaryDirectory(prefix="edgequant-xlsx-selfcheck-") as temp_dir:
            report_path = Path(temp_dir) / "provider-report.xlsx"
            daily_report_path = Path(temp_dir) / "provider-daily-report.xlsx"
            plan_path = Path(temp_dir) / "provider-plan.xlsx"
            ProviderStudio.export_provider_xlsx(
                report_path, publications=[], trades=[], engine=E,
                logo_path=logo_path,
                provider_name="EdgeQuant XLSX Package Check")
            daily_now = datetime.now().astimezone()
            daily_publications = [{
                "id": "daily-package-check", "created_ts": daily_now.timestamp(),
                "status": "PUBLISHED", "composer": {
                    "symbol": "XAUUSD", "direction": "BUY", "order_type": "MARKET",
                    "entry": "2000", "sl": "1990", "tp_levels": ["2010"]},
                "targets": [{"id": -10001, "name": "Daily Package Check", "message_id": 501}],
                "local_trade_ids": [], "progress_events": []}]
            ProviderStudio.export_provider_daily_xlsx(
                daily_report_path, daily_publications, trades=[], engine=E,
                logo_path=logo_path, destination_id=-10001,
                destination_name="Daily Package Check", now=daily_now)
            ProviderStudio.export_plan_xlsx(
                plan_path,
                {"capital": 10000, "days": 5, "months": 1, "risk_pct": 1.0,
                 "target_pct": 5.0, "win": 60.0, "rr": 2.0, "trades_day": 3,
                 "risk_usd": 100.0, "per_day": 50.0, "per_month": 1000.0,
                 "per": "DAYS", "day_pct": 0.5, "month_pct": 5.0,
                 "table": [{"label": "Day 1", "days": 1, "target_hit": False}],
                 "daily_target_status": {"net": 0.0, "target": 100.0,
                                          "done_pct": 0.0, "remaining": 100.0,
                                          "achieved": False}},
                logo_path=logo_path,
                provider_name="EdgeQuant XLSX Package Check")
            for path, expected in ((report_path, {"SUMMARY", "SIGNALS", "DESTINATIONS"}),
                                   (daily_report_path, {"SUMMARY", "SIGNALS", "DESTINATIONS"}),
                                   (plan_path, {"OVERVIEW", "PLAN INPUTS", "DAILY TARGET", "DAY-BY-DAY PLAN"})):
                with zipfile.ZipFile(path, "r") as archive:
                    if archive.testzip() is not None:
                        raise RuntimeError(f"Invalid Office ZIP structure: {path.name}")
                    media = [name for name in archive.namelist() if name.startswith("xl/media/")]
                    if not media:
                        raise RuntimeError(f"{path.name} does not contain the expected embedded logo image")
                book = load_workbook(path, read_only=True, data_only=True)
                actual = set(book.sheetnames)
                book.close()
                if not expected.issubset(actual):
                    raise RuntimeError(f"{path.name} is missing sheets: {sorted(expected - actual)}")
        log_path.write_text(
            f"PASS | provider and plan Excel exports opened successfully with logos; daily EOD workbook passed | {APP_BUILD}\n",
            encoding="utf-8")
        return 0
    except Exception as exc:
        detail = traceback.format_exc()
        try:
            log_path.write_text(
                f"FAIL | {type(exc).__name__}: {exc}\n\n{detail}", encoding="utf-8")
        except Exception:
            pass
        return 1


def _enable_windows_dpi_awareness():
    """Request per-monitor DPI awareness before the first Tk window is created."""
    if os.name != "nt":
        return False
    try:
        user32 = ctypes.windll.user32
        try:
            if user32.SetProcessDpiAwarenessContext(ctypes.c_void_p(-4)):
                return True  # PER_MONITOR_AWARE_V2
        except Exception:
            pass
        try:
            ctypes.windll.shcore.SetProcessDpiAwareness(2)  # PER_MONITOR_AWARE
            return True
        except Exception:
            pass
        try:
            return bool(user32.SetProcessDPIAware())
        except Exception:
            return False
    except Exception:
        return False


def _main() -> int:
    _enable_windows_dpi_awareness()
    root = tk.Tk()
    app = EdgeQuantApp(root)
    app.clear_log()
    _diag = startup_diagnostics(write=True)
    app._append("\n".join(_diag) + "\n", "info")
    app._append(f"(this is also saved to edgequant_startup.log)\n\n", "ok")
    app.refresh_channels()
    app.refresh_journal()
    app.refresh_dashboard()
    for line in (
        f"{E.BOT_NAME}  engine v{E.VERSION}   -   desktop app ready  ({APP_BUILD})",
        "",
        "HOW TO USE",
        "    START      = live trading (review the account and acknowledge the risk)",
        "    TEST RUN   = same engine, no real orders",
        "    STOP       = stop trading",
        "    DASHBOARD tab       = current P/L, daily P/L, equity curve, channel ranking",
        "    TRADE JOURNAL tab   = every EdgeQuant order: TP / SL / BE / missed",
        "    CHANNEL PROGRESS   = channel ranking + TP / BE / SL / manual-close results",
        "    MANUAL TRADES      = non-EdgeQuant trades opened today; confirmed local edits",
        "    SETTINGS tab        = change the settings without editing code",
        "",
        "First time ?   Press TEST RUN and watch the ACTIVITY tab.",
        "",
        "CHANNELS tab = switch any channel ON / OFF with one button (no editing).",
        "DASHBOARD    = the last line shows if the market is open + which session.",
        "               the line under it shows the daily loss limit (+ UNLOCK TODAY).",
    ):
        app._append(line + "\n", "ok" if line.startswith(("HOW", "First")) else "info")
    try:
        saved_status = E.tg_status_read() if E.tg_session_exists() else {}
        saved_name = telegram_display_name((saved_status or {}).get("who", ""))
    except Exception:
        saved_name = ""
    app_greeting = bilingual_welcome(saved_name, telegram=False)
    app._append(app_greeting + "\n", "ok")
    app.speak_welcome(saved_name, telegram=False)
    root.after(350, lambda: messagebox.showinfo(
        "Welcome | සාදරයෙන් පිළිගනිමු", app_greeting, parent=root))
    root.mainloop()
    return 0


if __name__ == "__main__":
    if "--engine-cli" in sys.argv:
        _engine_index = sys.argv.index("--engine-cli")
        sys.exit(E.main(sys.argv[_engine_index + 1:]))
    if "--mt5-import-selfcheck" in sys.argv:
        sys.exit(_mt5_import_selfcheck())
    if "--xlsx-selfcheck" in sys.argv:
        sys.exit(_xlsx_export_package_selfcheck())
    if "--selfcheck" in sys.argv:
        sys.exit(selfcheck())
    if "--diag" in sys.argv:
        for _l in startup_diagnostics(write=True):
            print(_l)
        print(f"\nwritten to {APP_DIR / 'edgequant_startup.log'}")
        sys.exit(0)
    sys.exit(main())
